struct Skill
{
 int points;
 int inc;
};

Skill a[100005];

bool Compare(Skill x,Skill y)
{
 if(x.inc!=y.inc)
  return x.inc<y.inc;

 return x.points<y.points;
}

int main()
{

int n,k,i,ans,cinc;
bool can;

scanf("%d%d",&n,&k);

ans=0;
 for(i=1;i<=n;i++)
 {
  scanf("%d",&a[i].points);
  a[i].inc=10-(a[i].points%10);
  ans+=a[i].points/10;
 }

sort(a+1,a+n+1,Compare);

can=true;
 for(i=1;i<=n;i++)
 {
  if(a[i].points!=100)
  {
   if(a[i].inc<=k)
   {
    k-=a[i].inc;
    a[i].points+=a[i].inc;
    ans++;
   }
   else
   {
    can=false;
    break;
   }
  }
 }

 if(can)
 {
  for(i=1;i<=n;i++)
  {
   cinc=min(k,100-a[i].points);
   k-=cinc;
   a[i].points+=cinc;
   ans+=cinc/10;
  }
 }

printf("%d\n",ans);

return 0;
}

