using namespace std;
const int N = 1003;
int a[N * N], b[N];
map <int, int> m;
void rd(int &t) {
    t = 0;
    char p = getchar();
    while (p < 48 || p > 57) p = getchar();
    do {(t *= 10) += p - 48; p = getchar();} while (p > 47 && p < 58);
}
void del(int x, int y = 1) {if (!(m[x] -= y)) m.erase(m.find(x));}
int gcd(int a, int b) {
    int r;
    while (b) {r = a % b; a = b; b = r;}
    return a;
}
int main() {
    int n, i, j;
    rd(n);
    for (i = 1; i <= n * n; ++i) {rd(a[i]); ++m[a[i]];}
    if (n == 1) {printf("%d\n", a[1]); return 0;}
    b[1] = m.rbegin() -> first; del(b[1]);
    b[2] = m.rbegin() -> first; del(b[2]);
    del(gcd(b[1], b[2]), 2);
    for (i = 3; i <= n; ++i) {
        b[i] = m.rbegin() -> first; del(b[i]);
        for (j = 1; j < i; ++j) del(gcd(b[i], b[j]), 2);
    }
    for (i = 1; i <= n; ++i) printf("%d ", b[i]); printf("\n");
    return 0;
}

