using namespace std;

int N,T,arr[110],res[110][110],aux[110][110],dp[110],cr[110][110];

void mult(int a[][110],int b[][110],int c[][110]){
    int i,j,k;
    for (i=1; i<=N; i++)
        for (j=1; j<=N; j++) c[i][j]=0;

    for (i=1; i<=N; i++)
        for (j=1; j<=N; j++){
            if (arr[i]>arr[j]) continue;
            for (k=1; k<=N; k++)
                if (arr[k]>=arr[i] && arr[k]<=arr[j])
                    c[i][j]=max(c[i][j],a[i][k]+b[k][j]);
        }
}

void cpy(int a[][110],int b[][110]){
    int i,j;
    for (i=1; i<=N; i++)
        for (j=1; j<=N; j++)
            b[i][j]=a[i][j];
}

int main(){
    cin >> N >> T;

    int i,j,k;
    for (i=1; i<=N; i++) cin >> arr[i];

    for (i=1; i<=N; i++){
        memset(dp,0,sizeof(dp));
        for (j=1; j<=N; j++){
            if (arr[j]<arr[i]) continue;
            dp[j]=1;
            for (k=j-1; k>0; k--)
                if (arr[k]<=arr[j]) dp[j]=max(dp[j],1+dp[k]);

            cr[i][j]=dp[j];
        }
    }

    bool st=0;
    while (T){
        if (T&1){
            mult(res,cr,aux),cpy(aux,res);
        }

        mult(cr,cr,aux);
        cpy(aux,cr);
        T>>=1;
    }

    int ans=0;
    for (i=1; i<=N; i++)
        for (j=1; j<=N; j++)
            ans=max(ans,res[i][j]);

    cout << ans << "\n";

    return 0;
}

