int N,a[400010],rmx[400010],K,l[400010],pos[200010]; bool v[400010],g[400010];
vector<int> cnt[1000];

int gcd(int a, int b){
    if (!b) return a;
    return gcd(b,a%b);
}

int main(){
    ios::sync_with_stdio(0);
    cin.tie(0);
    cin >> N;

    int i,d; LL res=0;
    for (i=0; i<N; i++) cin >> a[i];


    for (d=1; d<=N; d++)
        if (N%d==0){
            for (i=0; i<d; i++) rmx[i]=0;
            for (i=0; i<2*N; i++) g[i]=0;
            for (i=0; i<N; i++)
                rmx[i%d]=max(rmx[i%d],a[i]);

            for (i=0; i<N; i++)
                if (a[i]==rmx[i%d]) g[i]=1;
            for (i=N; i<2*N; i++) g[i]=g[i%N];

            for (i=2*N; i>=0; i--){
                if (g[i]==0) l[i]=0;
                else l[i]=1+l[i+1];
                l[i]=min(l[i],N-1);
            }

            K++;
            pos[d]=K;
            cnt[K].resize(N);
            for (i=0; i<N; i++) cnt[K][l[i]]++;
            for (i=N-2; i>=0; i--)
                cnt[K][i]+=cnt[K][i+1];
        }

    for (i=1; i<N; i++){
        d=gcd(i,N);
        res+=cnt[pos[d]][i];
    }

    cout << res << "\n";

    return 0;
}

