struct bignumber
{
	long long num[1010], dig;
	
	void set(char *s)
	{
		long long t = 1;
		num[dig = 0] = 0;
		int l = strlen(s);
		for (int i = l - 1; i >= 0; --i)
		{
			num[dig] = num[dig] + (s[i] - '0') * t;
			t *= 10;
			if (t == 1000000000ll)
			{
				t = 1;
				num[++dig] = 0;
			}
		}
		while (dig && num[dig] == 0) --dig;
	}
	
	long long divide(long long m)
	{
		long long ret = 0;
		for (int i = dig; i >= 0; --i)
		{
			num[i] += ret * 1000000000ll;
			ret = num[i] % m;
			num[i] /= m;
		}
		while (dig && num[dig] == 0) --dig;
		return ret;
	}
	
	bool empty()
	{
		return !(dig || num[0]);
	}
	
	void write(char ch = 0)
	{
		if (dig) printf("%lld", num[dig]);
		for (int i = dig - 1; i >= 0; --i)
			printf("%09lld", num[i]);
		putchar(ch);
	}
};

namespace lightningwork
{
	// my space

	const int mod = 1000000007;
	
	int (*read)() = defs::read<int>;

	int p, a;
	
	int num[3333], dg;
	
	int f[3333][3333][2][2];
	
	char str[1111];
	
	bignumber A;
	
	long long calc(long long mx)
	{
		if (mx < p)
		{
			return ((mx + 2) * (mx + 1) / 2) % mod;
		} else if (mx >= p + p - 2)
		{
			return 1ll * p * p % mod;
		} else
		{
			long long tmp = mx - p + 1;
			return (tmp * p + (tmp + p + 1) * (p - tmp) / 2) % mod;
		}
	}
	
	long long calc(long long low, long long high)
	{
		if (high < 0) return 0;
		if (low <= 0) return calc(high);
		long long ret = calc(high) - calc(low - 1);
		return (ret + mod) % mod;
	}

	long long dfs(int now, int dig, bool add, bool lim)
	{
		if (dig > a) dig = a;
		if (f[now][dig][add][lim] >= 0)
		{
			return f[now][dig][add][lim];
		}
		if (now == 0)
		{
			return dig >= a && add == 0;
		}
		long long ret = 0;
		if (lim)
		{
			if (add)
			{
				ret += dfs(now - 1, dig, 0, 1) * calc(num[now] + p, num[now] + p) % mod;
				ret += dfs(now - 1, dig + 1, 1, 1) * calc(num[now] + p - 1, num[now] + p - 1) % mod;
				ret += dfs(now - 1, dig, 0, 0) * calc(p, num[now] + p - 1) % mod;
				ret += dfs(now - 1, dig + 1, 1, 0) * calc(p - 1, num[now] + p - 2) % mod;
			} else
			{
				ret += dfs(now - 1, dig, 0, 1) * calc(num[now], num[now]) % mod;
				ret += dfs(now - 1, dig + 1, 1, 1) * calc(num[now] - 1, num[now] - 1) % mod;
				ret += dfs(now - 1, dig, 0, 0) * calc(0, num[now] - 1) % mod;
				ret += dfs(now - 1, dig + 1, 1, 0) * calc(0, num[now] - 2) % mod;
			}
			ret = ret % mod;
		} else
		{
			if (add)
			{
				ret += dfs(now - 1, dig, 0, 0) * calc(p, p + p - 2) % mod;
				ret += dfs(now - 1, dig + 1, 1, 0) * calc(p - 1, p + p - 2) % mod;
			} else
			{
				ret += dfs(now - 1, dig, 0, 0) * calc(0, p - 1) % mod;
				ret += dfs(now - 1, dig + 1, 1, 0) * calc(0, p - 2) % mod;
			}
			ret = ret % mod;
		}
		f[now][dig][add][lim] = ret;
		debug("%d %d %d %d - %lld\n", now, dig, add, lim, ret);
		return ret;
	}

	void work()
	{
		p = read();
		a = read();
		scanf("%s", str);
		A.set(str);
		while (!A.empty())
		{
			num[++dg] = A.divide(p);
		}
		if (a > dg + 3)
		{
			printf("0\n");
			return;
		}
		memset(f, -1, sizeof f);
		int ans = dfs(dg + 1, 0, 0, 1);
		printf("%d\n", ans);
	}
}

