#define M 1000000007
using namespace std;

intmax_t modularExpo(intmax_t a, intmax_t b)
{
	intmax_t res = 1;
	a = a % M;
	while(b)
	{
		if(b%2!=0)
		{
			res = (res*a) % M;
		}
		b = b>>1;
		a = (a*a) % M;
	}
	return res;
}	

int main(int argc, char const *argv[])
{
	int n; cin >> n;
	cout << (intmax_t)(modularExpo(3,3*n) - modularExpo(7,n) + M) % M << endl;
	//cout << modularExpo(2,6) << endl;
	return 0;
}

