const int MX = 1e6 + 5;
const int MOD = 1000000007;
int n, k, a[MX], aa[MX], pos[MX];
ll l, acc[2][MX], dp[2][MX];

int main () {
    ios_base::sync_with_stdio(false);
    cin>>n>>l>>k;
    for (int i=0; i<n; i++) {
        cin>>a[i];
        aa[i] = a[i];
    }
    sort (aa, aa+n);
    int usz = unique (aa, aa+n) - aa;
    for (int i=0; i<n; i++) pos[i] = lower_bound (aa, aa+usz, a[i]) - aa;
    ll res = 0;
    bool end_processing = false;
    for (int length = 1; length <= k && !end_processing; length++) {
        for (int ending = 0; ending < n; ending++) {
            ll position = ((ll) length - 1) * n + ending + 1;
            if (position > l) {
                end_processing = true;
                break;
            }
            ll rep = (l - position) / n + 1;
            dp[length%2][ending] = 0;
            if (length == 1) {
                dp[length%2][ending] = 1;
            }
            else {
                dp[length%2][ending] = acc[(length+1)%2][pos[ending]];
                dp[length%2][ending] %= MOD;
            }
            res = (res + (((dp[length%2][ending] % MOD) * (rep % MOD))%MOD)) % MOD;
        }
        for (int i=0; i<usz; i++) acc[length%2][i] = 0;
        for (int i=0; i<n; i++) {
            acc[length%2][pos[i]] += dp[length%2][i];
            acc[length%2][pos[i]] %= MOD;
        }
        // Prepare for the next iteration
        for (int i=1; i<usz; i++) {
            acc[length%2][i] = (acc[length%2][i] + acc[length%2][i-1])%MOD;
        }
    }
    cout<<res%MOD<<endl;
    return 0;
}

