ll st[1<<20][2];

void merge(ll *r, ll *a, ll *b){
	ll t[2];
	t[0]=a[0]+b[0];
	t[1]=a[1]+b[1];
	r[0]=t[0];
	r[1]=t[1];
}

void st_upd(ll k, ll s, ll e, ll p, ll v){
	if(s+1==e){
		st[k][0]=v;
		st[k][1]=1;
	}
	else {
		ll m=(s+e)/2;
		if(p<m)st_upd(2*k,s,m,p,v);
		else st_upd(2*k+1,m,e,p,v);
		merge(st[k],st[2*k],st[2*k+1]);
	}
}

void st_query(ll k, ll s, ll e, ll a, ll b, ll *r){
	if(s>=b||e<=a)return;
	if(s>=a&&e<=b)merge(r,r,st[k]);
	else {
		ll m=(s+e)/2;
		st_query(2*k,s,m,a,b,r);
		st_query(2*k+1,m,e,a,b,r);
	}
}

