int n, m, dep, shift[100005];
long long len, num[105], g[105][26], pre[64][26];
char s[105];

long long f(long long pos, int k, int o) {
	if(o < 0) return g[pos][k];
	if((len << o) > pos) return f(pos, k, o - 1);
	if((len << o) == pos) return num[k] << o;
	pos -= len << o;
	if(pos <= shift[o]) return (num[k] << o) + f(pos + (len << o) - shift[o], k, o - 1) - ((num[k] << o) - pre[o][k]);
	return (num[k] << o) + f(pos - shift[o], k, o - 1) + pre[o][k];
}

int main() {
	scanf("%s%d%d", s + 1, &n, &m);
	for(Int i = 0; i < n; ++i) scanf("%d", shift + i);
	len = strlen(s + 1);
	
	for(Int i = 1; i <= len; ++i) {
		++num[s[i] - 'a'];
		for(Int k = 0; k < 26; ++k)
			g[i][k] = num[k];
	}
	
	for(register long long L = len; dep < n && L <= 1e18; ++dep, L <<= 1) {
		shift[dep] %= L;
		for(Int k = 0; k < 26; ++k)
			pre[dep][k] = (num[k] << dep) - f(L - shift[dep], k, dep);
	}
	
	long long l, r;
	while(m--) {
		scanf("%lld%lld%s", &l, &r, s);
		printf("%lld\n", f(r, s[0] - 'a', dep) - f(l - 1, s[0] - 'a', dep));
	}
	return 0;
}

