    // 0<=O<=pi
    int cnt=0;
    double lb = 0, ub = pi, mid,val,val1,val2;
    
    while(lb <= ub && cnt++<70){
        mid = (lb+ub)/2;
        val = f(mid,r,d);
       val1 =f(lb,r,d); val2=f(ub,r,d);
        if(val*val1<0){
            ub=mid;
           // val2=f(ub,r,d);
        }
        else {
            lb=mid;         
            //val1 = f(lb,r,d);
        }
        
    }
    return (mid*r)/v;
    
}
