int l,r,i,j,k,gr[N],gl[N],h,n,m,x,y,a[N];double p,f[N][N][4];bool vis[N][N][4];
double dfs(int l,int r,int o){
	if(vis[l][r][o])return f[l][r][o];
	if(l>r)return 0;vis[l][r][o]=1;double&ans=f[l][r][o];
	ans+=p*0.5*(min(h,a[l]-a[l-1]-((o>>1)&1)*h)+dfs(l+1,r,o&1));
	ans+=(1.-p)*0.5*(min(h,a[r+1]-a[r]-(o&1)*h)+dfs(l,r-1,o&2));
	int L=gl[r],R=gr[l];
	ans+=(L<=l)?(p*0.5*(a[r]-a[l]+min(h,a[l]-a[l-1]-((o>>1)&1)*h))):(p*0.5*(a[r]-a[L]+h+dfs(l,L-1,o|1)));
	ans+=(R>=r)?((1-p)*0.5*(a[r]-a[l]+min(h,a[r+1]-a[r]-(o&1)*h))):((1-p)*0.5*(a[R]-a[l]+h+dfs(R+1,r,o|2)));
	return ans;
}
