struct point{
	long double x,y;
	long double cos;
	int num;
	point(){}
	point ( double _x , double _y ){
		x = _x ; y = _y ;
	}
	point operator - ( const point &b) const   //向量a->b 
	{
		return point( x - b.x ,y - b.y  );
	}
	long double  operator ^ ( const point &b) const  //叉乘 ( 叉乘>0 逆时针 ，叉乘 <0 顺时针 ，叉乘=0 共线 ) 
	{
		return    x * b.y  -  y * b.x    ;
	}
	long double operator * ( const point &b) const  //点乘 
	{
		return    x * b.x   +   y * b.y  ;
	}
	point operator  / ( const double &k)
	{
		return point(x/k,y/k);
	}
	long double len()
	{
		return sqrt(x*x+y*y);
	}
	
	long double rad(point a){   //余弦定理 ∠aob 
		point p = *this;
		return acos(   a*p   /(p.len() * a.len())   );
	    
	}
	
};
const int MAXN =100009;
point p[MAXN]; 

void v(point& q)
{
