int seen[405];
void bfs_rail(int x) {
	fila.push(x);
	int aux = 1;
	seen[x] = aux;
	while (!fila.empty()) {
		int a = fila.front();
		aux = seen[a] + 1;
		for (it = rail[a].begin(); it != rail[a].end(); ++it) {
			if (!seen[*it]) {
				fila.push(*it);
				seen[*it] = aux;
			}
		}
		fila.pop();
	}
}

void bfs_road(int x) {
	fila.push(x);
	int aux = 1;
	seen[x] = aux;
	while (!fila.empty()) {
		int a = fila.front();
		aux = seen[a]+1;
		for (it = road[a].begin(); it != road[a].end(); ++it) {
			if (!seen[*it]) {
				fila.push(*it);
				seen[*it] = aux;
			}
		}
		fila.pop();
	}
}



