void build(int n){
	
	naj[2] = 1;
	for ( int i = 3; i <= n; i++ )
	{
		naj[i] = naj[i-1];
		if ( (1 << (naj[i]+1) ) <= i )
			naj[i]++;
	}
	
	for ( int i = 0; i < n; i++ )
	{
		sp_table[0][i] = i;
		//printf("%d ", sp_table[0][i]);
	}
	
	//printf("\n");
	
	for ( int i = 1; i <= naj[n]; i++ )
	{
		int k = (1 << i);
		for ( int j = 0; j + k-1 < n; j++ )
		{
			sp_table[i][j] = array[sp_table[i-1][j]] > array[sp_table[i-1][j+(1<<(i-1))]] ? sp_table[i-1][j] : sp_table[i-1][j + (1<<(i-1))];
			//printf("%d ", sp_table[i][j]);
		}
		
		//printf("\n");
	}
	
	
}

unsigned long long query(int l, int r){
	
	//printf("query l=%d r=%d\n", l, r);
	
	if ( l >= r )
		return 0;
	
