            b[x]+=a[x]*p[x][u]*m[u];
            a[x]*=(1-p[x][u]);
        }
        for (x=1;x<=n;x++)
		{
            if (visited[x])
				continue;
            if (dcmp(1-a[x])==0)
				m[x]=1e30;
            else
                m[x]=b[x]/(1-a[x]);
        }
    }
    printf("%.12lf\n",m[1]);
    return 0;
}

