void relabel(int n)
{
	static pair<ld,int> sav[maxn * 2];
	int tot = 0;
	for(int i = 0;i < n;i ++) sav[tot ++] = make_pair(la[i],i << 1),sav[tot ++] = make_pair(ra[i],i << 1 | 1);
	sort(sav,sav + tot);
	ld lv;int cnt = 0;
	for(int i = 0;i < tot;i ++)
	{
		if (!i) ++ cnt,lv = sav[i].fe; else
			if (sav[i].fe != lv) ++ cnt,lv = sav[i].fe;
		if (sav[i].se & 1) r[sav[i].se >> 1].fe.se = cnt; else
			r[sav[i].se >> 1].fe.fe = cnt;
	}
}

