node crossing(int i,int j)
{
	ld x = (l[i].y - l[j].y) / (l[j].x - l[i].x),y = l[i].x * x + l[i].y;
	return node(x,y);
}

void build(int l,int r,int jd)
{
	sa[jd].clear();
	if (l == r) return;
	int mid = l + r >> 1;
	build(l,mid,jd << 1),build(mid + 1,r,jd << 1 | 1);
}

void push(int l,int r,int p,int v,int jd)
{
	sa[jd].push_back(v);
	if (l == r) return;
	int mid = l + r >> 1;
	if (p <= mid) push(l,mid,p,v,jd << 1); else push(mid + 1,r,p,v,jd << 1 | 1);
}

double query(int l,int r,int ref,int i,int j,int jd)
{
	if (!sa[jd].size() || j < l || i > r || i > j) return 0;
	if (i <= l && r <= j)
	{
		double tmp = 0;
		for(auto p : sa[jd]) tmp += (crossing(ref,p) - o).len();
		return tmp;
	}
	int mid = l + r >> 1;
	return query(l,mid,ref,i,j,jd << 1) + query(mid + 1,r,ref,i,j,jd << 1 | 1);
}

