			if (tmp >= m) return m;
		}
		for(;i < j;i ++) add(r[i].fe.se);
	}
	return tmp;
}

ld count_all(int n)
{
	ld tmp = 0;
	build(1,2 * n,1);
	for(int i = 0;i < n;)
	{
		int j = i;
		for(;j < n && r[i].fe.fe == r[j].fe.fe;j ++) tmp += query(1,2 * n,r[j].se,r[j].fe.fe + 1,r[j].fe.se - 1,1);
		for(;i < j;i ++) push(1,2 * n,r[i].fe.se,r[i].se,1);
	}
	return tmp;
}

ld calc(bool ty,ld rr)
{
	int tot = 0;
	for(int i = 0;i < n;i ++)
		if (dis[i] <= rr) 
		{
			ld ang_a,ang_b;
			if (dis[i] == 0)
			{
				ang_a = atan2l(l[i].x,1),ang_b = ang_a + PI;
			} else
			{
				ld alpha = acosl(dis[i] / rr);
				ang_a = ang[i] + alpha,ang_b = ang[i] - alpha;
			}
			la[tot ++] = treat(ang_a),ra[tot - 1] = treat(ang_b);
			if (la[tot - 1] > ra[tot - 1]) swap(la[tot - 1],ra[tot - 1]);
			r[tot - 1].se = i;
		}
	relabel(tot);
	sort(r,r + tot);
	if (!ty) return count_number(tot);
	return count_all(tot);
}	

