	}
	else
	{
		int mid=(st+end)>>1;
		initialize(nod<<1,st,mid);
		initialize((nod<<1)+1,mid+1,end);
		tree[nod]=max(tree[nod<<1],tree[(nod<<1)+1]);
	}
}
inline void update(int nod,int st,int end,int pos,ll val)
{
	if(pos>end||pos<st)
	{
		return;
	}
	else if(pos==st&&st==end)
	{
		tree[nod]=val;
	}
	else
	{
		int mid=(st+end)>>1;
		update(nod<<1,st,mid,pos,val);
		update((nod<<1)+1,mid+1,end,pos,val);
		tree[nod]=max(tree[nod<<1],tree[(nod<<1)+1]);
	}
}
inline int query(int nod,int st,int end,int r,ll x)
{
	if(st==end)
