			return -1;
		}
		else
		{
			return st;
		}
	}
	if(tree[nod]<x)
	{
		return -1;
	}
	int mid=(st+end)>>1;
	if(r<mid+1)
	{
		return query(nod<<1,st,mid,r,x);
	}
	else
	{
		if(tree[nod<<1]<x)
		{
			return query((nod<<1)+1,mid+1,end,r,x);
		}
		else
		{
			return query(nod<<1,st,mid,r,x);
		}
	}
}
