int letsMove ( int *usb, int size, int steps) {

	sort ( usb, usb+size);
	int moves = 0, total = 0;
	for ( int i=size-1; i>=0; i --) {
		moves ++;
		total += usb[i];

		if (total >= steps)
			break;
	}

	return moves;
}

