ll add(ll a, ll b) { a += b; if(a >= mod) a -= mod; if(a < 0) a += mod; return a;}
ll n, m, k;
string S;
struct node{
    ll lazy, s, e;
    ll c[12][12];
    node(ll _lazy = -1, ll _s = 0, ll _e = 0)
    {
        lazy = _lazy;
        s = _s;
        e = _e;
        memset(c, 0, sizeof(c));
    }
}st[4 * N];
node merge(node x, node y)
{
    node ret = node();
    f(i, k) f(j, k) ret.c[i][j] = x.c[i][j] + y.c[i][j];
    ret.s = x.s;
    ret.e = y.e;
    ret.c[x.e][y.s]++;
    return ret;
}
void build(ll id, ll s, ll e)
{
    if(s == e)
    {
        st[id] = node(-1, (ll)(S[s] - 'a'), (ll)(S[s] - 'a'));
        return;
    }
    ll m = (s + e) >> 1;
    build(id + id, s, m);
    build(id + id + 1, m + 1, e);
    st[id] = merge(st[id + id], st[id + id + 1]);
}
void push(ll id, ll s, ll e)
{
    ll x = st[id].lazy;
    if(x == -1) return;
    f(i, k) f(j, k) st[id].c[i][j] = 0;
    st[id].c[x][x] = e - s;
    st[id].s = st[id].e = x;
    if(s != e)
    {
		st[id + id].lazy = x;
		st[id + id + 1].lazy = x;
	}
	st[id].lazy = -1;
}
void update(ll id, ll s, ll e, ll l, ll r, ll v)
{
    push(id, s, e);
    if(s > e || s > r || l > e) return ;
    if(l <= s && e <= r)
    {
        st[id].lazy = v;
        push(id, s, e);
        return ;
    }
    ll m = (s + e) >> 1;
    update(id + id, s, m, l, r, v);
    update(id + id + 1, m + 1, e, l, r, v);
    st[id] = merge(st[id + id], st[id + id + 1]);
}
