	FOR(i,1,n){
		REP(j,i)if(str[j+1]!='0'){
			int s=i-j,p=0;
			if(j+1>=s){
				int a=j+1-s,b=i+1-s;
				int x=sa.as[a],y=sa.as[b];
				if(x>y)swap(x,y);
				int k=st.GetMin(x,y);
				if(k<s&&str[a+k]<str[b+k])
					p=a;
				else
					p=a+1;
			}
			Add(dp[i][j+1],dp[j][p]);
		}
		for(int j=i-1;j>=0;j--)
			Add(dp[i][j],dp[i][j+1]);
	}
	cout<<dp[n-1][0]<<endl;
}

