inline int solve(int a, int b, int c, int ac, int bc, int abc) {
  int res = abc;
  {
    res += bc;
    a = max(a - bc, 0);
  }
  {
    res += ac;
    int take = min(b, ac);
    b -= take;
    ac -= take;
    a = max(a - ac, 0);
  }
  res += max(c, max((b + c + 1) / 2, (a + b + c + 2) / 3));
  return res;
}

