vector <long long> get(char forw, char backw, int bound) {
  vector <long long> res;
  int x = 0, xl = 0, xr = 0;
  for (int i = 0; i < n; i++) {
    if (s[i] == forw) {
      x++;
      if (x > xr) {
        xr = x;
        res.push_back(i);
      }
    }
    if (s[i] == backw) {
      x--;
      if (x < xl) {
        xl = x;
        res.push_back(i);
      }
    }
  }
  // loop ones?
  {
    vector <long long> loop;
    for (int i = 0; i < n; i++) {
      if (s[i] == forw) {
        x++;
        if (x > xr) {
          xr = x;
          loop.push_back(i);
        }
      }
      if (s[i] == backw) {
        x--;
        if (x < xl) {
          xl = x;
          loop.push_back(i);
        }
      }
    }
    if (!loop.empty()) {
      while (res.size() < bound) {
        for (int i = 0; i < (int) loop.size(); i++) {
          loop[i] += n;
          res.push_back(loop[i]);
        }
      }
    }
