struct point{
    double x,y ;
    point(double x=0,double y=0):x(x),y(y){}
    double det(point p){
        return x*p.y-y*p.x;
    }
    double dis2(point p){
        return (x-p.x)*(x-p.x)+(y-p.y)*(y-p.y);
    }
    void show(){
        cout<<x<<" "<<y<<endl;
    }
};
point operator +(point a,point b){return point(a.x+b.x,a.y+b.y);}
point operator -(point a,point b){return point(a.x-b.x,a.y-b.y);}
point operator *(point a,double k){return point(a.x*k,a.y*k);}
point operator /(point a,double k){return point(a.x/k,a.y/k);}
struct line{
    point a,b;
    line(point a=point(0,0),point b=point(0,0)):a(a),b(b){}
    point intersect(line l){
        double s1=(b-a).det(l.a-a);
        double s2=(b-a).det(l.b-a);
        return (l.a*s2-l.b*s1)/(s2-s1);
    }
    line vertical(point p){
        return line(p,p+point(b.y-a.y,a.x-b.x));
    }
    int include(point p){
        return sign((b.x-p.x)*(p.x-a.x))>=0 && sign((b.y-p.y)*(p.y-a.y))>=0;
    }
};
