//vector<bool> sei(MAXN + 5,0);
long long fact[MAXN+3];

bool comp(const pii &a,const pii &b)
{
	if(a.se <= b.se)
		return true;
	return false;
}

void init()
{
	fact[0] = fact[1] = 1;
	for(long long i = 2;i<=MAXN;i++)
	{
		fact[i] = fact[i-1]*i;
	}
}
int bitC(long long a)
{
	int bits = 0;
	while(a)
	{
		++bits;
		a>>=1;
	}
	return bits;
}

long long power(long long a,long long b)
{
	//cout<<a<<endl;
	long long ans = 1;
	while(b)
	{
		if(b&1)
		{
			//cout<<bitC(ans) + bitC(a)<<endl;
			if(bitC(ans) + bitC(a) >= 64)
			{
				return -1;
			}
			//cout<<(ans*1ll*a)<<endl;
			ans = (ans*1ll*a)%MOD;
		}
		//cout<<ans<<" "<<b<<endl;
		a = (a*1ll*a)%MOD;
		//cout<<a<<endl;
		//cout<<"1."<<a<<endl;
		b = b/2;
	}
	//cout<<ans<<endl;
	return ans;
}

double C(int a,int b)
{
	double ans = 1;
	if(a < b)
		return 0;

	ans *= fact[a];
	ans /= fact[b];
	ans /= fact[a-b];
	return ans;
}

