using namespace std;

typedef long long ll;

const ll MOD = 1e9 + 7;

inline ll power(ll base, ll exp) {
	ll ans = 1;
	
	base %= MOD;

	while (exp > 0) {
		if (exp & 1) ans = (ans * base) % MOD;
		exp >>= 1;
		base = (base * base) % MOD;
	}

	return ans;
}

int main() {
	int m, p;
	ll cnt, f, d = 1, ans = 1;
	map<int, int> frq;
	scanf("%d", &m);
	
	while (m--) {
		scanf("%d", &p);
		frq[p]++;
	}

	for (auto a : frq) {
		p = a.first;
		cnt = a.second;
		f = power(p, (cnt + 1) * cnt / 2);
		ans = (power(ans, (cnt + 1)) * power(f, d)) % MOD;
		d = (d * (cnt + 1)) % (MOD - 1);
	}

	printf("%lld", ans);
	return 0;
}

