void check(int i,int j,int cnt,int r,int c){
	if(mark[i][j]!=cnt && in[i][j]=='.' && i<=n && j<=m && i>=1 && j>=1){
		dfs(i,j,cnt,r,c);
	}
}
void dfs(int i,int j,int cnt,int rs,int cs){
	mark[i][j]=cnt;
	ans[(rs-1)*m+cs]++;
	check(i+1,j,cnt,rs,cs);
	check(i,j+1,cnt,rs,cs);
	check(i-1,j,cnt,rs,cs);
	check(i,j-1,cnt,rs,cs);
}
void checka(int i,int j,int cnt,int &temp){
	if(mark2[mark[i][j]]!=cnt && in[i][j]!='*' && i>=1 && j>=1 && i<=n && j<=m){
		mark2[mark[i][j]]=cnt;
		temp+=ans[mark[i][j]];
	}
}
