typedef long long ll;
typedef vector<int> vi;
typedef pair<int, int> ii;
const double EPS = 1e-15, PI = acos(-1);
const int MOD = int(1e9) + 7, MX = int(1e3) + 1;

const int N = int(1e6);
vector<vi> Adj;
vector<int> color, tour, vis;
ll T[N<<2], L[N<<2];
int F[N], E[N];
int n, m, ln;

void build(int l = 0, int r = ln - 1, int p = 1) {
  if(l == r) {
    T[p] = 1LL<<color[tour[l]];
    return;
  }
  int md = (l + r) / 2, ch = p<<1;
  build(l, md, ch);
  build(md+1, r, ch|1);
  T[p] = T[ch] | T[ch|1];
}

void update(int x, int y, int v, int l = 0, int r = ln - 1, int p = 1) {
  int md = (l + r) / 2, ch = p<<1;
  if(L[p]) {
    T[p] = L[p];
    if(l != r) L[ch] = L[ch|1] = L[p];
    L[p] = 0;
  }
  if(l > y || r < x) return;
  if(x <= l && r <= y) {
    T[p] = 1LL<<v;
    if(l != r) L[ch] = L[ch|1] = 1LL<<v;
    return;
  }
  update(x, y, v, l, md, ch);
  update(x, y, v, md+1, r, ch|1);
  T[p] = T[ch] | T[ch|1];
}

ll query(int x, int y, int l = 0, int r = ln - 1, int p = 1) {
  int md = (l + r) / 2, ch = p<<1;
  if(L[p]) {
    T[p] = L[p];
    if(l != r) L[ch] = L[ch|1] = L[p];
    L[p] = 0;
  }
  if(l > y || r < x) return 0LL;
  if(x <= l && r <= y) return T[p];
  return query(x, y, l, md, ch) | query(x, y, md+1, r, ch|1);
}

void dfs(int pr = 1) {
  tour.pb(pr);
  F[pr] = F[pr] == -1 ? SZ(tour) - 1 : F[pr];
  E[pr] = max(E[pr], SZ(tour) - 1);
  vis[pr] = 1;
  for(int ch: Adj[pr]) {
    if(vis[ch]) continue;
    dfs(ch);
  }
  tour.pb(pr);
  E[pr] = max(E[pr], SZ(tour) - 1);
} 

void solve() {
  scanf("%d %d", &n, &m);
  Adj.resize(n+1);
  color.resize(n+1);
  vis.assign(n+1, 0);
  for(int i = 1; i <= n; i++) scanf("%d", &color[i]);
  for(int i = 2; i <= n; i++) {
    int u, v; scanf("%d %d", &u, &v);
    Adj[u].pb(v);
    Adj[v].pb(u);
  }
  memset(F, -1, sizeof F);
  dfs();
  ln = SZ(tour);
  build();
  while(m--) {
    int t, x, y; scanf("%d %d", &t, &x);
    if(t == 1) {
      scanf("%d", &y);
      update(F[x], E[x], y);
    }else {
      printf("%d\n", __builtin_popcountll(query(F[x], E[x])));
    }
  }
}

