    int query(int k, int p, int q) {
        int v = 1;
        int r = 0;
        FORD(i,19,0) {
            int e = (((1<<i)&k) != 0);
            if(!(q < P[2*v+(!e)] or p > Q[2*v+(!e)])) {
                v = 2*v+(!e);
                r |= (1<<i);
            } else {
                v = 2*v+e;
            }
        }
        return r;
    }

    void update_result(int k, int p, int q) {
        update(&result, max(result, query(k, p, q)));
    }

    void rollback() {
        while(!S.empty()) {
            *(S.back().X) = S.back().Y;
            S.pop_back();
        }
    }

    void begin() {
        S.clear();
    }

    void update(int *Z, int v) {
        S.push_back({Z, *Z});
        *Z = v;
    }

};

void read_data() {
    scanf("%d %d", &N, &QS);
    FOR(i,1,N) scanf("%d", A+i);
    FOR(i,1,QS) scanf("%d %d", X+i, Y+i);
}

void insert(trie &T0, trie &T1, int i) {
    /*cout << "INSERT: " << A[i] << endl;
    cout << "T0 insert: " << F[A[i]] << endl;
    cout << "T1 insert: " << F[A[i]-1] << endl;*/
    T0.insert(F[A[i]], A[i]);
    T1.insert(F[A[i]-1], A[i]);
    T0.update_result(F[A[i]-1], A[i], INF);
    T1.update_result(F[A[i]], 0, A[i]);
}

void solve() {
    map<int, vector<pair<int, int>>> M;
    map<pair<int, int>, int> R;
    FOR(i,1,QS) M[X[i]/S].PB(MP(X[i], Y[i]));
    trie P, Q;
    for(auto &m: M) {
        vector<pair<int, int>> &queries = m.Y;
        sort(ALL(queries), [](pair<int, int> a, pair<int, int> b){
            return MP(a.Y, a.X) < MP(b.Y, b.X);
        });
        int l = -INF;
        for(auto q: queries) l = max(l, q.X);
        P.clear();
        Q.clear();
        int r = l-1;
        for(auto q: queries) if(q.Y - q.X <= S+3) {
            P.begin();
            Q.begin();
            FOR(i,q.X,q.Y)  insert(P, Q, i);
            R[q] = max(P.result, Q.result);
            P.rollback();
            Q.rollback();
        }
        for(auto q: queries) if(q.Y - q.X > S+3) {         
//          cout << "QUERY: " << q << endl;
            int temp_l = q.X;
            int new_r = q.Y;
            FOR(i,r+1,new_r) if(q.X <= i and i <= q.Y) insert(P, Q, i);
            P.begin();
            Q.begin();

            FORD(i,l-1,temp_l) if(q.X <= i and i <= q.Y)  insert(P, Q, i);
            R[q] = max(P.result, Q.result);
        //    cout << q << " " << R[q] << endl;

            P.rollback();
            Q.rollback();
            r = new_r;
//            cout << "L=" << l << " templ=" << temp_l << endl;
        }
    }
    FOR(i,1,QS) printf("%d\n", R[MP(X[i], Y[i])]);
}


int main() {
//    trie T;    T.insert(2); T.insert(3);T.rollback(); cout << T.query(4); exit(0);
    FORW(i,1,MAXW) F[i] = (F[i-1] ^ i);
    read_data();
    solve();
}

