  Matrix C(0);
  for(int i = 0; i < x; i++)
    for(int j = 0; j < x; j++)
      for(int k = 0; k < x; k++)
        C(i, j) = Add(C(i, j), Mult(A(i, k), B(k, j)));
  return C;
}


void Pot(Matrix &baza, Matrix &poc, int e){
  while(e){
    if(e & 1) poc = poc * baza;
    baza = baza * baza;
    e >>= 1;
  }
}

