typedef pair<int,int> pii;
typedef pair<int,pii> pip;
const int maxn = 5.4e5;
vector<int> g[maxn];
int solve(int u)
{
	queue<pip> q;
	q.push({1, pii(1,u)});
	int cntl = 0;
	int lastd = 0;
	while (q.size()) {
		int d = q.front().D;
		int p = q.front().U.P;
		int v = q.front().U.U;
		q.pop();
		if (g[v].size() > 1) {
			for (int i : g[v]) if (i != p)
				q.push({d+1, pii(v, i)});
		} else {
			++cntl;
			if (d > lastd) {
				int emp = d - lastd;
				cntl -= min(cntl, emp);
				lastd = d;
			}
		}
	}
	return lastd + cntl;
}
