void get_pri_tab(int x, vector<int> &v)
{
    int nn = x;
    int p = 1;
    while (pri[p]*pri[p] <= nn)
    {
        if (nn % pri[p]) p++;
        else
        {
            v.push_back(pri[p]);
            while (nn % pri[p] == 0) nn /= pri[p];
            p++;
        }
    }
    if (nn > 1)
        v.push_back(nn);
}
