        while (r<n && sq(x[r+1].X-x[l].X)<=k && abs(x[r+1].X)<=abs(x[l].X)) r+=1;
        while (abs(x[r].X)>abs(x[l].X)) r-=1;
        ll low = min(lmin[l-1],rmin[r+1]);
        ll high = max(lmax[l-1],rmax[r+1]);
        //debug({l,r});
        if (sq(high-low)<=k && sq(max(abs(low),abs(high)))+sq(abs(x[l].X))<=k) return true;
    }
    ll l = n;
    for(r=n;r>=1;r--) {
        if (x[r].X<0) break;
        while (l>1 && sq(x[r].X-x[l-1].X)<=k && abs(x[l-1].X)<=abs(x[r].X)) l-=1;
        while (abs(x[l].X)>abs(x[r].X)) l+=1;
        ll low = min(lmin[l-1],rmin[r+1]);
