using namespace std;

ll int a,b;

struct node{
	ll int pos,pre;
}tree[4*MAXN],def;

node merge(node l,node r){
	node ans;
	ans.pre=l.pre+r.pre;
	ans.pos=l.pos+r.pos;
	return ans;
}

void update(int ind,int val,int l,int r,int nde){
	if(l==r){
		tree[nde].pre=min(tree[nde].pre+val,b);
		tree[nde].pos=min(tree[nde].pos+val,a);
		return ;
	}
	int mid=(l+r)>>1;
	if(ind>=l && ind<=mid)
		update(ind,val,l,mid,nde<<1);
	else
		update(ind,val,mid+1,r,nde<<1|1);
	tree[nde]=merge(tree[nde<<1],tree[nde<<1|1]);
}

node query(int x,int y,int l,int r,int nde){
	if(l>y ||r<x || x>y)
		return def;
	else if(l>=x && r<=y)
		return tree[nde];
	int mid=(l+r)>>1;
	node n1,n2;
	n1=query(x,y,l,mid,nde<<1);
	n2=query(x,y,mid+1,r,nde<<1|1);
	return merge(n1,n2);
}

