inline void add_edge(int x, int y)
{
	e[en] = edge(y, st[x]), st[x] = en++;
}

int n;

int dep[maxn + 5], fa[maxn + 5];

int dfs_tot = 0;
int dfn[maxn + 5], End[maxn + 5];

void dfs(int x, int f = -1)
{
	if (~f) dep[x] = dep[f] + 1;
	else dep[x] = 0;
	dfn[x] = dfs_tot++;
	fa[x] = f;
	for (int i = st[x]; i != -1; i = e[i].nxt)
	{
		int y = e[i].id;
		if (y == f) continue;
		dfs(y, x);
	}
	End[x] = dfs_tot;
}

