const int N = 1e5 + 1000;
int n;
vector<pair<ll, int>> a;
ll t[N * 4], dp[N];

void update(int idx, ll val, int s = 0, int e = n, int i = 0) {
    if (idx < s || idx > e) {
        return;
    }
    if (s == e && idx == s) {
        t[i] = dp[s] = val;
        return;
    }
    int m = (s + e) / 2, l = i * 2 + 1, r = i * 2 + 2;
    update(idx, val, s, m, l);
    update(idx, val, m + 1, e, r);
    t[i] = max(t[l], t[r]);
}

ll get(int qr, int ql = 0, int s = 0, int e = n, int i = 0) {
    if (s > qr || e < ql) {
        return 0;
    }
    if (s >= ql && e <= qr) {
        return t[i];
    }
    int m = (s + e) / 2, l = i * 2 + 1, r = i * 2 + 2;
    return max(get(qr, ql, s, m, l), get(qr, ql, m + 1, e, r));
}

int main() {
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        int r, h;
        scanf("%d %d", &r, &h);
        a.push_back(make_pair((ll)r * r * h, -i));
    }
    sort(a.begin(), a.end());
    for (int i = 0; i < n; i++) {
        int idx = -a[i].second;
        ll val = a[i].first;
        dp[idx] = val + get(idx);
        update(idx, dp[idx]);
    }
    printf("%.15f\n", PI * get(n - 1));
    return 0;
}

