	r.pb(p+v.rot(PI/2)*c/2-v*d);
	r.pb(p-v.rot(PI/2)*c/2-v*d);
	r.pb(p-v.rot(PI/2)*c/2);
	r.pb(p-v.rot(PI/2)*a/2);
	for(pt w:r)printf("%.12lf %.12lf\n",w.x,w.y);
