struct line {
  long a, b; 
  line () {}
  line (long a, long b) : a(a), b(b) {}
  long get (long x) { return a * x + b; }
}; 


/// intersection : l2.b - l1.b / l1.a - l2.a;
int N; 
long a[NX];
long sum[NX];
struct convex_hull {
  vector <line> hull;

  bool bad (line l1, line l2, line l3) {
    return (l3.b - l1.b) * (l1.a - l2.a) <= (l2.b - l1.b) * (l1.a - l3.a); 
  }

  #define l1 hull[hull.size() - 2]
  #define l2 hull[hull.size() - 1] 
  convex_hull () { hull.clear(); }
  
  void insert (line l3) {
    while (hull.size() >= 2 && bad(l1, l2, l3)) hull.pop_back();
    hull.push_back(l3);
  }
  
  long query (long x) {
    int low = -1, high = hull.size() - 1; 
    while (high - low > 1) {
      int mid = (low + high) / 2;
      if (hull[mid].get(x) <= hull[mid + 1].get(x)) {
        low = mid; 
      } 
      else high = mid; 
    }
    return hull[high].get(x);
  }
} hull; 



