  }
  long res = 0; 
  for (int RR = 2; RR <= N; RR++) {
    hull.insert(line(RR - 1, -sum[RR - 2]));
    res = max (res, hull.query(a[RR]) + sum[RR - 1] - 1LL * a[RR] * RR);
  }
  hull = convex_hull();
  for (int LL = N - 1; LL >= 1; LL--) {
    hull.insert(line(-(LL + 1), -sum[(LL + 1)]));
    res = max (res, hull.query(-a[LL]) + sum[LL] - 1LL * a[LL] * LL);
  }
  for (int i = 1; i <= N; i++) {
    res += 1LL * a[i] * i; 
  }
