typedef complex<double> base;

int rev(int x, int n)
{
	int res = 0;
	FOR(i, 0, n)
	{
		if (x & (1 << i)) res += 1 << (n - i - 1);
	}

	return res;
}

void fft(vector<base>& a, bool inverse)
{
	int n = 0;
	while ((1 << n) < SZ(a)) n++;

	FOR(i, 0, SZ(a))
	{
		if (i < rev(i, n)) swap(a[i], a[rev(i, n)]);
	}

	for (int len = 2; len <= SZ(a); len *= 2)
	{
		double angle = 2 * PI / len;
		if (inverse) angle = -angle;
		base wn(cos(angle), sin(angle));

		for (int i = 0; i < SZ(a); i += len)
		{
			base w = 1;
			FOR(j, 0, len/2)
			{
				base u = a[i + j];
				base v = a[i + j + len / 2] * w;
				a[i + j] = u + v;
				a[i + j + len / 2] = u - v;
				w *= wn;
			}
		}
	}
	

	if (inverse)
	{
		FOR(i, 0, SZ(a))
		{
			a[i] /= SZ(a);
		}
	}
}

vector<int> multiply(vector<int>& a, vector<int>& b)
{
	vector<base> A(ALL(a));
	vector<base> B(ALL(b));
	int n = 1;
	while (n < max(SZ(A), SZ(B)))
	{
		n *= 2;
	}
	n *= 2;
	A.resize(n);
	B.resize(n);

	fft(A, 0);
	fft(B, 0);
	FOR(i, 0, n)
	{
		A[i] *= B[i];
	}

	fft(A, 1);
	vector<int> res(n);;
	FOR(i, 0, n)
	{
		res[i] = A[i].real() + 0.5;
	}
	while (res.back() == 0) res.pop_back();
	FOR(i, 0, SZ(res))
	{
		if (res[i] != 0) res[i] = 1;
	}

	return res;
}

