        M1[B[i]] = A[i];
        addWord(B[i],0,0);
    }
    dp[S.length()]=1;
    ll i ;
    
    for(i=S.length()-1;i>=0;--i)
    {
        dp[i] = 0 ;
        
        int root = 0 ,j = i ;
        
        while(1)
        {
            if(!Trie[root].Next[S[j]-'a'])
                break;
            else
                root = Trie[root].Next[S[j]-'a'];
            
            if(Trie[root].exist)
                if(dp[j+1])
                {
                    dp[i] = 1;
                    pi[i] = j+1;
                    break;
                }
            ++j;
        }
    }
    i = 0;
    while(i!=S.length())
    {
        //        cout<<S.substr(i,pi[i]-i)<<"\n";
        cout<<M1[S.substr(i,pi[i]-i)]<<" ";
        i = pi[i];
    }
    return 0;
}

