				if(dp_down[v]>dp_down[id1])id2=id1,id1=v;
				else if(dp_down[v]>dp_down[id2])id2=v;	
			}
			else sum+=dp_down[v];
		}
	for(auto v:e[x])
		if(v!=par && !mark[v])
		{
			block_up[v]=(block_num>=2 || (block_num==1 && id!=v));
			if(block_down[v])
