                p = nxt[p];
                continue;
            }
            int l = p, r = n + 1;
            while (l + 1 < r) {
                int c = (l + r) / 2;
                if (a[c].first <= a[p].first + vol) {
                    l = c;
                } else {
                    r = c;
                }
            }
            if (p == l) {
