#define FORR(i,f,t) for(int i=f;i>(int)t;i--)

typedef long long ll;
typedef vector<int> vi;
typedef vector<pair<int,int> > vpii;

const int MAXM=2*1e5+1000;

bool possible=true;
ll ans=0;
int D,N,M,MM,A[MAXM],cur=0,gas;
vi dist;
vpii V;

struct STN{
	int x;
	void merge(STN& L, STN& R){
		if(A[L.x] <= A[R.x]) x=L.x;
		else x=R.x;
	}
	void operator=(int a){x=a;}
};

STN ST[4*MAXM];
void STB(int id = 1,int l = 0,int r = MM){
	if(r - l < 2){
		ST[id] = l;
		return;
	}
	int M = (l+r)>>1, L=id<<1, R=L|1;
	STB(L, l, M); STB(R, M, r);
	ST[id].merge(ST[L],ST[R]);
}

STN STQ(int x,int y,int id = 1,int l = 0,int r = MM){
	if(x>=y) return {-1};
	if(x == l && y == r)	return ST[id];
	int M = (l+r)>>1, L=id<<1, R=L|1;
	if(x>=M)	return STQ(x,y,R,M,r);
	if(y<=M)	return STQ(x,y,L,l,M);
	STN res,ln=STQ(x, M, L, l, M),rn=STQ(M, y, R, M, r);
	return res.merge(ln, rn), res;
}

int main() {
	ri(D);
	rii(N,M);
	FOR(i,0,M) {
		int x,p;
		rii(x,p);
		V.pb({x,p});
	}
	V.pb({0,0});
	V.pb({D,0});
	sort(V.begin(),V.end());
	M+=2;
	FOR(i,0,M) A[i]=V[i].second;
	FOR(i,0,M) dist.pb(V[i].first);
	gas=N;
	MM=M;
	STB();
	while(dist[cur]!=D && possible) {
		int lim=upper_bound(dist.begin(), dist.end(), dist[cur]+N) - dist.begin();
		int nxt=STQ(cur+1,lim).x;
		if(nxt==-1) possible=false;
		else if(A[nxt] <= A[cur]) {
			nxt=cur+1;
			while(A[nxt] > A[cur]) nxt++;
			gas-=dist[nxt]-dist[cur];
			if(gas<0) {
				ans+=1ll*abs(gas)*A[cur];				
				gas=0;
			}
			cur=nxt;
		} else {
			ans+=1ll*(N-gas)*A[cur];
			gas=N;
			gas-=dist[cur+1]-dist[cur];
			cur++;
		}
	}
	printf("%lld\n",possible?ans:-1);
}

