	inline Graph() { cnt = 1; }
	inline void insert(int u, int v) { nxt[++cnt] = head[u]; to[cnt] = v; head[u] = cnt; }
} G, T;

int bcc[MAXN], pre[MAXN], dfs_clock, bcc_cnt, st[MAXN], top;
inline int Tarjan(int u, int rev) {
	int lowu = pre[u] = ++dfs_clock;
	st[++top] = u;
	for(Int v, i = G.head[u]; i; i = G.nxt[i]) {
		if(i == rev) continue;
		v = G.to[i];
		if(!pre[v]) lowu = min(lowu, Tarjan(v, i ^ 1));
		else lowu = min(lowu, pre[v]);
	}
	if(lowu == pre[u]) {
		Int v; ++bcc_cnt;
		do bcc[v = st[top--]] = bcc_cnt; while(v != u);
	}
	return lowu;
}

int dfn[MAXN], dep[MAXN], idx, f[MAXN][24];
inline void dfs(int u, int fa) {
	dfn[u] = ++idx;
	for(Int v, i = T.head[u]; i; i = T.nxt[i]) {
		if((v = T.to[i]) == fa) continue;
		dep[v] = dep[u] + 1;
		f[v][0] = u;
		dfs(v, u);
	}
}

inline int get_lca(int u, int v) {
	if(dep[u] < dep[v]) swap(u, v);
	int t = dep[u] - dep[v];
	for(Int k = 0; t; ++k, t >>= 1)
		if(t & 1) u = f[u][k];
	if(u == v) return u;
	for(Int k = 20; k >= 0; --k)
		if(f[u][k] != f[v][k]) {
			u = f[u][k];
			v = f[v][k];
		}
	return f[u][0];
}

