const double EPS = 1e-7;

void solve(int i, int l, int r, int optl, int optr) {
    int mid = (l + r) / 2;
    int optm = 0;
    FOR (j, optl, optr + 1) {
        if (dp[i][mid] + EPS > dp[i - 1][j] + get(j + 1, mid)) {
            dp[i][mid] = dp[i - 1][j] + get(j + 1, mid);
            optm = j;
        }
    }
    if (l <= mid - 1) {
        solve(i, l, mid - 1, optl, optm);
    }
    if (mid + 1 <= r) {
        solve(i, mid + 1, r, optm, optr);
    }
}

