struct SegmentTree
{
    int n;
    vector<int> tree;

    void build(int v, int l, int r)
    {
        if (l == r)
        {
            tree[v] = -1;
        }
        else
        {
            build(v * 2, l, (l + r) / 2);
            build(v * 2 + 1, (l + r) / 2 + 1, r);
            tree[v] = tree[v * 2] + tree[v * 2 + 1];
        }
    }

    SegmentTree(int n)
    {
        this->n = n;
        tree.resize(4 * n);
        build(1, 0, n - 1);
    }

    void change(int v, int l, int r, int pos, int val)
    {
        if (l == r)
        {
            tree[v] = val;
        }
        else
        {
            if (pos <= (l + r) / 2)
                change(v * 2, l, (l + r) / 2, pos, val);
            else
                change(v * 2 + 1, (l + r) / 2 + 1, r, pos, val);
            tree[v] = max(tree[v * 2], tree[v * 2 + 1]);
        }
    }

    int get(int v, int l, int r, int L, int R)
    {
        if (r < L || R < l)
            return 0;
        if (l >= L && r <= R)
            return tree[v];
        return max(
                   get(v * 2, l, (l + r) / 2, L, R),
                   get(v * 2 + 1, (l + r) / 2 + 1, r, L, R)
               );
    }

    void change(int pos, int val)
    {
        change(1, 0, n - 1, pos, val);
    }

    int get(int l, int r)
    {
        if (l > r)
            return 0;
        return get(1, 0, n - 1, l, r);
    }
};

vector<int> startAns;

int calc()
{
    vector<int> left;
    left.resize(n);
    vector<int> right;
    right.resize(n);
    startAns.resize(n);

    SegmentTree tree(zipMap.size());
    map<int, int> uniqueLeft;
    for (int i = 0; i < n; i++)
    {
        left[i] = tree.get(0, ms[i] - 1);
        tree.change(ms[i], left[i] + 1);
    }

    tree = SegmentTree(zipMap.size());
    map<int, int> uniqueRight;
    for (int i = n - 1; i >= 0; i--)
    {
        right[i] = tree.get(ms[i] + 1, zipMap.size() - 1);
        tree.change(ms[i], right[i] + 1);
    }

    int ans = 0;
    for (int i = 0; i < n; i++)
        ans = max(ans, left[i] + right[i] + 1);

    fill(startAns.begin(), startAns.end(), ans - 1);

    for (int i = 0; i < n; i++)
    {
        if (left[i] + right[i] + 1 == ans)
        {
            uniqueLeft[left[i]]++;
            uniqueRight[right[i]]++;
        }
    }

    for (int i = 0; i < n; i++)
    {
        if (left[i] + right[i] + 1 == ans)
        {
            if (uniqueLeft[left[i]] == 1 || uniqueRight[right[i]] == 1)
                startAns[i] = ans - 1;
            else
                startAns[i] = ans;
        }
        else
        {
            startAns[i] = ans;
        }
    }

    return ans;
}

void precalcAns()
{
    precalc.resize(m);
    vint precLeft;
    rs(precLeft, m);
    vint precRight;
    rs(precRight, m);
    vint left;
    rs(left, n);
    vint right;
    rs(right, n);

    vector<pii> vec;
    for (int i = 0; i < m; i++)
        vec.push_back(mkp(as[i], i));
    sort(vec.begin(), vec.end());
    vint sorted;
    for (int i = 0; i < m; i++)
        sorted.push_back(vec[i].second);

    int cur = 0;
    SegmentTree tree(zipMap.size());
    for (int i = 0; i < n; i++)
    {
        left[i] = tree.get(0, ms[i] - 1);
        while (cur < m && as[sorted[cur]] == i)
        {
            precLeft[sorted[cur]] = tree.get(0, bs[sorted[cur]] - 1);
            cur++;
        }
        tree.change(ms[i], left[i] + 1);
    }


    cur = m - 1;
    tree = SegmentTree(zipMap.size());
    for (int i = n - 1; i >= 0; i--)
    {
        right[i] = tree.get(ms[i] + 1, zipMap.size() - 1);
        while (cur >= 0 && as[sorted[cur]] == i)
        {
            precRight[sorted[cur]] = tree.get(bs[sorted[cur]] + 1, zipMap.size() - 1);
            cur--;
        }
        tree.change(ms[i], right[i] + 1);
    }

    for (int i = 0; i < m; i++)
    {
        precalc[i] = precLeft[i] + precRight[i] + 1;
    }
}

int find(int v)
{
    return precalc[v];
}

int main()
