const int MAXN = 500005;
int n, ans, f[MAXN];
struct Graph {
	int fa[MAXN], head[MAXN], nxt[MAXN << 1], to[MAXN << 1], cnt;
	inline void insert(int u, int v) { nxt[++cnt] = head[u]; to[cnt] = v; head[u] = cnt; }
} G, T;

struct edge { int a, b, c, d; } e[MAXN];

inline void dfs(Graph& U, int u) {
	for(Int v, i = U.head[u]; i; i = U.nxt[i]) {
		if((v = U.to[i]) == U.fa[u]) continue;
		U.fa[v] = u;
		dfs(U, v);
	}
}

inline int find(int x) { return f[x] == x ? x : f[x] = find(f[x]); }
inline bool check(int u, int v) { return u && v && (G.fa[u] == v || G.fa[v] == u); }

inline void solve(int u) {
	for(Int v, i = G.head[u]; i; i = G.nxt[i]) {
		if((v = G.to[i]) == G.fa[u]) continue;
		solve(v);
		if(find(u) == find(v)) continue;
		e[++ans] = (edge) { u, v, find(v), T.fa[find(v)] };
	}
}

