		scanf("%d%d", &u, &v);
		T.insert(u, v); T.insert(v, u);
	}
	dfs(T, 1);
	
	for(Int i = 1; i <= n; ++i)
		f[i] = check(i, T.fa[i]) ? T.fa[i] : i;
	
