const int MAXN = 100100;
const double EPS = 1E-8;
const double PI = 3.1415926535897932384626433832795;
int N, A;
double X[MAXN];
double Y[MAXN];
double P[MAXN];
double Q[MAXN];
double theta[MAXN];
pair<double, int> ang[2*MAXN];
int T[MAXN];

bool check(double d)
{
    int sz = 0;
    for (int i = 0; i < N; i++)
    {
        double cosalpha = (Q[i]*Q[i] + d*d - P[i]*P[i])/(2*Q[i]*d);
        if (fabs(cosalpha) > 1 + EPS)
            continue;
        cosalpha = min(max(cosalpha, -1.0), 1.0);
        double alpha = acos(cosalpha);
        double a = theta[i] - alpha, b = theta[i] + alpha;
        if (a < 0)
            a += 2*PI;
        if (b < 0)
            b += 2*PI;

        ang[sz++] = make_pair(a, i);
        ang[sz++] = make_pair(b, i);
    }

    sort(ang, ang + sz);
    set<int> st;
    memset(T, -1, sizeof(T));
    for (int i = 0; i < sz; i++)
    {
        if (T[ang[i].second] == -1)
        {
            st.insert(i);
            T[ang[i].second] = i;
        }
        else
        {
            if (T[ang[i].second] != *(--st.end()))
                return true;
            st.erase(--st.end());
            T[ang[i].second] = -1;
        }
    }
    return false;
}

int main()
{
    ios::sync_with_stdio(0);

    cin >> N >> A;
    for (int i = 0; i < N; i++)
    {
        cin >> X[i] >> Y[i];
        P[i] = sqrt((X[i] - A)*(X[i] - A) + Y[i]*Y[i]);
        Q[i] = sqrt((X[i] + A)*(X[i] + A) + Y[i]*Y[i]);
        theta[i] = atan2(Y[i], X[i] + A);
    }

    double lo = 0, hi = 2*A;
    for (int i = 0; i < 100; i++)
    {
        double mid = (lo + hi)/2;
        if (check(mid))
            hi = mid;
        else
            lo = mid;
    }

    printf("%.10f\n", lo);

    return 0;
}

