const int MAXN = 2000005;
const int MOD = 1000000007;
int N, K, M;
string S;
int dp[MAXN][26];
int idx[26];

int main()
{
    ios::sync_with_stdio(0);

    cin >> N >> K >> S;
    M = S.size();

    ll total = 0;
    set<pair<int, int> > st;
    for (int i = 0; i < K; i++)
        st.insert(make_pair(0, i));

    for (int i = 1; i <= M; i++)
        for (int j = 0; j < K; j++)
        {
            if (S[i - 1] - 'a' == j)
            {
                dp[i][j] = (1 + total) % MOD;
                total = (total + total + 1 - dp[i - 1][j]) % MOD;

                st.erase(make_pair(idx[j], j));
                idx[j] = i;
                st.insert(make_pair(i, j));
            }
            else
                dp[i][j] = dp[i - 1][j];
        }

    for (int i = 1; i <= N; i++)
    {
        int x = st.begin()->second;
        st.erase(st.begin());
        idx[x] = M + i;
        st.insert(make_pair(M + i, x));

        dp[M + i][x] = (1 + total) % MOD;
        total = (total + total + 1 - dp[M + i - 1][x]) % MOD;

        for (int j = 0; j < K; j++)
            if (x != j)
                dp[M + i][j] = dp[M + i - 1][j];
    }

    ll ans = 1;
    for (int i = 0; i < K; i++)
        ans = (ans + dp[M + N][i]) % MOD;

    if (ans < 0)
        ans += MOD;

    cout << ans << "\n";

    return 0;
}

