int getDist(const vector<int>& pos, int begin) {
	int mid1 = lower_bound(pos.begin() + begin, pos.end(), (pos[begin] + pos.back()) / 2) - pos.begin();
	int mid2 = mid1 - (mid1 > begin);

	int a1 = max(pos.back() - pos[mid1], pos[mid1] - pos[begin]);
	int a2 = max(pos.back() - pos[mid2], pos[mid2] - pos[begin]);

	return min(a1, a2);
}

