void add(vt(int) &p, ll x, int i) {
  for (int c = 0, j = 0; j < 40; j ++) {
    int b = ((x>>j)&1) + c + p[i+j];
    p[i+j] = b&1;
    c = b>>1;
  }
}

void add(vt(int) &p, vt(int) q, int c = 0) {
  rep(i, sz(p)) {
    int b = p[i]+q[i]+c;
    c = b >> 1;
    p[i] = b&1;
  }
}

void sub(vt(int) &p, vt(int) q) {
  repe(&e, q) {
    e ^= 1;
  }
  add(p, q, 1);
}

