int LCA(int x,int y){
	if(lvl[x]<lvl[y])
		swap(x,y);
	for(int i=19;i>=0;i--)
		if(~P[x][i] and lvl[x]-(1<<i)>=lvl[y])
			x=P[x][i];
	if(x==y)
		return x;
	for(int i=19;i>=0;i--)
		if(~P[x][i] and P[y][i]!=P[x][i])
			x=P[x][i],y=P[y][i];
	return P[x][0];		
}
