double g(int j,int k){
    return 1.0*(h[j]-h[k])/(j-k);
}

int get(long long x){
    int L,R,mid,ret=l;
    L=l;R=r;
    while (L<=R){
        mid=(L+R)>>1;
        if (mid==1 || g(q[mid],q[mid-1])+1e-6<=x)  {L=mid+1;ret=mid;}
        else R=mid-1;
    }
    return q[ret];
}

