ll calc(string s) {
    int n = int(s.size());
    if (n == 1) {
        if (s[0] == '9') {
            return 1989;
        } else {
            return 1990 + s[0]-'0';
        }
    }

    ll u = calc(s.substr(1));

    u += TEN(n-1);
    while (true) {
        if (u / TEN(n-1) % 10 == s[0]-'0') break;
        u += TEN(n-1);
    }
    return u;
}

