int cal(int x, int y, int z)
{
    if (sco[x][0]>sco[x][1]||sco[y][0]>sco[y][1]||sco[z][0]>sco[z][1]) return n-1;
    if (sum[0]-hack[0]>sco[x][1]||sum[1]-hack[1]>sco[y][1]||sum[2]-hack[2]>sco[z][1]) return n-1;
