int dryrun(int n, int diff){
	for(int i=1;s[i];i++)
		if(s[i] == '?' && i - 2 > 0)
			if(s[i-2] == '-')
				diff = max(diff - (n - 1), 0);
	return diff;
}

int solve(){
	getline(cin, s);
	char t = 0; int plus = 0, neg = 0;
	stringstream ss(s);
	while(t != '='){
		ss >> t;
		if (t == '+') plus++;
		if (t == '-') neg++;
	}
	ss >> n;
