const int MOD = 1e9 + 7;

void add(int &a,int b) {
  a+=b;
  if(a >= MOD) a-=MOD;
  else if(a < 0) a+=MOD;
}

int mul(int a,int b) {
  return (long long)a * b % MOD;
}

int power(int a,int b) {
  int ans = 1;
  while(b > 0) {
    if(b & 1) ans = mul(ans,a);
    a = mul(a,a);
    b>>=1;
  }
  return ans;
}

int inverseMod(int a) {
  return power(a,MOD - 2);
}

const int N = 1e5 + 5;
int fact[N];
int invFact[N];

int ncr(int n,int r) {
  if(n < r) return 0;
  return mul(fact[n],mul(invFact[r],invFact[n - r]));
}

map<int,vector<int> > mp;

void calc(int m ) {
  vector<int> ans(100001);
  int X = mul(25,inverseMod(26));
  int cx = 1;
  int cc = inverseMod(power(25,m));
  for(int i = 1;i <= 100000;i++) {
    cx = mul(cx,X);
    cc = mul(cc,26);
    ans[i] = mul(ans[i - 1],26);
    add(ans[i],mul(cc, mul(ncr(i - 1,m - 1),cx) )  );
  }
  mp[m] = ans;
}

