vector<vector<int>> al;
vector<bool> used;
vector<vector<int>> dist;
vector<set<pair<int, int>>> sdist;
vector<set<pair<int, int>>> stdist;
queue<pair<int, int>> q;
int n, m;

int MINF = -1000000;

void bfs(int start){
    used.assign(n, false);
    q.push({start, 0});
    pair<int, int> pv;
    while (!q.empty()){
        pv = q.front();
        q.pop();
        int v = pv.first;
        int t = pv.second;
        if (used[v]) continue;
        used[v] = true;
        dist[start][v] = t;
        sdist[v].insert({t, start});
        if (sdist[v].size()>4){
            sdist[v].erase(*sdist[v].begin());
        }
        stdist[start].insert({t, v});
        if (stdist[start].size()>4){
            stdist[start].erase(*stdist[start].begin());
        }
        for (int i = 0; i<al[v].size(); i++){
            if (!used[al[v][i]]) q.push({al[v][i], t+1});
        }
    }
    for (int i = 0; i<n; i++){
        if (!used[i]){
            sdist[i].insert({MINF, start});
            if (sdist[i].size()>4){
                sdist[i].erase(*sdist[i].begin());
            }
            stdist[start].insert({MINF, i});
            if (stdist[start].size()>4){
                stdist[start].erase(*stdist[start].begin());
            }
            dist[start][i] = MINF;
        }
    }
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> n >> m;
    dist.assign(n, vector<int>(n));
