    for (int i = 0; i<n; i++){
        sdist.push_back(es);
        stdist.push_back(es);
    }
    al.assign(n, vector<int>(0));
    int from, to;
    for (int i = 0; i<m; i++){
        cin >> from >> to;
        from--;
        to--;
        al[from].push_back(to);
    }
    for (int i = 0; i<n; i++){
        bfs(i);
    }
    int maxans = MINF;
    int ans1 = -1;
    int ans2 = -1;
    int ans3 = -1;
    int ans4 = -1;
    pair<int, int> pi;
    pair<int, int> pj;
    pair<int, int> maxi;
    pair<int, int> maxj;
    bool was1 = false;
    bool was2 = false;
    for (int i = 0; i<n; i++){
        for (int j = 0; j<n; j++){
            if (i==j) continue;
            if (dist[i][j]==MINF) continue;
            pi = {dist[j][i], j};
            pj = {dist[j][i], i};
            if (sdist[i].count(pi)!=0){
                was1 = true;
                sdist[i].erase(pi);
            }
