                }
            }
            if (maxi.first<=0||maxj.first<=0) continue;
            int ans = dist[i][j]+maxi.first+maxj.first;
            if (ans>maxans){
                maxans = ans;
                ans1 = maxi.second;
                ans2 = i;
                ans3 = j;
