int codigo(int u)
{
  int su=u<0;
  if (u<0) u=-u;
  return ((u-1)<<1)|su;
}

void genera(int u,vector<int> g[limite],vector<int> &orden,int visto[limite])
{
  if (visto[u]) return;
  visto[u]=1;
  vector<int> &ar=g[u];
  for (int i=0;i<int(ar.size());i++)
    genera(ar[i],g,orden,visto);
  orden.push_back(u);
}

void calcula(int u,bitset<limite> &imp,
	     bitset<limite> implica[limite],vector<int> g[limite],int visto[limite])
{
  if (visto[u]==2) {
    imp|=implica[u];
    return;
  }
  if (visto[u]==1) return;
  visto[u]=1;
  imp[u]=1;
  vector<int> &ar=g[u];
  for (int i=0;i<int(ar.size());i++)
    calcula(ar[i],imp,implica,g,visto);
}

void propaga(int u,bitset<limite> &imp,
	     bitset<limite> implica[limite],vector<int> g[limite],int visto[limite])
{
  if (visto[u]==2) return;
  visto[u]=2;
  implica[u]=imp;
  vector<int> &ar=g[u];
  for (int i=0;i<int(ar.size());i++)
    propaga(ar[i],imp,implica,g,visto);
}

void leer(vector<int> g[limite],vector<int> ginv[limite],vector<int> &orden,int visto[limite],
	  bitset<limite> implica[limite],int &m,int &sat)
{
  //cout<<"leer "<<m<<endl;
  for (int i=0;i<m;i++) {
    int u,v;
    scanf("%d%d",&u,&v);
    g[codigo(-u)].push_back(codigo(v));
    g[codigo(-v)].push_back(codigo(u));
    ginv[codigo(v)].push_back(codigo(-u));
    ginv[codigo(u)].push_back(codigo(-v));
  }
  /*
  cout<<"g"<<endl;
  escribe(g);
  cout<<"ginv"<<endl;
  escribe(g);
  */
  for (int i=0;i<n;i++)
    if (not visto[i])
      genera(i,ginv,orden,visto);
  reverse(orden.begin(),orden.end());
  for (int i=0;i<n;i++) visto[i]=0;
  for (int i=0;i<n;i++) {
    int u=orden[i];
    if (not visto[u]) {
      bitset<limite> &imp=implica[u];
      calcula(u,imp,implica,g,visto);
      propaga(u,imp,implica,g,visto);
    }
  }
  sat=1;
  for (int i=0;i<n and sat;i++)
    sat=not (implica[i][i^1] and implica[i^1][i]);
  if (sat==0) return;
  for (int i=0;i<n;i++) {
    if (implica[i][i^1]) {
      implica[i].set();
      for (int j=0;j<n;j++)
	implica[j].set(i^1);
    }
  }
}

