void asignar1(int u,vector<int> g[limite])
{
  if (asignado[u]) return;
  asignado[u]=asignado[u^1]=true;
  asignacion[u]=1;
  vector<int> &ar=g[u];
  for (int i=0;i<int(ar.size());i++)
    asignar1(ar[i],g);
}

void generaasignacion(vector<int> g[limite],vector<int> &orden)
{
