const int N = 500007;
int n;
string s;
int pairs[N], lef[N], rig[N];
int fen[N];

void update(int p, int v)
{
    while (p <= n) {
        fen[p] += v;
        p += (p&-p);
    }
}

int sum(int p)
{
    int res = 0;
    while (p > 0) {
        res += fen[p];
        p -= (p&-p);
    }
    return res;
}

void solve()
{
    int m, p;
    cin >> n >> m >> p;
    cin >> s;
    s = '?'+s;

    for (int i = 1; i <= n; ++i) {
        if (s[i] == '(') {
            update(i, 1);
        }
        else if (s[i] == ')') {                        
            int lo = 1, hi = i;
            while (lo < hi) {
                int md = (lo+hi)/2;
                if (sum(md) >= sum(i)) hi = md;
                else lo = md+1;
            }
            pairs[i] = lo;
            pairs[lo] = i;
            update(lo, -1);
        }
    }
    //cout << s << endl;
    //for (int i = 0; i <= n; ++i) cout << pairs[i]; cout << endl;

    for (int i = 1; i <= n; ++i) {
        lef[i] = i-1;
        rig[i] = i+1;
    }
    rig[0] = 1;
    
    string t;
    cin >> t;
    for (int k = 0; k < m; ++k) {
        if (t[k] == 'L') {
            p = lef[p];
        }
        else if (t[k] == 'R') {
            p = rig[p];
        }
        else if (t[k] == 'D') {
            int q = pairs[p];
            if (q < p) {
                int l = lef[q];
                int r = rig[p];
                lef[r] = l;
                rig[l] = r;
                if (r <= n) p = r;
                else p = l;
            }
            else if (q > p) {
                int l = lef[p];
                int r = rig[q];                
                lef[r] = l;
                rig[l] = r;
                if (r <= n) p = r;
                else p = l;
            }
        }
    }

    int pos = 0;
    while (pos <= n) {
        if (pos > 0) cout << s[pos];
        pos = rig[pos];
    }
    cout << endl;
}

int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.precision(10);
    cout << fixed;

    solve();
    return 0;
}

