vi convert(int d)
{
    vi res(10, 0);
    while (d) {
        ++res[d%10];
        d /= 10;
    }
    return res;
}

vi check(int d)
{
    vi h = convert(d);
    int sum = 0;
    for (int i = 0; i <= 9; ++i) {        
        if (ht[i] < hs[i]+h[i]) return vi();
        sum += ht[i]-h[i];
    }
    if (sum != d) return vi();

    vi res(10);
    for (int i = 0; i <= 9; ++i)
        res[i] = ht[i]-hs[i]-h[i];
    return res;
}

int get(const vi& h)
{
    for (int i = 1; i <= 9; ++i)
        if (h[i] > 0) return i;
    return h[0] > 0 ? 0 : -1;
}

string make(vi& h, bool& first, bool& s_used)
{
    int fnz = get(h);
    if (fnz < 0) {
        if (s_used) return "";
        else {
            s_used = true;
            return s;
        }
    }

    if (first && s[0] == '0') {       
        --h[fnz];
        first = false;
        string res = string(1, fnz+'0')+string(h[0], '0');
        h[0] = 0;
        return res;
    }

    if (first && s[0] != '0') {        
        if (fnz > s[0]-'0' || fnz == 0) {
            string res = s;
            first = false;
            s_used = true;
            res += string(h[0], '0');
            h[0] = 0;
            return res;
        }
        else if (fnz < s[0]-'0') {
            --h[fnz];
            first = false;
            string res = string(1, fnz+'0')+string(h[0], '0');
            h[0] = 0;
            return res;
        }
        else if (fnz == s[0]-'0') {
            string a, b, tmp;
            a = s;
            for (int i = 0, r = s.size(); i <= 9 && r > 0; ++i) {
                int x = min(r, h[i]);
                a += string(x, i+'0');
                r -= x;
            }
            b = s[0];
            --h[fnz];
            int r = s.size()-1;
            for (int i = 0; i <= 9 && r > 0; ++i) {
                int x = min(r, h[i]);
                b += string(x, i+'0');
                r -= x;
            }
            b += s;
            if (a <= b) {
                ++h[fnz];                
                first = false;
                s_used = true;
                string res = s;
                res += string(h[0], '0');
                h[0] = 0;
                return res;
            }
            else {
                string res(1, s[0]);           
                first = false;
                res += string(h[0], '0');                
                h[0] = 0;
                return res;
            }
        }
    }

    if (s_used) {
        string res;
        for (int i = 0; i <= 9; ++i) {
            res += string(h[i], i+'0');
            h[i] = 0;
        }
        return res;
    }
    else {
        if (fnz < s[0]-'0') {
            string res(h[fnz], fnz+'0');
            h[fnz] = 0;
            return res;
        }
        else if (fnz > s[0]-'0') {            
            s_used = true;
            return s;
        }
        else {
            string a, b, tmp;
            int r = s.size();            
            for (int i = 0; i <= 9 && r > 0; ++i) {
                int x = min(r, h[i]);
                tmp += string(x, i+'0');
                r -= x;
            }
            a = s+tmp;
            b = tmp+s;
            if (a <= b) {                
                s_used = true;
                return s;
            }
            else {
                string res;
                res = string(h[fnz], fnz+'0');
                h[fnz] = 0;
                return res;
            }
        }
    }
}

void solve()
{
    string t;
    cin >> t;
    for (auto e : t)
        ++ht[e-'0'];

    cin >> s;
    for (auto e : s)
        ++hs[e-'0'];

    if (t == "10" || t == "01") {
        cout << "0" << endl;
        return;
    }

    for (int d = 1; d <= 1000000; ++d) {
        vi h = check(d);
        if (h.empty()) continue;
        bool all_zero = (accumulate(h.begin(), h.end(), 0) == h[0]);
        if (s.size() > 1 && s[0] == '0' && all_zero) continue;

        string res, tmp;
        bool first = true, s_used = false;
        while (true) {
            tmp = make(h, first, s_used);
            if (tmp.empty()) break;            
            res += tmp;
            //cout << res << endl;
        }
        //cout << d << " " << res << endl;
        cout << res << endl;
        return;
    }
}

