#include <iostream>
#include <algorithm>
#include <vector>
using namespace std;
typedef long long ll;

const int MAXN = 200005;
const int MAXSEG = 1<<19;
int N;
int A[MAXN];
int used[MAXN];
vector<int> D[MAXN];
ll seg[MAXSEG];
ll maxval[MAXSEG];
ll lazy[MAXSEG];
ll cnt[MAXN];

void build_tree(int node, int left, int right)
{
    if (left == right)
    {
        seg[node] = maxval[node] = left;
        return;
    }

    int mid = (left + right)/2;
    build_tree(2*node, left, mid);
    build_tree(2*node+1, mid+1, right);
    seg[node] = seg[2*node] + seg[2*node+1];
    maxval[node] = max(maxval[2*node], maxval[2*node+1]);
}

void down(int node, int left, int right)
{
    if (lazy[node] > 0)
    {
        int mid = (left + right)/2;
        seg[2*node] = (mid - left + 1)*lazy[node];
        seg[2*node+1] = (right - mid)*lazy[node];
        maxval[2*node] = maxval[2*node+1] = lazy[node];
        lazy[2*node] = lazy[2*node+1] = lazy[node];
        lazy[node] = 0;
    }
}

void update(int node, int left, int right, int ql, int qr, ll val)
{
    if (left > right || ql > qr || right < ql || qr < left)
        return;

    if (ql <= left && right <= qr)
    {
        seg[node] = (right - left + 1)*val;
        maxval[node] = val;
        lazy[node] = val;
        return;
    }

    down(node, left, right);

    int mid = (left + right)/2;
    update(2*node, left, mid, ql, qr, val);
    update(2*node+1, mid+1, right, ql, qr, val);
    seg[node] = seg[2*node] + seg[2*node+1];
    maxval[node] = max(maxval[2*node], maxval[2*node+1]);
}

int query(int node, int left, int right, ll val)
{
    if (left == right)
    {
        if (val <= maxval[node])
            return left;
        return N + 1;
    }

    down(node, left, right);

    int mid = (left + right)/2;
    if (val <= maxval[2*node])
        return query(2*node, left, mid, val);
    return query(2*node+1, mid+1, right, val);
}

int main()
{
    ios::sync_with_stdio(0);

    cin >> N;
    for (int i = 1; i <= N; i++)
    {
        cin >> A[i];
        used[A[i]] = i;
    }

    for (int i = 1; i < MAXN; i++)
        for (int j = i; j < MAXN; j += i)
            if (used[j] > 0)
                D[i].push_back(used[j]);

    build_tree(1, 1, N);

    for (int i = MAXN - 1; i >= 1; i--)
    {
        sort(D[i].begin(), D[i].end());
        if (D[i].size() >= 2)
        {
            update(1, 1, N, D[i][1] + 1, N, N + 1);
            int idx = query(1, 1, N, D[i].back());
            update(1, 1, N, D[i][0] + 1, min(idx - 1, D[i][1]), D[i].back());
            idx = query(1, 1, N, D[i][D[i].size() - 2]);
            update(1, 1, N, 1, min(idx - 1, D[i][0]), D[i][D[i].size() - 2]);
        }
        cnt[i - 1] = (ll)N*N - seg[1] + N;
    }

    ll ans = 0;
    for (int i = MAXN - 2; i >= 1; i--)
        ans += (cnt[i] - cnt[i - 1])*i;

    cout << ans << "\n";

    return 0;
}

