typedef long long i64; typedef vector<int> ivec; typedef vector<string> svec;

int N, K;
i64 C[505050];

void pohe()
{
	i64 sum = 0;
	for (int i = N - 1; i >= 0; --i) {
		sum += C[i];
		i64 bk = (i == 0 ? 0 : C[i - 1]) * (N - i);
		if (sum - bk > K) {
			i64 rem = sum - bk - K;
			i64 rr = rem % (N - i);
			for (int j = i; j < N; ++j) {
				C[j] = C[i - 1] + rem / (N - i) + (N - j - 1 < rr ? 1 : 0);
			}
			break;
		}
	}
}

int main()
{
