	}
	sort(C, C + N);

	i64 tot = 0;
	for (int i = 0; i < N; ++i) tot += C[i];
	if (tot <= K) {
		printf("%d\n", (tot % N == 0) ? 0 : 1);
		return 0;
	}

	pohe();

	for (int i = 0; i < N; ++i) C[i] = 21000000 - C[i];
