const int MAXN = 300005;
int n, m, fir[MAXN], head[MAXN], nxt[MAXN<<2], to[MAXN<<2], w[MAXN<<2], cnt;
inline void insert(int u, int v) { nxt[++cnt] = head[u]; to[cnt] = v; head[u] = cnt; }
inline void insert(int u, int v, int c) { nxt[++cnt] = fir[u]; to[cnt] = v; w[cnt] = c; fir[u] = cnt; }

int dep[MAXN], root[MAXN], idx;
long long ans;
bool flag;
struct Heap { int l, r, d, w, ky, tag; } T[MAXN];

inline void push(int u) {
	if(T[u].tag == 0) return;
	T[u].w += T[u].tag;
	if(T[u].l) T[T[u].l].tag += T[u].tag;
	if(T[u].r) T[T[u].r].tag += T[u].tag;
	T[u].tag = 0;
}

inline int merge(int u, int v) {
	if(!u || !v) return u | v;
	push(u); push(v);
	if(T[u].w > T[v].w) swap(u, v);
	T[u].r = merge(T[u].r, v);
	if(T[T[u].l].d < T[T[u].r].d) swap(T[u].l, T[u].r);
	T[u].d = T[T[u].l].d + 1;
	return u;
}

inline void pop(int& u) { push(u); u = merge(T[u].l, T[u].r); }

inline void dfs(int u) {
	if(flag) return;
	for(Int v, i = head[u]; i; i = nxt[i]) {
		if(dep[v = to[i]]) continue;
		dep[v] = dep[u] + 1;
		dfs(v);
