using namespace std;

const int MAX_N = 500000;
int n, k, a[MAX_N];

bool res_is_0(int n, int k, int a[]) {
    long long sum = 0;
    for (int i = 0; i < n; ++i) {
        sum += a[i];
    }
    if (sum % n != 0) {
        return false;
    }
    int average = sum / n;
    long long need = 0;
    for (int i = 0; i < n; ++i) {
        need += max(0, a[i] - average);
    }
    return need <= k;
}

bool chk_upper(int n, int k, int a[], int upper) {
    long long give = 0;
    long long need = 0;
    for (int i = 0; i < n; ++i) {
        if (a[i] >= upper) {
            give += a[i] - upper;
        } else {
            need += upper - a[i];
        }
    }
    return need >= give && give <= k;
}

int bs_upper(int n, int k, int a[]) {
    int l = 1e9 + 1;
    int r = 0;
    for (int i = 0; i < n; ++i) {
        l = min(l, a[i]);
        r = max(r, a[i]);
    }
    while (r - l > 1) {
        int m = (l + r) / 2;
        if (chk_upper(n, k, a, m)) {
            r = m;
        } else {
            l = m;
        }
    }
    return chk_upper(n, k, a, l) ? l : r;
}

bool chk_lower(int n, int k, int a[], int upper, int lower) {
    long long give = 0;
    long long need = 0;
    for (int i = 0; i < n; ++i) {
        if (a[i] >= upper) {
            give += a[i] - upper + 1;
        }
        if (a[i] < lower) {
            need += lower - a[i];
        }
    }
    --give;
    give = min(give, k * 1ll);
    return need <= give;
}

int bs_lower(int n, int k, int a[], int upper) {
    int l = 1e9 + 1;
    int r = upper - 1;
    for (int i = 0; i < n; ++i) {
        l = min(l, a[i]);
    }
    while (r - l > 1) {
        int m = (l + r) / 2;
        if (chk_lower(n, k, a, upper, m)) {
            l = m;
        } else {
            r = m;
        }
    }
    return chk_lower(n, k, a, upper, r) ? r : l;
}

int main () {
    cin >> n >> k;
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    if (res_is_0(n, k, a)) {
        cout << "0" << endl;
        return 0;
    }

    int upper = bs_upper(n, k, a);
    int lower = bs_lower(n, k, a, upper);
    cout << (upper - lower) << endl;

    return 0;
}

