const int MAX_N = 200000;
const int MAX_K = 50;

int n, k;
double t[MAX_N], sum[MAX_N], rev[MAX_N], exc[MAX_N];
int Q[MAX_N], st, ed;
double f[MAX_N][MAX_K + 1];

void init() {
    cin >> n >> k;
    for (int i = 0; i < n; ++i) {
        cin >> t[i];
    }

    for (int i = 0; i < n; ++i) {
        sum[i] = t[i] + (i == 0 ? 0 : sum[i - 1]);
        rev[i] = 1.0 / t[i] + (i == 0 ? 0 : rev[i - 1]);
        exc[i] = sum[i] / t[i] + (i == 0 ? 0 : exc[i - 1]);
    }
}

double range_exc(int l, int r) {
    if (l == 0) {
        return exc[r];
    }
    return exc[r] - exc[l - 1] - sum[l - 1] * (rev[r] - rev[l - 1]);
}

double g(int i, int j) {
    return f[i][j] - exc[i] + sum[i] * rev[i];
}

double slope(int i_0, int i_1, int j) {
    return (g(i_0, j) - g(i_1, j)) / (sum[i_0] - sum[i_1]);
}

int main() {

    init();

    for (int i = 0; i < n; ++i) {
        f[i][1] = exc[i];
    }

    for (int j = 2; j <= k; ++j) {
        st = ed = 0;
        for (int i = 0; i < n; ++i) {
            if (i + 1 >= j) {
                while (ed - st >= 2 && slope(Q[st], Q[st + 1], j - 1) <= rev[i]) {
                    ++st;
                }
                f[i][j] = f[Q[st]][j - 1] + range_exc(Q[st] + 1, i);
            }
            if (i + 1 >= j - 1) {
                while (ed - st >= 2 && slope(Q[ed - 2], Q[ed - 1], j - 1) > slope(Q[ed - 1], i, j - 1)) {
                    --ed;
                }
                Q[ed++] = i;
            }
        }
    }

    cout << setprecision(12) << f[n - 1][k] <<endl;

    return 0;
}

