int main () {
    cin >> n >> p >> q;

    comb[0] = 1;
    vector<unsigned> muls;
    for (unsigned i = 1; i <= p; ++i) {
        muls.push_back(n - i + 1);
        unsigned div = i;
        for (unsigned j = 0; j < muls.size() && div > 1; ++j) {
            unsigned g = __gcd(div, muls[j]);
            if (g > 1) {
                div /= g;
                muls[j] /= g;
            }
        }
        comb[i] = 1;
        for (unsigned j = 0; j < muls.size(); ++j) {
            comb[i] *= muls[j];
        }
    }

    unsigned hash_res = 0;
    unsigned max_p = std::min(p, n - 1);
    for (unsigned i = 1; i <= q; ++i) {
        unsigned res = 0;
        unsigned base = 1;
        for (unsigned j = 0; j <= max_p; ++j) {
            res += comb[j] * base;
            base *= i;
        }
        hash_res ^= i * res;
    }

    cout << hash_res << endl;

    return 0;
}

