using namespace std;

const int MAX_LENGTH = 1e5 + 1000;

int n;

int range[MAX_LENGTH];
ll dp[MAX_LENGTH];

int seg_tree[4 * MAX_LENGTH];


void build_tree(int l, int r, int pos)
{
	if(l == r)
	{
		seg_tree[pos] = l;
		return;
	}

	int mid = (l+r) >> 1;
	build_tree(l,mid,pos<<1);
	build_tree(mid+1,r,pos<<1 | 1);

	seg_tree[pos] = (range[seg_tree[pos<<1]] > range[seg_tree[pos<<1 | 1]])?seg_tree[pos<<1]:seg_tree[pos<<1 | 1];
}




int range_max(int l, int r, int start, int end, int pos)
{
	if(l >= start && r <= end)
	{
		return seg_tree[pos];
	}
	if(r < start || l > end )
	{
		return n;
	}
	int mid = (l + r)>>1;
	int a = range_max(l,mid,start,end,pos<<1);
	int b = range_max(mid+1,r,start,end,pos<<1 | 1);
	// cout<<"start = "<<start<<", end = "<<end<<" , Range max "<<l<<","<<mid<<" => "<<a<<endl;
	// cout<<"start = "<<start<<", end = "<<end<<" , Range max "<<mid+1 <<","<<r<<" => "<<b<<endl;
	return ((range[a] > range[b])?a:b);
}




ll calc_dp(int i)
{
	if(dp[i] != 0)
	{
		return dp[i];
	}
	else
	{
		if(range[i] == n-1)
		{
			dp[i] = n - i -1;
		}
		else
		{
			int max = range_max(0,n-1,i+1,range[i],1);
			// cout<<"Range max ("<<i+1<<","<<range[i]<<") => "<<max<<endl;
			dp[i] = calc_dp(max) + n - i - 1  - (range[i] - max);
		}
		return dp[i];
	}	
}

