    cin>>n;

    for(int i=0;i<n-1;i++)
    {
    	si(range[i]);
    	--range[i];
    }

    build_tree(0,n-1,1);

    ll answer = 0;

    dp[n-1] = 0;

    for(int i=0;i<n-1;i++)
    {
    	answer += calc_dp(i);
    }

    cout<<answer<<endl;

