ll pow(ll a, ll b){
	ll ret=1;
	while(b>0){
		if(b&1) ret*=a;
		b/=2;
		a*=a;
	}
	return ret;
}

ll aton(char c){
	if(c=='-') return 62;
	if(c=='_') return 63;
	if(c<='9' && c>='0') return c-'0';
	if(c<='Z' && c>='A') return (c-'A')+10;
	if(c<='z' && c>='a') return (c-'a')+36;
}

ll pos(ll xx){
	ll cnt=0;
	for(ll i=0; i<6; i++){
		if(!((1<<i) & (xx))) cnt++; 
	}
	return pow(3, cnt);
}

