inline int dist(pair<int, int> a, pair<int, int> b) { return abs(a.x - b.x) + abs(a.y - b.y); }

inline int get(int x, int y) { return m * (x - 1) + y; }

inline pair<int, int> invget(int x) { return x ? make_pair(x / m + (x % m != 0), x % m ? x % m : m) : make_pair(0, 0); }

bool cmp(int a, int b) {
  auto x = invget(a);
  auto y = invget(b);

  return d[x.x][x.y] < d[y.x][y.y];
}

