double p[20][20];
int n, done[20][(1<<19)];
double dp[20][(1<<19)];

double solve(int i, int mask){
    if(mask&1) return 0;
    if(mask == (1<<n)-2) return 1;
    if(done[i][mask]) return dp[i][mask];

    double ret = 0;

    if(i == 0){
        REP(j, n){
            double tmp = 0;
            if(mask&(1<<j) || j == i) continue;
            tmp += p[0][j]*solve(i, mask|(1<<j));
            ret = max(ret, tmp);
        }
    }
    else{
        REP(j, n){
            if(mask&(1<<j) || i == j) continue;
            double tmp = 0;
            tmp += p[i][j]*solve(i, mask|(1<<j)) + p[j][i]*solve(j, mask|(1<<i)); 
            ret = max(ret, tmp);
        }
    }
    done[i][mask] = 1;
    return dp[i][mask] = ret;
}

