    cin >> n;
    REP(i, n) REP(j, n) cin >> p[i][j];
    double ret = 0;

    REP(i, n){

        ret = max(ret, solve(i, 0));
    }

    cout << fixed << setprecision(10) << ret;
    return 0;
}

