long long mod = 1e9 + 7;
/*f(f(f(f(f(f(f(f(f(x)))))))))) = 
A(A(A(A(A(A(A(A(Ax + B) + B) +B) + B)+ B) + B) + B) + B) + B = 
A ^ n x + B (A ^ n - 1 + ... + 1) = A ^ n x + B * (A ^ n - 1)/(A - 1);*/

int bin(long long a, long long n, long long m = 1e9 + 7) {
	long long res = 1;
	while(n) {
		if(n & 1) res = res * a % m;
		n >>= 1;
		a = a * a % m;
	}
	return res;
}
	

 main() {
	long long a, b, n, x;
	cin >> a >> b >> n >> x;
	if(a == 1) {cout << (b * (n%mod )+ x) % mod << endl; return 0;}
	int res = (bin(a, n) * x + ((b * (bin(a, n) - 1) % mod) * bin(a - 1, (int)1e9 + 5))%mod) % ((int)1e9 + 7);
	cout << res << endl;
	return 0;
}

