#define  line  pair<int,int>
#define a first
#define b second
const ll INF = 1LL << 62;
bool ccw(line o, line u, line v)
{
    return 1LL * (u.a-o.a)*(v.b-o.b)-1LL *(v.a-o.a)*(u.b-o.b) >=0LL;
}
const int N = 3e5 + 10;
int t[N], ao[N], bo[N], id[N], q[N];
ll ans[N];
int n;
vector<pair<line,int> > lines;
bool ded[N], inSet[N];
vector<line> bao;
void baotren()///-------------------------------------------bao tren cho 1 tap ham so da co
{
    bao.clear();
    bao.reserve(n);
    forn(i, lines.size())
    {
        int ind = lines[i].second;
        if(inSet[ind] && !ded[ind])
        {
            line d = mp(ao[ind], bo[ind]);
            while(!bao.empty())
            {
                if(bao.back().a == d.a) { bao.pop_back(); continue; }
                else if(bao.size() > 1)
                {
                    if(!ccw(bao.back(), bao[bao.size() - 2], d)) {bao.pop_back(); continue; }
                }
                break;
            }
            bao.pb(d);
        }
    }
}
vector<pair<int,int> > qs;///------------------------------Ham tinh ket qua qk ko lq trong O(n)
void beforeBlock()
{
    int p = 0;
    if(bao.size()==0) return;
    forn(i, qs.size())
    {
        int ind = qs[i].second;
        int x = qs[i].first;
        while(p + 1 < bao.size())
        {
            ll cva = 1LL * bao[p].a * x + bao[p].b;
            ll nva = 1LL * bao[p+1].a*x + bao[p+1].b;
            if(cva > nva) break;
            p ++;
        }
        ans[ind] = 1LL* bao[p].a * x + bao[p].b;
    }
}

void solve()
{
    for1(i, n) if(t[i]==1) lines.pb(mp(mp(ao[i], bo[i]), i));
    sort(all(lines));
    forn(i, N- 2) ans[i] = -INF;

    int blen = 2500;
    for(int l = 1; l<= n;l += blen)
    {
        int r = min(n, l + blen - 1);
        FOR(i, l, r) if(t[i]==2) ded[id[i]] = true;
        baotren();
        qs.clear();
        qs.reserve(r - l + 1);
        FOR(i, l, r) if(t[i]==3) qs.pb(mp(q[i],i));
        sort(all(qs));
        beforeBlock();

        FOR(i, l, r)
        {
            if(t[i]==1) inSet[i] = true;
            else if(t[i]==2) inSet[id[i] ] = false;
            else{
                FOR(j, l, r)
                {
                    if(t[j]==1 && inSet[j]) ans[i] = max(ans[i],1LL * q[i] * (ao[j]) + bo[j] );
                    else if(t[j]==2 &&inSet[id[j]]) ans[i] = max(ans[i],1LL * q[i] * (ao[id[j] ]) + bo[id[j] ] );
                }
                if(ans[i]==-INF) puts("EMPTY SET");
                else printf("%lld\n", ans[i]);
            }
        }
    }
}

int main()
{
    //freopen("test.inp","r",stdin);
    scanf("%d", &n);
    for1(i, n)
    {
        scanf("%d", &t[i]);
        if(t[i]==1) scanf("%d %d", &ao[i], &bo[i]);
        else if(t[i]==2) scanf("%d", &id[i]);
        else scanf("%d", &q[i]);
    }
    solve();
}

