struct st
{
    ll v,ans;
    ll lz;
    int same;
    st(void)
    {
        v = ans = lz = same = 0;
    }
    st(ll v,ll ans,ll lz,int same) : v(v),ans(ans),lz(lz),same(same) {}
};
st t[1 << 21];
static vector < ll > pw;
void lazy(int p,int u,int node)
{
    t[node].v += t[node].lz;
    t[node].ans -= t[node].lz;
    if (p == u) return void(t[node].lz = 0);
    if (t[node].same)
        {
            t[node].lz = 0;
            t[node << 1] = t[node << 1 | 1] = t[node];
            return;
        }
    t[node << 1].lz += t[node].lz;
    t[node << 1 | 1].lz += t[node].lz;
    t[node].lz = 0;
}
st operator + (st a,st b)
{
    st c;
    c.same = (a.same && b.same && (a.v == b.v));
    c.v = c.same ? a.v : 0;
    c.lz = 0;
    c.ans = min(a.ans,b.ans);
    return c;
}
st g(ll k)
{
    return st(k,*lower_bound(pw.begin(),pw.end(),k) - k,0,1);
}
int Init[1 << 20];
void build(int p,int u,int node)
{
    if (p == u) t[node] = g(Init[p]);
    else
    {
        int m = (p + u) / 2;
        build(p,m,node << 1);
        build(m+1,u,node << 1 | 1);
        t[node] = t[node << 1] + t[node << 1 | 1];
    }
}
void Set(int p,int u,int l,int r,ll val,int node)
{
    lazy(p,u,node);
    if (l <= p && u <= r)
        {
            t[node] = g(val);
            lazy(p,u,node);
        }
        else
        {
            int m = (p + u) / 2;
            if (l <= m) Set(p,m,l,r,val,node << 1);
            else lazy(p,m,node << 1);
            if (m+1<=r) Set(m+1,u,l,r,val,node << 1 | 1);
            else lazy(m+1,u,node << 1 | 1);
            t[node] = t[node << 1] + t[node << 1 | 1];
        }
}
ll query(int p,int u,int pos,int node)
{
    lazy(p,u,node);
    if (p == u) return t[node].v;
    else
    {
        int m = (p + u) / 2;
        if (pos <= m)
            return query(p,m,pos,node << 1);
        else
            return query(m+1,u,pos,node << 1 | 1);
    }
}
ll update(int p,int u,int l,int r,ll val,int node)
{
    lazy(p,u,node);
    if (l <= p && u <= r && (t[node].same || t[node].ans > val))
    {
        if (t[node].same)
            t[node] = g(t[node].v + val);
        else
            t[node].lz += val,lazy(p,u,node);
        return t[node].ans;
    }
    else
    {
        int m = (p + u) / 2;
        ll cnt = 1e18 + 69;
        if (l <= m)
            cnt = min(cnt,update(p,m,l,r,val,node << 1));
        else
            lazy(p,m,node << 1);
        if (m+1<=r)
            cnt = min(cnt,update(m+1,u,l,r,val,node << 1 | 1));
        else
            lazy(m+1,u,node << 1 | 1);
        t[node] = t[node << 1] + t[node << 1 | 1];
        return cnt;
    }
}
