#include <bits/stdc++.h>

using namespace std;

const int MAX_N = 100000;

long long f[MAX_N + 1][2];

long long pw3(long long a) {
    return a * a * a;
}

long long calc_max_cnt(long long n) {
    f[0][0] = f[0][1] = 0;
    long long res = 0;
    for (int i = 1; i <= MAX_N; ++i) {
        long long upper = pw3(1LL * (i + 1)) - 1;
        long long need = pw3(1LL * i);
        if (need > n) {
            break;
        }
        long long cnt = max(0LL, min(n, upper) - f[i - 1][1]) / need;
        f[i][0] = f[i - 1][0] + cnt;
        f[i][1] = f[i - 1][1] + cnt * need;
        res = max(res, f[i][0]);
    }
    return res;
}

void init() {
    f[0][0] = f[0][1] = 0;
    for (int i = 1; i <= MAX_N; ++i) {
        long long upper = pw3(1LL * (i + 1)) - 1;
        long long need = pw3(1LL * i);
        long long cnt = (upper - f[i - 1][1]) / need;
        f[i][0] = f[i - 1][0] + cnt;
        f[i][1] = f[i - 1][1] + cnt * need;
    }
}

long long min_need(long long m) {
    int low = 1, high = MAX_N;
    while (high - low > 1) {
        int middle = (low + high) / 2;
        if (f[middle][0] >= m) {
            high = middle;
        } else {
            low = middle;
        }
    }
    int len = (f[low][0] >= m ? low : high);
    if (f[len][0] == m) {
        return f[len][1];
    } else {
        return f[len - 1][1] + (m - f[len - 1][0]) * pw3(1LL * len);
    }
}

long long calc_max_num(long long n, long long m) {
    if (n == 0 || m == 0) {
        return 0;
    }
    int low = 1, high = MAX_N;
    while (high - low > 1) {
        int middle = (low + high) / 2;
        if (min_need(m - 1) <= n - pw3(middle)) {
            low = middle;
        } else {
            high = middle;
        }
    }
    int len = (min_need(m - 1) <= n - pw3(high) ? high : low);
    if (len == 1) {
        return m;
    }
    long long need = pw3(1LL * len);
    n = min(n, pw3(1LL * (len + 1)) - 1);
    long long long_low = 1, long_high = n / need;
    while (long_high - long_low > 1) {
        long long long_middle = (long_low + long_high) / 2;
        if (min_need(m - long_middle) <= n - long_middle * need) {
            long_low = long_middle;
        } else {
            long_high = long_middle;
        }
    }
    long long cnt = (min_need(m - long_high) <= n - long_high * need ? long_high : long_low);
    return cnt * need + calc_max_num(n - cnt * need, m - cnt);
}

int main() {
    long long n;
    cin >> n;
    long long m = calc_max_cnt(n);
    init();
    cout << m << " " << calc_max_num(n, m) << endl;
    return 0;
}

#include <bits/stdc++.h>

using namespace std;

const int MAX_N = 500;

const int dx[] = {0, 0, 1, -1};
const int dy[] = {1, -1, 0, 0};

int n, k;
string graph[MAX_N];
int m, belongs[MAX_N][MAX_N];
int cnt[MAX_N * MAX_N], add_time[MAX_N * MAX_N];

bool inside(int x, int y) {
    return min(x, y) >= 0 && max(x, y) < n;
}

void dfs(int x, int y, int sign) {
    belongs[x][y] = sign;
    ++cnt[sign];
    for (int i = 0; i < 4; ++i) {
        int u = x + dx[i];
        int v = y + dy[i];
        if (inside(u, v) && graph[u][v] == '.' && belongs[u][v] == -1) {
            dfs(u, v, sign);
        }
    }
}

void add(int x, int y, int& cur, int cur_time) {
    if (inside(x, y) && graph[x][y] == '.' && add_time[belongs[x][y]] != cur_time) {
        add_time[belongs[x][y]] = cur_time;
        cur += cnt[belongs[x][y]];
    }
}

int main() {
    cin >> n >> k;
    for (int i = 0; i < n; ++i) {
        cin >> graph[i];
    }
    memset(belongs, 0xFF, sizeof(belongs));
    m = 0;
    memset(cnt, 0x00, sizeof(cnt));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (graph[i][j] == '.' && belongs[i][j] == -1) {
                dfs(i, j, m++);
            }
        }
    }
    memset(add_time, 0x00, sizeof(add_time));
    int cur_time = 0, res = 0;
    for (int y_low = 0; y_low <= n - k; ++y_low) {
        for (int i = 0; i < k; ++i) {
            for (int j = y_low; j < y_low + k; ++j) {
                if (graph[i][j] == '.') {
                    --cnt[belongs[i][j]];
                }
            }
        }
        for (int x_low = 0; x_low <= n - k; ++x_low) {
            ++cur_time;
            int cur = k * k;
            for (int i = 0; i < k; ++i) {
                add(x_low - 1, y_low + i, cur, cur_time);
                add(x_low + k, y_low + i, cur, cur_time);
                add(x_low + i, y_low - 1, cur, cur_time);
                add(x_low + i, y_low + k, cur, cur_time);
            }
            res = max(res, cur);
            if (x_low != n - k) {
                for (int i = 0; i < k; ++i) {
                    if (graph[x_low][y_low + i] == '.') {
                        ++cnt[belongs[x_low][y_low + i]];
                    }
                    if (graph[x_low + k][y_low + i] == '.') {
                        --cnt[belongs[x_low + k][y_low + i]];
                    }
                }
            }
        }
        for (int i = n - k; i < n; ++i) {
            for (int j = y_low; j < y_low + k; ++j) {
                if (graph[i][j] == '.') {
                    ++cnt[belongs[i][j]];
                }
            }
        }
    }
    cout << res << endl;
    return 0;
}

