using namespace std;

const int HOUSE_COST = 1234567;
const int CAR_COST = 123456; 
const int COMPUTER_COST = 1234; 

pair<int, int> solveLinearDiophantineEquation(int a, int b, int c) {  
  /* Find integers x and y such that ax + by = c.
   * gcd(a,b) | c
   */
  int A = a, B = b;
  int m00 = 1, m01 = 0, m10 = 0, m11 = 1;
  /* We can write is M[a;b] = [A; B], where
   * M = [ m00 m01]
   *     [ m10 m11]
   */
  while (A > 0 && B > 0) {
    if (A > B) {
      int q = A/B;
      A -= q*B;
      m00 -= q*m10;
      m01 -= q*m11;
    } else { // B >= A
      int q = B/A;
      B -= q*A;
      m10 -= q*m00;
      m11 -= q*m01;
    }
  }
  int x, y, d;
  if (A == 0) {
    x = m10; y = m11; d = B;
  } else { // B == 0
    x = m00; y = m01; d = A;
  }
  if (c % d != 0) throw logic_error("No solution exists!");  
  /* If ax + by = c
   * a(x + k*b/d) + b(y - k*a/d) = c.
   * for some integer k gives us all solution.
   * Let l = c/d. 
   */
  int l = c/d;
  x *= l; y *= l;  
  int xShift = b/d;
  int yShift = a/d;
  if (x < 0) {
    int k = -(x - xShift + 1)/xShift;
    x += k*xShift;
    y -= k*yShift;
  } else if (y < 0) {
    int k = (y - yShift + 1)/yShift;
    x += k*xShift;
    y -= k*yShift;    
  }
  return make_pair(x, y);
}


int main(int argc, char *argv[]) {
  ios::sync_with_stdio(false); cin.tie(NULL);
  
  int N; cin >> N;
  while (N >= 0) {
    if (N % 2 == 0) {
      pair<int, int> solution =
        solveLinearDiophantineEquation(CAR_COST, COMPUTER_COST, N);
      if (solution.first >= 0 && solution.second >= 0) {
        cout << "YES" << endl;
        return 0;
      }
    }    
    N -= HOUSE_COST;
  }
  cout << "NO" << endl;
  return 0;
}

