vector<long long> count_dists(vector<vector<pii>>& G, int origin) {
    int n = G.size();
    vector<int> used(n, false);
    vector<long long> dist(n, -1);
    used[0] = true;
    dist[0] = 0;
    queue<int> Q;
    Q.push(0);
    while (!Q.empty()) {
        int u = Q.front(); Q.pop();
        for (auto& edge : G[u]) {
            int v = edge.first, cost = edge.second;
            if (used[v]) continue;
            used[v] = true;
            dist[v] = dist[u] + cost;
            Q.push(v);
        }
    }
    return dist;
}

vector<int> vis;
int count_bad(vector<vector<pii>>& G, int from, vector<long long>& D,
              vector<int>& A,
              long long min_dist=INT64_MAX, bool stop=false) {
    vis[from] = true;
    int res = 0;
    if (stop) {
        res++;
    }
    else {
        if (min_dist < (long long) D[from] - A[from]) {
            stop = true;
            res++;
        }
    }
    auto new_min_dist = min_dist;
    new_min_dist = min(new_min_dist, D[from]);
    for (auto& edge : G[from]) {
        int to = edge.first, cost = edge.second;
        if (vis[to]) continue;
        res += count_bad(G, to, D, A, new_min_dist, stop);
    }
    return res;
}

