        int p, c; cin >> p >> c;
        --p;
        G[i+1].push_back(mp(p, c));
        G[p].push_back(mp(i+1, c));
    }
    vector<long long> D = count_dists(G, 0);
    vis.assign(n, false);
    int res = count_bad(G, 0, D, A);
    cout << res << "\n";
    return 0;
}

