	{
		vp ans; ll s = 0;
		for(int i = 0; i < n; i ++) {
			int k = i + 1;
			for(int j = i + 1; j < i + n; j ++) {
				while(xmul(v[i], v[j % n], v[k % n]) <
					xmul(v[i], v[j % n], v[(k + 1) % n])) k ++;
				if(xmul(v[i], v[j % n], v[k % n]) > s) {
					s = xmul(v[i], v[j % n], v[k % n]);
					ans = {v[i], v[j % n], v[k % n]};
				}
			}
		}
		for(int i = 0; i < 3; i ++)
			(ans[i] + ans[(i + 1) % 3] - ans[(i + 2) % 3]).w();
	}
	return 0;
}

