int getlen(int x) {
  if (x == 0) {
    return 1;
  }
  int res = 0;
  while (x) {
    x /= 7;
    ++res;
  }
  return res;
}

bool check(LL x, int len) {
  vis = 0;
  while (len--) {
    if (vis & (1 << (x % 7))) {
      return false;
    }
    vis |= 1 << (x % 7);
    x /= 7;
  }
  return true;
}

