#include<bits/stdc++.h>

using namespace std;

int n;

typedef long long ll;

const int SIZE =100005;

struct node {
    ll x, y, z;
    void in() {
        scanf("%I64d%I64d%I64d",&x,&y,&z);
    }
} a[SIZE];

typedef pair<ll,ll> p;

struct equation {
    pair<ll, ll> S;
    pair<ll, ll> a;
    pair<ll, ll> b;
    pair<ll, ll> c;
};

equation operator+(const equation& e1, const equation& e2) {
    equation res;
    res.S = {max(e1.S.first, e2.S.first), min(e1.S.second, e2.S.second)};
    res.a = {max(e1.a.first, e2.a.first), min(e1.a.second, e2.a.second)};
    res.b = {max(e1.b.first, e2.b.first), min(e1.b.second, e2.b.second)};
    res.c = {max(e1.c.first, e2.c.first), min(e1.c.second, e2.c.second)};
    return res;
}

node get_solution(const equation& eq) {
    if ((eq.S.first > eq.S.second)
     or (eq.a.first > eq.a.second)
     or (eq.b.first > eq.b.second)
     or (eq.c.first > eq.c.second))
        return node {INT64_MAX, INT64_MAX, INT64_MAX};

     if ((eq.a.first + eq.b.first + eq.c.first > eq.S.second)
     or (eq.a.second + eq.b.second + eq.c.second < eq.S.first))
        return node {INT64_MAX, INT64_MAX, INT64_MAX};

     node res;
     res.x = eq.a.first;
     res.y = eq.b.first;
     res.z = eq.c.first;
     ll delta = max(ll(0), eq.S.first - res.x - res.y - res.z);

     res.x += min(delta, eq.a.second - eq.a.first);
     delta -= min(delta, eq.a.second - eq.a.first);
     res.y += min(delta, eq.b.second - eq.b.first);
     delta -= min(delta, eq.b.second - eq.b.first);
     res.z += min(delta, eq.c.second - eq.c.first);
     delta -= min(delta, eq.c.second - eq.c.first);
     return res;
}

ll DIV2(ll arg) {
    return (arg - (arg & 1)) / 2;
    //return arg >> 1;
}

node can(ll MAXANS) {
    equation eq;
    eq.S = eq.a = eq.b = eq.c = {-INT64_MAX, INT64_MAX};
    //printf("%I64d %I64d\n",eq.S.first,eq.S.second);
    for(int i = 1; i <= n; i++) {
        node crd = a[i];
        equation nw;
        nw.S = p( crd.x + crd.y + crd.z - MAXANS,  crd.x + crd.y + crd.z + MAXANS);
        nw.a = p(-crd.x + crd.y + crd.z - MAXANS, -crd.x + crd.y + crd.z + MAXANS);
        nw.b = p( crd.x - crd.y + crd.z - MAXANS,  crd.x - crd.y + crd.z + MAXANS);
        nw.c = p( crd.x + crd.y - crd.z - MAXANS,  crd.x + crd.y - crd.z + MAXANS);
        //对于每个平面确定一个线性规划方程：
        //x + y + z >= a.x + a.y + a.z - r && x + y + z <= a.x + a.y + a.z + r
        //-x + y + z >= -a.x + a.y + a.z - r && -x + y + z <= -a.x + a.y + a.z + r
        //x - y + z >= a.x - a.y + a.z - r && x - y + z <= a.x - a.y + a.z + r
        //x + y - z >= a.x + a.y - a.z - r && x + y - z <= a.x + a.y - a.z + r

        eq = eq + nw;

     //   printf("%I64d %I64d\n",eq.S.first,eq.S.second);
    }
   // printf("%I64d %I64d\n",eq.S.first,eq.S.second);
    for (ll r = 0; r <= 1; ++r) {
        equation tr = eq;

        tr.S.first  = DIV2(tr.S.first - 3 * r + 1);
        tr.a.first  = DIV2(tr.a.first - r + 1);
        tr.b.first  = DIV2(tr.b.first - r + 1);
        tr.c.first  = DIV2(tr.c.first - r + 1);

        tr.S.second = DIV2(tr.S.second - 3 * r);
        tr.a.second = DIV2(tr.a.second - r);
        tr.b.second = DIV2(tr.b.second - r);
        tr.c.second = DIV2(tr.c.second - r);

        node sol = get_solution(tr);
        if (sol.x != INT64_MAX) {
            node ans;
            ans.x = r + sol.y + sol.z;
            ans.y = r + sol.x + sol.z;
            ans.z = r + sol.x + sol.y;

            return ans;
        }
    }

    return node {INT64_MAX, INT64_MAX, INT64_MAX};
}
