        ll l = -1;
        ll r =  3 * 1000000000LL * 1000000000LL + 10;
        while(r - l > 1) {
            ll m = l + (r - l) / 2;
            if(can(m).x != INT64_MAX) {
                r = m;
            } else {
                l = m;
            }
        }

        node res = can(r);
        printf("%I64d %I64d %I64d\n",res.x,res.y,res.z);
    }
    return 0;
}

