vector<int> T[MAXM << 2], res;

inline int find(int x) {
	if(!fa[x]) return x;
	int f = find(fa[x]);
	val[x] ^= val[fa[x]];
	return fa[x] = f;
}

inline bool Merge(int i, vector<int>& o) {
	int u = s[i].u, v = s[i].v, fu = find(u), fv = find(v);
	if(fu != fv) {
		val[fv] = val[u] == val[v];
		fa[fv] = fu;
		o.push_back(i);
		return true;
	}
	if(val[u] == val[v]) { o.push_back(i); return false; }
	return true;
}

inline vector<int> Merge(vector<int> L, vector<int> R) {
	int p = 0, q = 0;
	memset(fa, 0, sizeof fa);
	memset(val, 0, sizeof val);
	vector<int> o;
	bool flag = true;
	while(flag && p < L.size() && L[p] != -1 && q < R.size() && R[q] != -1)
		if(s[L[p]].w > s[R[q]].w) flag = Merge(L[p++], o);
		else flag = Merge(R[q++], o);
	while(flag && p < L.size() && L[p] != -1) flag = Merge(L[p++], o);
	while(flag && q < R.size() && R[q] != -1) flag = Merge(R[q++], o);
	if(flag) o.push_back(-1);
	return o;
}

#define lson o << 1, l, mid
#define rson o << 1 | 1, mid + 1, r
inline void build(int o, int l, int r) {
	if(l == r) {
		T[o].push_back(l);
		T[o].push_back(-1);
		return;
	}
	int mid = l + r >> 1;
	build(lson); build(rson);
	T[o] = Merge(T[o << 1], T[o << 1 | 1]);
}

int L, R;
inline vector<int> Query(int o, int l, int r) {
	if(L <= l && R >= r) return T[o];
	int mid = l + r >> 1;
	if(R <= mid) return Query(lson);
	if(L > mid) return Query(rson);
	return Merge(Query(lson), Query(rson));
}

