vector<vector<int> > P;
vector<int> H;

int lca(int u, int v) {
    if (H[u]<H[v]) swap(u, v);
    for (int i=(int)P.size()-1; i>=0; i--) if (H[P[i][u]]>=H[v]) u=P[i][u];
    if (u==v) return u;
    for (int i=(int)P.size()-1; i>=0; i--) if (P[i][u]!=P[i][v]) {
        u=P[i][u];
        v=P[i][v];
    }
    return P[0][u];
}

int dist(int u, int v) {
    return H[u]+H[v]-2*H[lca(u, v)];
}

