class tree {
 private:
  long long vertices;
  std::list<long long>* adj;
  long long* degree;

 public:
  tree(long long vertices) {
    this->vertices = vertices;
    adj = new std::list<long long>[vertices];
    degree = new long long[vertices];
    for (long long i = 0; i < vertices; i++) degree[i] = 0;
  }

  void addEdge(long long a, long long b) {
    degree[a-1] = degree[a-1] + 1;
    degree[b-1] = degree[b-1] + 1;
    adj[a-1].push_back(b-1);
    adj[b-1].push_back(a-1);
    return;
  }

  long long calculate_path(){
    long long i,count = 0;
    std::list<long long>::iterator it;
    for(i = 0;i < vertices; i++){
      for (it = adj[i].begin(); it != adj[i].end(); it++)
        count = count + degree[*it] - 1;
    }
    return count/2;
  }

};

int main() {
  long long  n,a,b;
  std::cin >> n;
  tree mytree(n);
  for (long long i = 0; i < n - 1; i++){
    std::cin>>a>>b;
    mytree.addEdge(a,b);
  } 
  std::cout<<mytree.calculate_path()<<std::endl;
  return 0;
}

