const long long modulo = 1e6 + 3;

long long f[modulo], n, c, cc[100][100];

long long pow(long long a, long long b){
	if (!b){
		return 1;
	}

	if (b & 1){
		return (pow(a, b - 1) * a) % modulo;
	}

	long long res = pow(a, b >> 1);
	return (res * res) % modulo;
}

long long cnt(int n, int m){
	return (f[n]  *  pow((f[m]  * f[n - m]) % modulo, modulo - 2)) % modulo;
}

int main(){
	f[0] = 1;
	for (int i = 1; i < modulo; ++i){
		f[i] = (f[i - 1] * i) % modulo;
	}

	cin >> n >> c;
	long long ans = 0;
	for (int i = 1; i <= n; ++i){
		ans += cnt(c + i - 1, i);
		ans %= modulo;
	}

	cout << ans << "\n";
	return 0;
}

