const int mod=1e9+7;
int matsz;
typedef long long ll;
unsigned long long mod2=mod*mod;
typedef vector<vector<ll> > matrix;
ll arr[110];
matrix matmult(matrix A,matrix B)
{
	matrix ret(matsz,vector<ll>(matsz));
	for(int i=0;i<matsz;i++)
		for(int j=0;j<matsz;j++)
		{
			for(int k=0;k<matsz;k++)
			{
				ret[i][j]+=(A[i][k]*B[k][j]);
				ret[i][j]%=mod;
			}
		}
			
	return ret;
}
matrix matexpo(matrix A,ll b)
{
	matrix ret(matsz,vector<ll>(matsz));
	for(int i=0;i<matsz;i++)
		ret[i][i]=1;
	while(b)
	{
		if(b%2)
			ret=matmult(ret,A);
		A=matmult(A,A);
		b/=2;
	}
	return ret;
}
int main() {
	int n;
	ll k;
	cin>>n>>k;
	matsz=n;
	for(int i=0;i<n;i++)
		cin>>arr[i];
	matrix F(matsz,vector<ll>(matsz));
	for(int i=0;i<n;i++)
		for(int j=0;j<n;j++)
			if(__builtin_popcountll(arr[i]^arr[j])%3==0)
                    F[i][j]=1;
	
	F=matexpo(F,k-1);
	ll ans=0;
		
	for(int i=0;i<matsz;i++)
		for(int j=0;j<matsz;j++)
		{
			ans+=F[i][j];
			ans%=mod;
		}
	cout<<ans<<"\n";
	return 0;
}

