#include <bits/stdc++.h>

using namespace std;

map <__int64, __int64> mapp;

int findc(__int64 num)
{
    int ans = 0;
    while(num > 0)
    {
        ans++;
        num = num >> 1;
    }
    return ans;
}

int main()
{
    int n;
    scanf("%d", &n);
    for(int i = 0; i < n; i++)
    {
        int type;
        __int64 v, u, w;
        scanf("%d", &type);
        scanf("%I64d%I64d", &v, &u);
        if(u > v)
            swap(u, v);
        if(type == 1)
        {
            scanf("%I64d", &w);
            int c1 = findc(u);
            int c2 = findc(v);
            while(c2 > c1)
            {
                mapp[v] += w;
                v = v >> 1;
                c2--;
            }
            while(u != v)
            {
                mapp[v] += w;
                mapp[u] += w;
                u = u >> 1;
                v = v >> 1;
            }
        }
        else
        {
            __int64 ans = 0;
            int c1 = findc(u);
            int c2 = findc(v);
            while(c2 > c1)
            {
                ans += mapp[v];
                v = v >> 1;
                c2--;
            }
            while(u != v)
            {
                ans += mapp[v];
                ans += mapp[u];
                u = u >> 1;
                v = v >> 1;
            }
            printf("%I64d\n", ans);
        }
    }
}

