LL pow_mod( LL a , LL b , LL p = MOD)//a^b % p  
{  
	LL r = 1 ;  
	a %= p ;
	while( b )  
	{  
		if( b&1 ) r = r*a%p ;  
		b >>= 1 ;  
		a = a*a%p ;  
	}  
	return r ;  
}

