typedef double R;
typedef complex<R> C;

const R eps = 1e-9;

bool eq(R r1, R r2) { return fabs(r1 - r2) < eps; }

bool eq(C c1, C c2) { return eq(c1.real(), c2.real()) and eq(c1.imag(), c2.imag()); }

R dot(C c1, C c2) { return c1.real() * c2.real() + c1.imag() * c2.imag();}
R det(C c1, C c2) { return c1.real() * c2.imag() - c1.imag() * c2.real();}

struct line{
    C n;
    R c;
    line(C n1, R c1)
        :n{n1 / abs(n1)}, c{c1} {}

    line(C p1, C p2)
        :n{((p2 - p1) / abs(p2 - p1)) * C(0, 1)}, c{dot(p1, n)} {}

    C dir() const { return n * C(0, 1); }

    C val(R t) const { return c * n + t * dir();}

    R tintersect(const line& other, bool& ok) const {
        ok = !eq(det(n, other.n), 0);
        if(ok) {
            return (other.c - c * dot(n, other.n)) / dot(dir(), other.n);
        } else {
            return 0;
        }
    }
};

C intersect(const line& a, const line& b, bool& ok) { return a.val(a.tintersect(b, ok)); }

R dist(const line& l, const C& p) { return fabs(dot(p, l.n) - l.c); }

struct seg{
    line l;
    R start, end;

    seg(C p1, C p2)
        :l{p1, p2}, start{dot(l.dir(), p1)}, end{dot(l.dir(), p2)} {}


    C p1() const { return l.val(start); }
    C p2() const { return l.val(end); }

    R len() const { return fabs(end - start); }

	bool okt(R t) const { return eq(fabs(t - start) + fabs(t - end), len()); }
};

C intersect(const seg& s1, const seg& s2, bool& ok) {
	R t1 = s1.l.tintersect(s2.l, ok), t2 = s2.l.tintersect(s1.l, ok);
	ok &= (s1.okt(t1) and s2.okt(t2));
	return s1.l.val(t1);
}

C intersect(const seg& s, const line& l, bool& ok) {
	R t = s.l.tintersect(l, ok);
	ok &= s.okt(t); return s.l.val(t);
}


int n;
vector<C> polygon;

bool check_r( R radius, C& candB, C& candL) {
    int i1 = 2, m = 0;
    vector<int> best(n);
    vector<C> cand(n);
    rep(i, 0, n) {
        cand[i] = polygon[i + 1];
    }
    rep(i, 0, n) {
        /* cout << endl << i << polygon[i] << " " << polygon[i + 1] << endl; */
        i1 = max(i1, i + 2);
        m = max(m, i);
        best[i] = i1 - i;
        line l1(polygon[i], polygon[i + 1]);
        while(i1 != i + n) {
            /* cout << i1 << " " << polygon[i1] << " " << polygon[i1 + 1] << endl; */
            line l2(polygon[i1], polygon[i1 + 1]);
            if(det(polygon[i + 1] - polygon[i], polygon[i1 + 1] - polygon[i1]) < eps) {
                break;
            }
            /* cout << "l1 " << l1.val(0) << " " << l1.dir() << endl; */
            /* cout << "l2 " << l2.val(0) << " " << l2.dir() << endl; */
            bool ok;
            C temp = intersect(l1, l2, ok);
            /* cout << "temp =" << temp << endl; */
            C u1 = polygon[i] - polygon[i + 1], u2 = polygon[i1 + 1] - polygon[i1];
            u1 /= abs(u1); u2 /= abs(u2);
            /* cout << "other point =" << temp + (u1 + u2) / 2.0 << endl; */
            line bisect(temp, temp + (u1 + u2) / 2.0);
            /* cout << bisect.val(0) << " " << bisect.val(1) << endl; */
            /* cout << "middle " << m << " " <<  polygon[m] << " " << polygon[m + 1] << endl; */
            bool slint = false;
            while(true) {
                intersect(seg(polygon[m], polygon[m + 1]), bisect, slint);
                if(!slint) {
                    m++;
                } else {
                    break;
                }
            }
            C cross = intersect(seg(polygon[m], polygon[m + 1]), bisect, ok);
            /* cout << "intersection " << cross << endl; */
            /* cout << "distances " << dist(l1, cross) << " " << dist(l2, cross) << endl; */
            if(max(dist(l1, cross), dist(l2, cross)) < radius) {
                i1++;
                best[i] = i1 - i;
                cand[i] = cross;
            } else {
                break;
            }
        }
    }
    /* cout << endl; */
    rep(i, 0, n) {
        /* cout << i << " " << best[i] << endl; */
        if(best[i] + best[(i + best[i]) % n] >= n) {
            candB = cand[i]; candL = cand[(i + best[i]) % n];
            return true;
        }
    }
    return false;
}

