using namespace std;
typedef long long ll;
const ll p = 1e9 + 7;

ll mult(ll a, ll b) {
    return a * b % p;
}

ll add(ll a, ll b) {
    a += b;
    if (a >= p)
        a -= p;
    return a;
}

ll sub(ll a, ll b) {
    a -= b;
    if (a < 0)
        a += p;
    return a;
}

ll binPow(ll a, ll x) {
    if (x == 0)
        return 1;
    ll ans = binPow(a, x / 2);
    ans = mult(ans, ans);
    if (x % 2 == 1)
        ans = mult(ans, a);
    return ans;
}

