	if(ll==rr)return;
	int mm=ll+rr>>1;
	if(pos<=mm)ins(l[v],l[u],ll,mm,pos);
		else ins(r[v],r[u],mm+1,rr,pos);
}

bool Qs(int u,int ll,int rr){
	if(!t[u])return 0;
	if(L<=ll && rr<=R)return 1;
	int mm=ll+rr>>1;bool res=0;
	if(L<=mm)res=Qs(l[u],ll,mm);
	if(R>mm)res=res || Qs(r[u],mm+1,rr);
	return res;
}

