void down(int x)
{
	if(t[x].lz1 || t[x].lz2)
	{
		t[x].d+=t[x].lz1;
		t[x].ans+=t[x].lz2;
		if(t[x].son[0]) t[t[x].son[0]].lz1+=t[x].lz1,t[t[x].son[0]].lz2+=t[x].lz2;
		if(t[x].son[1]) t[t[x].son[1]].lz1+=t[x].lz1,t[t[x].son[1]].lz2+=t[x].lz2;
		t[x].lz1=t[x].lz2=0;
	}
}
void rot(int x,int f1,int t1)
{
	int f2=t[f1].fa,t2=(t[f2].son[1]==f1);
	t[f1].son[t1]=t[x].son[t1^1];
	t[t[f1].son[t1]].fa=f1;
	
	t[f2].son[t2]=x;
	t[x].fa=f2;
	
	t[x].son[t1^1]=f1;
	t[f1].fa=x;
}
void splay(int x,int aim)
{
	while(t[x].fa!=aim)
	{
		int f1=t[x].fa,t1=(t[f1].son[1]==x),f2=t[f1].fa,t2=(t[f2].son[1]==f1);
		down(f2);down(f1);down(x);
		if(f2==aim) rot(x,f1,t1);
		else if(t1==t2) rot(f1,f2,t2),rot(x,f1,t1);
		else rot(x,f1,t1),rot(x,f2,t2);
	}
	down(x);
}
int insert(int st,int y)
{
	if(st==0) return y;
