typedef long long ll;

constexpr int MAX_N = 200200;
constexpr int MOD = 1000000007;

using namespace std;

int n;
int nxt[MAX_N];
bool vis[MAX_N];
bool vis1[MAX_N];
int depth[MAX_N];

vector<int> adj[MAX_N];

int comp[MAX_N];
int comp_sz[MAX_N];
int done[MAX_N];

int pow(int b, int e) {
    if (e == 0) return 1;
    ll res = pow(b, e >> 1);
    res = (res * res) % MOD;
    if (e & 1) res = (res * b) % MOD;
    return (int) res;
}

void dfs1(int u, int p, int c) {
    if (vis1[u]) return;
    vis1[u] = true;
    comp[u] = c;
    comp_sz[c]++;
    for (int v : adj[u]) {
        if (v != p) {
            dfs1(v, u, c);
        }
    }
}

int dfs(int u, int d) {
    if (vis[u]) return d - depth[u];
    vis[u] = true;
    depth[u] = d;
    return dfs(nxt[u], d + 1);
}

