    scanf(" %d", &n);
    for (int i = 1; i <= n; i++) {
        scanf(" %d", &nxt[i]);
        adj[i].push_back(nxt[i]);
        adj[nxt[i]].push_back(i);
    }

    int cc = 0;
    for (int i = 1; i <= n; i++) {
        if (!vis1[i]) {
            dfs1(i, i, ++cc);
        }
    }

    ll ans = 1;
    for (int i = 1; i <= n; i++) {
        if (done[comp[i]]) continue;
        done[comp[i]] = true;
        int cyc = dfs(i, 0);
        // Must change some subset of the cycle edges
        ll num = (pow(2, cyc) - 2 + MOD) % MOD;
        num = (num * pow(2, comp_sz[comp[i]] - cyc)) % MOD;
        ans = (ans * num) % MOD;
    }

    printf("%lld\n", ans);

    return 0;
}

