struct node{double p1,p2;int lc,rc,l,r;}lt[2*N];
int n,m,tl;
double p[N];
void upd(int now)
{
	int lc=lt[now].lc,rc=lt[now].rc;
	double l1=lt[lc].p1,l2=lt[lc].p2,r1=lt[rc].p1,r2=lt[rc].p2,p1,p2;
	p1=l1*r1/(1-(1-r1)*l2);
	p2=r2+l2*(1-r2)*r1/(1-(1-r1)*l2);
	lt[now].p1=p1;lt[now].p2=p2;
}
void bt(int l,int r)
{
	int now=++tl;
	lt[now].l=l;lt[now].r=r;
	if(l<r)
	{
		int mid=(l+r)/2;
		lt[now].lc=tl+1;bt(l,mid);
		lt[now].rc=tl+1;bt(mid+1,r);
		upd(now);
	}
	else lt[now].p1=p[l],lt[now].p2=p[l];
}
void change(int now,int k,double p)
{
	int lc=lt[now].lc,rc=lt[now].rc,mid=(lt[now].l+lt[now].r)/2;
	if(lt[now].l==lt[now].r) {lt[now].p1=p;lt[now].p2=p;return;}
	if(mid>=k) change(lc,k,p);
	else change(rc,k,p);
	upd(now);
}
void find(int now,int l,int r,double &p1,double &p2)
{
	int lc=lt[now].lc,rc=lt[now].rc,mid=(lt[now].l+lt[now].r)/2;
	if(lt[now].l==l && lt[now].r==r) {p1=lt[now].p1;p2=lt[now].p2;return;}
	if(mid>=r) find(lc,l,r,p1,p2);
	else if(l>mid) find(rc,l,r,p1,p2);
	else
	{
		double l1,l2,r1,r2;
		find(lc,l,mid,l1,l2);
		find(rc,mid+1,r,r1,r2);
		p1=l1*r1/(1-(1-r1)*l2);
		p2=r2+l2*(1-r2)*r1/(1-(1-r1)*l2);
	}
}
