int n, m;
int a[MAXN][MAXM];
int f[MAXN][MAXM][LOGM];
int g[MAXM][LOGM][MAXN][LOGN];

void build() {
	for (int k = 1; k <= n; k++) {
		for (int j = 1; 1 << j <= m; j++) {
			for (int i = 0; i + (1 << j) - 1 <= m; i++) {
				f[k][i][j] = max(f[k][i][j - 1], f[k][i + (1 << (j - 1))][j - 1]);
			}
		}
	}
	for (int k = 1; k <= m; k++) {
		for (int l = 0; k + (1 << l) - 1 <= m; l++) {
			for (int i = 1; i <= n; i++) {
				g[k][l][i][0] = f[i][k][l];
			}
			for (int j = 1; 1 << j <= n; j++) {
				for (int i = 0; i + (1 << j) - 1 <= n; i++) {
					g[k][l][i][j] = max(g[k][l][i][j - 1], g[k][l][i + (1 << (j - 1))][j - 1]);
				}
			}
		}
	}
}
int query(int i, int j, int a, int b) {
	int lga = __lg(a);
	int lgb = __lg(b);
	int res = g[j][lgb][i][lga];
	res = max(res, g[j + b - (1 << (lgb))][lgb][i + a - (1 << (lga))][lga]);
	res = max(res, g[j][lgb][i + a - (1 << (lga))][lga]);
	res = max(res, g[j + b - (1 << (lgb))][lgb][i][lga]);
	return res;
}

void solve() {
	scanf("%d%d", &n, &m);
	FOR(i, 1, n + 1) FOR(j, 1, m + 1) scanf("%d", &a[i][j]);
	FOR(i, 1, n + 1) FOR(j, 1, m + 1) {
		if (a[i][j]) {
			f[i][j][0] = min(f[i - 1][j - 1][0], min(f[i - 1][j][0], f[i][j - 1][0])) + 1;
		}
	}
	build();
	int q; scanf("%d", &q);
	while (q--) {
		int x[2], y[2];
		FOR(i, 0, 2) scanf("%d%d", x + i, y + i);
		int lo = 0, hi = min(x[1] - x[0] + 1, y[1] - y[0] + 1);
		while (lo < hi) {
			int mi = lo + hi + 1 >> 1;
			if (query(x[0] + mi - 1, y[0] + mi - 1, x[1] - x[0] - mi + 2, y[1] - y[0] - mi + 2) >= mi) {
				lo = mi;
			}
			else {
				hi = mi - 1;
			}
		}
		cout << lo << "\n";
	}
}

