                wrap = R - mid + 1;
                dp[0] = 1;
                p = 1;
            }
            else
            {
                if (b[1] >= mid)
                    continue;
                wrap = R + b[1] - mid + 1;
                dp[0] = INT_MIN;
                dp[1] = mid;
                p = 2;
            }

            for (; p < N; p++)
            {
                if (dp[p - 1] >= b[p])
                    dp[p] = b[p] + mid;
                else if (p >= 2 && dp[p - 2] > b[p] - mid)
                    dp[p] = max(b[p] + 1, b[p - 1] + mid);
                else if (dp[p - 1] > b[p] - mid)
                    dp[p] = b[p] + 1;
                else
                    break;
            }
            if (p == N && dp[N - 1] >= wrap)
                good = true;
        }
        if (good)
            hi = mid;
        else
            lo = mid;
   }

    cout << hi - 1 << '\n';
    return 0;
}

