namespace solve {
const int maxn = 100005;
int n, u[maxn], v[maxn];
int64_t mod, w[maxn], phi_mod;

vector<int> g[maxn];
int64_t ans = 0, pow10[maxn], inv_pow10[maxn];

bool centroid[maxn];
int sizes[maxn];
map<int64_t, int> cur[maxn], tot;
int level = 0;
bool used_l[maxn];

int64_t phi(int64_t n) {
  int64_t result = n;
  for (int64_t i = 2; i * i <= n; ++i)
    if (n % i == 0) {
      while (n % i == 0) n /= i;
      result -= result / i;
    }
  if (n > 1) result -= result / n;
  return result;
}

int64_t binpow(int64_t a, int64_t n, int64_t m) {
  int64_t res = 1;
  while (n) {
    if (n & 1) res = res * a % m;
    a = a * a % m;
    n >>= 1;
  }
  return res;
}

int64_t inv(int64_t a, int64_t m) { return binpow(a, phi_mod - 1, m); }

void find_sizes(int v1, int prev) {
  sizes[v1] = 1;
  for (int e : g[v1]) {
    int to = u[e] == v1 ? v[e] : u[e];
    if (to != prev && !centroid[to]) {
      find_sizes(to, v1);
      sizes[v1] += sizes[to];
    }
  }
}

int find_centroid(int v1, int prev, int sz) {
  for (int e : g[v1]) {
    int to = u[e] == v1 ? v[e] : u[e];
    if (to != prev && !centroid[to] && sizes[to] > sz / 2)
      return find_centroid(to, v1, sz);
  }
  return v1;
}

void fill_cur(int v1, int prev, int root, int64_t f, int h) {
  if (root != -1) {
    cur[root][f] += 1;
    tot[f] += 1;
  }
  for (int e : g[v1]) {
    int to = u[e] == v1 ? v[e] : u[e];
    if (to != prev && !centroid[to]) {
      if (root == -1) cur[to].clear();
      fill_cur(to, v1, root == -1 ? to : root,
               (w[e] * pow10[h] % mod + f) % mod, h + 1);
    }
  }
}

void add_ans(int v1, int prev, int root, int64_t b, int h) {
  // Z * 10^h + b == 0
  // Z = (mod - b) * inv(10^h, mod)

  if (h != 0 && b == 0) ans += 1;

  int64_t need = h == 0 ? 0 : ((mod - b) * inv_pow10[h - 1] % mod);
  int cnt = 0;

  auto it = tot.find(need);
  if (it != tot.end()) cnt += it->second;
  if (root != -1) {
    it = cur[root].find(need);
    if (it != cur[root].end()) cnt -= it->second;
  }
  ans += cnt;

  for (int e : g[v1]) {
    int to = u[e] == v1 ? v[e] : u[e];
    if (to != prev && !centroid[to]) {
      add_ans(to, v1, root == -1 ? to : root, (b * 10 % mod + w[e]) % mod,
              h + 1);
    }
  }
}

void process(int root, int sz, int lvl = 0) {
  if (!used_l[lvl]) {
    used_l[lvl] = true;
    for (int i = 0; i < n; ++i) {
      cur[i].clear();
      sizes[i] = 0;
    }
    tot.clear();
  }
  find_sizes(root, -1);
  int c = find_centroid(root, -1, sz);

  find_sizes(c, -1);
  tot.clear();

  fill_cur(c, -1, -1, 0, 0);
  add_ans(c, -1, -1, 0, 0);

  //  cout << "centroid " << c << " ans = " << ans << '\n';

  centroid[c] = true;

  for (int e : g[c]) {
    int to = u[e] == c ? v[e] : u[e];
    if (!centroid[to]) process(to, sizes[to], lvl + 1);
  }
}

