LL K,l,r,comb[210][210],coef[210],aux[210]; magic_nr r1,r2,sr5;

LL fpow(LL nr, LL put){
    LL res=1;
    nr%=prim;
    while (put){
        if (put&1) res=(res*nr)%prim;
        nr=(nr*nr)%prim;
        put>>=1;
    }
    return res;
}

LL inv(LL nr){
    return fpow(nr,prim-2);
}

magic_nr neg(magic_nr x){
    x.a=-x.a,x.b=-x.b;
    return x;
}

magic_nr sum(magic_nr x, magic_nr y){
    x.a=(x.a+y.a)%prim;
    x.b=(x.b+y.b)%prim;
    return x;
}

magic_nr prodc(LL c, magic_nr x){
    c%=prim;
    x.a=(c*x.a)%prim;
    x.b=(c*x.b)%prim;
    return x;
}

magic_nr prod(magic_nr x, magic_nr y){
    magic_nr res;
    res.a=(x.a*y.a+(5*(x.b*y.b)%prim)%prim)%prim;
    res.b=(x.a*y.b+x.b*y.a)%prim;
    return res;
}

magic_nr inv(magic_nr x){
    magic_nr res;
    LL aux=(x.a*x.a-(5*(x.b*x.b)%prim)%prim)%prim;
    if (aux<0) aux+=prim;
    res.a=x.a,res.b=(prim-x.b)%prim;
    aux=inv(aux);
    res=prodc(aux,res);
    return res;
}

magic_nr fpow(magic_nr x, LL put){
    magic_nr res(1,0);
    while (put){
        if (put&1) res=prod(res,x);
        x=prod(x,x);
        put>>=1;
    }
    return res;
}

LL power_sum(LL r, LL put){
    LL i; magic_nr f,s,produs,aux,res(0,0);

    for (i=0; i<=put; i++){
        f=fpow(r1,i),s=fpow(r2,put-i);
        produs=prod(f,s); aux=produs;
        if ((produs.a-1)%prim==0 && produs.b==0) produs=magic_nr((r+1)%prim,0);
        else {
            produs=sum(fpow(produs,r+1),magic_nr(-1,0));
            produs=prod(produs,inv(sum(aux,magic_nr(-1,0))));
        }
        if ((put-i)%2) produs=prodc(-comb[put][i],produs);
        else produs=prodc(comb[put][i],produs);
        res=sum(res,produs);

    }

    res=prod(res,fpow(sr5,put));
    res=prodc(fpow(inv(5),put),res);
    if (res.b!=0) cout << "wtf\n";
    return res.a;
}

