#define se second

using namespace std;

typedef pair<int,int> pi;

const int maxn = 1000005,mo = int(1e9) + 7;

struct node
{
	int sum;bool zero;
}t[maxn * 4];

multiset<int> block;
vector<pi> in[maxn],out[maxn];
vector<int> val[maxn];
int n,m,k;

void mark(int jd)
{
	t[jd].sum = 0;
	t[jd].zero = 1;
}

void change(int l,int r,int p,int v,int jd)
{
	if (l == r) t[jd].sum = v; else
	{
		int mid = l + r >> 1;
		if (t[jd].zero) mark(jd << 1),mark(jd << 1 | 1),t[jd].zero = 0;
		if (p <= mid) change(l,mid,p,v,jd << 1); else change(mid + 1,r,p,v,jd << 1 | 1);
		t[jd].sum = (t[jd << 1].sum + t[jd << 1 | 1].sum) % mo;
	}
}

int query(int l,int r,int i,int j,int jd)
{
	if (j < l || i > r) return 0;
	if (i <= l && r <= j) return t[jd].sum;
	int mid = l + r >> 1;
	if (t[jd].zero) mark(jd << 1),mark(jd << 1 | 1),t[jd].zero = 0;
	return (query(l,mid,i,j,jd << 1) + query(mid + 1,r,i,j,jd << 1 | 1)) % mo;
}

void make_zero(int l,int r,int i,int j,int jd)
{
	if (j < l || i > r) return;
	if (i <= l && r <= j) mark(jd); else
	{
		int mid = l + r >> 1;
		if (t[jd].zero) mark(jd << 1),mark(jd << 1 | 1),t[jd].zero = 0;
		make_zero(l,mid,i,j,jd << 1),make_zero(mid + 1,r,i,j,jd << 1 | 1);
		t[jd].sum = (t[jd << 1].sum + t[jd << 1 | 1].sum) % mo;
	}
}

int main()
{
	scanf("%d%d%d", &n, &m, &k);
	for(int i = 1;i <= k;i ++)
	{
		int x,y,x1,y1;
		scanf("%d%d%d%d", &x, &y, &x1, &y1);
		in[y].push_back(pi(x,x1));
		out[y1 + 1].push_back(pi(x,x1));
	}
	change(1,n,1,1,1);
	for(int i = 0;i < in[1].size();i ++) block.insert(in[1][i].fe),block.insert(in[1][i].se);
	for(int x = 2;x <= m;x ++)
	{
		sort(in[x].begin(),in[x].end());
		for(int i = 0;i < in[x].size();i ++)
		{
			int r = in[x][i].se + 1,l = 1;
			multiset<int>::iterator it = block.upper_bound(r);
			if (it != block.begin()) it --,l = (*it) + 1;
			if (r <= n) val[x].push_back(query(1,n,l,r,1)); else val[x].push_back(0);
		}
		for(int i = 0;i < in[x].size();i ++)
		{
			int r = in[x][i].se + 1,l = 1;
			multiset<int>::iterator it = block.upper_bound(r);
			if (it != block.begin()) it --,l = (*it) + 1;
			if (r <= n) change(1,n,r,val[x][i],1);
			make_zero(1,n,in[x][i].fe,in[x][i].se,1);
		}
		for(int i = 0;i < in[x].size();i ++)
			block.insert(in[x][i].fe),block.insert(in[x][i].se);
		for(int i = 0;i < out[x].size();i ++)
			block.erase(block.find(out[x][i].fe)),block.erase(block.find(out[x][i].se));
	}
	int l = 1;
	multiset<int>::iterator it = block.upper_bound(n);
	if (it != block.begin()) it --,l = (*it) + 1;
	printf("%d\n", query(1,n,l,n,1));
	return 0;
}

