void calc(int val){

// cout<<"called calc"<<endl;
// cout<<"window: ";for(auto i : window)   cout<<i<<" ";cout<<endl;

    for(int len=1;len<=40;len++)
        remainder_fixed[len].clear();

    int j = 0;
