        while(j < (int)window.size()){
            
            int row = window[j];
            set<ii>::iterator it = pos[row].lower_bound({val, -1});
            int pos = (*it).ss;
            
            bool clash = false;
            for(int len=1;len<=40;len++)
                if(!remainder_fixed[len].empty()){
                    int g = gcd(len, sz[row]);
                    if(pos % g != remainder_fixed[len][0] % g){
                        clash = true;
                        break;
                    }
                }

            if(clash)   break;
            remainder_fixed[sz[row]].pb(pos);
            j++;
        }

        ans[val] = max(ans[val], j-i);

        int row = window[i];
        remainder_fixed[sz[row]].pop_back();
    }
}



