using namespace std;
const int N = 1e5 + 5;

int x[N],y[N];
long long int ans[N];
set <int> setAdd[2*N];
set <int> setDif[2*N];


long long int calc(int curx,int it)
{
    return abs(curx-x[it]);
}

int main()
{
    int n,m,k;
    cin>>n>>m>>k;

    for(int i=1;i<=k;i++)
    {
        cin>>x[i]>>y[i];
        setAdd[x[i]+y[i]].insert(i);
        setDif[x[i]-y[i]+N].insert(i);
        ans[i] = -1;
    }

    int dx = 1;
    int dy = 1;
    int curx = 0;
    int cury = 0;
    long long int curtm = 0;

    for(int i=1;i<=4*N;i++)
    {
        int tm;
        if(dx>0)
            tm = n - curx;
        else
            tm = curx;

        if(dy>0)
            tm = min(tm,m-cury);
        else
            tm = min(tm,cury);

        if(dx*dy==1)
        {
            for(auto it:setDif[curx-cury+N])
            {
                ans[it] = curtm + calc(curx,it);
                setAdd[x[it]+y[it]].erase(it);
            }
            setDif[curx-cury+N].clear();
        }

        else
        {
            for(auto it:setAdd[curx+cury])
            {
                ans[it] = curtm + calc(curx,it);
                setDif[x[it]-y[it]+N].erase(it);
            }
            setAdd[curx+cury].clear();
        }

        int nx = curx + tm * dx;
        int ny = cury + tm * dy;
        int cnt = 0;

        if(nx == n or nx == 0)
        {
            dx *= -1;
            ++cnt;
        }
        if(ny == m or ny == 0)
        {
            dy *= -1;
            ++cnt;
        }

        curtm += tm;
        curx = nx;
        cury = ny;

        // if any of the four corners is reached
        if(cnt==2)
            break;

    }

    for(int i=1;i<=k;i++)
        cout<<ans[i]<<endl;

    return 0;
}

