#include <bits/stdc++.h>
using namespace std;

typedef long long LL;
typedef pair<int, int> PII;
typedef vector<int> VI;

const int N = 200005;

int n;
double l[N], t[N];
LL r;

int bsearch(int L, int R, double ll, int tt) {
  int M;
  double D = 2.0 * (tt - ll);
  while (R - L > 1) {
    M = (L + R) / 2;
    if (D >= M) {
      L = M;
    } else {
      R = M;
    }
  }
  return L;
}

LL toDrink(double L) {
  return (LL)ceil(L / r);
}

vector<LL> sol;
LL K;

bool solve(int pos, LL drinks, double skips, double timeLine) {
  if (pos == n) {
    return drinks <= (int)1e5;
  }
  if (skips >= l[pos]) {
    return solve(pos + 1, drinks, skips - l[pos], timeLine + l[pos]);
  } else {
    l[pos] -= skips;
    t[pos] -= skips;
    timeLine += skips;
    if (l[pos] * 2 <= t[pos]) {
      return solve(pos + 1, drinks, 0, timeLine + l[pos] * 2);
    } else {
      int slow = bsearch(0, t[pos] + 1, l[pos], t[pos]);
      timeLine += slow;
      l[pos] -= slow / 2.0;
      t[pos] -= slow;
      LL curDrinks = toDrink(l[pos]);
      K += curDrinks;
      bool ok = solve(pos + 1, drinks + curDrinks, curDrinks * r - l[pos], timeLine + l[pos]);
      if (ok) {
        LL nTimeLine = timeLine;
        assert(abs(timeLine - nTimeLine) == 0);
        while (curDrinks--) {
          sol.push_back(nTimeLine);
          nTimeLine += r;
        }
      }
      return ok;
    }
  }
  return 0;
}

int main() {
  ios_base::sync_with_stdio(0);
  cin.tie(0);
  cin >> n >> r;
  for (int i = 0; i < n; ++i) {
    cin >> l[i];
  }
  for (int i = 0; i < n; ++i) {
    cin >> t[i];
    if (t[i] < l[i]) {
      cout << "-1";
      return 0;
    }
  }
  if (!solve(0, 0, 0, 0)) {
    cout << K;
  } else {
    assert(K == (int)sol.size());
    cout << K << "\n";
    sort(sol.begin(), sol.end());
    for (auto i : sol) {
      cout << i << " ";
    }
  }
  return 0;
}

