void dfs(int x, int f){
	dep[x] = dep[f] + 1;
	p[x][0] = f;
	for (int i = 1; (1 << i) <= dep[x]; ++i){
		p[x][i] = p[p[x][i - 1]][i - 1];
		//debug("p[%I64d][%I64d] = %I64d\n", x, i, p[x][i]);
		if (E[mx[x][i - 1]].a > E[mx[p[x][i - 1]][i - 1]].a)
			mx[x][i] = mx[x][i - 1];
		else mx[x][i] = mx[p[x][i - 1]][i - 1];
		//debug("mx[%I64d][%I64d] = %I64d, %I64d with %I64d\n", x, i, E[mx[x][i]].u, E[mx[x][i]].v, E[mx[x][i]].a);
	}
