		mx[g[x][i]][0] = id[x][i];
		dfs(g[x][i], x);
	}
}

int lca(int x, int y){
	if (dep[x] < dep[y]) swap(x, y);
	int dt = dep[x] - dep[y];
	for (int i = 0; i <= 20; ++i)
		if (dt & (1 << i)) x = p[x][i];
	if (x == y) return x;
	for (int i = 20; i >= 0; --i)
		if (p[x][i] != p[y][i]){
			x = p[x][i];
			y = p[y][i];
		}
	return p[x][0];
}

int query(int x, int y, int z){
	int dt = dep[x] - dep[z];
	int res = 0;
	for (int i = 0; i <= 20; ++i)
		if (dt & (1 << i)){
			if (E[mx[x][i]].a > E[res].a)
				res = mx[x][i];
			x = p[x][i];
		}
	dt = dep[x = y] - dep[z];
	for (int i = 0; i <= 20; ++i)
		if (dt & (1 << i)){
			if (E[mx[x][i]].a > E[res].a)
				res = mx[x][i];
			x = p[x][i];
		}
	return res;
}

