class TaskA {
public:
	void solve(std::istream& in, std::ostream& out) {
		int n, k, s, t;
		in >> n >> k >> s >> t;
		vector<pair<int, int>> v(n);
		for(int i: range(n)) {
			in >> v[i].first >> v[i].second;
		}

		vector<int> p(k + 2);
		for (int i: inclusiveRange(1, k)) {
			in >> p[i];
		}
		p.back() = s;

		sort(p);

		auto can = [&](int tank) {
			int needTime = 0;
			for (int i: range(1, (int)p.size())) {
				int d = p[i] - p[i - 1];
				if (tank < d) {
					return false;
				}
				if (tank >= 2 * d) {
					needTime += d;
				} else {
					needTime += (2 * d - tank) + d;
				}
			}
			return needTime <= t;
		};

		if (!can(1000000000)) {
			out << -1;
			return;
		}

		int l = 0, r = 1000000000;
		while (r - l > 1) {
			int m = (l + r) / 2;
			if (can(m)) {
				r = m;
			} else {
				l = m;
			}
		}


		int ans = std::numeric_limits<int>::max();
		bool found = false;

		for (int i: range(n)) {
			if (v[i].second >= r) {
				ans = min(ans, v[i].first);
				found = true;
			}
		}

		if (!found) {
			out << -1;
			return;
		}

		out << ans << "\n";
	}
};


