int dfs(int u) {
    if (u == DST) {
        return 1;
    }
    if (vis[u]) {
        return 0;
    }
    vis[u] = true;
    for (int i = 0; i < MAX_M; i++) {
        if (f[u][i] < c[u][i] && dfs(i)) {
            f[u][i]++;
            f[i][u]--;
            return 1;
        }
    }
    return 0;
}

bool match(pair<int, int> a, pair<int, int> b) {
    if (b.first >= 0 && b.first != a.first) {
        return false;
    }
    if (b.second >= 0 && b.second != a.second) {
        return false;
    }
    return true;
}

bool try_solve() {
