        for (int j = 0; j < n; j++) {
            if (rim[j] >= 0) {
                continue;
            }
            if (hypo[i].first == precycle[j] && hypo[i].second == cycle[j]) {
                im[i] = j;
                rim[j] = i;
                dec++;
                break;
            }
        }
    }
    for (int i = 0; i < hypo.size(); i++) {
        for (int j = 0; j < n; j++) {
            if (match(hypo[i], make_pair(precycle[j], cycle[j]))) {
                if (rim[j] >= 0 || im[i] >= 0) {
                    continue;
                }
                c[i + MAX_N][j] = 1;
            }
        }
    }
    for (int i = 0; i < hypo.size(); i++) {
        if (im[i] >= 0) {
            continue;
        }
        c[SRC][i + MAX_N] = 1;
    }
    for (int j = 0; j < n; j++) {
        if (rim[j] >= 0) {
            continue;
        }
        c[j][DST] = 1;
    }
    int flow = 0;
    do {
        memset(vis, false, sizeof(vis));
        if (!dfs(SRC)) {
            break;
        }
        flow++;
    } while (true);

    if (flow != hypo.size() - dec) {
        return false;
    }
    for (int i = 0; i < hypo.size(); i++) {
        for (int j = 0; j < n; j++) {
            if (f[i + MAX_N][j] == 1) {
                im[i] = j;
                rim[j] = i;
            }
        }
