        if (rim[i] >= 0) {
            continue;
        }
        if (precycle[i] < 0 && cycle[i] < 0) {
            ans[i] = im[0];
        }
        if (precycle[i] < 0 && cycle[i] >= 0) {
            for (int j = 0; j < hypo.size(); j++) {
                if (hypo[j].second == cycle[i]) {
                    ans[i] = im[j];
                    break;
                }
            }
        }
        if (precycle[i] >= 0 && cycle[i] < 0) {
            if (precycle[i] == 0) {
                ans[i] = i;
            }
            else {
                for (int j = 0; j < hypo.size(); j++) {
                    if (hypo[j].first == precycle[i] - 1) {
                        ans[i] = im[j];
                        break;
                    }
