            mx_unknown_cycle = max(mx_unknown_cycle, precycle[i]);
        }
        if (precycle[i] >= 0 && cycle[i] >= 0) {
            mx_known_cycle = max(mx_known_cycle, precycle[i]);
            dst[cycle[i]].push_back(precycle[i]);
        }
    } 
