        int cnt_z = count(dst[i].begin(), dst[i].end(), 0);
        int cnt_c = max((cnt_z + i - 1) / i, pos_len[i]);
        if (cnt_c == 0) {
            continue;
        }
        for (int j = 0; j < cnt_c; j++) {
            int f = hypo.size();
            for (int k = 0; k < i; k++) {
