            hypo_edge.push_back(k);
            k = hypo_edge.size() - 1;
        }
    }
    if (mx_known_cycle >= 0) {
        if (mx_unknown_cycle > mx_known_cycle) {
            for (int i = 1; i <= n; i++) {
                if (dst[i].empty() && !pos_len[i]) {
                    continue;
                }
                vector<pair<int, int>> tmp_hypo = hypo;
                vector<int> tmp_hypo_edge = hypo_edge;
                int mx = (dst[i].empty())? 0: dst[i][dst[i].size() - 1];
