int lcp(int i, int j){
    i = c[i], j = c[j];
    if(i > j)  swap(i, j);
    return min(suf[i][ lg2[j - i] ], suf[ j - (1 << lg2[j - i]) ][ lg2[j - i] ]);
}
bool cmp(int i, int j){
    bool rev = 0;
    if(i > j)  rev = 1, swap(i, j);
    if(j - i >= m){
	int st = lcp(i, n);
	if(st < m)
	    return rev ^ (t[st] < s[i + st]);
	int ss = lcp(i, i + m);
	if(ss < j - i - m)
	    return rev ^ (s[i + ss] < s[i + m + ss]);
	int ts = lcp(n, i + j - (i + m));
	if(ts < m)
	    return rev ^ (s[i + j - (i + m) + ts] < t[ts]);
	return !rev;
    }
    int st = lcp(i, n);
    if(st < j - i)
	return rev ^ (t[st] < s[i + st]);
    int tt = lcp(n + j - i, n);
    if(tt < i + m - j)
	return rev ^ (t[j - i + tt] < t[tt]);
    int ts = lcp(n + m - (j - i), i);
    if(ts < j - i)
	return rev ^ (s[i + ts] < t[m - (j - i) + ts]);
    return !rev;
}
void get_ranks(){
    //copy()
    memcpy(s + n, t, sizeof t);
    len = n + m;
    s[len++] = '$';

    for(int i = 0; i < len; i++)  cnt[s[i]]++;
    for(int i = 0; i < maxdn; i++)  sumc[i + 1] = sumc[i] + cnt[i];
    for(int i = 0; i < len; i++){
	p[sumc[s[i]]] = i;
	sumc[s[i]]++;
    }
    c[ p[0] ] = 0;
    for(int i = 1; i < len; i++)
	c[ p[i] ] = c[ p[i - 1] ] + !(s[ p[i] ] == s[ p[i - 1] ]);
    for(int mid = 1; mid <= len; mid *= 2){
	for(int i = 0; i < len; i++)
	    if((p[i] -= mid) < 0)
		p[i] += len;
	memset(cnt, 0, sizeof cnt);
	for(int i = 0; i < len; i++)  cnt[ c[i] ]++;
	sumc[0] = 0;
	for(int i = 0; i < maxdn; i++)  sumc[i + 1] = sumc[i] + cnt[i];
	for(int i = 0; i < len; i++){
	    pn[ sumc[ c[ p[i] ] ] ] = p[i];
	    sumc[ c[ p[i] ] ]++;
	}
	cn[ pn[0] ] = 0;
	for(int i = 1; i < len; i++){
	    int j = pn[i] + mid, k = pn[i - 1] + mid;
	    if(j >= len)  j -= len;
	    if(k >= len)  k -= len;
	    cn[ pn[i] ] = cn[ pn[i - 1] ] + !(c[pn[i]] == c[pn[i - 1]] && c[j] == c[k]);
	}
	copy(pn, pn + len, p), copy(cn, cn + len, c);
    }

    for(int i = 0, k = 0; i < len; i++)
	if(c[i] != len - 1){
	    for(int j = p[c[i] + 1]; s[i + k] == s[j + k]; )  k++;
	    suf[ c[i] ][0] = k;
	    if(k)  k--;
	}
    for(int i = 2; i < len; i++)  lg2[i] = lg2[i >> 1] + 1;
    for(int k = 1; k < lg; k++)
	for(int i = 0; i + (1 << k) < len; i++)
	    suf[i][k] = min(suf[i][k - 1], suf[i + (1 << k - 1)][k - 1]);
    iota(p, p + n + 1, 0);
    sort(p, p + n + 1, cmp);
    for(int i = 0; i < n + 1; i++)  whole[0][ p[i] ] = rnk[ p[i] ] = i;
}

int st[maxn], tail, par[maxn];
inline int root(int v){
    return ~par[v] ? par[v] = root(par[v]) : v;
}
void Arpas_technique(int k){
    for(int g = 0; g < k; g++, tail = 0)
	for(int i = g; i < n + 1; i += k){
	    par[i] = -1;
	    while(tail && rnk[ st[tail - 1] ] >= rnk[i])
		par[ st[--tail] ] = i;
	    st[tail++] = i;
	    for(auto &q : qs[i])
		ans[q.id] = min(ans[q.id], rnk[root(q.l)]);
	}
}
