    for(int k = 1; k < lg; k++)
	for(int i = 0; i + (1 << k) <= n + 1; i++)
	    whole[k][i] = min(whole[k - 1][i], whole[k - 1][i + (1 << k - 1)]);
    fill(ans, ans + q, inf);
    for(int qi = 0, l, r, k, x, y; qi < q; qi++){
	scanf("%d%d%d%d%d", &l, &r, &k, &x, &y);
	if(k == 1)
	    ans[qi] = min(whole[ lg2[r - l + 1] ][l], whole[ lg2[r - l + 1] ][r + 1 - (1 << lg2[r - l + 1])]);
	if(k >= sq){
	    for(int i = 0; i < n + 1; i += k){
		int lef = max(l, i + x), ri = min(r, i + y);
		if(lef <= ri)
		    ans[qi] = min({ans[qi], whole[ lg2[ri - lef + 1] ][lef], whole[ lg2[ri - lef + 1] ][ri + 1 - (1 << lg2[ri - lef + 1])]});
	    }
	}
	else{
	    ql[qi] = l, qr[qi] = r, qx[qi] = x, qy[qi] = y;
	    small[k].push_back(qi);
	}
    }
    for(int k = 2; k < sq; k++){
	for(auto qi : small[k]){
	    int l = ql[qi], r = qr[qi], x = qx[qi], y = qy[qi];
	    do{
		int lef = l % k <= x ? l + x - l % k : l + k - (l % k - x), ri = r % k >= x ? r - (r % k - x): r - k + x - r % k;
		if(lef <= ri)
		    qs[ri].push_back({lef, qi});
	    }  while(x++ < y);
	}
	Arpas_technique(k);
	for(int i = 0; i < n + 1; i++)  qs[i].clear();
    }
    for(int i = 0; i < q; i++)
	printf("%d ", ans[i] == inf ? -1 : p[ ans[i] ]);
    printf("\n");
    return 0;
}

