struct Grafo
{
    static constexpr long NIL = -1;

    struct Arc;

    struct Node {
        // Essencial
        long id;
        vector<Arc> adj;

        // Específico
        long pai = NIL;
        long pre = NIL, low;
        long rotulo = NIL;
        long grauIn = 0;
        long cont;
        long chefe, size;
        long valor, valorTotal, valorMax;

        bool red;
        bool artic;

        operator long() {
            return id;
        }
    };

    struct Arc {
        long from, to;
        long peso = 1;

        const Arc & operator=(const Arc &arco) {
            return arco;
        }

        bool operator==(const Arc &arco) {
            return this->from == arco.from and this->to == arco.to;
        }
    };

    struct Lista : public vector<Node> {
        Lista(long n) : vector<Node>(n) {}

        Node & operator[](long id) {
            return vector<Node>::operator[](id-1);
        }
    };

    // Lista de nós
    long n;
    Lista nodes;
    vector<long> ord;

    Grafo(long n) : n(n), nodes(Lista(n)) {
        long id = 1;
        for (auto &v : nodes) {
            v.chefe = v.pai = v.id = id++;            
            v.size = 1;
        }
    }

