public:
    long dfs(Node &r, long k) {
        r.cont += r.red;
        if (r.cont > k) return 0;
        if (r != 1 and r.adj.size() <= 1) {
            return r.cont <= k;
        }
        long total = 0;
        for (auto &arco : r.adj) {
            Node &v = nodes[arco.to];
            if (v == r.pai) continue;
            v.pai = r;
            if (v.red) v.cont = r.cont;
            total += dfs(v, k);
        }
        return total;
    }

public:
    bool topologica() {
        queue<long> fontes;
        for (auto &v : nodes) {
            // Procura-se por fontes
            if (v.grauIn == 0) {
                ord.pb(v);
                fontes.push(v);
            }
        }
        while (not fontes.empty()) {
            Node &fonte = nodes[fontes.front()];
            fontes.pop();

            for (auto &arco : fonte.adj) {
                Node &v = nodes[arco.to];
                if (v.grauIn == 1) {
                    v.grauIn = 0;
                    ord.pb(v);
                    fontes.push(v);
                }
                else --v.grauIn;
            }
        }
        // É topológica apenas se conseguiu
        // enumerar todos os vértices.
        return (long) ord.size() == n;
    }

public:
    void dfsCiclos() {
        for (auto &v : nodes) {
            if (v.pre == NIL) {
                v.pai = NIL;
                dfsCiclos(v);
            }
        }
        // Se v for raiz com mais de um filho, ou se houver
        // mais de um filho com retorno antes de v,
        // então v é articulação.
        for (auto &v : nodes) {
            if (v.pai == NIL) {
                bool um = false;
                for (auto &arc : v.adj) {
                    Node &w = nodes[arc.to];
                    if (w.pai == v) {
                        if (not um) um = true;
                        else {
                            v.artic = true;
                            break;
                        }
                    }
                }
            } else for (auto &arc : v.adj) {
                Node &w = nodes[arc.to];
                if (w == v.pai or w.pai != v) continue;
                if (w.low == v.pre or w.low == w.pre) {
                    v.artic = true;
                }
            }
        }
    }

private:
    long dfsCiclos(Node &v) {

        static long pre = 1;
        if (pre > n) pre = 1;

        v.pre = v.low = pre++;

        for (auto &arc : v.adj) {
            Node &w = nodes[arc.to];
            if (w == v.pai) continue;

            // Se já visitado, é arco de retorno
            long low;
            if (w.pre != -1) low = w.pre;
            else {
                low = dfsCiclos(w);
                w.pai = v;
            }
            if (low < v.low) {
                v.low = low;
            }
        }
        return v.low;
    }

public:
    void DAGfortes() {
        long k = kosaraju();
        Grafo GF(k);
        for (auto &v : nodes) {
            for (auto &arc : v.adj) {
                Node &w = nodes[arc.to];
                if (v.rotulo != w.rotulo) {
                    Node &V = GF.nodes[v.rotulo];
                    Node &W = GF.nodes[w.rotulo];
                    V.adj.pb(Arc({V, W, 1}));
                }
            }
        }
    }

    long kosaraju() {
        // Cria grafo com arcos revertidos
        Grafo GR(n);
        for (auto &v : nodes) {
            for (auto &arc : v.adj) {
                Node &w = GR.nodes[arc.to];
                w.adj.pb(Arc({w, v, 1}));
            }
        }
        // Faz DFS e gera ordenamento topológico
        GR.dfsCiclos();
        Lista ord(n);
        for (auto &v : GR.nodes) {
            ord[v.pre] = v;
        }
        // Inverte para obter pós-ordem
        reverse(ord.begin(), ord.end());

        // Aplica DFS para rotular componentes
        // fortes no grafo original
        long k = 1;
        for (auto &id : ord) {
            Node &v = nodes[id];
            if (v.rotulo == NIL) {
                dfsRotulo(v, k++);
            }
        }
        return k;
    }

private:
    void dfsRotulo(Node &v, long k) {
        if (v.rotulo != NIL) return;
        v.rotulo = k;
        for (auto &arc : v.adj) {
            Node &w = nodes[arc.to];
            dfsRotulo(w, k);
        }
    }

public:
    pll dfs(Node &r) {
        static long ord = 1;
        r.pre = ord++;

        r.valorTotal = r.valor;
        long maximo = -1e18;
        r.red = true;
        for (auto &arco : r.adj) {
            Node &v = nodes[arco.to];
            if (v.red) continue;
            pll resp = dfs(v);
            if (resp.second > maximo) {
                maximo = resp.second;
            }
            r.valorTotal += resp.first;
        }
        r.valorMax = max(r.valorTotal, maximo);
        return {r.valorTotal, r.valorMax};
    }
};

long UFfind(long v, Grafo &G) { 
    long v0 = v; 
    while (v0 != G.nodes[v0].chefe) {
        v0 = G.nodes[v0].chefe;
    }
    return v0; 
}

void UFunion(auto &v0, auto &w0) { 
   if (v0.size < w0.size) { 
      v0.chefe = w0; 
      w0.size += v0.size; 
   }
   else { 
      w0.chefe = v0; 
      v0.size += w0.size;
   }
}

long mdc(long a, long b)
{
    if (b == 0) return a;
    return mdc(b, a % b);
}

