struct Grafo
{
    static constexpr long NIL = -1;

    struct Arc;

    struct Node {
        // Essencial
        long id;
        vector<Arc> adj;

        // Específico
        long pai = NIL;
        long pre = NIL, low;
        long rotulo = NIL;
        long grauIn = 0;
        long cont;
        long chefe, size;
        long valor, valorTotal, valorMax;

        bool red;
        bool artic;

        operator long() {
            return id;
        }
    };

    struct Arc {
        long from, to;
        long peso = 1;

        const Arc & operator=(const Arc &arco) {
            return arco;
        }

        bool operator==(const Arc &arco) {
            return this->from == arco.from and this->to == arco.to;
        }
    };

    struct Lista : public vector<Node> {
        Lista(long n) : vector<Node>(n) {}

        Node & operator[](long id) {
            return vector<Node>::operator[](id-1);
        }
    };

    // Lista de nós
    long n;
    Lista nodes;
    vector<long> ord;

    Grafo(long n) : n(n), nodes(Lista(n)) {
        long id = 1;
        for (auto &v : nodes) {
            v.chefe = v.pai = v.id = id++;            
            v.size = 1;
        }
    }

    Grafo(long n, long m, bool peso = false) : Grafo(n) {
        for (long i = 0; i < m; i++) {
            long from, to, p = 1;
            cin >> from >> to;
            if (peso) cin >> p;
            Node &v = nodes[from];
            Node &w = nodes[to];
            v.adj.pb(Arc({v, w, p}));
            w.adj.pb(Arc({w, v, p}));
            UFunion(v, w);
        }
    }

    // template<typename T>
    // Grafo(Matriz2D<T> &mat, (bool)(T &a, T &b) *cond);
    //     : nodes(Lista(mat.n * mat.m)) {
    //     for (size_t i = 0; i < mat.n; i++) {
    //         for (size_t j = 0; j < mat.m; j++) {
    //             if (i < mat.n - 1 and cond(mat[i][j], mat[i+1][j])) {
    //                 Node &v = nodes[ i    * mat.m + (j + 1)];
    //                 Node &w = nodes[(i+1) * mat.m + (j + 1)];
    //                 v.adj.pb(Arc({v, w, 1}));
    //                 w.adj.pb(Arc({w, v, 1}));
    //             }
    //             if (j < mat.j - 1 and cond(mat[i][j], mat[i][j+1])) {
    //                 Node &v = nodes[i * mat.m + (j + 1)];
    //                 Node &w = nodes[i * mat.m + (j + 2)];
    //                 v.adj.pb(Arc({v, w, 1}));
    //                 w.adj.pb(Arc({w, v, 1}));
    //             }
    //         }
    //     }
    // }

public:
    long dfs(Node &r, long k) {
        r.cont += r.red;
        if (r.cont > k) return 0;
        if (r != 1 and r.adj.size() <= 1) {
            return r.cont <= k;
        }
        long total = 0;
        for (auto &arco : r.adj) {
            Node &v = nodes[arco.to];
            if (v == r.pai) continue;
            v.pai = r;
            if (v.red) v.cont = r.cont;
            total += dfs(v, k);
        }
        return total;
    }

public:
    bool topologica() {
        queue<long> fontes;
        for (auto &v : nodes) {
            // Procura-se por fontes
            if (v.grauIn == 0) {
                ord.pb(v);
                fontes.push(v);
            }
        }
        while (not fontes.empty()) {
            Node &fonte = nodes[fontes.front()];
            fontes.pop();

            for (auto &arco : fonte.adj) {
                Node &v = nodes[arco.to];
                if (v.grauIn == 1) {
                    v.grauIn = 0;
                    ord.pb(v);
                    fontes.push(v);
                }
                else --v.grauIn;
            }
        }
        // É topológica apenas se conseguiu
        // enumerar todos os vértices.
        return (long) ord.size() == n;
    }

public:
    void dfsCiclos() {
        for (auto &v : nodes) {
            if (v.pre == NIL) {
                v.pai = NIL;
                dfsCiclos(v);
            }
        }
        // Se v for raiz com mais de um filho, ou se houver
        // mais de um filho com retorno antes de v,
        // então v é articulação.
        for (auto &v : nodes) {
            if (v.pai == NIL) {
                bool um = false;
                for (auto &arc : v.adj) {
                    Node &w = nodes[arc.to];
                    if (w.pai == v) {
                        if (not um) um = true;
                        else {
                            v.artic = true;
                            break;
                        }
                    }
                }
            } else for (auto &arc : v.adj) {
                Node &w = nodes[arc.to];
                if (w == v.pai or w.pai != v) continue;
                if (w.low == v.pre or w.low == w.pre) {
                    v.artic = true;
                }
            }
        }
    }

private:
    long dfsCiclos(Node &v) {

        static long pre = 1;
        if (pre > n) pre = 1;

        v.pre = v.low = pre++;

        for (auto &arc : v.adj) {
            Node &w = nodes[arc.to];
            if (w == v.pai) continue;

            // Se já visitado, é arco de retorno
            long low;
            if (w.pre != -1) low = w.pre;
            else {
                low = dfsCiclos(w);
                w.pai = v;
            }
            if (low < v.low) {
                v.low = low;
            }
        }
        return v.low;
    }

public:
    void DAGfortes() {
        long k = kosaraju();
        Grafo GF(k);
        for (auto &v : nodes) {
            for (auto &arc : v.adj) {
                Node &w = nodes[arc.to];
                if (v.rotulo != w.rotulo) {
                    Node &V = GF.nodes[v.rotulo];
                    Node &W = GF.nodes[w.rotulo];
                    V.adj.pb(Arc({V, W, 1}));
                }
            }
        }
    }

    long kosaraju() {
        // Cria grafo com arcos revertidos
        Grafo GR(n);
        for (auto &v : nodes) {
            for (auto &arc : v.adj) {
                Node &w = GR.nodes[arc.to];
                w.adj.pb(Arc({w, v, 1}));
            }
        }
        // Faz DFS e gera ordenamento topológico
        GR.dfsCiclos();
        Lista ord(n);
        for (auto &v : GR.nodes) {
            ord[v.pre] = v;
        }
        // Inverte para obter pós-ordem
        reverse(ord.begin(), ord.end());

        // Aplica DFS para rotular componentes
        // fortes no grafo original
        long k = 1;
        for (auto &id : ord) {
            Node &v = nodes[id];
            if (v.rotulo == NIL) {
                dfsRotulo(v, k++);
            }
        }
        return k;
    }

private:
    void dfsRotulo(Node &v, long k) {
        if (v.rotulo != NIL) return;
        v.rotulo = k;
        for (auto &arc : v.adj) {
            Node &w = nodes[arc.to];
            dfsRotulo(w, k);
        }
    }

public:
    pll dfs(Node &r) {
        static long ord = 1;
        r.pre = ord++;

        r.valorTotal = r.valor;
        long maximo = -1e18;
        r.red = true;
        for (auto &arco : r.adj) {
            Node &v = nodes[arco.to];
            if (v.red) continue;
            pll resp = dfs(v);
            if (resp.second > maximo) {
                maximo = resp.second;
            }
            r.valorTotal += resp.first;
        }
        r.valorMax = max(r.valorTotal, maximo);
        return {r.valorTotal, r.valorMax};
    }
};


long mdc(long a, long b)
{
    if (b == 0) return a;
    return mdc(b, a % b);
}

struct Hose
{
    long id;
    long w, b;
    long size = 1;
    long chefe;
};

long UFfind(long v, vector<Hose> &a) { 
    long v0 = v; 
    while (v0 != a[v0].chefe) {
        v0 = a[v0].chefe;
    }
    return v0; 
}

void UFunion(auto &v0, auto &w0) { 
    if (v0.size < w0.size) { 
        v0.chefe = w0.id; 
        w0.size += v0.size;
    }
    else { 
        w0.chefe = v0.id; 
        v0.size += w0.size;
    }
}
int main()
{
    ios::sync_with_stdio(false);

    long n, m, w;
    cin >> n >> m >> w;

    vector<Hose> v(n+1);
    for (long i = 1; i <= n; i++) {
        cin >> v[i].w;
        v[i].id = i;
    }
    for (long i = 1; i <= n; i++) {
        cin >> v[i].b;
        v[i].chefe = i;
    }
    while (m--) {
        long x, y;
        cin >> x >> y;
        long cx = UFfind(x, v);
        long cy = UFfind(y, v);
        UFunion(v[cx], v[cy]);
    }
    map<long, vector<Hose>> grupos;
    for (auto &h : v) {
        long chefe = UFfind(h.id, v);
        grupos[chefe].pb(h);
    }
    vector<long> memo(w+1);
    for (auto &grupo : grupos) {
        if (grupo.second[0].id == 0) continue;
        vector<long> ant = memo;
        long somaW = 0, somaB = 0;
        for (auto &h : grupo.second) {
            for (long k = 1; k <= w; k++) {
                if (k - h.w < 0) continue;
                memo[k] = max({ant[k], memo[k], h.b + ant[k - h.w]});
            }
            somaW += h.w;
            somaB += h.b;
        }
        for (long k = 1; k <= w; k++) {
            if (k - somaW < 0) continue;
            memo[k] = max({ant[k], memo[k], somaB + ant[k - somaW]});
        }
    }
    printf("%lld\n", memo[w]);
}

