ll solve (ll mask , ll i , const ll  LOWER_LENGTH) {
    
    if(mask == (1<<8)-1 ) return 0;
    
    if(dp[i][mask] != -1) return dp[i][mask];
    
    lp(a, 1, 8)
        if(!(mask & (1<<(a-1)))) {
            ll upperIndex = (ll)(upper_bound(all(numPos[a]), i)-numPos[a].begin());
            if(numPos[a].size()-upperIndex < LOWER_LENGTH) return dp[i][mask] = -infll;
            
            
            dp[i][mask] = max( dp[i][mask],
                              LOWER_LENGTH + solve(mask | (1<<(a-1)), !LOWER_LENGTH?i:numPos[a][upperIndex+LOWER_LENGTH-1] , LOWER_LENGTH));
            
            if(numPos[a].size()-upperIndex > LOWER_LENGTH)
                dp[i][mask] = max(dp[i][mask], LOWER_LENGTH+1+ solve(mask | (1<<(a-1)), numPos[a][upperIndex+LOWER_LENGTH] , LOWER_LENGTH));

        }
    
    return dp[i][mask];
}

bool check(ll len) {
    clr(dp, -1);
    return solve(0, 0, len) >= 8*len;
}

