    while (l < r) {
        ll mid = ((l+r)>>1)+1;
        if(check(mid)) l = mid;
        else r = mid-1;
    }
    
    clr(dp, -1);
    printf("%lld\n" , solve(0, 0, l));
    return 0;
}

