			}
		}
	}
	for(int j = 0; j < 2; j++){
		for(int k = 0; k < 300; k++){
			if(dp[MAXN][j][k] == MOD)
				continue;
			int rr, rb;
			(j? rb: rr) = 0;
			(j? rr: rb) = k;
			int wr = max(0, needr - rr);
			int wb = max(0, needb - rb);
			int req = max(wr, wb);
			res = min(dp[MAXN][j][k] + req, res);
		}
	}
	cout << res << endl;
	return 0;
}

