using namespace std;
class comp {
    public:
    bool operator() (pair <ll,ll> a, pair <ll,ll> b) {
        if (a.second > b.second) return true;
        else if (a.second == b.second) {
            if (a.first > b.first) return true;
        }
        return false;
    }  
    
};

class taskSchedule {
    public:
    //ll *t, *k, *d;
    ll freeServer;
    priority_queue< pair<ll,ll>, vector<pair<ll,ll>>, comp > timeQ;
    priority_queue< pair<ll,ll>, vector<pair<ll,ll>>, comp > fServer;
    taskSchedule(ll n) {
        //t = (ll*)malloc(n*sizeof(ll));
        //k = (ll*)malloc(n*sizeof(ll));
        //d = (ll*)malloc(n*sizeof(ll));
        pair <ll,ll> p;
        freeServer = n;
        for (ll i = 0; i <n; i++) {
            //t[i] = 0;
            //k[i] = 0;
            //d[i] = 0;
            p.first = i+1;
            p.second = 0;
            fServer.push(p);
        }
    }
    ll allotServers(ll t, ll k, ll d) {
        ll req = k;
        ll init = t;
        ll fin = t + d;
        pair <ll,ll> p;
        //cout << "fin is " << fin << endl;
        while(!timeQ.empty() && ((timeQ.top()).second) <= t) {
            p = timeQ.top();
            //cout << " top is " << p.first << " val = " << p.second << endl;
            p.second = 0;
            fServer.push(p);
            timeQ.pop();
            //freeServer++;
        }
        //cout << "size = " << fServer.size() << endl;
        if (fServer.size() < req) return -1;
        ll sum = 0;
        while (!fServer.empty() && req--) {
            p = fServer.top();
            sum += p.first;
            p.second = fin;
            //cout << " top is " << p.first << " val = " << p.second << endl;
            fServer.pop();
            timeQ.push(p);
            //freeServer--;
        }
        //cout << endl << endl;
        return sum;
    }
};
