int n,m,a[1000100],dp[10000010];

int count(int curr, int x){
	if(curr==x) return 1;
	if(curr<x) return 0;
	if(curr<x*2-1) return 1;
	if(dp[curr]!=-1) return dp[curr];
	if(curr%2==0) dp[curr] = count(curr/2,x) * 2;
	else dp[curr] = count(curr/2,x) + count(curr/2+1,x);
	return dp[curr];
}


bool can(int x){
	int y = m;
	dp[x] = 1;
	for(int i=0;i<=10000000;i++){
		if(i<x) dp[i] = 0;
		else if(i==x) dp[i] = 1;
		else{
			dp[i] = dp[i-1];
			if(i%2==0) dp[i] = max(dp[i],dp[i/2]*2);
			else dp[i] = max(dp[i],dp[i/2]+dp[(i+1)/2]);
		}
	}
	// cout<<x<<endl;
	// for(int i=1;i<=10;i++) cout<<dp[i]<<" ";cout<<endl; 
	for(int i=0;i<n;i++){
		y-=dp[a[i]];
		if(y<=0) return true;
	}
	return false;
}

int bs(int l,int r){
	if(l>r) return -1;
	int mid = (l+r)/2;
	if(can(mid)) return max(mid,bs(mid+1,r));
	return bs(l,mid-1);
}

