void dfs(bool **map, bool ****state, int *t, pii *dir, int l, int d, int x, int y, int n)
{
	if (!state[l][d][x][y])
	{
		state[l][d][x][y] = 1;
		for (int i = 0; i < t[l]; ++i)
			map[x + dir[d].first * i][y + dir[d].second * i] = 1;
		if (l < n - 1)
		{
			dfs(map, state, t, dir, l + 1, (d + 7) % 8, x + dir[(d + 7) % 8].first + dir[d].first * (t[l] - 1), y + dir[(d + 7) % 8].second + dir[d].second * (t[l] - 1), n);
			dfs(map, state, t, dir, l + 1, (d + 1) % 8, x + dir[(d + 1) % 8].first + dir[d].first * (t[l] - 1), y + dir[(d + 1) % 8].second + dir[d].second * (t[l] - 1), n);
		}
	}
}

