string rev(const string &str){
    return string(str.rbegin(), str.rend());
}
bool ispalin(const string &str){
    return str == rev(str);
}

int main(){
    std::ios_base::sync_with_stdio(false);
    int n, m; cin >> n >> m;
    map<string, vi> mmap;
    for (int i = 0; i < n; i++){
        string str;
        int x;
        cin >> str >> x;
        mmap[str].push_back(x);
    }
    for (auto &it : mmap){
        sort(it.Y.rbegin(), it.Y.rend());
    }
    ll res = 0;
    ll Ma = 0;
    for (auto &it : mmap){
        if (ispalin(it.X)){
            ll a = 0, b = 0;
            for (int i = 0; i + 1 < (int)it.Y.size(); i += 2){
                if (it.Y[i] + it.Y[i + 1] <= 0) break;
                a += it.Y[i] + it.Y[i + 1];
            }
            b += it.Y[0];
            for (int i = 1; i + 1 < (int)it.Y.size(); i += 2){
                if (it.Y[i] + it.Y[i + 1] <= 0) break;
                b += it.Y[i] + it.Y[i + 1];
            }
            if (a >= b) {
                res += a;
            } else {
                res += a;
                Ma = max(Ma, b - a);
            }
        } else {
            string rstr = rev(it.X);
            if (mmap.count(rstr) && it.X < rstr){
                for (int i = 0; i < min(it.Y.size(), mmap[rstr].size()); i++){
                    if (it.Y[i] + mmap[rstr][i] <= 0) break;
                    res += it.Y[i] + mmap[rstr][i];
                }
            }
        }
    }
    res += Ma;
    cout << res << endl;
}

