int main()
{
    int n;
    string str;
    cin>>n;
    cin>>str;
    int count=1;
    int x=0;
    int y=0;
    int x_cur=0,xprev,yprev;
    int y_cur=0;
    int dist=0;
    for(int i=0;i<n;i++){
        dist++;
        xprev=x_cur;
        yprev=y_cur;
        if(str[i]=='L'){
            x_cur--;
        }
        else if(str[i]=='R'){
            x_cur++;
        }
        else if(str[i]=='U'){
            y_cur++;
        }
        else{
            y_cur--;
        }
        if(dist>(abs(x-x_cur)+abs(y-y_cur))){
            count++;
            x=0;
            y=0;
            x_cur=0;
            y_cur=0;
            if(str[i]=='L'){
                x_cur=x-1;
            }
            else if(str[i]=='R'){
                x_cur=x+1;
            }
            else if(str[i]=='U'){
                y_cur=y+1;
            }
            else{
                y_cur=y-1;
            }
            dist=0;
        }
    }
    cout<<count<<"\n";
    return 0;
}

