int main(){
    std::ios_base::sync_with_stdio(false);
    int n, k; cin >> n >> k;
    vi arr(n);
    for (int i = 0; i < n; i++) cin >> arr[i];
    ll sum = accumulate(arr.begin(), arr.end(), 0LL);
    if (sum < k) {
        cout << -1 << endl;
        return 0;
    }
    ll lo = 1, hi = sum / k + 10;
    vi lg(10001000);
    lg[0] = 0;
    lg[1] = 0;
    for (int i = 2; i < 10001000; i++)
        lg[i] = lg[i/2] + 1;
    while (lo < hi){
        ll mid = (lo + hi) / 2;
        ll tot = 0;
        for (int i = 0; i < n; i++){
            if (arr[i] < mid) continue;
            if (arr[i] == mid) {
                tot += 1;
                continue;
            }
            int e = lg[arr[i] / mid];
            int Ma = 0;
            for (int d = e; d <= e + 1; d++){
                int x = arr[i] / (1 << d), y = x + 1;
                int b = (arr[i] % (1 << d));
                if (mid <= x) Ma = max(Ma, (1 << d));
                else if (mid == y) Ma = max(Ma, b);
            }
            tot += Ma;
        }
        if (tot >= k) lo = mid + 1;
        else hi = mid;
    }
    cout << max(1LL, lo - 1) << endl;
}

