struct node_t {
	int l, r, id;

	bool operator< (const node_t& a) const {
		if (l == a.l)
			return r < a.r;
		else
			return l < a.l;
	}
};

const int maxn = 3e5+5;
node_t nd[maxn];
node_t Q[maxn];
int ans[maxn];
int n, k, m;

int calc() {
	set<pii> st;
	int ansd = -1, ans = 0;
	
	rep(i, 0, n) {
		st.insert(mp(nd[i].r, nd[i].id));
		if (st.size() < k) continue;
		
		while (st.size() > k) {
			st.erase(st.begin());
		}
		
		set<pii>::iterator iter = st.begin();
		if (iter->fir >= nd[i].l) {
			int tmp = iter->fir - nd[i].l + 1;
			if (tmp > ans) {
				ans = tmp;
				ansd = i;
			}
		}
	}
	
	return ansd;
}

void printAns(int idx) {
	set<pii> st;
	int ansd = -1, ans = 0;
	
	rep(i, 0, n) {
		st.insert(mp(nd[i].r, nd[i].id));
		if (st.size() < k) continue;
		
		while (st.size() > k) {
			st.erase(st.begin());
		}
		
		set<pii>::iterator iter = st.begin();
		if (iter->fir >= nd[i].l) {
			int tmp = iter->fir - nd[i].l + 1;
			if (tmp > ans) {
				ans = tmp;
				ansd = i;
			}
		}
		
		if (i == idx) {
			printf("%d\n", ans);
			for (iter=st.begin(); iter!=st.end(); ++iter)
				printf("%d ", iter->sec);
			putchar('\n');
			return ;
		}
	}
}

void solve() {
	sort(nd, nd+n);
	int idx = calc();
	if (idx < 0) {
		puts("0");
		rep(i, 1, k+1)
			printf("%d ", i);
		putchar('\n');
		return ;
	}
	printAns(idx);
}

