static const int N = 1000100;
static const int K = N / 32 - 2;
struct Bitset {
    uint arr[N / 32 + 2];
    int pos = 0;
    Bitset() {
        memset(arr, 0, sizeof(arr));
        arr[0] = 1;
    }
    void add(int x) {
        int step = x / 32;
        int shift = x & 31;
        if (shift) {
            int steps = min(pos / 32 + 1, K - step) + 4;
            steps -= steps & 3;
            auto* ptr = arr + steps - 4;
            int k4 = steps / 4;
            while (k4--) {
                ull tmp3 = *(ptr + 0);
                ull tmp2 = *(ptr + 1);
                ull tmp1 = *(ptr + 2);
                ull tmp0 = *(ptr + 3);
                (*(ull*)(ptr + step + 0)) |= tmp3 << shift;
                (*(ull*)(ptr + step + 1)) |= tmp2 << shift;
                (*(ull*)(ptr + step + 2)) |= tmp1 << shift;
                (*(ull*)(ptr + step + 3)) |= tmp0 << shift;
                ptr -= 4;
            }
        } else {
            for (int i = min(pos / 32 + 1, K - step); i >= 0; --i) {
                auto val = arr[i];
                arr[i + step] |= val;
            }
        }
        pos += x;
    }
    bool check(int k) {
        uint x = arr[k / 32];
        return checkbit(x, k & 31);
    }
};
