using namespace std;
int parent[100005];
int find(int x)          //查找 
{
    return x==parent[x]?x:find(parent[x]);
}

void Union(int a,int b)    //合并 
{
    int x,y;
    x=find(parent[a]);    //寻找a的祖先 
    y=find(parent[b]);    //寻找b的祖先 
    if(x!=y)
      parent[x]=y;     //如果两个点的祖先不一样，则把b的祖先作为a的祖先的子结点 
}

int main()
{
    int n;
    while(cin>>n)
    {
        int a,sum=0;
        for(int i=1;i<=n;i++)
          parent[i]=i;           //赋初值 
        for(int i=1;i<=n;i++)
        {
            cin>>a;
            Union(i,a);           //合并操作 
        }
        for(int i=1;i<=n;i++)
        {
            if(parent[i]==i)         //遍历一次查找所有独立的树的个数 
              sum++; 
        }
        cout<<sum<<endl; 
    }
    return 0;
}

