typedef long long int64;
const int64 mod = 1000000007;

int dp[1<<20][77];
int b[77], n;

int solve(int mask , int i) {
	int cnt = __builtin_popcount(mask);
	if(i == n)
		return cnt != 0 && (1 << cnt) - 1 == mask;

	if(dp[mask][i] != -1) return dp[mask][i];

	int ans = 0;

	if(b[i] == 0)
		ans = solve(mask , i + 1);
	else {
		int num = 0;
		int j = i;
		while(true) {
			num *= 2;
			num += b[j];
			if(num > 20) break;
			//if(!(mask & (1<<(num-1))))
			ans = (ans + solve(mask | (1 << (num - 1)), j + 1)) % mod;
			j++;
			if(j == n) break;
		}
		if(cnt != 0 && mask == (1 << cnt) - 1)
			ans++;
	}
	return dp[mask][i] = ans;
}

