vlli w [ N + 1 ] ;
vlli s [ N + 1 ] ;
lli max_decrease [ N + 1 ] ;
lli w_sum [ N + 1 ] ;
lli total [ N + 1 ] ;
lli new_w [ N + 1 ] ;
lli new_s [ N + 1 ] ;

void dfs ( lli cur , lli rem , lli weight , lli strength )
{
    if ( cur == 1 )
    {
        fie ( i , 0 , edges [ cur ].size () )
        {
            dfs ( edges [ cur ] [ i ] , 0 , w [ cur ] [ i ] , s [ cur ] [ i ] ) ;
        }
        return ;
    }
    lli temp = 0 , tot = 0 ;
    fie ( i , 0 , edges [ cur ].size () )
    {
        temp += max_decrease [ edges [ cur ] [ i ] ] ;
        tot += total [ edges [ cur ] [ i ] ] ;
    }
    if ( tot > strength )
    {
        rem += tot - strength ;
    }
    if ( temp < rem )
    {
        new_w [ cur ] = weight - rem + temp ;
        new_s [ cur ] = strength - rem + temp ;
        rem = temp ;
    }
    else
    {
        new_w [ cur ] = weight ;
        new_s [ cur ] = strength ;
    }
    fie ( i , 0 , edges [ cur ].size () )
    {
        dfs ( edges [ cur ] [ i ] , min ( rem , max_decrease [ edges [ cur ] [ i ] ] ) , w [ cur ] [ i ] , s [ cur ] [ i ] ) ;
        rem -=  min ( rem , max_decrease [ edges [ cur ] [ i ] ] ) ;
    }
}

bool dfs_max_decrease ( lli cur , lli weight , lli strength )
{
    #ifdef dbg
        cout << "dfs_max_decrease called for " << cur << " " << weight << " " << strength << endl ;
    #endif
    fie ( i , 0 , edges [ cur ].size () )
    {
        if ( ! dfs_max_decrease ( edges [ cur ] [ i ] , w [ cur ] [ i ] , s [ cur ] [ i ] ) )
        {
            return false ;
        }
        w_sum [ cur ] += w_sum [ edges [ cur ] [ i ] ] ;
        max_decrease [ cur ] += max_decrease [ edges [ cur ] [ i ] ] ;
        total [ cur ] += total [ edges [ cur ] [ i ] ] ;
    }
    if ( cur == 1 )
    {
        return true ;
    }
    if ( strength < w_sum [ cur ] )
    {
        return false ;
    }
    max_decrease [ cur ] += min ( strength - w_sum [ cur ] , weight - 1 ) ;
    w_sum [ cur ] += weight - min ( strength - w_sum [ cur ] , weight - 1 ) ;
    if ( total [ cur ] > strength )
    {
        max_decrease [ cur ] -= total [ cur ] - strength ;
        total [ cur ] = strength ;
    }
    total [ cur ] += weight ;
    #ifdef dbg
        cout << "w_sum for " << cur << " = " << w_sum [ cur ] << endl ;
    #endif
    return true ;
}

