ll seg[4*N],ind[4*N],lazy[4*N];
ll lazyupdate(ll low,ll high,ll pos)
{
    seg[pos]+=lazy[pos];
    if(low!=high)
    {
        lazy[2*pos+1]+=lazy[pos];
        lazy[2*pos+2]+=lazy[pos];
    }
    lazy[pos]=0;
}
ll query(ll low,ll high,ll pos)
{
    // cout<<low<<" "<<high<<endl; 
  
    lazyupdate(low,high,pos);
    if(low==high)
    {
        if(seg[pos]>0)
        {
            return low;
        }
        else
        {
            return (-1);
        }
    }
    else
    {
        ll mid=(low+high)/2;
        if(seg[2*pos+2]+lazy[2*pos+2]>0)
        {
            return query(mid+1,high,2*pos+2);
        }
        else if(seg[2*pos+1]+lazy[2*pos+1]>0)
        {
            return query(low,mid,2*pos+1);
        }
        else
        {
            return (-1);
        }
        // seg[pos]=max(seg[2*pos+1],seg[2*pos+2]);
    }
}
void update(ll qlow,ll qhigh,ll low,ll high,ll pos,ll val)
{
    // cout<<"low"<<" "<<"high="<<low<<" "<<high<<endl;
    lazyupdate(low,high,pos);
    if((qlow<=low)&&(qhigh>=high))
    {
        seg[pos]+=val;
        if(low!=high)
        {
            lazy[2*pos+1]+=val;
            lazy[2*pos+2]+=val;
        }
    }
    else
    {
        ll mid=(low+high)/2;
        if((qhigh<low)||(qlow>mid))
        {
            return;
        }
        else
        {
            update(qlow,qhigh,low,mid,2*pos+1,val);
            update(qlow,qhigh,mid+1,high,2*pos+2,val);    
        }
        seg[pos]=max(seg[2*pos+1],seg[2*pos+2]);

    }
    // if(seg[pos]==(-1))
    // {
    //     cout<<"low="<<low<<" "<<"high="<<high<<"pos="<<pos<<endl;
    // }
}
