                f[e[i]][c[i] + 1][b[i]]--;
                f[e[i]][c[i] + 1][d[i] + 1]++;
        }
        for(int h = 0; h < 26; h++)
        {
                for(int i = 1; i <= n; i++)
                {
                        for(int j = 1; j <= m; j++)
                        {
                                f[h][i][j] += f[h][i - 1][j] + f[h][i][j - 1] - f[h][i - 1][j - 1];
                        }
                }
        }
        ll all = 0;
        for(int i = 1; i <= n; i++)
        {
                for(int j = 1; j <= m; j++)
                {
                        ll up = 0;
                        ll down = 0;
