                        for(int h = 0; h < 26; h++)
                        {
                                up += h * f[h][i][j];
                                cup += f[h][i][j];
                        }
                        for(int h = 0; h < 26; h++)
                        {
                                s[h][i][j] = cdown * h - down + up - cup * h;
                                s[h][i][j] += (k - cdown - cup) * abs(h - (sh[i][j] - 'a'));
                                if(h == sh[i][j] - 'a')
                                {
                                        na[i][j] = s[h][i][j];
