                                s[h][i][j] += s[h][i][j - 1];
                                s[h][i][j] -= s[h][i - 1][j - 1];
                                down += h * f[h][i][j];
                                cdown += f[h][i][j];
                                up -= h * f[h][i][j];
                                cup -= f[h][i][j];
                        }
                }
        }
        ll ans = 1e18;
        for(int i = 1; i <= k; i++)
