void recover(int tm){
	while(on.size()>0 and tm){
		ata[on.back()]=on.back();
		on.ppb();tm--;
	}
}
bool merge(int x,int y){
	if((x=tap(x))==(y=tap(y)))
		return 0;
	on.pb(y);		
	ata[y]=x;	return true;
}
int solve_naive(int l,int r){
	int res=0;
	for(int i=l;i<=r;i++){
		tr(it,one[i])	
			if(*it<=r)
				res+=merge(i,*it);		
	}
	recover(INF);
	return (r-l+1)-res;
}
