const int MAXN = 400001;
const long long h1 = 1000003;
const long long h2 = 424243;


long long hashes[MAXN];
long long in[MAXN];
long long d[MAXN];
long long s[MAXN];
int an[MAXN];
int szv;
vector<int> g[MAXN];
int cnts[MAXN];
int cur;
int ans = 0;
int ansv;


void lower(long long &x) {
    x = lower_bound(in, in + szv, x) - in;
}

    

void change(int i, int j) {
    if (cnts[i] == 1) {
        cur--;
    }
    cnts[i]--;
    if (cnts[j] == 0) {
        cur++;
    }
    cnts[j]++;
}

void dfs1(int u, int pr = -1) {
    d[u] = 0;
    for (auto h: g[u]) {
        if (h != pr) {
            dfs1(h, u);
            d[u] += d[h] * h1;
        }
    }
    d[u] ^= h2;
}


void dfs2(int u, int pr = -1) {
    hashes[u] = d[u] ^ h2;
    if (pr != -1) {
        hashes[u] += s[u] * h1;
    }
    hashes[u] ^= h2;
    for (auto h: g[u]) {
        if (h != pr) {
            s[h] = ((hashes[u] ^ h2) - d[h] * h1) ^ h2;
            dfs2(h, u);
        }
    }
}


void dfs3(int u, int pr) {
    if (pr != -1) {
        change(hashes[pr], s[u]);
        change(d[u], hashes[u]);
    }
    if (cur > ans) {
        ans = cur, ansv = u;
    }
    an[u] = cur;
    for (auto h: g[u]) {
        if (h != pr) {
            dfs3(h, u);
        }
    }
    if (pr != -1) {
        change(s[u], hashes[pr]);
        change(hashes[u], d[u]);
    }
}


