    }
    dfs1(1);
    dfs2(1);
    for (int i = 1; i <= n; i++) {
        in[i * 3 - 3] = d[i];
        in[i * 3 - 2] = hashes[i];
        in[i * 3 - 1] = s[i];
    }
    sort(in, in + 3 * n);
    memset(cnts, 0, sizeof(cnts));
    szv = unique(in, in + 3 * n) - in;
    cur = 1;
    for (int i = 1; i <= n; i++) {
        lower(d[i]);
        lower(hashes[i]);
        lower(s[i]);
    }
    cnts[hashes[1]] = n;
    for (int i = 2; i <= n; i++) {
        change(hashes[1], d[i]);
    }
    dfs3(1, 1);
    writeInt(ansv, '\n');
    return 0;
}

