	ll t = pow(x,n>>1,m);
	return (t * t) % m;
}
ll divide(ll a,ll b,ll m)
{
	return (a * pow(b,m-2,m)) % m;
}

bool is_good_difference(ll d,ll& first)
{
	ll y = c[0];
	ll cnt = 0;
	it = lower_bound(c.begin(),c.end(),y);
	while(it != c.end() && *it == y)
	{
		y += d;
		if(y >= m)y -= m;
		cnt++;
		it = lower_bound(c.begin(),c.end(),y);
	}
	y = c[0];
	it = lower_bound(c.begin(),c.end(),y);
	while(it != c.end() && *it == y)
	{
		first = y;
		y-=d;
		if(y < 0)y += m;
		cnt ++;
		it = lower_bound(c.begin(),c.end(),y);
	}
	
	return (cnt == n+1);
}

ll count_difference(ll d)
{
	ll cnt = 0;
	FOR(i,0,n-1)
	{
		for(ll add = -d;add <= d; add += 2*d)
		{
			ll y = c[i] + add;
			if(y >= m) y -= m;
			if(y < 0) y += m;
			if(c[i] > y)continue;
			it = lower_bound(c.begin(),c.end(),y);
			if(it != c.end() && *it == y)cnt++;
		}
	}
	return cnt;
}

ii solve()
{
	if(n == 0)return mp(1,1);
	if(n == 1) return mp(c[0],1);
	sort(c.begin(),c.end());
	ll first;
	ll difference = c[1] - c[0];
	ll k = n - count_difference(difference);
	ll d = divide(difference,k,m);
	if(is_good_difference(d,first))
	{
		return mp(first,d);
	}
	else return mp(-1,-1);
}
