#define MOD (1000000007LL)
#define LEFT(n) (2*(n))
#define RIGHT(n) (2*(n)+1)

using namespace std;
typedef long long ll;
typedef pair<int, int> ii;
typedef pair<int, ii> iii;

ll pwr(ll base, ll p, ll mod = MOD){
ll ans = 1;while(p){if(p&1)ans=(ans*base)%mod;base=(base*base)%mod;p/=2;}return ans;
}


ll gcd(ll a, ll b){
    if(b == 0)  return a;
    return gcd(b, a%b);
}


int r, c, mod, arr1[20005], arr2[20005], diag_ele_value[20005], DP[20005];
ii cell[40005];

inline int value(int x, int y){
	return (arr1[x]+arr2[y]) % mod;
}

void flush(int l, int r){
	for (int j=l;j<=r;j++)
		DP[j] = 0;
}


void dp(int x1, int y1, int x2, int y2){

	//dp() recursives finds the point on the diagonal
	//which we will go through for the optimal path from (x1, y1)
	//to (x2, y2) by running the standard r*c DP

	cell[x1+y1] = {x1, y1};
	cell[x2+y2] = {x2, y2};

	if((x2+y2) - (x1+y1) <= 1)	return;

	int diag_sum = (x1+y1+x2+y2)/2;
	
	flush(y1, y2);
	for(int i=x1;i<=x2;i++){
		int lim = min(diag_sum-i, y2);
		for(int j=y1;j<=lim;j++){
			int temp = (j > y1 ? DP[j-1] : 0);
			DP[j] = max(DP[j], temp) + value(i, j);
			if(i+j == diag_sum)
				diag_ele_value[i] = DP[j];
		}
	}

	int maxi = -1, diag_x, diag_y;

	flush(y1, y2);
	for(int i=x2;i>=x1;i--){
		int lim = max(diag_sum-i, y1);
		for(int j=y2;j>=lim;j--){
			int temp = (j < y2 ? DP[j+1] : 0);
			DP[j] = max(DP[j], temp) + value(i, j);
			if(i+j == diag_sum){
				diag_ele_value[i] += DP[j] - value(i, j);
				if(diag_ele_value[i] > maxi){
					maxi = diag_ele_value[i];
					diag_x = i;	diag_y = j;
				}
			}
		}
	}

	dp(x1, y1, diag_x, diag_y);
	dp(diag_x, diag_y, x2, y2);
}



int main(){

	ios_base::sync_with_stdio(0);

	cin>>r>>c>>mod;
	for(int i=0;i<r;i++)	cin>>arr1[i];
	for(int i=0;i<c;i++)	cin>>arr2[i];

	dp(0, 0, r-1, c-1);

	int ans = 0;
	string path = "";
	for(int i=0;i<=r-1+c-1;i++){
		ans += value(cell[i].ff, cell[i].ss);
		if(i > 0){
			if(cell[i].ff == cell[i-1].ff)
				path += 'S';
			else
				path += 'C';
		}
	}

	cout<<ans<<endl<<path;
    return 0;
}

