    int id;

    bool operator<(const data& aa)const {
        if(x==aa.x){
            if(type == aa.type)return id<aa.id;
            return type<aa.type;
        }
        return x<aa.x;
    }

}P[mxn];

ll st,nd;

ll cursum;

ll dp[mxn];

int startid[mxn];

int main(){
//freopen("in.txt","r",stdin);
