        cin>>st>>nd;
        P[pdx].x    = st;
        P[pdx].id   = i;
        P[pdx].type = 0;
        pdx++;
        P[pdx].x    = nd;
        P[pdx].id   = i;
        P[pdx].type = 1;
        pdx++;
    }
    sort(P+1,P+pdx);
    //for(int i = 1;i<pdx;i++){
//cout<<"i:"<<i<<"\ttype:"<<P[i].type<<"\tx:"<<P[i].x<<"\tid:"<<P[i].id<<endl;
