                dp[cid]  = 0;
            }
            //cout<<"\t\tstartid["<<cid<<"]:"<<startid[cid]<<"\tdp["<<cid<<"]:"<<dp[cid]<<"\n";

        }
        else{
            cstartid = startid[cid];
            dp[cid]+=(cursum%mod - sum[cstartid - 1]%mod + mod)%mod;
            dp[cid]%mod;
           // cout<<"\t\tprevx:"<<prevx<<"\tprevval:"<<prevval<<endl;
            if(prevx == cx){
                dp[cid] = (dp[cid]%mod - prevval%mod + mod) %mod;
                prevval = (prevval%mod + dp[cid]%mod + mod) %mod;
            }
            else{
                prevx    = cx;
                prevval  = dp[cid]%mod;
            }
            dp[cid]%=mod;
           // cout<<"\t\tcstartid:"<<cstartid<<"\tdp["<<cid<<"]:"<<dp[cid]<<"\tcursum:"<<cursum<<"\tsum["<<cstartid-1<<"]:"<<sum[cstartid - 1]<<endl;

