const int MAX_N = 3 * 1000 * 100 + 9;
const int SQ = 548;

int n;
int cows[ MAX_N ];
ll dp[ MAX_N ];
ll answ[ MAX_N ];


struct Query{
    int a, b;
    int id;

    bool operator<( const Query& rhs )const
    {
        return b < rhs.b ;
    }
}q[ MAX_N ];

ll Solve( int a, int b )
{
    ll sum = 0;

    for ( ; a<=n; a+=b )
        sum += cows[ a ];

    return sum;
}

void SolveD( int b )
{
    for ( int i=n-b+1; i<=n; i++ )
        dp[ i ] = cows[ i ];

    for ( int i=n-b; i>0; i-- )
        dp[ i ] = dp[ i+b ] + cows[ i];
}

int main()
{
    //freopen("input.txt", "r", stdin);
    //freopen(".out", "w+", stdout);
    //ios_base::sync_with_stdio( false );

    scanf("%d", &n );
    for ( int i=1; i<=n; i++ )
        scanf("%d", &cows[ i ] );

    int Q;
    scanf("%d", &Q );

    for ( int i=1; i<=Q; i++ )
        scanf("%d %d", &q[ i ].a, &q[ i ].b ), q[ i ].id = i;

    sort( q+1, q+1+Q );

    q[ 0 ].b = 0;
    int sqn = min( (int)sqrt( n ) + 1, n );
    for ( int i=1; i<=Q; i++ )
    {
        if ( q[ i ].b <= sqn )
        {
            if ( q[ i ].b != q[ i-1 ].b )
                SolveD( q[ i ].b );

            answ[ q[ i ].id ] = dp[ q[ i ].a ];
        }
        else
            answ[ q[ i ].id ] = Solve( q[ i ].a, q[ i ].b );
    }

    for ( int i=1; i<=Q; i++ )
        printf("%lld\n", answ[ i ] );

    return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
char solve(ll n, ll k, ll a){
   if(k == 0) return '.';
   if(a == n) return 'X';
   if(n & 1) return solve(n-1, k-1, a);   
   if(k+k > n){
      if((a%2) == 0) return 'X';
      ll pl = k - n/2;
      if(n-2*pl < a) return 'X';
      return '.';
   } else {
      if(a & 1) return '.';
      ll pl = n - 2*k;
      if(a <= pl) return '.';
      return 'X';
   }
}

int main(){
   ll n, k, p;
   cin >> n >> k >> p;
   while(p --){
      ll a; cin >> a;    
      cout << solve(n, k, a);
   }
   cout << endl;
}

