double x[101], y[101], z[101];

int main()
{
	int n;
	cin>>n;
	for(int i=0; i<n; i++) {
	    cin>>x[i]>>y[i]>>z[i];
	}
	// Hill Climbing Algorithm
	double ansx = 0.0, ansy = 0.0, ansz = 0.0; // random initial solution
	double nbr = 0.999; // range of neighbourhood
	for(int it=0; it<500000; it++) {
		double dist = 0.0, dx = 0.0, dy = 0.0, dz = 0.0;
		for(int i=0; i<n; i++) {
			double curDist = (ansx - x[i]) * (ansx - x[i]) + (ansy - y[i]) * (ansy - y[i]) + (ansz - z[i]) * (ansz - z[i]);
			if(dist < curDist) {
				dist = curDist;
				dx = x[i] - ansx, dy = y[i] - ansy, dz = z[i] - ansz;
			}
		}
		// move in direction of point with max distance for better solution
		ansx += dx * nbr, ansy += dy * nbr, ansz += dz * nbr; // Move to the better neighbour point in solution space
		nbr *= 0.999; // reduce the range of neighbourhood
	}
	printf("%.8lf %.8lf %.8lf\n", ansx, ansy, ansz);
	return 0;
}

