bool can(int x,int y){
    for(auto& p : inst){
        if (p.first == 'N')  {
            int x1 = x;
            x -= p.second;
            if (x < 0 || grid[x][y] == '#' || col[x][y] != col[x1][y] ) return false;
        }
        else if (p.first == 'S') {
            int x1 = x;
            x += p.second;
            if (x >= n || grid[x][y] == '#' || col[x][y] != col[x1][y] ) return false;
        }
        else if (p.first == 'E') {
            int y1 = y;
            y += p.second;
            if (y >= m || grid[x][y] == '#' || row[x][y] != row[x][y1] ) return false;
        }
        else {
            int y1 = y;
            y -= p.second;
            if (y < 0 || grid[x][y] == '#' || row[x][y] != row[x][y1] ) return false;
        }
    }
    return true;
}

