using namespace std;

int numlucky(int x)
{
  int num=0;
  while (x>0) {
    if (x%10==4 or x%10==7) num++;
    x/=10;
  }
  return num;
}

int siguienteiguallucky(int x)
{
  int d=x%10;
  if (d<3) return x+1;
  if (d==3) return x+2;
  if (d==4) return x+3;
  if (d==5) return x+1;
  if (d==6) return x+2;
  if (d==8) return x+1;
  int nx=numlucky(x);
  int xx=x/10;
  int xx1=xx+1;
  int nxx1=numlucky(xx1);
  if (d==9) {
    if (nxx1==nx) return x+1;
    if (nxx1==nx+1) return siguienteiguallucky(xx)*10;
    return xx1*10+4;
  }
  if (nxx1==nx) return x+3;
  if (nxx1==nx-1) return x+7;
  return siguienteiguallucky(xx)*10+4;
}

int tramaa[50];

bool trama(int a,int l)
{
  for (int i=0;i<=l;i++)
    if (numlucky(a+i)!=tramaa[i])
      return false;
  return true;
}

int calcula(int a,int l)
{
  if (l==0) return siguienteiguallucky(a);
  int pasos=l/10;
  if (a%10+l%10>=10) pasos++;
  int minimo=calcula(a/10,pasos)*10+a%10;
  if (l>20) return minimo;
  for (int i=0;i<=l;i++)
    tramaa[i]=numlucky(a+i);
  for (int b=siguienteiguallucky(a);b<minimo;b=siguienteiguallucky(b))
    if (trama(b,l))
      return b;
  return minimo;
}

