int cal(string s) {
    int l = s.size(), p = 0, q = 0, cnt1 = 0, flag = 0;
    char ch;
    for (int i = 0; i < l; i++) {
        ch = (q & 1) ? 'R' : 'L';
        if (s[i] == 'X') {
            q++;
        } else {
            if (s[i] == ch) {
                p++;
                q++;
                flag = 0;
            } else {
                p++;
                q += 2;
                cnt1 += flag;
                flag = !flag;
            }
        }
    }
    if (q & 1) {
        q++;
        cnt1 += flag;
    }
    if (p * 2 > q) {
        p -= cnt1;
        q -= cnt1 * 2;
    }
    return (long long)p * 100000000 / q;
}

