bool good(int h, int w, int y, int x) {
    if (y < 0 || x < 0) return false;
    if (h > w) {
        swap(h,w);
        swap(y,x);
    }
    if (h == 1) return x >= w-2;
    return y != 0 || x != 0;
}

void f(int h, int w, int y, int x, int dy, int dx, int sy, int sx, vector<ii> &res) {
