const int N = 100001;
vector<int> g[N], cycle, hld[N], st[N], rev[N];
char used[N] = {}, done = 0, revc[N] = {};
int sz[N] = {}, which[N] = {}, status, hldsz = 0, p[N] = {}, szsnm[N] = {}, stc[N] = {};
int up[N][17] = {}, tin[N] = {}, tout[N] = {}, tm = 0, place[N] = {}, cycleplace[N] = {};
int get(int v)
{
	return v == p[v] ? v : p[v] = get(p[v]);
}
void unite(int a, int b)
{
	a = get(a);
	b = get(b);
	if (a == b)
		return;
	if (szsnm[a] > szsnm[b])
	{
		p[b] = a;
		szsnm[a] += szsnm[b];
	}
	else
	{
		p[a] = b;
		szsnm[b] += szsnm[a];
	}
}
void build_st(int j, int l, int r, int i = 0)
{
	if (l >= r)
		return;
	if (l + 1 != r)
	{
		int mid = (r + l) / 2;
		build_st(j, l, mid, 2 * i + 1);
		build_st(j, mid, r, 2 * i + 2);
	}
	st[j][i] = rev[j][i] = 0;
}
void build_c(int l, int r, int i = 0)
{
	if (l + 1 != r)
	{
		int mid = (r + l) / 2;
		build_c(l, mid, 2 * i + 1);
		build_c(mid, r, 2 * i + 2);
		stc[i] = stc[2 * i + 1] + stc[2 * i + 2];
	}
	stc[i] = revc[i] = 0;
}
void dfs(int v = 0, int p = -1)
{
	used[v] = 1;
	for (int i : g[v])
		if (i != p)
		{
			if (done)
			{
				cycle.emplace_back(v);
				return;
			}
			if (!used[i])
				dfs(i, v);
			else
			{
				done = 1;
				cycle.emplace_back(i);
				cycle.emplace_back(v);
				return;
			}
		}
	if (done)
		cycle.emplace_back(v);
}
void dec(int v, int l, int r = - 1)
{
	sz[v] = 1;
	tin[v] = ++tm;
	if (r != -1)
	{
		up[v][0] = v;
	}
	else
		up[v][0] = l;

	for (int i = 1; i < 17; i++)
		up[v][i] = up[up[v][i - 1]][i - 1];
	for(int u : g[v])
		if (u != l && u != r)
		{
			unite(u, v);
			dec(u, v);
			sz[v] += sz[u];
		}
	for (int u : g[v])
		if (u != l && u != r)
		{	
			place[u] = hld[which[u]].size() - 1;
			hld[which[u]].emplace_back(v);
			if (sz[u] >= sz[v] / 2)
				which[v] = which[u];
		}
	if (which[v] == -1)
	{
		which[v] = hldsz++;
		hld[which[v]].emplace_back(v);
		place[v] = 0;
	}
	for (int u : g[v])
		if (u != l && u != r)
		{
			if (which[u] != which[v])
			{
				///���� ������� ���� �� ��� �����
				st[which[u]].resize(4 * (hld[which[u]].size() - 1));
				rev[which[u]].resize(4 * (hld[which[u]].size() - 1));
				build_st(which[u], 0, hld[which[u]].size() - 1);
			}
		}
	if (r != -1)
	{
		place[v] = hld[which[v]].size() - 1;
		st[which[v]].resize(4 * (hld[which[v]].size() - 1));
		rev[which[v]].resize(4 * (hld[which[v]].size() - 1));
		build_st(which[v], 0, hld[which[v]].size() - 1);
	}
	tout[v] = ++tm;
}
void build_dec()
{
	dfs();
	for (int i = 1; i < cycle.size(); i++)
		if (cycle[i] == cycle[0])
			cycle.resize(i);
	for (int i = 0; i < cycle.size(); i++)
		dec(cycle[i], cycle[(i + 1) % cycle.size()], cycle[(i - 1 + cycle.size()) % cycle.size()]);
	int buf = cycle.size();
	for (int i = 0; i < buf; i++)
		cycleplace[cycle[i]] = i;
	build_c(0, cycle.size());
}
bool son(int u, int v)
{
	return tin[u] <= tin[v] && tout[u] >= tout[v];
}
int lca(int u, int v)
{
	if (son(u, v))
		return u;
	if (son(v, u))
		return v;
	int ans = v;
	for (int i = 16; i >= 0; i--)
		if (!son(up[ans][i], u))
			ans = up[ans][i];
	return up[ans][0];
}
void push(int i, int j, int tl, int tr)
{
	if (rev[j][i])
	{
		rev[j][i] = 0;
		if (2 * i + 1 < st[j].size())
		{
			rev[j][2 * i + 1] = !rev[j][2 * i + 1];
			st[j][2 * i + 1] = (tl + tr) / 2 - tl - st[j][2 * i + 1];
		}
		if (2 * i + 2 < st[j].size())
		{
			rev[j][2 * i + 2] = !rev[j][2 * i + 2];
			st[j][2 * i + 2] = tr - (tl + tr) / 2 - st[j][2 * i + 2];
		}
	}
}
void update(int l, int r, int j, int tl, int tr, int i = 0)
{
	if (l >= r)
		return;
	push(i, j, tl, tr);
	if (tl == l && tr == r)
	{
		rev[j][i] = 1;
		st[j][i] = r - l - st[j][i];
	}
	else
	{
		int mid = (tl + tr) / 2;
		update(l, min(mid, r), j, tl, mid, 2 * i + 1);
		update(max(mid, l), r, j, mid, tr, 2 * i + 2);
		st[j][i] = st[j][2 * i + 1] + st[j][2 * i + 2];
	}
}
void pushc(int i, int tl, int tr)
{
	if (revc[i])
	{
		revc[i] = 0;
		if (2 * i + 1 < cycle.size() * 4)
		{
			revc[2 * i + 1] = !revc[2 * i + 1];
			stc[2 * i + 1] = (tl + tr) / 2 - tl - stc[2 * i + 1];
		}
		if (2 * +2 < cycle.size() * 4)
		{
			revc[2 * i + 2] = !revc[2 * i + 2];
			stc[2 * i + 2] = tr - (tl + tr) / 2 - stc[2 * i + 2];
		}
	}
}
void update_c(int l, int r, int tl = 0, int tr = cycle.size(), int i = 0)
{
	if (l >= r)
		return;
	pushc(i, tl, tr);
	if (tl == l && tr == r)
	{
		revc[i] = 1;
		stc[i] = r - l - stc[i];
	}
	else
	{
		int mid = (tl + tr) / 2;
		update_c(l, min(mid, r), tl, mid, 2 * i + 1);
		update_c(max(mid, l), r, mid, tr, 2 * i + 2);
		stc[i] = stc[2 * i + 1] + stc[2 * i + 2];
	}
}
void inverse(int u, int v)
{
	if (which[v] == which[u])
	{
		if (u == v)
			return;
		status += st[which[u]][0];
		update(place[u], place[v], which[v], 0, hld[which[v]].size() - 1);
		status -= st[which[u]][0];
	}
	else
	{
		status += st[which[u]][0];
		update(place[u], hld[which[u]].size() - 1, which[u], 0, hld[which[u]].size() - 1);
		status -= st[which[u]][0];
		inverse(hld[which[u]][hld[which[u]].size() - 1], v);
	}
}
void inverse_c(int u, int v)
{
	if (abs(cycleplace[u] - cycleplace[v]) == min(cycleplace[u], cycleplace[v]) + cycle.size() - max(cycleplace[u], cycleplace[v]))
	{
		if (cycle[(cycleplace[u] + 1) % cycle.size()] < cycle[(cycleplace[u] - 1 + cycle.size()) % cycle.size()])
		{
			if (cycleplace[u] <= cycleplace[v])
				update_c(cycleplace[u], cycleplace[v]);
			else
			{
				update_c(0, cycleplace[v]);
				update_c(cycleplace[u], cycle.size());
			}
		}
		else
		{
			if (cycleplace[u] <= cycleplace[v])
			{
				update_c(0, cycleplace[u]);
				update_c(cycleplace[v], cycle.size());
			}
			else
				update_c(cycleplace[v], cycleplace[u]);
		}
	}
	else
	{
		if (abs(cycleplace[u] - cycleplace[v]) < min(cycleplace[u], cycleplace[v]) + cycle.size() - max(cycleplace[u], cycleplace[v]))
			update_c(min(cycleplace[u], cycleplace[v]), max(cycleplace[u], cycleplace[v]));
		else
		{
			update_c(0, cycleplace[v]);
			update_c(cycleplace[u], cycle.size());
		}
	}
}
int get(int u, int v)
{
	u--, v--;
	if (get(u) == get(v))
	{
		int e = lca(u, v);
		inverse(u, e);
		inverse(v, e);
	}
	else
	{
		inverse(u, get(u));
		inverse(v, get(v));
		status += min(stc[0], int(cycle.size()) - 1);
		inverse_c(get(u), get(v));
		status -= min(stc[0], int(cycle.size()) - 1);
	}
	return status;
}
