		cin >> sphere[i];
	}
	while (m--) {
		cin >> plane;
		for (int i = 0; i < n; ++i) {
			p[i] = sphere[i].project(plane);
		}
		random_shuffle(p, p + n);
		point center;
		double radius = 0;
		for (int i = 0; i < n; ++i) {
			if (dist(center, p[i]) > radius + EPS) {
				center = p[i];
				radius = 0;
				for (int j = 0; j < i; ++j) {
					if (dist(center, p[j]) > radius + EPS) {
						center = (p[i] + p[j]) / 2;
						radius = dist(center, p[i]);
						for (int k = 0; k < j; ++k) {
							if (dist(center, p[k]) > radius + EPS) {
								center = circumcenter(p[i], p[j], p[k]);
								radius = dist(center, p[i]);
							}
						}
					}
				}
			}
		}
		cout << radius << '\n';
	}
	cout << fixed;
}

