using namespace std;

const int N = 1e5 + 10;

struct point
{
    double x, y;
    int i;
};

int n, p1, p2;
point a[N], b[N], tmp[N];
double ans = 1e9+10;

bool cmp(point a, point b)
{
    if(a.x < b.x)
        return 1;
    if(a.x == b.x && a.y < b.y)
        return 1;
    return 0;
}

double dist(point a, point b)
{
    return sqrt((a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y));
}

void ud(point a, point b)
{
    if(dist(a, b) < ans)
    {
        ans = dist(a, b);
        p1 = a.i;
        p2 = b.i;
    }
}

bool pos(double x)
{
    return x >= 0;
}

bool neg(double x)
{
    return x <= 0;
}

int make_neg(int i)
{
    if(pos(a[i].x) && pos(a[i].y))
        return 4;
    if(pos(a[i].x) && neg(a[i].y))
        return 2;
    if(neg(a[i].x) && pos(a[i].y))
        return 3;
    return 1;
}

int make_pos(int i)
{
    if(pos(a[i].x) && pos(a[i].y))
        return 1;
    if(pos(a[i].x) && neg(a[i].y))
        return 3;
    if(neg(a[i].x) && pos(a[i].y))
        return 2;
    return 4;
}


void Calc(int l, int r)
{
    if(l >= r)
        return;
    if(r - l == 1)
    {
        if(b[l].y > b[r].y)
            swap(b[l], b[r]);
        ud(b[l], b[r]);
        return;
    }

    int m = (l + r) / 2;
    double ma = b[m].x;

    Calc(l, m);
    Calc(m + 1, r);

    int lp = l, rp = m + 1, sz = 1;

    while(lp <= m || rp <= r)
    {
        if(lp > m || (rp <= r && b[lp].y > b[rp].y))
        {
            tmp[sz] = b[rp];
            rp ++;
        }
        else
        {
            tmp[sz] = b[lp];
            lp ++;
        }
        sz ++;
    }

    for(int i = l ; i <= r ; i ++)
        b[i] = tmp[i - l + 1];

    sz = 0;

    for(int i = l ; i <= r ; i ++)
        if(abs(b[i].x - ma) < ans)
            tmp[++ sz] = b[i];

    for(int i = 1 ; i <= sz ; i ++)
        for(int j = i - 1 ; j >= 1 ; j --)
        {
            if(tmp[i].y - tmp[j].y >= ans)
                break;
            ud(tmp[i], tmp[j]);
        }
}

main()
{
    freopen("input.txt", "r", stdin);
    freopen("output.txt", "w", stdout);
    scanf("%d", &n);
