        b[i].x = fabs(a[i].x);
        b[i].y = fabs(a[i].y);
        b[i].i = i;
    }

    sort(b + 1, b + n + 1, &cmp);

    Calc(1, n);

    cout << p1 << " " << make_pos(p1) << " " << p2 << " " << make_neg(p2) << endl;
}

