const ll INF = 1000000000000000000 + 50;

ll Licz(string nap)
{
    int n = nap.size();
    vector< vector<ll> > dp(n + 1, vector<ll>(n + 1, 0));
    if (nap[0] == '?' || nap[0] == '(')
        dp[1][1] = 1;
    for (int i = 1; i < n; ++i)
    {
        for (int otw = 1; otw <= n; ++otw)
        {
            int zam = i - otw;
            if (nap[i] == '?')
            {
                if (otw + 1 >= zam)
                    dp[i + 1][otw + 1] += dp[i][otw];
                if (otw >= zam + 1)
                    dp[i + 1][otw] += dp[i][otw];
            }
            if (nap[i] == '(')
                if (otw + 1 >= zam)
                    dp[i + 1][otw + 1] += dp[i][otw];
            if (nap[i] == ')')
                if (otw >= zam + 1)
                    dp[i + 1][otw] += dp[i][otw];
            if (dp[i + 1][otw] >= INF)
                dp[i + 1][otw] = INF;
            if (dp[i + 1][otw + 1] >= INF)
                dp[i + 1][otw + 1] = INF;
        }
    }
    return dp[n][n / 2];
}

