#define P_B push_back

struct edge{
	int u, v, ind;
	double t, w;
	edge(){}
	edge(int u, int v, double w, int ind, double t): u(u), v(v), ind(ind), t(t), w(w){}
	bool operator < (edge a) const{
		if(w < a.w)
			return true;
		if(w > a.w)
			return false;
		if(t)
			return true;
		return false;
	}
};

const int MAXN = 1000 * 100 + 10;
edge ed[MAXN * 10];
vector <int> ans;
int par[MAXN];
int n, m, k;
bool connect = false;

int get_par(int v)
{
	return par[v] = (v == par[v])? v: get_par(par[v]);
}

bool merge(int u, int v)
{
	u = get_par(u), v = get_par(v);
	if(u == v)
		return false;
	par[u] = v;
	return true;
}

bool ok(double x)
{
	ans.clear();
	for(int i = 0; i < m; i ++)
		ed[i].w += ed[i].t * x;
	for(int i = 0; i < n; i ++)
		par[i] = i;

	sort(ed, ed + m);
	int num = 0;
	for(int i = 0; i < m; i ++)
	{
		int j = i;
		while(i + 1 < m && ed[i].w == ed[i + 1].w)
			i++;
		for(int p = j; p <= i; p++)
			if(num >= k && ed[p].t)
				continue;
			else if(merge(ed[p].u, ed[p].v))
			{
				ans.P_B(ed[p].ind);
				if(ed[p].t)
					num++;
			}

/*		for(int p = j; p <= i; p++)
			if(merge(ed[p].u, ed[p].v))
			{
				ans.P_B(ed[p].ind);
				if(ed[p].t)
					num++;
		}
		*/
	}

	if((int)ans.size() == n - 1)
		connect = true;

	for(int i = 0; i < m; i ++)
		ed[i].w -= ed[i].t * x;
//	cout<< x << " "<< num << endl;
	if(num >= k)
		return true;
	return false;
}

double bs(double s, double e)
{
	if(e - s <= 1e-3)
		return s;
	double mid = (s + e) / 2;
	if(!ok(mid))
		return bs(s, mid);
	else
		return bs(mid, e);
}

