	if(p == -1) st[cur].link = 0;
	else{
		int q = st[p].next[c];
		if(st[p].len+1 == st[q].len) st[cur].link = q;
		else{
			int clone = sz++;
			st[clone] = st[q];
			st[clone].cnt = 0;
