const long long mod = 1000000007;

long long C(int n, int k) {
	if(k > n) {
		return 0;
	}
	int dp[n + 1][n + 1];
	for(auto i = 0; i <= n; i++) {
		dp[i][i] = 1;
		dp[i][0] = 1;
	}
	for(auto i = 2; i <= n; i++) {
		for(auto j = 1; j < i; j++) {
			dp[i][j] = (dp[i - 1][j - 1] + dp[i - 1][j]) % mod;
		}
	}
	return dp[n][k];
}

int main() {
	long long n, m, k;
	cin >> n >> m >> k;
	cout << C(n - 1, 2 * k) * C(m - 1, 2 * k) % mod;
	return 0;
}

