using namespace std;

double sqr(double a){
    return a * a;
}

bool eq(double a, double b){
    return fabs(a - b) < 1e-9;
}

bool lessOrEq(double a, double b){
    return a < b || eq(a, b);
}

struct Point{
    double x, y;

    Point(){}
    Point(double x1, double y1){
        x = x1;
        y = y1;
    }

    void scan(){
        cin >> x >> y;
    }
    bool operator==(const Point &p) const
    {
        return x == p.x && y == p.y;
    }

    Point operator+(const Point & p) const
    {
        return Point(x + p.x, y + p.y);
    }

    Point operator-(const Point & p) const
    {
        return Point(x - p.x, y - p.y);
    }
    Point rotate() const
    {
        return Point(-y, x);
    }
    Point operator-() const
    {
        return Point(-x, -y);
    }

    Point operator*(double k) const
    {
        return Point(x * k, y * k);
    }

    Point operator/(double k) const
    {
        return Point(x/k, y/k);
    }

    bool koll(const Point & p) const
    {
        return x * p.y == y * p.x;
    }

    double operator%(const Point & p) const
    {
        return x * p.x + y * p.y;
    }

    double operator&(const Point & p) const
    {
        return x * p.y - y * p.x;
    }

    double len() const
    {
        return sqrt(sqr(x) + sqr(y));
    }

    Point normalize(double k = 1) const
    {
        return *this * (k/len());
    }

    double distTo(const Point & p) const
    {
        return sqrt(sqr(x - p.x) + sqr(y - p.y));
    }

    bool onLine(const Point & A, const Point & B) const
    {
        Point C = *this;
        if (eq((C - A) & (B - A), 0))
            return true;

        return false;
    }
    double distTo(const Point & A, const Point & B) const
    {
        Point C = *this;

        if (C.onLine(A, B))
            return 0;

        double s = fabs((C - A) & (C - B));
        return s/(A - B).len();
    }

};

bool isInSegment(Point C, Point A, Point B){
    if (C == A || C == B)
        return true;
    if (!C.onLine(A, B))
        return false;

    if (lessOrEq(0, (C - A) % (B - A)) && lessOrEq(0, (C - B) % (A - B)))
        return true;
    else
        return false;
}

double how_much(Point C, Point A, Point B){
    if (C == A || C == B)
        return 0.0;

    return (min(C.distTo(A), C.distTo(B))/max(C.distTo(A), C.distTo(B)));
}

