vector < vector<int> > city;
bool ringroad [3001]= {false};
bool visited [3001] = {false};
bool gotRingRoad = false;
int ringRoadStart = -1;
bool metRingRoadStart = false;
void FindRingRoad (int ts, int ors) {
  //  cout << "frr called " << ts << " " << ors << "\n";
    vector<int> s = city[ts];
    visited[ts] = true;
    for (int i = 0; i < s.size(); i++) {
        int nts = s[i];
        if (gotRingRoad && !metRingRoadStart) {
            ringroad[ts] = true;
            if (ts == ringRoadStart)
                metRingRoadStart = true;
            return;
        }
        if (visited[nts] && nts != ors) {
            //Ringroad found
            gotRingRoad = true;
            ringroad[ts] = true;
            ringRoadStart = nts;
            return;
        } else if (!visited[nts]) {
            visited[nts] = true;
            FindRingRoad(nts,ts);
        }
    }
    if (gotRingRoad && !metRingRoadStart) {
        ringroad[ts] = true;
        if (ts == ringRoadStart)
            metRingRoadStart = true;
        return;
    }
}

int distances[3001] = {0};
void GetDistances (int si) {
    queue< pair<int,int> > bfsQueue;
    bfsQueue.push(make_pair(si,0));
    while (!bfsQueue.empty()) {
        pair<int,int> cp = bfsQueue.front();
        bfsQueue.pop();
        visited[cp.first] = true;
        int ci = cp.first;
        int d = cp.second;
        distances[ci] = d;
        for (int i = 0; i < city[ci].size(); i++) {
            if (!visited[city[ci][i]] && !ringroad[city[ci][i]]) {
                visited[city[ci][i]] = true;
                bfsQueue.push(make_pair(city[ci][i],d+1));
            }
        }
    }
}

