    for (int i = 0; i < 3001; i++) {
        visited[i] = false;
    }

    for (int i = 0; i < n; i++) {
        if (ringroad[i]) {
            GetDistances(i);
        }
    }

    for (int i = 0; i < n; i++) {
        cout << distances[i] << " ";
    }
    return 0;
}

