        while (cin.peek() != '\n') {
              cin >> B[i][j];
              if (B[i][j] != '0')
                 if (B[i][j] == B[i - 1][j]) {
                             ingroup[i][j] = ingroup[i - 1][j];
                             G[ingroup[i][j]].Add(i, j);
                 } else if (B[i][j] == B[i][j - 1]) {
                        ingroup[i][j] = ingroup[i][j - 1];
                        G[ingroup[i][j]].Add(i, j);
                 } else {
                        ingroup[i][j] = G.size();
                        G.push_back(group(i, j));
                 }
              j++;
        }
        cin.ignore();
    }
    int b = ingroup[1][1];
