    return (n%mod + mod)%mod;
}

long long FUNCREV(long long n){

    vector<long long> dp(8,0);
 	long long dpC = 0;
    while(n > 1){

        dp[dpC++] = n%2;
        n = n / 2;
    }
 	 if(n != 0)	
		dp[dpC++] = n;
    long long ans = 0 , mul = 1;
    for(long long i=7;i>=0;i--){

        ans = ans + dp[i]*mul;
        mul = mul << 1;
    }
    return ans;
}

