void go(lo dp[N][N][2], lo i, lo j, lo d) {
	// dp[i+1][j][1-d]=dp[i][j][d];
	dp[i+1][(c[i]=='F' ? 1 : 0 )+j][1-d]=max(dp[i+1][(c[i]=='F' ? 1 : 0 )+j][1-d], dp[i][j][d]);
	dp[i+1][(c[i]=='F' ? 0 : 1 )+j][d]=max(dp[i+1][(c[i]=='F' ? 0 : 1 )+j][d], dp[i][j][d]+(d==1? 1: -1));	
}


int main() {
