			for (lo d=0;d<2;d++)
				L[i][j][d]=R[i][j][d]=-1000;

	L[0][0][0]=R[0][0][1]=0;
	for (lo i=0;i<l;i++)
		for(lo j=0;j<=n;j++)
			for (lo d=0;d<2;d++) {
