struct point
{
	double x;
	double y;

	point(double _x, double _y) {
		x = _x, y = _y;
	}
};

bool operator<(const point &a, const point &b) {
	if(fabs(a.x - b.x) < EPS)
		return a.y < b.y;
	return a.x < b.x;
}
	
bool operator==(const point &a, const point &b) {
	return (a.x == b.x && a.y == b.y);
}

point getVector(const point &a, const point &b) {
	return point(b.x - a.x, b.y - a.y);
}

double dist(const point &a, const point &b) {
	return sqrt((a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y));
}

double dotProduct(const point &a, const point &b) {
	return a.x * b.x + a.y * b.y;
}


bool all_90_angles(point &a, point &b, point &c, point &d){
    if(dotProduct(getVector(a, b), getVector(b, c) )) return false;
    if(dotProduct(getVector(b, c), getVector(c, d) )) return false;
    if(dotProduct(getVector(c, d), getVector(d, a) )) return false;
	return true;
}

bool isSquare(point &a, point &b, point &c, point &d){
	if(a == b || a == c || a == d || b == c || b == d || c == d)
		return false;
	if(!all_90_angles(a, b, c, d)) return false;
	double cur = dist(a , b);
	if(cur != dist(b, c)) return false;
	if(cur != dist(c, d)) return false;
	if(cur != dist(d, a)) return false;
	return true;
}

bool isRectangle(point &a, point &b, point &c, point &d){
	if(a == b || a == c || a == d || b == c || b == d || c == d)
		return false;
	if(!all_90_angles(a, b, c, d)) return false;
	return (dist(a, b) == dist(c, d) && dist(b, c) == dist(d, a));
}

typedef vector<pair<point, double> > PT; 
PT v, v1, v2;

bool isSquare(PT &tmp)
{
	do {
		if(isSquare(tmp[0].ft, tmp[1].ft, tmp[2].ft, tmp[3].ft))
			return true;
	} while(next_permutation(tmp.begin(), tmp.end()));
