}

bool isRectangle(PT &tmp)
{
	do {
		if(isRectangle(tmp[0].ft, tmp[1].ft, tmp[2].ft, tmp[3].ft))
			return true;
	} while(next_permutation(tmp.begin(), tmp.end()));
	return false;
}

