int x[8], y[8], a[8]; bool found;

inline int dist(int dx, int dy) {
	return dx*dx + dy*dy;
}

inline bool square() {
	int x1 = x[a[0]], y1 = y[a[0]];
	int x2 = x[a[1]], y2 = y[a[1]];
	int x3 = x[a[2]], y3 = y[a[2]];
	int x4 = x[a[3]], y4 = y[a[3]];

	int d1 = dist(x2 - x1, y2 - y1);
	int d2 = dist(x3 - x2, y3 - y2);
	int d3 = dist(x4 - x3, y4 - y3);
	int d4 = dist(x1 - x4, y1 - y4);
	int d5 = dist(x3 - x1, y3 - y1);
	int d6 = dist(x4 - x2, y4 - y2);

	return (d1 == d2 && d2 == d3 && d3 == d4 && d4 == d1 && d5 == d6);
}

inline bool rectangle() {
	int x1 = x[a[4]], y1 = y[a[4]];
	int x2 = x[a[5]], y2 = y[a[5]];
	int x3 = x[a[6]], y3 = y[a[6]];
	int x4 = x[a[7]], y4 = y[a[7]];

	int d1 = dist(x2 - x1, y2 - y1);
	int d2 = dist(x3 - x2, y3 - y2);
	int d3 = dist(x4 - x3, y4 - y3);
	int d4 = dist(x1 - x4, y1 - y4);
	int d5 = dist(x3 - x1, y3 - y1);
	int d6 = dist(x4 - x2, y4 - y2);

	return (d1 == d3 && d2 == d4 && d5 == d6);
}

