struct node {
  int x, min, y, pos;
  node *left, *right;
  node(int x, int pos) : x(x), min(pos), y(rand()), pos(pos), left(NULL), right(NULL) {}
};

typedef node* treap;

const int inf = 1e9;

int getmin(treap &t) {
  return t ? t->min : inf;
}

void upd(treap &t) {
  if (t) {
    t->min = min({t->pos, getmin(t->left), getmin(t->right)});
  }
}

void split(treap t, int v, treap &l, treap &r) {
  if (!t) {
    l = r = NULL;
    return;
  }
  if (t->x < v) {
    split(t->right, v, t->right, r);
    l = t;
  } else {
    split(t->left, v, l, t->left);
    r = t;
  }
  upd(l), upd(r);
}

void merge(treap l, treap r, treap &t) {
  if (!l) {
    t = r;
    return;
  }
  if (!r) {
    t = l;
    return;
  }
  if (l->y < r->y) {
    merge(l, r->left, r->left);
    t = r;
  } else {
    merge(l->right, r, l->right);
    t = l;
  }
  upd(t);
}

void insert(int v, int pos, treap &t) {
  treap a, b;
  split(t, v, a, b);
  merge(a, new node(v, pos), t);
  merge(t, b, t);
}

int get_ans(int value, treap &t) {
  treap a, b;
  split(t, value, a, b);
  int ans = getmin(b);
