bool check(int x,int y,int idx){
	if(x+2 >= N || y+2 >= M) return false;
	for(int i=0;i<3;i++) for(int j=0;j<3;j++) if(board[x+i][y+j] && shape[idx][i][j]) return false;
	return true;
}
