//			for(int i=0;i<9;i++,cout<<endl) for(int j=0;j<9;j++) cout<<board[i][j];
			maxIdx = idx;
		}
		return 0;
	}else{
		if(dp.count(make_pair(r,prev)) != 0){
			vector<int>& p = dp[make_pair(r,prev)].second;
			int ret = 0;
			for(int i=0;i<p.size();i++){
				if(p[i] == -1) continue;
				ret += 1;
				for(int x=0;x<3;x++) for(int y=0;y<3;y++) if(shape[p[i]][x][y]) board[r+x-2][i+y] = idx;
				idx += 1;
			}
