			int t = 0;
			for(int i=0;i<M;i++,t++) if(board[r-1][i]) state |= (1<<t);
			for(int i=0;i<M;i++,t++) if(board[r][i]) state |= (1<<t);
			ret += solve(r+1,state);
			for(int i=0;i<p.size();i++){
				if(p[i] == -1) continue;
				idx -= 1;
				for(int x=0;x<3;x++) for(int y=0;y<3;y++) if(shape[p[i]][x][y]) board[r+x-2][i+y] = 0;
			}
			return ret;
		}else{
			vector<int> p(M,-1);
			return fillC(r,0,prev,p);
		}
	}
	
}

int fillC(int r,int c,int prev,vector<int>& p){
	if(c != M){
		int ret = 0;
		for(int i=0;i<4;i++){
			if(!check(r-2,c,i)) continue;
			for(int x=0;x<3;x++) for(int y=0;y<3;y++) if(shape[i][x][y]) board[x+r-2][y+c] = idx;
			idx += 1;
			p[c] = i;
			ret = max(ret,fillC(r,c+1,prev,p));
			p[c] = -1;
			idx -= 1;
			for(int x=0;x<3;x++) for(int y=0;y<3;y++) if(shape[i][x][y]) board[x+r-2][y+c] = 0;
		}
		ret = max(ret,fillC(r,c+1,prev,p));
		return ret;
	}else{
		int state = 0;
		int t = 0;
		int ret = 0;
		for(int i=0;i<p.size();i++) if(p[i] != -1) ret += 1;
		for(int i=0;i<M;i++,t++) if(board[r-1][i]) state |= (1<<t);
		for(int i=0;i<M;i++,t++) if(board[r][i]) state |= (1<<t);
		ret += solve(r+1,state);
		if(dp[make_pair(r,prev)].first < ret) dp[make_pair(r,prev)] = make_pair(ret,p);
		return dp[make_pair(r,prev)].first;
	}	
}
			

