ll fac[maxn];

void init() {
	fac[0] = 1;
	for(int i = 1; i <= 100000; i++)
		fac[i] = fac[i - 1] * i % mod;
}

ll quickMod(ll x, ll y) {
	ll res = 1;
	while(y) {
		if(y & 1) res = res * x % mod;
		y >>= 1, x = x * x % mod;
	}
	return res;
}

ll C(int n, int m) {
	if(n > m) return 0;
	ll up = fac[m];
	ll down = fac[n] * fac[(m - n)] % mod;
	return up * quickMod(down, mod - 2) % mod;
}

