using namespace std;

const int MAXN = 305;
const int inf = 10000007;

typedef long long ll;

struct Matrix{
  int mat[MAXN + 1][MAXN + 1];
  Matrix(){}
  Matrix(int val){
    memset(mat, val, sizeof mat);
  }
  int operator()(int a, int b) const{
    return mat[a][b];
  }
  int& operator()(int a, int b){
    return mat[a][b];
  }

  void refresh(){
    for(int i = 0; i <= MAXN; i++)
      for(int j = 0; j <= MAXN; j++)
        mat[i][j] = (i == j) ? 0 : -inf;
  }

};

int n, m;
Matrix mat, poc;

Matrix operator * (const Matrix &A, const Matrix &B){
  Matrix C;
  for(int i = 1; i <= n; i++){
    for(int j = 1; j <= n; j++){
      C(i, j) = -inf;
      for(int k = 1; k <= n; k++){
        C(i, j) = max(C(i, j), A(i, k) + B(k, j));
      }
    }
  }
  return C;
}

Matrix tmp;

void Pot(int x){
  poc.refresh();
  while(x){
    if(x & 1) poc = poc * tmp;
    tmp = tmp * tmp;
    x >>= 1;
  }
}

bool moze(int x){
  tmp = mat;
  Pot(x);
  for(int i = 1; i <= n; i++)
    if(poc(i, i) > 0) return true;
  return false;
}

