ll solve(int l, int r, int t1, int t2){
	//cout << l << " " << r << endl; return 0;
	if(l>=r) return 0;
	if(dp[l][r][t1][t2]!=-1) return dp[l][r][t1][t2];

	ll ans=0;
	if(par[l]==r){
		if(t1!=0 && t2!=0) return 0;
		if(t1==0 && t2==0) return 0;
		if(l+1==r) return 1;

		rep(i,3) rep(j,3){
			if(i>0 && i==t1) continue;
			if(j>0 && j==t2) continue;
			ans+= solve(l+1, r-1, i, j);
			ans%= MOD;
		}
		//cout << l << " " << r << endl;
	}
	else{
		rep(i,3) rep(j,3){
			if(i>0 && i==j) continue;
			ans+= (solve(l,par[l],t1,i)*solve(par[l]+1,r,j,t2))%MOD;
			ans%= MOD;
		}
	}
	return dp[l][r][t1][t2]= ans;
}


