void build(int node,int b,int e){
    if(b==e){
        st[node].sum=a[b];
        st[node].pref=st[node].suff=st[node].sub=max(a[b],a[b]);
    }else{
        build(left,b,mid);
        build(right,mid+1,e);
        st[node].pref=max(st[left].pref,st[left].sum+st[right].pref);
        st[node].suff=max(st[right].suff,st[right].sum+st[left].suff);
        st[node].sum=st[left].sum+st[right].sum;
        st[node].sub=max(st[left].suff+st[right].pref,max(st[left].sub,st[right].sub));
    }   
}

Node query(int node,int b,int e,int i,int j){
    if(b>j||e<i)return Node();
    if(b>=i&&e<=j)return st[node];

    Node l=query(left,b,mid,i,j);
    Node r=query(right,mid+1,e,i,j);

    Node an;
    an.pref=max(l.pref,l.sum+r.pref);
    an.suff=max(r.suff,r.sum+l.suff);
    an.sum=l.sum+r.sum;
    an.sub=max(l.suff+r.pref,max(l.sub,r.sub));
    return an;
}

