const int N = 5123;
const int mod = 1e9 + 7;
int nCr[N][N];
char s[N];

int main(){
	for(int i = 0; i < N; ++i){
		for(int j = 0; j <= i - j; ++j){
			if(j == 0) 
				nCr[i][j] = nCr[i][i] = 1;
			else
				nCr[i][j] = nCr[i][i - j] = (nCr[i - 1][j] + nCr[i - 1][j - 1]) % mod;
		}
	}
	int t;
	scanf("%d", &t);
	while(t--){
		scanf("%s", s);
		int n = strlen(s);
		int r = 0;
		for(int i = 0; i < n; ++i)
			r += s[i] - 'a';
		int ans = 0;
		for(int i = 0; 26 * i <= r; ++i){
			int sgn = (i & 1) ? -1 : 1;
			ans = (ans + mod + 1LL * sgn * nCr[n][i] * nCr[n + r - 26 * i - 1][n - 1] % mod) % mod;
		}
		ans = (ans + mod - 1) % mod;
		printf("%d\n", ans);
	}
}

