int fishes;

double rec(int mask)
{
	if(__builtin_popcount(mask) == fishes)
		return 1.0;

	double &ret = dp[mask];
	if(ret >= 0.0)
		return ret;

	ret = 0.0;

	int i, j, done = 0;

	fl(i,0,fishes)
		if((1 << i) & mask)
			done++;

	fl(j,0,fishes)
	{
		if((1 << j) & mask)
			continue;
		fl(i,0,fishes)
		{
			if((1 << i) & mask)
				ret += ((2 * mat[i][j] / (done * (done + 1))) * rec(mask | (1 << j)));
		}
	}

	return ret;
}

