using namespace std;

typedef long long LL;
typedef pair<int,int> ii;
typedef pair<ii,ii> iv;

int num[100100],low[100100],mark[100100],number,p[100100],n,m,x,y,c,z,ans[100100];
vector<iv> edge;
vector<ii> graph[100100];

int findSet(int u){
	return u==p[u] ? u : p[u] = findSet(p[u]);
}

void dfs(int u, int par){
	num[u] = low[u] = number++;
	for(int i=0;i<graph[u].size();i++){
		int v = graph[u][i].fi;
		int id = graph[u][i].sc;
		if(id==par) continue;
		if(!num[v]){
			dfs(v, id);
			low[u] = min(low[u], low[v]);
		}
		else low[u] = min(low[u], num[v]);
	}
	if(par!=-1 && low[u]==num[u]) ans[par]++;
}

int main(){
	memset(mark,-1,sizeof(mark));
	scanf("%d %d",&n,&m);
	for(int i=1;i<=n;i++){
		p[i] = i;
	}
	for(int i=0;i<m;i++){
		scanf("%d %d %d",&x,&y,&c);
		edge.pb(mp(mp(c,i),mp(x,y)));
	}
	sort(edge.begin(),edge.end());
	for(int i=0;i<edge.size();){
		int j = i;
		vector<int> v;
		number = 1;
		bool check = false;
		while(j<edge.size() && edge[j].fi.fi==edge[i].fi.fi){
			x = edge[j].sc.fi;
			y = edge[j].sc.sc;
			z = edge[j].fi.sc;
			check = true;
			x = findSet(x);
			y = findSet(y);
			if(findSet(x)!=findSet(y)){
				ans[z]++;
				if(mark[x]!=i){
					mark[x] = i;
					graph[x].clear();
					num[x]=0;
					v.pb(x);
				}
				if(mark[y]!=i){
					mark[y] = i;
					graph[y].clear();
					num[y]=0;
					v.pb(y);
				}
				graph[x].pb(mp(y,z));
				graph[y].pb(mp(x,z));
			}
			j++;
		}
		for(int k=0;k<v.size();k++){
			if(check && !num[v[k]]) dfs(v[k], -1);
		}
		while(i<j){
			x = edge[i].sc.fi;
			y = edge[i].sc.sc;
			p[findSet(x)] = findSet(y);
			i++;
		}
	}
	for(int i=0;i<m;i++){
		if(ans[i]==0) printf("none\n");
		else if(ans[i]==1) printf("at least one\n");
		else printf("any\n");
	}
	return 0;
}

