int n, m, T[MAXT * 2], Tnum, maxv[MAXT << 4], ans[MAXT];
map<int, int> mp;

void update(const int &lur, const int &x, int o, int L, int R) {
    if(L == R) {
        maxv[o] = x;
        return;
    }
    int mid = (L + R) >> 1;
    if(lur <= mid)  update(lur, x, o << 1, L, mid);
    else  update(lur, x, o << 1 | 1, mid + 1, R);
    maxv[o] = max(maxv[o << 1], maxv[o << 1 | 1]);
}

int query(const int &ql, const int &qr, const int &u, int o, int L, int R) {
    if(maxv[o] < u)  return -1;
    if(L == R)  return L;
    int mid = (L + R) >> 1;
    if(ql <= mid) {
        int tmp = query(ql, qr, u, o << 1, L, mid);
        if(tmp != -1)  return tmp;
    }
    if(qr > mid) {
        int tmp = query(ql, qr, u, o << 1 | 1, mid + 1, R);
        if(tmp != -1)  return tmp;
    }
    return -1;
}

