		tpos[i] = getNxt(a[i], -1);
		for (int k = i + 1; k < 2 * la; k++)
			if (getNxt(a[k], tpos[k - 1] + 1) < tpos[k])
				tpos[k] = getNxt(a[k], tpos[k - 1] + 1);
