#include <bits/stdc++.h>
#define X first
#define Y second
#define FI(i,a,b) for(int i=(a);i<=(b);i++)
#define FD(i,a,b) for(int i=(a);i>=(b);i--)
using namespace std;
using LL = long long;
using PII = pair<int,int>;

const int N = 1005;
int n, k, dis[N][N], vis[N];
PII ps[N];
vector<int> g[N];
inline int dist(PII p, PII q) { return (p.X-q.X)*(p.X-q.X)+(p.Y-q.Y)*(p.Y-q.Y); }

bool dfs(int u, int k) {
	if (u>n) return true;
	if (vis[u]) return dfs(u+1, k);
	for (auto v: g[u]) k -= !vis[v]++;
	if (k>=0 && dfs(u+1, k)) return true;
	int tmp = k;
	vis[u] = 1;
	for (auto v: g[u]) k += !--vis[v];
	if ((--k)>=0 && k>tmp && dfs(u+1, k)) return true;
	vis[u] = 0;
	return false;
}
bool check(int mid) {
	FI(i,1,n) vis[i]=0, g[i].clear();
	FI(i,1,n) FI(j,1,n) if (dis[i][j]>mid) g[i].push_back(j);
	return dfs(1,k);
}
int main() {
	scanf("%d%d", &n, &k);
	FI(i,1,n) scanf("%d%d", &ps[i].X, &ps[i].Y);
	FI(i,1,n) FI(j,i+1,n) dis[i][j]=dis[j][i]=dist(ps[i], ps[j]);
	int lb = -1, ub = INT_MAX;
	while (lb+1<ub) {
		int mid = (LL)lb+ub>>1;
		if (check(mid)) ub=mid; else lb = mid;
	}
