#include<bits/stdc++.h>
#define MAXN 100010
#define LN 20
#define inf 100000000
#define pb push_back
using namespace std;

//dfs variables
bool vis[MAXN];
vector<int>adj[MAXN],costs[MAXN],indx[MAXN];
int tme=-1,par[MAXN],sze[MAXN],endon[MAXN],spc[MAXN],depth[MAXN],mx=-1;

//lca variables
//

//hld variables
int iter=0,chainno=0,chainhead[MAXN],chainpos[MAXN],chainind[MAXN];

//segtree variables
int tree[4*MAXN],arr[MAXN],posinarr[MAXN];

void dfs(int node){
	if(vis[node])
		return ;
	vis[node]=true; sze[node]=1;mx=-1;
	for(int i=0;i<adj[node].size();i++){
		int child=adj[node][i];
		if(vis[child])
			continue;
		depth[child]=depth[node]+1;
		endon[indx[node][i]]=child;
		dfs(child);
		par[child]=node;
		sze[node]+=sze[child];	
		if(sze[child]>mx){
			mx=sze[child];
			spc[node]=i;
		}
	}
}

//
//lca begin
//

int LCA(int u,int v){
	int uchain=chainind[u],vchain=chainind[v];
	while(uchain!=vchain){
		if(depth[chainhead[uchain]]>depth[chainhead[vchain]]){
			u=par[chainhead[uchain]];
		}
		else
			v=par[chainhead[vchain]];
		uchain=chainind[u];vchain=chainind[v];
	}
	if(depth[u]<depth[v])
		return u;
	return v;
}
//
//lca end
//


//
//segment tree begins
//
void build(int l,int r,int node){
	if(l==r){
		tree[node]=arr[l];
		return ;
	}
	int mid=(l+r)>>1;
	build(l,mid,node<<1);
	build(mid+1,r,node<<1|1);
	tree[node]=tree[node<<1]+tree[node<<1|1];
}

void update(int ind,int val,int l,int r,int node){
	if(l==r){
		tree[node]=val;
		arr[l]=val;
		return ;
	}
	int mid=(l+r)>>1;
	if(ind>=l && ind<=mid)
		update(ind,val,l,mid,node<<1);
	else
		update(ind,val,mid+1,r,node<<1|1);
	tree[node]=tree[node<<1]+tree[node<<1|1];
}

int query(int x,int y,int l,int r,int node){
	if(l>y || r<x)
		return 0;
	else if(l>=x && r<=y)
		return tree[node];
	int mid=(l+r)>>1;
	return query(x,y,l,mid,node<<1)+query(x,y,mid+1,r,node<<1|1);
}
//
//segment tree ends
//

//
//hld begins
//

void HLD(int node,int val){
	if(chainhead[chainno]==-1){
		chainhead[chainno]=node;
	}
	
	chainind[node]=chainno;	
	posinarr[node]=iter;
	arr[iter]=val;
	iter++;
	if(spc[node]>=0)
		HLD(adj[node][spc[node]],costs[node][spc[node]]);
	
	for(int i=0;i<adj[node].size();i++){
		int child=adj[node][i];
		if(chainind[child]==-1){
			chainno++;
			HLD(adj[node][i],costs[node][i]);
		}
	}
}
//
//hld ends
//

//
//tree updates and queries: start
//
int sub_query(int u,int v){
	if(u==v)
		return 0;
	int uchain=chainind[u],vchain=chainind[v],ans=0,x,y;
	while(uchain!=vchain){
		x=posinarr[u];y=posinarr[chainhead[uchain]];
		ans+=query(y,x,0,iter,1);
		u=par[chainhead[uchain]];
		uchain=chainind[u];
	}
	x=posinarr[u];y=posinarr[v];
	return ans+query(y+1,x,0,iter,1);
}

void update_tree(int ind,int val){
	update(posinarr[endon[ind]],val,0,iter,1);
}

int query_tree(int u,int v){
	int lca=LCA(u,v);
	if(sub_query(u,lca)+sub_query(v,lca))
		return -1;
	return depth[u]+depth[v]-2*depth[lca];
}
//
//end
//

void cleanup(int n){
	tme=-1;chainno=0,iter=0,mx=-1;
	for(int i=0;i<=n;i++){
		adj[i].clear(); costs[i].clear(); indx[i].clear();
		chainhead[i]=-1; chainind[i]=-1; spc[i]=-1;
		vis[i]=false;
	}	
}

int main(){
	int n,u,v,w,ind,val;
	scanf("%d",&n);
	cleanup(n);
	for(int i=0;i<n-1;i++){
		scanf("%d%d",&u,&v);
		adj[u].pb(v);	
		adj[v].pb(u);
		costs[u].pb(0);
		costs[v].pb(0);
		indx[u].pb(i);
		indx[v].pb(i);
	}
	depth[1]=1;
	dfs(1); HLD(1,0); build(0,iter,1);
	int q,ty;
	scanf("%d",&q);
	for(int i=0;i<q;i++){
		scanf("%d",&ty);
		if(ty==1){
			scanf("%d",&ind);
			ind--;
			update_tree(ind,0);
		}
		else if(ty==2){
			scanf("%d",&ind);
			ind--;
			update_tree(ind,1);
		}		
		else{				
			scanf("%d%d",&u,&v);
			printf("%d\n",query_tree(u,v));
		}
	}
	return 0;
}

