    int left_son;
    int right_son;
    int sum;
}tree1[MAX_N * 32], tree2[MAX_N * 32];

int total1 = 1;
int total2 = 1;
int root = 1;

void add1(int &u, int lt, int rt, int pos, int value){
    if(u==0){
        u = ++total1;
    }
    tree1[u].sum += value;
    if(lt == rt) return;
    int z = (rt + lt ) >>1;
    if(pos<=z) add1(tree1[u].left_son, lt, z, pos, value); else
               add1(tree1[u].right_son, z+1, rt, pos, value);
}

int get_sum1(int u, int lt, int rt, int l, int r){
    if(u==0 || lt > r || rt < l) return 0;
    if(lt >= l && rt <= r) return tree1[u].sum;
    int mid = (lt + rt) >> 1;
    int r1 = get_sum1(tree1[u].left_son, lt, mid, l, r);
    int r2 = get_sum1(tree1[u].right_son, mid+1, rt, l, r);
    return r1 + r2;
}

void try_add2(int &u, int lt, int rt, int pos, int value){
    if(u==0){
        u = ++total2;
    }
    tree2[u].sum = max(tree2[u].sum, value);
    if(lt == rt) return;
    int z = (rt + lt) >>1;
    if(pos<=z) try_add2(tree2[u].left_son, lt, z, pos, value); else
               try_add2(tree2[u].right_son, z+1, rt, pos, value);
}

int get_max2(int u, int lt, int rt, int l, int r){
    if(u==0 || lt > r || rt < l) return 0;
    if(lt >= l && rt <= r) return tree2[u].sum;
    int mid = (lt + rt) >> 1;
    int r1 = get_max2(tree2[u].left_son, lt, mid, l, r);
    int r2 = get_max2(tree2[u].right_son, mid+1, rt, l, r);
    return max(r1,r2);
}

