int n;
char s[N];
vector<int> p, ans;
bool solve() {
	if (!sz(p))
		return false;
	if (p.front() == 0 || p.front() > 8)
		return false;
	if (p.back() == n - 1 || n - p.back() > 4)
		return false;
	rep(i, 1, sz(p)) {
		int d = p[i] - p[i - 1] - 1;
		if (!(2 <= d && d <= 11))
			return false;
	}
	rep(i, 1, sz(p)) {
		int d = p[i] - p[i - 1] - 1;
		rep(j, 1, 4)
			if (1 <= d - j && d - j <= 8) {
				ans.pb(p[i - 1] + j);
				break;
			}
	}
	ans.pb(n - 1);
	return true;
}
