int n, a[N], lg[N], st[N][20];
vector<int> p[N];
vector<pii> ans;
int qry(int l, int r) {
	int k = lg[r - l + 1];
	return min(st[l][k], st[r - (1 << k) + 1][k]);
}
void dfs(int l, int r, int dec) {
	if (l > r)
		return ;
	int i, mn = qry(l, r);
	rep(i, dec, mn)
		ans.pb(mp(l + 1, r + 1));
	if (l == r)
		return ;
	i = lower_bound(p[mn].begin(), p[mn].end(), l) - p[mn].begin();
	int last = l;
	while (i < sz(p[mn]) && p[mn][i] <= r) {
		dfs(last, p[mn][i] - 1, mn);
		last = p[mn][i] + 1;
		++i;
	}
	dfs(last, r, mn);
}
