double dp[2][201];
double p[2];
double q[2];
double win = 0;
double lose = 0;


void add(int k, int h, double q) {
	if (h <= 0) h = 0;
	dp[k][h] += q;
}

void go(int k, int hp,int l,int r) {	
	int z = 1 - k;
	double __p = dp[k][hp] / (r - l + 1);
	dp[k][hp] = 0;
	for (int x = l; x <= r; x++){
			add(k,hp - x, q[z] * __p);
			add(k,hp,	  p[z] * __p);
		}
}

int main()
{
	int hp1, hp2, dt1, dt2, _p1, _p2, l0, l1, r0, r1;
	cin >> hp1 >> dt1 >> l0 >> r0 >> _p1;
	cin >> hp2 >> dt2 >> l1 >> r1 >> _p2;
	if (_p1 == 100) { cout << 0 << endl; return 0; }
	if (_p2 == 100) { cout << 1 << endl; return 0; }
	p[0] = _p1 / 100.0;
	p[1] = _p2 / 100.0;
	q[0] = 1 - p[0];
	q[1] = 1 - p[1];
	dp[0][hp1] = dp[1][hp2] = 1;
	int t = 0;
	double res = 0;
	while (win + lose < 2 - 1e-4 )
	{
		if (t % dt1 == 0)
			for (int i = 1; i <= hp2; i++)
				go(1, i, l0, r0);
		if (t % dt2 == 0) 
			for (int i = 1; i <= hp1; i++)
				go(0, i, l1, r1);
		res += dp[1][0] * (1 - lose);
		win += dp[1][0]; 
		lose += dp[0][0];
		dp[1][0] = dp[0][0] = 0;
		t++;
	}
	cout << res << endl;
	cerr << lose << endl;
	
#ifdef _DEBUG
	system("pause"); //453246046 / 359738130
#endif 
	return 0;
}

