int get(int x, int y) {
    int i = lower_bound(pref, pref + m + 1, 1 + x) - pref;
    int in_our = -1;
    if (i >= 1 && i <= m) {
        in_our = upper_bound(all(ex[id[i]][y]), x - pref[i - 1]) - ex[id[i]][y].begin();
        if (in_our == sz(ex[id[i]][y])) in_our = -1;
        else in_our = ex[id[i]][y][in_our] + pref[i - 1]; 
    }
    return merge((i < m ? last[i + 1][y] : -1), in_our);             
}
  
