#include<bits/stdc++.h>

using namespace std;

const int Maxn=1e5+10;

int n,m,k,par[Maxn][22],f[Maxn][22],h[Maxn],cr[Maxn],ans[Maxn];
bool mark[Maxn];
vector<int> adj[Maxn];
map<pair<int,int>,bool> c;
pair<int,int> p[Maxn];

void DFS(int v)
{
    mark[v]=1;
    for(int i=0;i<adj[v].size();i++)
    {
        if(mark[adj[v][i]]&&par[v][0]!=adj[v][i])
            cr[v]=min(cr[v],h[adj[v][i]]);
        else if(!mark[adj[v][i]])
            {
                par[adj[v][i]][0]=v;
                h[adj[v][i]]=h[v]+1;
                DFS(adj[v][i]);
                cr[v]=min(cr[v],cr[adj[v][i]]);
                if(cr[adj[v][i]]>h[v])
                    c[make_pair(v,adj[v][i])]=c[make_pair(adj[v][i],v)]=1;
                if(c[make_pair(adj[v][i],v)])
                    f[adj[v][i]][0]=1;
            }
    }
}

void pr(int v)
{
    for(int i=1;i<20;i++)
    {
        par[v][i]=par[par[v][i-1]][i-1];
        if(par[v][i]==par[v][i-1])
        {
            f[v][i]=f[v][i-1];
        }
        else
        f[v][i]=f[v][i-1]+f[par[v][i-1]][i-1];
    }
}

int LCA(int v,int u)
{
    int res=0;
    //cerr<<"u,v:"<<u+1<<" "<<v+1<<endl;
    for(int i=20;i>=0;i--)
        if(par[v][i]!=par[u][i])
        {
            res+=f[v][i]+f[u][i];
            v=par[v][i];
            u=par[u][i];
        }
    //cerr<<"v,u:"<<v+1<<" "<<u+1<<"par v,u:"<<par[v][0]+1<<" "<<par[u][0]+1<<endl;
    return res+f[v][0]+f[u][0];
}

pair<int,int> rep(int v,int u)
{
    int res=0;
    if(h[v]==h[u])
        return make_pair(v,0);
    for(int i=20;i>=0;i--)
        if(h[par[v][i]]>=h[u])
        {
          //  cerr<<"res+="<<f[v][i]<<endl;
            res+=f[v][i];
            v=par[v][i];
        }
        return make_pair(v,res);
}

int main()
{
    cin>>n>>m;
    for(int i=0;i<m;i++)
    {
        int t1,t2;
        cin>>t1>>t2;
        adj[--t1].push_back(--t2);
        adj[t2].push_back(t1);
    }
    for(int i=0;i<n;i++)
        cr[i]=1e9;
    DFS(0);
    cin>>k;
    for(int i=0;i<k;p[i].first--,p[i].second--,i++)
        cin>>p[i].first>>p[i].second;
   // for(int i=0;i<n;i++)
     //   pr(i);
    for(int i=1;i<=20;i++)
        for(int j=0;j<n;j++)
        {
            par[j][i]=par[par[j][i-1]][i-1];
            if(par[j][i]!=par[j][i-1])
                f[j][i]=f[j][i-1]+f[par[j][i-1]][i-1];
            else
                f[j][i]=f[j][i-1];
        }
    for(int i=0;i<k;i++)
    {
        int t1=p[i].first,t2=p[i].second;
        if(h[t1]>h[t2])
            swap(t1,t2);
        pair<int,int>t=rep(t2,t1);
        int t3=t.first,t4=t.second;
      //  cerr<<t4<<endl;
        if(t3==t1)
            ans[i]=t4;
        else
            ans[i]=LCA(t1,t3)+t4;
    }
    for(int i=0;i<k;i++)
        cout<<ans[i]<<endl;
     // cerr<<"*********\n";
 //   for(map<pair<int,int>,bool>::iterator it=c.begin();it!=c.end();it++)
