  if (dis(x, y, i, j) > d) xx = i, yy = j, d = dis(x, y, i, j);
  f[i][j] = 0;
  if (f[i][j - 1]) dfs(i, j - 1);
  if (f[i][j + 1]) dfs(i, j + 1);
  if (f[i - 1][j]) dfs(i - 1, j);
  if (f[i + 1][j]) dfs(i + 1, j);
}
void dfs2(int i, int j) {
  cnt++;
  if (dis(x, y, i, j) > d) xx = i, yy = j, d = dis(x, y, i, j);
  s[i][j] = 0;
  if (s[i][j - 1]) dfs2(i, j - 1);
  if (s[i][j + 1]) dfs2(i, j + 1);
  if (s[i - 1][j]) dfs2(i - 1, j);
  if (s[i + 1][j]) dfs2(i + 1, j);
}
