  for (int i = 1; i <= m; i++) {
    temps[r][i] = (i & 1) ? a : b;
  }
}

void preproces() {
  if (m == 1) {
    for (char i = 'a'; i <= 'z'; i++) {
      temps[++sz][1] = i;
    }
  } else {
    for (char i = 'a'; i <= 'z'; i++) {
      for (char j = 'a'; j <= 'z'; j++) {
        if (i == j) {
          continue;
        }
        fill(i, j, ++sz);
      }
    }
  }
}

bool check(int r1, int r2) {
  for (int i = 1; i <= m; i++) {
    if (temps[r1][i] == temps[r2][i]) {
      return 0;
    }
  }
  return 1;
}

int calcDifference(int r1, int r2) {
  int ret = 0;
  for (int i = 1; i <= m; i++) {
    ret += (mt[r1][i] != temps[r2][i]);
  }
  return ret;
}

