  for (int i = 2; i <= n; i++) {
    for (int j = 1; j <= sz; j++) {
      for (int k = 1; k <= sz; k++) {
        if (ch[j][k]) {
          if (dp[i - 1][k] + diff[i][j] < dp[i][j]) {
