const double EPS = 1e-8;
//--------head--------
int n, m, k;
int a[N][N], b[N][N], c[N][N];
char str[N];
struct Node {
	int buy, sell, cnt;
	Node() {
	}
	Node(int _buy, int _sell, int _cnt) {
		buy = _buy, sell = _sell, cnt = _cnt;
	}
	bool operator<(const Node &p) const {
		return sell - buy > p.sell - p.buy;
	}
};
vector<Node> item;
int main() {
	scanf("%d%d%d", &n, &m, &k);
	rep(i, 0, n) {
		scanf(" %s", str);
		rep(j, 0, m)
			scanf("%d%d%d", &a[i][j], &b[i][j], &c[i][j]);
	}
	int ans = 0;
	rep(i, 0, n)
		rep(j, 0, n) { // i -> j
			item.clear();
			rep(r, 0, m)
				item.pb(Node(a[i][r], b[j][r], c[i][r]));
			sort(item.begin(), item.end());
			int profit = 0, can = k;
			rep(r, 0, sz(item)) {
				int num = min(can, item[r].cnt);
				if (item[r].sell - item[r].buy < 0)
					break;
				profit += num * (item[r].sell - item[r].buy);
				can -= num;
				if (can == 0)
					break;
			}
			ans = max(ans, profit);
		}
	printf("%d\n", ans);
	return 0;
}

