			inc(f[w][j], sum), inc(f[w][j], MOD - f[w ^ 1][j]);
			inc(nsum, sum), inc(nsum, MOD - f[w ^ 1][j]);
		}
		sum = nsum;
	}
	int ans = 0;
	rep(i, 0, n) 
		if (check(n, s + i, t))
			inc(ans, f[w][i]);
	printf("%d\n", ans);
