typedef long long ll;
typedef int int_type;
typedef pair<int_type, int_type> pii;
typedef vector<int_type> vi;

const int MAXN = 100010;
vi adj[MAXN];
vi radj[MAXN];
int num[MAXN];
int color[MAXN];

int dfs1(int src, int val) {
	color[src] = 1;
	num[src] = val;
	int ans = 0;
	for (auto x : adj[src]) {
		if (!color[x]) ans = max(ans, dfs1(x, val+1));
		else if (color[x] == 1) ans = max(ans, abs(val+1 - num[x]));
	}

	for (auto x : radj[src]) {
		if (!color[x]) ans = max(ans, dfs1(x, val-1));
		else if (color[x] == 1) ans = max(ans, abs(val-1 - num[x]));
	}	

	color[src] = 2;
	return ans;
}

bool dfs2(int src, int val, int mod) {
	color[src] = 1;
	num[src] = val;
	for (auto x : adj[src]) {
		if (!color[x] && !dfs2(x,(val+1)%mod, mod)) return false;
		else if (color[x] == 1 && (val+1)%mod != num[x]%mod) return false; 
	}

	for (auto x : radj[src]) {
		if (!color[x] && !dfs2(x,((val-1)%mod + mod)%mod, mod)) return false;
		else if (color[x] == 1 && ((val-1)%mod + mod)%mod != num[x]%mod) return false; 
	}	

	color[src] = 2;
	return true;
}

int main() {
	int n, m;
	cin >> n >> m;
	while (m--) {
		int x, y;
		cin >> x >> y;
		--x; --y;
		adj[x].pb(y);
		radj[y].pb(x);
	}
	int maxd = 0;
	CLR(color);

	FOR0(i,n) if (!color[i]) {
		maxd = max(maxd, dfs1(i,0));
	}

	//~ DBG(maxd);

	if (!maxd) cout << n << endl;
	else {
		for (int i = maxd; i>=1; --i) if(maxd%i == 0) {
			CLR(color);
			bool ans = true;
			FOR0(j,n) if (!color[j] && !dfs2(j,0,i)) {ans = false; break;}
			if (ans) {
				cout << i << "\n";
				exit(0);
			} 
		}
	}
}

#include <bits/stdc++.h>
using namespace std;

const int N = 3011, M = 311;

int p[M][N];
double dp[M][N];
double acc[M];

double nxt[N];
void solve(int p[], double dp[], double &acc, int n) {
	fill(nxt, nxt + n + 1, 0);
	for(int i = 1; i <= n; i ++)
		nxt[i] = (dp[i - 1] * p[i] + nxt[i - 1] * (1000 - p[i])) / 1000;
	copy(nxt, nxt + n + 1, dp);
	acc += dp[n];
}

int main() {
	int n, m; scanf("%d%d", &n, &m);
	for(int i = 1; i <= n; i ++)
		for(int j = 1; j <= m; j ++)
			scanf("%d", &p[j][i]);
	for(int i = 1; i <= m; i ++) {
		dp[i][0] = 1;
		for(int j = 1; j <= n; j ++)
			dp[i][j] = dp[i][j - 1] * (1000 - p[i][j]) / 1000;
		acc[i] += dp[i][n];
	}

	double ans = 0;
	for(int i = 1; i <= n; i ++) {
		int buy = 1;
		for(int j = 2; j <= m; j ++)
			if(acc[j] < acc[buy])
				buy = j;
		ans += 1 - acc[buy];
		solve(p[buy], dp[buy], acc[buy], n);
	}

	cout << fixed << setprecision(12) << ans << '\n';
	return 0;
}

