typedef long long int ll;

ll n,m,mini;

ll r[2000000];
ll rini[2000000];

ll sol=0;
ll grupos=0;
ll caben[2000000];


void unomas()
{
  ll solact=0;
  for (int i=1;i<=n;i++)
    r[i]=rini[i];
  m=mini;
  grupos++;
  if (grupos*n>m) return;
  for (int i=1;i<=n;i++)
    if (grupos*i+n*grupos*(grupos-1)/2>r[i])
      return;
  for (ll g=grupos;g>=1;g--) {
    for (int i=n;i>=1;i--) {
      m=min(m,r[i]);
      while ((g-1)*i+n*(g-1)*(g-2)/2>r[i]-m) m--;
      solact+=m;
      r[i]-=m;
      m--;
    }
  }
  sol=max(sol,solact);
}

int main()
{
  ios::sync_with_stdio(false);
  cin>>n>>m;
  mini=m;
  for (int i=1;i<=n;i++) {
    cin>>r[i];
    rini[i]=r[i];
  }
  for (;;) {
    ll acum=0;
    for (int i=n;i>=1;i--) {
      m=min(m,r[i]);
      if (m==0) {
	if (grupos) unomas();
	cout<<sol<<endl;
	exit(0);
      }
      acum+=m;
      r[i]-=m;
      m--;
    }
    grupos++;
    sol+=acum;
  }
}

