using namespace std;

typedef long long int ll;

ll mcd(ll a,ll b)
{
  if (a<b) swap(a,b);
  if (b==0) return a;
  return mcd(a%b,b);
}

ll absolut(ll x)
{
  if (x<0) return -x;
  return x;
}

struct point {
  ll x,y;
  point ()
  {
  }
  point (ll inx,ll iny) {
    x=inx;y=iny;
  }
};

ll prodvec(point p1,point p2)
{
  return p1.x*p2.y-p1.y*p2.x;
}

ll prodesc(point p1,point p2)
{
  return p1.x*p2.x+p1.y*p2.y;
}

point operator-(point p1,point p2)
{
  p1.x-=p2.x;
  p1.y-=p2.y;
  return p1;
}

int n,m;
point base;
vector<point> v;

int mitad(point p)
{
  return p.y<0 or (p.y==0 and p.x<0);
}

bool operator<(point p1,point p2)
{
  int m1=mitad(p1);
  int m2=mitad(p2);
  return m1<m2 or (m1==m2 and prodvec(p1,p2)>0);
}

int amount[2000000];

vector<point> f;

int main()
{
  cin>>n>>m;
  f=vector<point> (m);
  for (int i=0;i<m;i++)
    cin>>f[i].x>>f[i].y;
  for (int i=1;i<=n;i++)
    amount[i]=1;
  for (int i=0;i<m;i++) {
    base=f[i];
    //cout<<"caso "<<f[i].x<<" "<<f[i].y<<endl;
    v=vector<point> ();
    for (int j=0;j<m;j++)
      if (i!=j)
	v.push_back(f[j]-base);
    sort(v.begin(),v.end());
    int j=0;
    for (;j<int(v.size());) {
      point dir=v[j];
      //cout<<"dir "<<dir.x<<" "<<dir.y<<endl;
      int cuantos=2;
      while (j+1<int(v.size()) and prodesc(v[j],v[j+1])>0 and prodvec(v[j],v[j+1])==0) {
	j++;
	cuantos++;
      }
      j++;
      //cout<<"cuantos "<<cuantos<<endl;
      ll mc=mcd(absolut(dir.x),absolut(dir.y));
      dir.x/=mc;
      dir.y/=mc;
      if (dir.y!=0 and base.y%dir.y==0) {
	ll posx=base.x-dir.x*(base.y/dir.y);
	//cout<<"posx "<<posx<<endl;
	if (posx>=1 and posx<=n)
	  amount[posx]=max(amount[posx],cuantos);
      }
    }
  }
  ll sol=0;
  for (int i=1;i<=n;i++) {
    //cout<<"("<<i<<","<<amount[i]<<")";
    sol+=amount[i];
  }
  //cout<<endl;
  cout<<sol<<endl;
}

