long long fast_pow(long long  a, long long n)
{
	unsigned long long result = 1;
	unsigned long long power = n;
	unsigned long long value = a;
	while (power>0)
	{
		if (power & 1)
		{
			result = result*value;
			result = result % 1000000007;
		}
		value = value*value;
		value = value % 1000000007;
		power /= 2;
		//power >>= 1;
	}
	return result % 1000000007;
}
