long long power (long long a, long long n, long long mod )
{
    a %= mod ;
    long long res = 1 ;
    while(n)
    {
        if (n & 1) res = (res * a) % mod ;
        a = (a * a) % mod ;
        n >>= 1 ;
    }
    return res ;
}
long long power2(long long x, long long n, long long p)  // (x ^ (2 ^ n)) mod p
{
    if(x % p == 0) return 0;
    long long tmp = power(2, n, p - 1);
    return power(x, tmp, p );
}
