	for(int i=0; i<n; i++){
		a[i].nsub = 1e9;
		int s = 0, e = 5e8;
		while(s != e){
			int m = (s+e)/2;
			if(query(a[i].first - m, a[i].first + m, a[i].second - m, a[i].second + m)){
				e = m;
			}
			else s = m+1;
		}
		a[i].nsub = s;
