	}
	sort(cnd.begin(), cnd.end());
	cnd.resize(unique(cnd.begin(), cnd.end()) - cnd.begin());
	ret = min(ret, cnd.back());
	reverse(cnd.begin(), cnd.end());
	int pnt = 0;
	int sx = -1e9, ex = 1e9, sy = -1e9, ey = 1e9;
	for(auto &i : cnd){
