const int MOD = 1e9 + 7;

long long POW(long long x, long long p){
	if (p == 0)	{
		return 1;
	}
	if (p == 1) {
		return x % MOD;
	}
	if (p & 1){
		return (x * POW(x, p - 1)) % MOD;
	} else {
		long long X = POW(x, p / 2);
		return (X * X) % MOD;
	}
}

long long f(long long i){
	return (POW(2, i - 1) * (POW(2, i) - 1)) % MOD;
}

long long broot(long long n){
	long long U = 1, D = 0;
	for (int i = 1; i <= n; ++ i){
		long long nU = U * 3 + D, nD = D * 3 + U;
		U = nU % MOD, D = nD % MOD;
	}
	return U;
}

