		int hit = fhit(sub(0, a[i]));
		if (hit == inf)
			dp[i] = pos[n] - pos[i];
		else {
			int wait = mod - sub(a[hit], a[i]);
			dp[i] = dp[hit] + pos[hit] - pos[i] + wait;
		}
		update(t, a[i], i);
	}
