void RUN(int p, int qq)
{
    if(dis[p] <= 0) return;
    int d = dis[p];

    for(auto v : V[p])
    {
        if(dis[v] < d-1)
        {
            Q.push(v);
            dis[v] = d-1;
            if(vis[v])
                dis[v] = qq;
        }
    }
    return;
}

bool dijkstra(int val)
{
    clr(dis, -1);

    while(!Q.empty()) Q.pop();
    Q.push(src);
    dis[src] = val;

    while(!Q.empty())
    {
        RUN(Q.front(), val);
        Q.pop();
    }
    return dis[des] != -1;
}

