inline void update(int nod,int st,int end,int pos,pii val)
{
	if(pos>end||pos<st)
	{
		return;
	}
	else if(pos==st&&end==st)
	{
		tree[nod]=val;
	}
	else
	{
		int mid=(st+end)>>1;
		update(nod<<1,st,mid,pos,val);
		update((nod<<1)+1,mid+1,end,pos,val);
		tree[nod]=merge(tree[nod<<1],tree[(nod<<1)+1]);
	}
}
inline pii querry(int nod,int st,int end,int l,int r,int val)
{
	if(end<l)
	{
		return mk(-1,-1);
	}
	if(tree[nod].first<=val)
	{
		return mk(-1,-1);
	}
	if(st==end)
	{
		return tree[nod];
	}
	int mid=(st+end)>>1;
	pii ans=querry(nod<<1,st,mid,l,r,val);
	if(ans.first<val)
	{
		return querry((nod<<1)+1,mid+1,end,l,r,val);
	}
	return ans;
}
