int lca(int a,int b)
{
	int tmp,lg;
    if(l[a]<l[b])
    {
    	tmp=a;
    	a=b;
    	b=tmp;
    }
    for(lg=1;(1<<lg)<=l[a];lg++);
    lg--;
    for(int j=lg;j>=0;--j)
    {
    	if(l[a]-(1<<j)>=l[b])
    		a=p[a][j];
    }
    if(a==b)
    	return a;
    for(int j=lg;j>=0;--j)
    {
    	if(~p[a][j]&&p[a][j]!=p[b][j])
    		a=p[a][j],b=p[b][j];
    }
    if(~parent[a].first)
    	return parent[a].first;
    return a;
}
