const int MAXN = 300005;
int n, p[MAXN], a[MAXN];
struct Tree { int Mi, w1, w2, tag; } T[MAXN << 2];
#define lson o << 1, l, mid
#define rson o << 1 | 1, mid + 1, r
void Up(int o) {
	Int l = o << 1, r = o << 1 | 1;
	T[o].w1 = T[o].w2 = 0; T[o].Mi = min(T[l].Mi, T[r].Mi);
	if(T[l].Mi == T[o].Mi) T[o].w1 += T[l].w1, T[o].w2 += T[l].w2;
	else if(T[l].Mi - 1 == T[o].Mi) T[o].w2 += T[l].w1;
	if(T[r].Mi == T[o].Mi) T[o].w1 += T[r].w1, T[o].w2 += T[r].w2;
	else if(T[r].Mi - 1 == T[o].Mi) T[o].w2 += T[r].w1;
}

void Down(int o) {
	if(!T[o].tag) return;
	T[o << 1].tag += T[o].tag; T[o << 1].Mi += T[o].tag;
	T[o << 1 | 1].tag += T[o].tag; T[o << 1 | 1].Mi += T[o].tag;
	T[o].tag = 0;
}

void build(int o, int l, int r) {
	if(l == r) return void(T[o].Mi = T[o].w1 = 1);
	int mid = l + r >> 1;
	build(lson); build(rson);
	Up(o);
}

void Modify(int o, int l, int r, int p, int w) {
	if(p > r) return;
	if(p <= l) { T[o].tag += w; T[o].Mi += w; return; }
	int mid = l + r >> 1;
	Down(o);
	Modify(lson, p, w); Modify(rson, p, w);
	Up(o);
}

