		Modify(1, 1, n, (a[p[i]] = i) + 1, 1);
		if(a[p[i] - 1]) Modify(1, 1, n, a[p[i] - 1], -1);
		if(a[p[i] + 1]) Modify(1, 1, n, a[p[i] + 1], -1);
		ans += T[1].w1 - i + T[1].w2;
	}
	
	printf("%lld\n", ans);
