        if(y-t>0&&!vis[i][y-t]) {
            ex=i;
            ey=y-t;
            return false;
        }
        if(y+t<=m&&!vis[i][y+t]) {
            ex=i;
            ey=y+t;
            return false;
        }
    }
    return true;
}
