                if(x+i<=0||y+j<=0||x+i>=n||y+j>=m)continue;
                d[x][y]=max(d[x][y],d[x+i][y+j]-abs(i)-abs(j));
            }
        }
        while(Check(x,y)) {//接着一步一步往外扩展
