void solve() {
	ans = INF;
	int g = __gcd(c3, c5);
	rep(k4, 0, s + 1) {
		if (k4 * (c4 + c5) > s)
			break;
		if ((s - c4 * k4) % g)
			continue;
		int L, R, l = 0, r = min(k4, (s - c4 * k4 - c5 * k4) / c3);
		int v1 = c4 * k4 / c3, v2 = (s - 2 * c4 * k4) / c3, v3 = s - c4 * k4;
		// + +
		L = max(l, (c4 * k4 - 1) / c3 + 1), R = min(r, (s - 2 * c4 * k4) / c3);
		rep(k3, L, R + 1) 
			if ((v3 - c3 * k3) % c5 == 0) {
				upd(k3, k4, (v3 - c3 * k3) / c5);
				break;
			}
		// + -
		L = max(l, max((c4 * k4 - 1) / c3, (s - 2 * c4 * k4) / c3) + 1), R = r;
		rep(k3, L, R + 1) 
			if ((v3 - c3 * k3) % c5 == 0) {
				upd(k3, k4, (v3 - c3 * k3) / c5);
				break;
			}
		// - +
		L = l, R = min(r, min(c4 * k4 / c3, (s - 2 * c4 * k4) / c3));
		for (int k3 = R; k3 >= L; --k3)
			if ((v3 - c3 * k3) % c5 == 0) {
				upd(k3, k4, (v3 - c3 * k3) / c5);
				break;
			}
		// - -
		L = max(l, (s - 2 * c4 * k4 - 1) / c3 + 1), R = min(r, c4 * k4 / c3);	
		rep(k3, L, R + 1) 
			if ((v3 - c3 * k3) % c5 == 0) {
				upd(k3, k4, (v3 - c3 * k3) / c5);
				break;
			}
	}
	if (ans == INF) {
		puts("-1");
		return ;
	}
	printf("%d %d %d", K3, K4, K5);
}
