			continue;
		}
		bool z = !(t & 1);
		if (r.back().first < 0 && !z)r.back().second += t, --r.back().first;
		else if (r.back().first >= 0 && z)++r.back().first, r.back().second += t - 1;
		else r.push_back(make_pair(z ? 1 : -1, (t - 1) / 2 * 2 + 1));
	}
