		if (r[i].first < 0 && r[i].second == 1) {
			p[i] = 0;
			continue;
		}
		if (r[i].first >= 0)p[i] = r[i].first + r[i].second;
		else p[i] = r[i].second + r[i].first;
		p[i] += p[i - 1];
	}
	s[r.size() - 1] = r.back().second + r.back().first;
	for (int i = r.size() - 2; i >= 0; --i) {
		if (r[i].first < 0 && r[i].second == 1) {
			s[i] = 0;
