	ll mx2 = 0, a = 0, b = 0, an = 0;
	f(i, 0, r.size()) {
		an = max(an, (r[i].first < 0 ? r[i].second : r[i].first + r[i].second) + (i + 1 == r.size() ? 0 : s[i + 1]) + (i ? p[i - 1] : 0));
		a += r[i].second;
		if (r[i].first >= 0 || i == 0 || i + 1 == r.size()) {
			ll t = a + r[i].first + (i + 1 == r.size() ? 0 : s[i + 1]);
			an = max(an, t + mx2);
			mx2 = max(mx2, b + r[i].first + (i ? p[i - 1] : 0));
