class NumberMagic {
public:
	int theMin(int _N, int _M) {
		if (_N == 1) return 0;
		for (int i = 0; i < 100; i++) {
			c[i][0] = 1;
			for (int j = 1; j <= i; j++)
				c[i][j] = c[i - 1][j - 1] + c[i - 1][j];
		}
		ll N = _N, M = _M;
		ll lb = 0, ub = N - 1;
		while (ub - lb > 1) {
			ll mid = (lb + ub) / 2;
			ll n = N, sum = 0;
			for (ll k = 0; k <= mid && n; k++) {
				ll unko = min(n, C(mid, k));
				n -= unko;
				sum += k * unko;
			}
			if (!n && sum <= mid * M) ub = mid;
			else lb = mid;
		}
		return ub;
	}
};

