//--------head--------
struct Node {
	int c, f, l;
	Node() {
	}
	Node(int _c, int _f, int _l) {
		c = _c, f = _f, l = _l;
	}
};
int n, d, S;
vector<Node> vec;
bool cmp(const Node &p, const Node &q) {
	return p.f < q.f;
}
pair<int, int> solve() {
	pair<int, int> ans = mp(0, 0);
	int C = 0, flag = 0, minFuel = INF;
	rep(i, 0, n) {
		int c, f, l;
		scanf("%d%d%d", &c, &f, &l);
		C = min(n, C + c);
		if (l >= d && f <= S) {
			vec.pb(Node(c, f, l));
			if (c > 0)
				flag = 1, minFuel = min(minFuel, f);
		}
	}
	C *= flag;
	if (C >= n)
		ans = mp(n, -minFuel), C = 0;
	sort(vec.begin(), vec.end(), cmp);
	if (flag) {
		rep(i, 1, sz(vec))
			if (vec[i].f == minFuel) {
				swap(vec[i], vec[0]);
				break;
			}
		sort(vec.begin() + 1, vec.end(), cmp);
	}
	int s = 0;
	for (int i = 0; i < sz(vec) && s + vec[i].f <= S && C < n; ++i)
		++C, s += vec[i].f;
	ans = max(ans, mp(C, -s));
	C = s = 0;
	for (int i = 1; i < sz(vec) && s + vec[i].f <= S && C < n; ++i)
		++C, s += vec[i].f;
	ans = max(ans, mp(C, -s));
	return ans;
}
int main() {
	scanf("%d%d%d", &n, &d, &S);
	pair<int, int> ans = solve();
	printf("%d %d\n", ans.first, -ans.second);
	return 0;
}

