    for (d = 1; d < ld; ++d)
        for (i = 1; i <= n + n - (1 << d) + 1; ++i)
            lmin[d][i] = getminL(lmin[d - 1][i], lmin[d - 1][i + (1 << (d - 1))]);
    for (i = 1; i <= n + n; ++i) {
        jump[0][i] = getmin(L[i], i); range[0][i] = L[i];
        for (d = 1; range[d - 1][i]; ++d)
