string onlyLower(string s)
{
	string ret;
	for(int i = 0; i < (int)s.length(); i++)
		if('a' <= s[i] && s[i] <= 'z')
			ret += s[i];
	return ret;
}

int MAIN()
{
	prepare();
	string s;
	double s1 = 0, s2 = 0, s3 = 0;
	while(cin >> s)
	{
		s = onlyLower(s);
		if(s.length() <= 3)
			continue;
		if(Score1.count(s))
			s1 += Score1[s];
		if(Score2.count(s))
			s2 += Score2[s];
		if(Score3.count(s))
			s3 += Score3[s];

		if(Score1.count(s) && !Score2.count(s) && !Score3.count(s))
			s1 += Score1[s] * factor;
		if(!Score1.count(s) && Score2.count(s) && !Score3.count(s))
			s2 += Score2[s] * factor;
		if(!Score1.count(s) && !Score2.count(s) && Score3.count(s))
			s3 += Score3[s] * factor;
	}
	s1 /= 5150.0;
	s2 /= 4650.0;
	s3 /= 12000.0;

	double maxScore = max(max(s1, s2), s3);
	if(s1 == maxScore)
		cout << 1 << endl;
	else if(s2 == maxScore)
		cout << 2 << endl;
	else if(s3 == maxScore)
		cout << 3 << endl;
	//cout << s1 << " " << s2 << " " << s3 << endl;
	return 0;
}

