ll big_dfs(ll u, ll p, ll lv = 1)
{
    level[u] = lv;
    ll cn = 1, x, mx = 0, best = -1;

    for(ll i = 0; i < ed[u].size(); i++)
    {
        if(ed[u][i] != p)
        {
           x = big_dfs(ed[u][i], u, lv + 1);
           cn += x;

           if (x > mx)
           {
               best = ed[u][i];
               mx = x;
           }
        }
    }

    bigChild[u] = best;

    return cn;
}

void add(ll u, ll p, ll x)
{
    cnt[level[u]] += x;

    for(ll i = 0; i < ed[u].size(); i++)
        if(ed[u][i] != p && big[ed[u][i]] == 0)
            add(ed[u][i], u, x);
}


void dfs(ll u, ll p, bool keep)
{
    for(ll i = 0; i < ed[u].size(); i++)
        if(ed[u][i] != p && ed[u][i] != bigChild[u])
            dfs(ed[u][i], u, 0);  // traversing to all nodes bigChild will be traversed last

    if(bigChild[u] != -1)
    {
        dfs(bigChild[u], u, 1); //bigChild is being traversed last
        big[bigChild[u]] = 1;  // bigChild marked as big so that it is not used in add function
    }

    add(u, p, 1);

  //  cout << "in DFS " << u << " " << qr[u].size() << endl;

    for (ll i = 0; i < qr[u].size(); i++)
    {
       // cout << u << " " << qr[u][i].sd << " " << qr[u][i].fr << " " << level[u] << " " << cnt[qr[u][i].fr + level[u]].size() << endl;
        ans[qr[u][i].sd] = cnt[qr[u][i].fr];
     //   cout << cnt[qr[u][i].fr + level[u]].size() << " " << ans[qr[u][i].sd] << endl;
    }


    if(bigChild[u] != -1)
        big[bigChild[u]] = 0;

    if(keep == 0)
    {
        add(u, p, -1);
    }
}


