		return dp[pt][c1][c2][c3] = can(c2, c3);
	} else if (pt == 2) {
		return dp[pt][c1][c2][c3] = can(c3, c2) && can(c3, c1);
	} else {
		int ans = 0;
		if (can(c3, c2)) ans |= solve(pt - 1, pt - 3, c1, c3);
		if (can(c3, pt - 3)) ans |= solve(pt - 1, c3, c1, c2);
		return dp[pt][c1][c2][c3] = ans;
	}
}

