			if(s[i] == 'A' && s[(i - 1 + n) % n] == 'B') {
				rotate(s.begin(), s.begin() + i, s.end());
				break;
			}
		cout << solve(s, 0) + solve(s, 1) << '\n';
	}
	return 0;
}

