      if (!c[j]) addE(px[j], n + py[j], 1, 0);
    for (int j = 0; j < n; j++) {
      addE(le, j, dx[j] / i, 0);
      if (dx[j] % i) addE(le, j, 1, 1);
    }
    for (int j = 0; j < m; j++) {
      addE(n + j, ri, dy[j] / i, 0);
      if (dy[j] % i) addE(n + j, ri, 1, 1);
    }
