//-------head-------
int n, m, s;
ll nest() {
	if (!(s & 1))
		return 0;
	ll ret = 0;
	for (int i = 1, I = sqrt(s); i <= I; i += 2)
		if (s % i == 0) {
			if (i <= n && s / i <= m) {
				int a = i >> 1, b = (s / i) >> 1;
				ret += 1ll * (n - i + 1) * (m - s / i + 1) * (2ll * (a + 1) * (b + 1) - 1);
			}
			if (i * i != s && s / i <= n && i <= m) {
				int a = (s / i) >> 1, b = i >> 1;
				ret += 1ll * (n - s / i + 1) * (m - i + 1) * (2ll * (a + 1) * (b + 1) - 1);
			}
		}
//	printf("nest = %lld\n", ret);
	return ret;
}
ll cross() {
	ll ret = 0;
	for (int a = 1; a <= n; a += 2)
		for (int b = 1; b <= m && a * b < s; b += 2)
			for (int d = 1; d < b; d += 2)
				if ((s - a * b) % d == 0) {
					int c = (s - a * b) / d + a;
					if ((c & 1) && 1 <= c && c <= n) 
						ret += 1ll * (n - c + 1) * (m - b + 1);
				}
	return ret << 1;
}
int main() {
	scanf("%d%d%d", &n, &m, &s);
	ll ans = nest() + cross();
	printf("%lld", ans);
	return 0;
}

