void reduce(int &x, int &y, int &turns, int &errs) {
  while (min(x, y) > 0) {
    if (y == 1) {
      turns += x;
      errs += max(x - 2, 0);
      x = 1;
      y = 0;
      return;
    }
    if (x == 1) {
      turns += y;
      errs += max(y - 2, 0);
      x = 0;
      y = 1;
      return;
    }
    if (x > y) {
      turns += x / y;
      errs += max(0, x / y - 1);
      x %= y;
    } else {
      turns += y / x;
      errs += max(0, y / x - 1);
      y %= x;
    }
  }
}

