pair<int, int> gao(int a, int b) {
	pair<int, int> ret = make_pair(1, 0);
	while(max(a, b) > 1) {
		if (a < b)
			swap(a, b);
		int t = (a - 1) / b;
		a -= b * t;
		ret.first += t, ret.second += t - 1;

	}
	return ret;
}
void solve(int n, int r) {
	if (r == 1) {
		if (n == 1) {
			printf("0\nT");
