#include <bits/stdc++.h>

using namespace std;

vector<int> p;
vector<vector<int>> g;
vector<vector<pair<int, int>>> og;
vector<int> ans;
vector<int> dp;

// 0 - down edge 1 - back edge

void dfs_p(int v, int anc) {
    p[v] = anc;
    for (int to : g[v]) {
        if (to != anc) {
            dfs_p(to, v);
        }
    }
}

int dfs_dp(int v) {
    for (auto to : og[v]) {
        dp[v] += dfs_dp(to.first) + to.second;
    }
    return dp[v];
}

void dfs_ans(int v, int ans_up) {
    ans[v] = dp[v] + ans_up;
    for (auto to : og[v]) {
        dfs_ans(to.first, ans_up + dp[v] - dp[to.first] + (to.second == 0 ? 1 : -1));
    }
}

