const int mo = 1000000007;
int n, m, w, h, ans, res;
int main() {
  scanf("%d%d", &n, &m);
  for (w = 2; w <= n + 1; ++w)
    for (h = 2; h <= m + 1; ++h) {
      int v = (w / 2) * (h / 2);
      ans = (ans +
             (long long)(n + 2 - w) * (m + 2 - h) *
                 ((h % 2 == 0 && w % 2 == 0)
                      ? (4 * (v - 1))
                      : (4 * (h * w - 1 - v) - 2 * h - 2 * w))) %
            mo;
      int x = (w - 1) / 2, y = (h - 1) / 2;
      if (h & 1 && w & 1) res = (w - 2) * (h - 2);
      if (!(h & 1) && !(w & 1)) res = x * (h - 2 - y) + (w - 2 - x) * y;
      if (!(h & 1) && (w & 1)) res = (w - 2 - x) * (h - 2);
      if ((h & 1) && !(w & 1)) res = (w - 2) * (h - 2 - y);
      res -= __gcd(w - 1, h - 1) - 1;
      ans = (ans + 2ll * res * (n + 2 - w) * (m + 2 - h)) % mo;
    }
  printf("%d\n", 6ll * ans % mo);
}

