unordered_map<int, int> cnt;
int n,m, arr[100005], cur_ans,ans[100005];
pair<pair<int, int>, int> queries[100005];
int block_sz;
void add(int x)
{ 
		cnt[x]++; int cntx = cnt[x];
		if (cntx == x) cur_ans++; else if (cntx == x + 1) cur_ans--;
}
void rem(int x)
{ 
	cnt[x]--; int cntx = cnt[x];
	if (cntx + 1 == x) cur_ans--; else if (cntx == x) cur_ans++; 
}

bool cmp(const pair<pair<int, int>, int> &x, const pair<pair<int, int>, int> &y)
{
	int fir = x.first.first/block_sz, se = y.first.first/block_sz;
	if (fir != se)
		return fir < se;
	else return x.first.second < y.first.second;
}	
int main(void)
{
	cin >> n >> m; block_sz = sqrt(n);
	FOR(i, n) scanf("%d", &arr[i]);
	FOR(i, m)
	{
		scanf("%d %d", &queries[i].first.first, &queries[i].first.second);
		queries[i].second = i;
	}
	sort(queries, queries + m, cmp);
	int mo_left = 0, mo_right = 0; cnt[arr[0]]++; cur_ans = (arr[0] == 1);
	FOR(i, m)
	{
		int curleft = queries[i].first.first-1, curright = queries[i].first.second-1;
		while (mo_left < curleft)   rem(arr[mo_left++]);		
		while (mo_left > curleft)   add(arr[--mo_left]);		
		while (mo_right > curright) rem(arr[mo_right--]);
		while (mo_right < curright)	add(arr[++mo_right]);
		ans[queries[i].second] = cur_ans;
	}
	FOR(i, m) printf("%d\n", ans[i]);
	
	return 0;
}

