//-------head-------
const int INF = 1e9 + 7;
const int N =  1e5 + 7;
int n, a[N], p[N], ans[N];
vector<int> ac[N], dc[N];
void solve() {
	rep(i, 1, n + 1) ans[i] = INF;
	rep(i, 1, n + 1) {
		int j = p[a[i]];
		if (i <= j) {
			ac[1].push_back(j - i);
			ac[j + 1].push_back(n - i);
			dc[j].push_back(i - 1);
		} else {
			ac[j + 1].push_back(n - i);
			dc[j].push_back(i - 1);
			dc[n].push_back(i - j - 1);
		}
	}
	priority_queue<int> que;
	for (int i = 1; i <= n; ++i) {
		rep(j, 0, sz(ac[i]))
			que.push(-(ac[i][j] + i));
		while (!que.empty() && -i - que.top() < 0) que.pop();
		ans[i] = min(ans[i], -i - que.top());
	}
	while (!que.empty()) que.pop();
	for (int i = n; i >= 1; --i) {
		rep(j, 0, sz(dc[i]))
			que.push(-(dc[i][j] - i));
		while (!que.empty() && i - que.top() < 0) que.pop();
		ans[i] = min(ans[i], i - que.top());
	}
}
