double getKhar(int a, int b)
{
	int dx = x[b] - x[a];
	int dy = y[b] - y[a];
	double th = atan2(dy, dx);
	return PI - th;
}

bool cmp(int i, int j)
{
	return getKhar(center, i) < getKhar(center, j);
}

int dfs(int v)
{
	mark[v] = sz[v] = 1;
	for(int u : g[v])
		if(!mark[u])
		{
			sz[v] += dfs(u);
			w[{v, u}] = -sz[u];
			w[{u, v}] = sz[u];
		}
	return sz[v];
}


double area(vector <int> &v)
{
    double ans = 0;
    for(int i = 0; i < v.size(); i++)
    {
		int a = v[i];
		int b = v[(i+1)%v.size()];
		ans += (x[a] + x[b]) * (y[b] - y[a]);
    }
    return ans;
}


int calc(int a, int b, int c)
{
	a = ind[b][a];
	c = ind[b][c];
	if(a < c)
		return psum[b][c - 1] - psum[b][a];
	return psum[b].back() - psum[b][a] + (c ? psum[b][c - 1] : 0);
}

