        for (j=i; j<n && x[P[j]]==x[P[i]]; ++j);
        Descend(i,j);
        for (j=i; j<n && x[P[j]]==x[P[i]]; ++j){
            int u=P[j];
            int va=perv(u), vb=next(u);
            if (x[va]<x[u]) s.erase(line(0,y[u],-1));
            if (x[vb]<x[u]) s.erase(line(0,y[u],-1));

            multiset<line>::iterator ita=s.end(), itb=s.end(), it;

            if (x[va]>x[u]){
                double ax=(double)(y[va]-y[u])/(x[va]-x[u]);
                ita=s.insert(line(ax,y[u]-X*ax,pos));
                da[pos]=u; db[pos]=va; ++pos;
            }

            if (x[vb]>x[u]){
                double ax=(double)(y[vb]-y[u])/(x[vb]-x[u]);
                itb=s.insert(line(ax,y[u]-X*ax,pos));
                da[pos]=u; db[pos]=vb; ++pos;
            }

            if (ita!=s.end() && itb!=s.end() && *itb<*ita) swap(ita,itb);

            if (ita!=s.end()){
                it=ita; --it;
                if (ita==s.begin())
                    side[ita->id]=1;
                else
                    side[ita->id]=side[it->id]^1;
            }

            if (itb!=s.end()){
                it=itb; --it;
                if (itb==s.begin())
                    side[itb->id]=1;
                else
                    side[itb->id]=side[it->id]^1;
            }

        }
        Descend(i,j);
        i=j;
    }
    for (int i = 0; i < n; i++){
        double d=dist(x[i]-x[i+1],y[i]-y[i+1]);
         e[i].pb(make_pair((i+1)%n,d)); e[(i+1)%n].pb(make_pair(i,d));
    }

    for (int i = 0; i < n; i++) D[i]=inf;
    priority_queue<pair<double,int> > Q;
    D[S]=0;
    Q.push(make_pair(-0.,S));
    while(Q.size()){
        double d=-Q.top().fi;
        int a=Q.top().se;Q.pop();
        if (a==T) {printf("%.10lf\n",d);
            return 0;}
        if (d!=D[a]) continue;
        for (int i = 0; i < e[a].size(); i++){
            int b=e[a][i].fi;
            double se=d+e[a][i].se;
            if (D[b]>se) D[b]=se, Q.push(make_pair(-se,b));
        }
    }
}

