#define ls ((t)<<1)
#define rs ((t)<<1|1)
int mx[N << 2];
void upd(int t, int l, int r, int L, int R, int val) {
	if (R < l || r < L)
		return ;
	if (L <= l && r <= R) {
		mx[t] = max(mx[t], val);
		return ;
	}
	int mid = (l + r) >> 1;
	upd(ls, l, mid, L, R, val), upd(rs, mid + 1, r, L, R, val);
}
int qry(int t, int l, int r, int p) {
	if (l == r)
		return mx[t];
	int mid = (l + r) >> 1, ret = mx[t];
	if (p <= mid)
		ret = max(ret, qry(ls, l, mid, p));
	else
		ret = max(ret, qry(rs, mid + 1, r, p));
	return ret;
}
bool solve() {
	rep(i, 0, n) 
		if (!(pre[i] > 0 && pre[i] + suf[i + 1] >= m)) 
			return false;
	return true;
}
