	n = strlen(s), m = strlen(t);
	rep(i, 0, n) {
		int x = s[i] - 'a';
		p[i] = sz(v[x]);
		v[x].push_back(i);
	}
	rep(i, 1, 26) w[i] += w[i - 1] + sz(v[i - 1]);
	rep(i, 0, n) {
		int x = s[i] - 'a';
		pre[i] = max((int) (s[i] == t[0]), qry(1, 0, n - 1, w[x] + p[i]));
		if (1 <= pre[i] && pre[i] < m) {
			int y = t[pre[i]] - 'a';
			int l = w[y] + upper_bound(v[y].begin(), v[y].end(), i) - v[y].begin();
			int r = w[y] + sz(v[y]) - 1;
			if (l <= r)
				upd(1, 0, n - 1, l, r, pre[i] + 1);
		}
//		printf("pre[%d] = %d\n", i, pre[i]);
	}
	for (int i = n - 1; i >= 0; --i) {
		if (suf[i + 1] > 0)
			suf[i] = suf[i + 1] + (s[i] == t[m - suf[i + 1] - 1]);
		suf[i] = max(suf[i], (int) (t[m - 1] == s[i]));
	}
