int f(int j, int boja, int d) {
	int &ret = dp[j][boja][d];
	if (ret != -1) {
		return ret;
	}
	if (j == 0) {
		if (d + 1 == X) {
			return ret = (boja == 0 ? belo[j] : crno[j]);
		}
		if (X <= d && d < Y) {
			if (X > 1) {
				return ret = (boja == 0 ? belo[j] : crno[j]);
			}
			return ret = min(crno[j], belo[j]);
		}
		if (X > 1) {
			return ret = INF;
		} else {
			return ret = (boja == 0 ? crno[j] : belo[j]);
		}
	}

	if (d < X) {
		return ret = f(j- 1, boja, ++d) + (boja == 0 ? belo[j] : crno[j]);
	} 
	if (X <= d && d < Y) {
		return ret = min(belo[j] + f(j - 1, 0, (boja == 0 ? d + 1 : 1)), 
						 crno[j] + f(j - 1, 1, (boja == 1 ? d + 1 : 1)));
	}
	return ret = f(j-1, (boja + 1) % 2, 1) + (boja == 0 ? crno[j] : belo[j]);

}

