bool check(long long int mid,long long int L,long long int R,long long int K){
	long long int st = L/mid;
	if(L%mid != 0LL) st += 1;
	long long int ed = R/mid;
	if(ed - st + 1LL >= K) return true;
	else return false;
}

long long fibonacci(long long int n,long long int M)
{
    long long fib[2][2]= {{1,1},{1,0}},ret[2][2]= {{1,0},{0,1}},tmp[2][2]= {{0,0},{0,0}};
    long long int i,j,k;
    while(n)
    {
        if(n&1)
        {
            memset(tmp,0,sizeof tmp);
            for(i=0; i<2; i++) for(j=0; j<2; j++) for(k=0; k<2; k++)
                        tmp[i][j]=(tmp[i][j]+(ret[i][k]*fib[k][j])%M)%M;
            for(i=0; i<2; i++) for(j=0; j<2; j++) ret[i][j]=tmp[i][j];
        }
        memset(tmp,0,sizeof tmp);
        for(i=0; i<2; i++) for(j=0; j<2; j++) for(k=0; k<2; k++)
                    tmp[i][j]=(tmp[i][j]+(fib[i][k]*fib[k][j])%M)%M;
        for(i=0; i<2; i++) for(j=0; j<2; j++) fib[i][j]=tmp[i][j];
        n/=2;
    }
    return (ret[0][1])%M;
}
	
