long long fp(long long base, long long pw) {
	if(pw == 0)
		return 1;
	if(pw == 1)
		return base % mod;
	long long ret = fp(base, pw / 2);
	ret = (ret * ret) % mod;
	if(pw % 2) {
		ret *= base;
		ret %= mod;
	}
	return ret;
}




