ll solve(int k) {
	if (~f[k])
		return f[k];
	ll ret = 0, t = 0, p = 1;
	for (int i = 2, j; i <= n; i = j) {
		++t, p = p * k;
		j = min((ll) (n + 1), i + p);
		ret += t * (s[j - 1] - s[i - 1]);
	}
	return f[k] = ret;
}
int main() {
