int B[505][505], DP[505][505][8][2][2][2][2], E[8], S[505][505], H, W;

inline int sum(int i1, int j1, int i2, int j2)
{
    return S[i2][j2] - S[i1-1][j2] - S[i2][j1-1] + S[i1-1][j1-1];
}

inline int allBlack(int i1, int j1, int i2, int j2)
{
    int tot = (i2-i1+1) * (j2-j1+1);
    return tot == sum(i1,j1,i2,j2) ? 1 : 0;
}

int isFractal(int i1, int j1, int sz, int a1, int a2, int a3, int a4)
{
    if(sz < 0) return 1;
    int i2 = i1 + E[sz] - 1;
    int j2 = j1 + E[sz] - 1;
    if(DP[i1][j1][sz][a1][a2][a3][a4] != -1) return DP[i1][j1][sz][a1][a2][a3][a4];
    if(i1 == i2) return true;
    int mi = (i1+i2) / 2;
    int mj = (j1+j2) / 2;
    if(a1 != allBlack(i1,j1,mi,mj))
    {
//        if(i1 == 3 && j1 == 1 && i2 == 6 && j2 == 4) cout << "Bad 1\n";
        return DP[i1][j1][sz][a1][a2][a3][a4] = 0;
    }
    if(a2 != allBlack(i1,mj+1,mi,j2))
    {
//        if(i1 == 3 && j1 == 1 && i2 == 6 && j2 == 4) cout << "Bad 2\n";
        return DP[i1][j1][sz][a1][a2][a3][a4] = 0;
    }
    if(a3 != allBlack(mi+1,j1,i2,mj))
    {
//        if(i1 == 3 && j1 == 1 && i2 == 6 && j2 == 4) cout << "Bad 3\n";
        return DP[i1][j1][sz][a1][a2][a3][a4] = 0;
    }
    if(a4 != allBlack(mi+1,mj+1,i2,j2))
    {
//        if(i1 == 3 && j1 == 1 && i2 == 6 && j2 == 4) cout << "Bad 4\n";
        return DP[i1][j1][sz][a1][a2][a3][a4] = 0;
    }
    if(!a1 && !isFractal(i1,j1,sz-1,a1,a2,a3,a4))
    {
        return DP[i1][j1][sz][a1][a2][a3][a4] = 0;
    }
    if(!a2 && !isFractal(i1,mj+1,sz-1,a1,a2,a3,a4))
    {
        return DP[i1][j1][sz][a1][a2][a3][a4] = 0;
    }
    if(!a3 && !isFractal(mi+1,j1,sz-1,a1,a2,a3,a4))
    {
        return DP[i1][j1][sz][a1][a2][a3][a4] = 0;
    }
    if(!a4 && !isFractal(mi+1,mj+1,sz-1,a1,a2,a3,a4))
    {
        return DP[i1][j1][sz][a1][a2][a3][a4] = 0;
    }

    return DP[i1][j1][sz][a1][a2][a3][a4] = 1;
}

