const int N = 1e5 + 7;
int n, m, a[N], c[20];
ll ans[N];
#define ls ((t)<<1)
#define rs ((t)<<1|1)
struct SegmentTree {
	ll sum[N << 2];
	void build(int t, int l, int r) {
		sum[t] = 0;
		if (l < r) {
			int m = (l + r) >> 1;
			build(ls, l, m), build(rs, m + 1, r);
		}
	}
	void upd(int t, int l, int r, int p, ll v) {
		if (l == r) {
			sum[t] = v;
			return ;
		}
		int m = (l + r) >> 1;
		p <= m ? upd(ls, l, m, p, v) : upd(rs, m + 1, r, p, v);
		sum[t] = sum[ls] + sum[rs];
	}
	ll qry(int t, int l, int r, int L, int R) {
		if (R < l || r < L)
			return 0;
		if (L <= l && r <= R)
			return sum[t];
		int m = (l + r) >> 1;
		return qry(ls, l, m, L, R) + qry(rs, m + 1, r, L, R);
	}
} tree[10];
struct Node {
	int l, r, z, id;
	Node() {
	} 
	Node(int _l, int _r, int _z, int _id) {
		l = _l, r = _r, z = _z, id = _id;
	}
	bool operator<(const Node &p) const {
		if (z != p.z)
			return z < p.z;
		return id < p.id;
	}
};
vector<Node> q1, q2;
int main() {
	scanf("%d", &n);
	rep(i, 1, n + 1)
		scanf("%d", &a[i]);
	scanf("%d", &m);
	rep(i, 0, m) {
		ans[i] = -1;
		int t;
		scanf("%d", &t);
		if (t == 1) {
			int p, v;
			scanf("%d%d", &p, &v);
			q1.push_back(Node(p, v, 0, i));
		} else {
			int l, r, z;
			scanf("%d%d%d", &l, &r, &z);
			q2.push_back(Node(l, r, z, i));
		}
	}
	sort(q2.begin(), q2.end());
	for (int i = 0, j; i < sz(q2); i = j) {
		j = i + 1;
		while (j < sz(q2) && q2[j].z == q2[i].z)
			++j;
		int z = q2[i].z, L = 2 * q2[i].z - 2;
		rep(r, 0, L) {
			int R = r % L;
			c[r] = (R ? min(R, 2 * z - R) : 2);
		}
		rep(s, 0, L) {
			tree[s].build(1, 1, n);
			rep(r, 1, n + 1)
				tree[s].upd(1, 1, n, r, 1ll * a[r] * c[(r - s + 1 + L) % L]);
		}
		int k = 0;
		while (i < j) {
			while (k < sz(q1) && q1[k].id < q2[i].id) {	
				int p = q1[k].l, v = q1[k].r;
				rep(s, 0, L)
					tree[s].upd(1, 1, n, p, 1ll * v * c[(p - s + 1 + L) % L]);
				++k;
			}
			int l = q2[i].l, r = q2[i].r;
			ans[q2[i].id] = tree[l % L].qry(1, 1, n, l, r);
			++i;
		}
	}
	rep(i, 0, m)
		if (~ans[i])
			printf("%lld\n", ans[i]);
	return 0;
}

