		return a.x!=b.x?a.x>b.x:a.id<b.id;
	}
}p[N];
int n,m,top,cnt,dpt;
int use[N],tot[N],st[N],vis[N];
LB f[N][N],dp[N][N],ans=1.0;
//bool cmp(int a,int b){return a>b;}
vector<int>v[N];
long double DP(int lim){
	dp[0][0]=1;
	for(int i=1;i<=lim;i++){
		int k=st[i];LB tmp1,tmp2;
		for(int j=1;j<=min(n,i);j++){
			tmp1=dp[i-1][j]/f[tot[k]][use[k]];
			tmp2=dp[i-1][j-1]/f[tot[k]][use[k]+1];
			dp[i][j]=tmp1+tmp2;
		}
		dp[i][0]=dp[i-1][0]/f[tot[k]][use[k]];
	}
	return dp[lim][n];	
}
int main(){
	scanf("%d%d",&n,&m);
	for(int i=1,x;i<=m;i++){
		scanf("%d",&tot[i]);
		for(int j=1;j<=tot[i];j++){
			scanf("%d",&x);
			p[++top]=(Node){x,i};
		}
	}
	sort(p+1,p+top+1);
	for(int i=1;i<=top;i++){
		if(p[i].x!=p[i-1].x)++cnt;
		v[cnt].push_back(p[i].id);
	}
	
	f[0][0]=1.0;
	for(int i=1;i<N;i++){
		f[i][0]=f[i][i]=1.0;
		for(int j=0;j<i;j++)
			f[i][j]=f[i-1][j-1]+f[i-1][j];
	}
			
	
	for(int i=1;i<=cnt;i++){
		int sz=v[i].size();
		if(sz>=n){
			//for(int j=1;j<=m;j++)
			//	ans*=1.0/f[tot[j]][use[j]];
			for(int j=0;j<sz;j++){
				st[++dpt]=v[i][j];
				vis[v[i][j]]=true;
			}
			ans=DP(sz)/f[sz][n];
			for(int i=1;i<=m;i++)
				if(!vis[i])ans/=f[tot[i]][use[i]];
			break;
		}
		else{
			for(int j=0;j<sz;j++)
				use[v[i][j]]+=1;
			n-=sz;	
		}
	}
	printf("%.9lf\n",(double)ans);
	return 0;
}

