int dfs(int u,int p){
	vis[u] = true;
	bool is_cycle = false;
	bool ret_cycle = true;
	for(auto v: adjList[u]){
		if(v == p) continue;
		if(vis[v]){
			if(cycle_id[v] == -1){
				cycle_id[v] = cycle_id[u] =  v;
				is_cycle = true;
			}
			//cout<<u+1<<" "<<v+1<<endl;
		}else{
			int ret = dfs(v,u);
			if(ret >= 0){
				if(cycle_id[u] != -1){
					assert(cycle_id[u] == ret);
					ret_cycle = false;
				}else{
					cycle_id[u] = ret;
					is_cycle = true;
				}
			}
		}
	}
	//cout<<u+1<<" "<<cycle_id[u]+1<<" "<<is_cycle<<endl;
	if(is_cycle && ret_cycle) return cycle_id[u];
	else return -1;
}


vector< int > adjListN[100010];


const int max_nodes=100010, log_max_nodes=20;
int num_nodes, log_num_nodes;

vector<int> children[max_nodes];	// children[i] contains the children of node i
int A[max_nodes][log_max_nodes+1];
int B[max_nodes][log_max_nodes+1];	// A[i][j] is the 2^j-th ancestor of node i, or -1 if that ancestor does not exist
int L[max_nodes];			// L[i] is the distance between node i and the root

// floor of the binary logarithm of n
int lb(unsigned int n)
{
    if(n==0)
	return -1;
    int p = 0;
    if (n >= 1<<16) { n >>= 16; p += 16; }
    if (n >= 1<< 8) { n >>=  8; p +=  8; }
    if (n >= 1<< 4) { n >>=  4; p +=  4; }
    if (n >= 1<< 2) { n >>=  2; p +=  2; }
    if (n >= 1<< 1) {           p +=  1; }
    return p;
}

void DFS(int i, int l,int p)
{
    L[i] = l;
	A[i][0] = p;
	B[i][0] = (cycle_id[i] == i?1:0);
    for(int j = 0; j < adjListN[i].size(); j++) if(adjListN[i][j] != p)
	DFS(adjListN[i][j], l+1,i);
}

int LCA(int p, int q)
{
    // ensure node p is at least as deep as node q
    if(L[p] < L[q])
	swap(p, q);

    // "binary search" for the ancestor of node p situated on the same level as q
    for(int i = log_num_nodes; i >= 0; i--)
	if(L[p] - (1<<i) >= L[q])
	    p = A[p][i];

    if(p == q)
	return p;

    // "binary search" for the LCA
    for(int i = log_num_nodes; i >= 0; i--)
	if(A[p][i] != -1 && A[p][i] != A[q][i])
	{
	    p = A[p][i];
	    q = A[q][i];
	}

    return A[p][0];
}

int LCAB(int u,int p){
	int total = 0;
    for(int i = log_num_nodes; i >= 0; i--) if(A[u][i] != -1 && L[A[u][i]] >= L[p]){
		total += B[u][i];
		u = A[u][i];
	}
	return total;
}


