const int N = 107;
const int MOD = 1e9 + 7;
int n, k, c[N][N], f[N][N * N];
ll m;
void inc(int &x, int y) {
	x += y;
	if (x >= MOD)
		x -= MOD;
}
ll kpow(ll a, ll b) {
	ll r = 1;
	while (b > 0) {
		if (b & 1)
			r = r * a % MOD;
		a = a * a % MOD, b >>= 1;
	}
	return r;
}
int solve() {
	rep(i, 0, N) {
		c[i][0] = c[i][i] = 1;
		rep(j, 1, i)
			c[i][j] = (c[i - 1][j - 1] + c[i - 1][j]) % MOD;
	}
	f[0][0] = 1;
	rep(i, 1, n + 1) {
		rep(j, 0, min(n, k) + 1) {
			int tmp = kpow(c[n][j], 1 + (m - i) / n);	
			rep(t, j, k + 1) {
				inc(f[i][t], 1ll * f[i - 1][t - j] * tmp % MOD);
			}
		}
	}
	return f[n][k];
}
int main() {
	scanf("%d%lld%d", &n, &m, &k);
	printf("%d", solve());
	return 0;
}

