const int N = 200;
const int A = 40001;

int dp[N][A][2], a, b, nn, ch[N], h[N];

int solve(int n, int ar, int pc)
{
    if(n == 0)
    {
        if(ar < 0 || b - (ch[nn-1] - (a - ar)) < 0)
            return INF;
        else
            return 0;
    }
    if(ar < 0 || b - (ch[nn-1] - ch[n-1] - (a - ar)) < 0)
        return INF;
    if(dp[n][ar][pc] != -1)
        return dp[n][ar][pc];
    if(pc == 0)
        dp[n][ar][0] = min(solve(n-1, ar-h[n-1], 0), solve(n-1, ar, 1) + min(h[n], h[n-1]));
    else
        dp[n][ar][1] = min(solve(n-1, ar, 1), solve(n-1, ar-h[n-1], 0) + min(h[n], h[n-1]));
    return dp[n][ar][pc];
}

