const int N = 1e5 + 7;
const int INF = 1e9 + 7;
int n, m, a[N], b[N];
ll calc(int start) {
	if (a[0] != start && b[0] != start)
		return INF;
	ll ret = 0;
	int i = 0, j = 0, c = start ^ 1;
	while (i < n || j < m) {
		c ^= 1;
		while (i < n && a[i] == c)
			++i;
		while (j < m && b[j] == c)
			++j;
		ret += 2 * c;
	}
	ret -= start;
	return ret;
}
void solve(int s) {
	int i = 0, j = 0, c = s ^ 1;
	vector<int> vec;
	while (i < n || j < m) {
		c ^= 1;
		while (i < n && a[i] == c) 
			vec.push_back(i++);
		while (j < m && b[j] == c)
			vec.push_back(n + (j++));
	}
	rep(i, 0, sz(vec)) {
		if (i)
			putchar(' ');
		printf("%d", vec[i] + 1);
		vec[i] = (vec[i] < n ? a[vec[i]] : b[vec[i] - n]);
	}
	puts("");
	vector<int> ans;
	i = 0;
	if (vec[0]) {
		while (i < sz(vec) && vec[i])
			++i;
		ans.push_back(i);
	}
	while (i < sz(vec)) {
		while (i < sz(vec) && !vec[i])
			++i;
		if (i >= sz(vec))
			break;
		ans.push_back(i);
		while (i < sz(vec) && vec[i])
			++i;
		ans.push_back(i);
	}
	printf("%d\n", sz(ans));
	rep(i, 0, sz(ans)) {
		if (i)
			putchar(' ');
		printf("%d", ans[i]);
	}
}
