int dfs(int a,int f)
{
	int ans = 0;
	for(int i = 0; i < G[a].size(); i++)
	{
		if(G[a][i].first == f) continue;
		ans = ans + dfs(G[a][i].first,a) + G[a][i].second;
	}
	return ans;
}
int work(int a,int f,int root)
{
	int ans = 0;
	for(int i = 0; i < G[a].size(); i++)
	{
		if(G[a][i].first == f) continue;
		int m = a > G[a][i].first ? 0 : 1;
		int tmp = work(G[a][i].first, a,root) + G[a][i].second;
		int id = mp[a][G[a][i].first];
		dp[id][m] = min(dp[id][m], B[root] - tmp);
		ans = ans + tmp;
	}
	return ans;
}
