		G[a].pb(mk(b,0));
		G[b].pb(mk(a,1));
	}
	memset(dp,0x3f,sizeof dp);
	int ans = 0x3f3f3f3f;
	for(i = 1; i <= n; i++)
	{
		B[i] = dfs(i,-1);
