//-------head-------
const int N = 3e3 + 7;
int n, E, D, up[N];
vector<pair<int, int> > e[N];
void dfs(int u, int fa) {
	D = max(D, up[u]);
	rep(i, 0, sz(e[u])) {
		int v = e[u][i].first, s = e[u][i].second;
		if (v == fa)
			continue;
		E += (v == s);
		up[v] = max(0, up[u] + (v == s ? 1 : -1));
		dfs(v, u);
	}
}
