	vector<double> e_n(m,-1.0/4.0);
	vector<double> r_n(m,1);
	f_n[0]=2.0/3.0; f_n[m-1]=2.0/3.0;
	g_n[0]=-1.0/3.0; g_n[m-1]=0;
	e_n[0]=0; e_n[m-1]=-1.0/3.0;

	for (int x=1; x<m-1 ; x++){
		r_n[x]+=grid[i+1][x]/4.0;
	}
	r_n[0]+=grid[i+1][0]/3.0; r_n[m-1]+=grid[i+1][m-1]/3.0;

	for (int x=1; x<m; x++){
		e_n[x]=e_n[x]/f_n[x-1];
		f_n[x]=f_n[x]-e_n[x]*g_n[x-1];
		r_n[x]=r_n[x]-e_n[x]*r_n[x-1];
	}

	/*cout<<"f_n"<<endl;
