#include <bits/stdc++.h>
using namespace std;

#define lrt rt<<1
#define rrt rt<<1|1
#define lson l,m,lrt
#define rson m+1,r,rrt

const int N = 100100;
int n, m;
string s;

struct Node{
    int num[26];
    void init() {
        memset(num, 0, sizeof num);
    }
    Node operator + (const Node& b) const  {
        Node res;
        for(int i = 0; i < 26; i++) res.num[i] = num[i]+b.num[i];
        return res;
    }
};
struct Node2{
    char ch;
    int num;
    Node2() {}
    Node2(char ch, int num) : ch(ch), num(num) {}
};

struct Seg{
    Node node;
    vector<Node2> ve;
    int flag;
}seg[N<<4];

void push_up(int rt) {
    seg[rt].node = seg[lrt].node+seg[rrt].node;
}
void build(int l, int r, int rt) {
    seg[rt].node.init();
    seg[rt].flag = 0;
    seg[rt].ve.clear();
    if(l == r) {
        int x = s[l]-'a';
        seg[rt].node.num[x] = 1;
        return ;
    }
    int m = (l+r)>>1;
    build(lson); build(rson);
    push_up(rt);
}
void maintain(int rt) {
    seg[rt].node.init();
    for(int i = 0; i < seg[rt].ve.size(); i++) {
        int x = seg[rt].ve[i].ch-'a';
        seg[rt].node.num[x] += seg[rt].ve[i].num;
    }
}
void push_down(int l, int r, int rt) {
    int m = (l+r)>>1;
    if(seg[rt].flag) {
        seg[lrt].ve.clear();
        seg[rrt].ve.clear();
        int cnt = 0;
        for(int i = 0; i < seg[rt].ve.size(); i++) {
            if(seg[rt].ve[i].num+cnt <= (m-l+1)) {
                seg[lrt].ve.push_back(seg[rt].ve[i]);
                cnt += seg[rt].ve[i].num;
            } else if(cnt < (m-l+1)) {
                seg[lrt].ve.push_back(Node2(seg[rt].ve[i].ch, m-l+1-cnt));
                seg[rrt].ve.push_back(Node2(seg[rt].ve[i].ch, seg[rt].ve[i].num-(m-l+1-cnt)));
                cnt = m-l+1;
            } else {
                seg[rrt].ve.push_back(seg[rt].ve[i]);
            }
        }
        seg[lrt].flag = seg[rrt].flag = 1;
        maintain(lrt); maintain(rrt);

        seg[rt].flag = 0;
        seg[rt].ve.clear();
    }
}
vector<Node2> v, tmp;
void update(int L, int R, int l, int r, int rt) {
    if(L<=l && r<=R) {
        tmp.clear();
        int cnt = 0;
        for(int i = 0; i < v.size(); i++) {
            if(cnt+v[i].num <= l-L) cnt += v[i].num;
            else if(cnt == l-L) tmp.push_back(v[i]);
            else {
                tmp.push_back( Node2( v[i].ch, v[i].num-(l-L-cnt) ) );
                cnt = l-L;
            }
        }

        seg[rt].ve.clear();
        cnt = 0;
        for(int i = 0; i < tmp.size(); i++) {
            if(cnt == r-l+1) break;
            if(cnt+tmp[i].num <= r-l+1) {
                seg[rt].ve.push_back(tmp[i]);
                cnt += tmp[i].num;
            } else {
                seg[rt].ve.push_back(Node2(tmp[i].ch, r-l+1-cnt));
                cnt = r-l+1;
            }
        }

        seg[rt].flag = 1;
        maintain(rt);
        return ;
    }
    push_down(l, r, rt);
    int m = (l+r)>>1;
    if(L <= m) update(L, R, lson);
    if(R > m) update(L, R, rson);
    push_up(rt);
}
Node res;
void query(int L, int R, int l, int r, int rt) {
    if(L<=l && r<=R) {
        res = res+seg[rt].node;
        return ;
    }
    push_down(l, r, rt);
    int m = (l+r)>>1;
    if(R <= m) query(L, R, lson);
    else if(L > m) query(L, R, rson);
    else { query(L, m, lson); query(m+1, R, rson); }
    push_up(rt);
}

string ss;
void query2(int l, int r, int rt) {

//    cout<<l<<' '<<r<<endl;
//    for(int i = 0; i <seg[rt].ve.size(); i++) cout<<seg[rt].ve[i].ch<<' '<<seg[rt].ve[i].num<<endl;
//    cout<<endl;

    if(l == r) {
        for(int i = 0; i < 26; i++) {
            if(seg[rt].node.num[i]) {
                ss += (char)('a'+i);
            }
        }
        return ;
    }
    push_down(l, r, rt);
    int m = (l+r)>>1;
    query2(lson); query2(rson);
}

