#include <bits/stdc++.h>
using namespace std;

typedef long long LL;
const int N = 50010;
const int M = 30;
const int MM = 20;
const LL mod = 1e9+7;

int n;
LL m;
int a[N];

int ch[N*MM][2];
int val[N*MM];
int num[N*MM][M][2];
int sz;

void init() { sz = 1; memset(ch[0], 0, sizeof(ch[0])); }
void insert(int x) {
    int u = 0, len = M;
    for(int i = M-1; i >= 0; i--) {
        int c = (x>>i)&1;
        if(!ch[u][c]) {
            memset(ch[sz], 0, sizeof(ch[sz]));
            val[sz] = 0;
            ch[u][c] = sz++;
        }
        u = ch[u][c];
        val[u]++;
    }
}
void pre(int rt, int d) {
    for(int i = 0; i < M; i++) num[rt][i][0]=num[rt][i][1]=0;
    for(int i = 0; i < 2; i++) {
        int u = ch[rt][i];
        if(!u) continue;
        pre(u, d-1);
        for(int i = 0; i < M; i++) {
            num[rt][i][0]+=num[u][i][0];
            num[rt][i][1]+=num[u][i][1];
        }
        num[rt][d-1][i] += val[u];
    }
}
int Find(int rt, int x, int d, int de) {
    if(de == d) return rt;
    int u = (x>>(de-1))&1;
    if(!ch[rt][u]) return 0;
    return Find(ch[rt][u], x, d, de-1);
}
LL cal(int x, int d, LL& cnt) {
    cnt = 0;
    LL res = 0;
    for(int i = 0; i < n; i++) {
        int u = Find(0, a[i]^x, d, M);
        if(!u) continue;
        cnt += val[u];
        res += (long long)x*val[u];
        for(int j = 0; j < M; j++)
            res += (LL)num[u][j][ ((a[i]>>j)&1)^1 ]<<j;
    }
    return res;
}
void solve() {
    LL ans = 0, cnt;
    int k = 0;
    m <<= 1;
    pre(0, M);
    for(int i = M-1; i >= 0; i--) {
        k += (1<<i);
        LL tmp = cal(k, i, cnt);
        if(cnt <= m) {
            m -= cnt;
            ans += tmp;
            k -= (1<<i);
        }
    }
    LL tmp = cal(k, 0, cnt);
    ans += tmp*m/cnt;
    ans >>= 1;
    ans %= mod;
    cout<<ans<<endl;
}

int main() {
    ios::sync_with_stdio(false);

    init();

    cin>>n>>m;
    for(int i = 0; i < n; i++) {
        cin>>a[i];
        insert(a[i]);
    }

    solve();

    return 0;
}

