int Get(int cur, int h1, int h2, int tims)
{
	if (h1 >= h2) return 0;
	int res = 0;
	fill(taken, taken + n, false);
	for (int i = 1; i <= tims; i++) {
		ld x = 1e5l / ld(h2 - h1) * (100 * i - h1);
