		for (int j = 0; j < n && !found; j++)
			if (c[j] == cur && a[j] <= x + eps && x <= b[j] + eps)
				if (taken[j]) return 0;
				else { found = true; taken[j] = true; res += v[j]; }
		if (!found) return false;
		cur = 1 - cur;
	}
	return res;
}

