#include <bits/stdc++.h>
#define ll long long
#define mp make_pair
#define pb push_back
#define s second
#define f first

using namespace std;

const int N = 1e5 + 2;
const int mod = 1e9 + 7;
const ll inf = 1e18;

ll t[20][4*N];
int add[20][4*N], b[20][N], n, m;


void push(int k, int v, int tl, int tr) {
 	if (add[k][v]&1) {
		add[k][v+v]++;
		add[k][v+v+1]++;
		int tm = (tl+tr) >> 1;
		t[k][v+v] = (1<<k)*1ll*(tm - tl+1) - t[k][v+v];
		t[k][v+v+1] = (1<<k)*1ll*(tr-tm) - t[k][v+v+1];
 		add[k][v] = 0;
 	}
}
void build(int k, int v, int tl, int tr) {
 	if (tl == tr) t[k][v] = b[k][tl]*(1<<k);
 	else {
 	 	int tm = (tl+tr) >> 1;
 	 	build(k, v+v, tl, tm);
 	 	build(k, v+v+1, tm+1, tr);
 	 	t[k][v] = t[k][v+v] + t[k][v+v+1];
 	}
}
void upd(int k, int v, int tl, int tr, int l, int r) {
  	if (l > tr || tl > r) return;
  	if (l <= tl && tr <= r) {
  	 	t[k][v] = (tr-tl+1)*1ll*(1<<k) - t[k][v];
  	 	add[k][v]++;
  	 	return;
  	}
  	push(k, v, tl, tr);
  	int tm = (tl+tr) >> 1;
  	upd(k, v+v, tl, tm, l, r);
  	upd(k, v+v+1, tm+1, tr, l, r);
  	t[k][v] = t[k][v+v] + t[k][v+v+1];
}
ll get(int k, int v, int tl, int tr, int l, int r) {
 	if (l > tr || tl > r) return 0;
 	if (l <= tl && tr <= r) return t[k][v];
 	push(k, v, tl, tr);
 	int tm = (tl+tr) >> 1;
 	return get(k, v+v, tl, tm, l, r) + get(k, v+v+1, tm+1, tr, l, r);
}


int main(){ 
 	#ifndef ONLINE_JUDGE
 	freopen("in","r",stdin);
	freopen("out", "w", stdout);
	#endif
	cin >> n;
	for (int i = 1; i <= n; i++) {
	 	int x;
	 	cin >> x;
	 	for (int j = 0; j < 20; j++)
	 		if (x&(1<<j))
	 			b[j][i] = 1;
	}
	for (int i = 0; i < 20; i++)
		build(i, 1, 1, n);
	cin >> m;
	for (int i = 1; i <= m; i++) {
	 	int type, l, r, x;
	 	cin >> type;
	 	if (type == 1) {
	 		cin >> l >> r;
	 		ll res = 0;
	 		for (int j = 0; j < 20; j++)
	 			res += get(j, 1, 1, n, l, r);
	 		cout << res << endl;
	   	}
	   	else {
	   	 	cin >> l >> r >> x;
			for (int j = 0; j < 20; j++)
				if (x&(1<<j))
					upd(j, 1, 1, n, l, r);
