            r[x][y] = -INF;
            h[x][y] = INF;
            forn(dx, 2)
                forn(dy, 2) {
                    l[x][y] = min(l[x][y], (x + dx) * vy - (y + dy) * vx);
                    r[x][y] = max(r[x][y], (x + dx) * vy - (y + dy) * vx);
                    h[x][y] = min(h[x][y], (x + dx) * vx + (y + dy) * vy);
                }
            p.pb(l[x][y]);
            p.pb(r[x][y]);
            b.pb(mp(h[x][y], mp(x, y)));
        }
    sort(all(p));
    int z = sz(p);
    p.erase(unique(all(p)), p.end());
    sort(all(b));
    int lf, rf, h;
    forn(i, sz(b)) {
        int x = b[i].y.x, y = b[i].y.y;
        lf = int(lower_bound(all(p), l[x][y]) - p.begin());
        rf = int(lower_bound(all(p), r[x][y]) - p.begin()) - 1;
        h = get(1, 0, z, lf, rf);
        if (h < a[x][y])
            ans += a[x][y] - h;
        update(1, 0, z, lf, rf, a[x][y]);
    }
    cout << ans;
    return 0;
}


