void incluir(fagocito &fag,int i)
{
  //cout<<"incluir "<<i<<endl;
  int numpartes=fag.a.back();
  // Caso con una sola parte:
  if (numpartes==1) {
    fagocito nextfag;
    meterconjunto0(nextfag,i);
    meterlosdedentro(fag,nextfag,0,numpartes,i);
    meterlosdefuera(fag,nextfag,0,numpartes,i);
    nextfag.acumula();
    fag=nextfag;
    return;
  }
  // Caso con mas de una parte:

  vector<int> cuantos(numpartes+1,0);
  for (int j=0;j<int(fag.v.size());j++)
    cuantos[fag.a[j]]++;
  vector<int> inside(numpartes+1,0);
  for (int jj=0;jj<int(fila[i].size());jj++) {
    int j=fila[i][jj];
    inside[conjunto[j]]++;
  }
  int primero;
  for (int k=1;k<=numpartes;k++) {
    if (inside[k]) {
      primero=k;
      break;
    }
  }
  int ultimo;
  for (int k=numpartes;k>=1;k--) {
    if (inside[k]) {
      ultimo=k;
      break;
    }
  }
  for (int k=primero+1;k<ultimo;k++)
    if (inside[k]<cuantos[k])
      morir();
  if (inside[0]) {
    if (primero>1) {
      if (ultimo<numpartes)
	morir();
      else if (primero<ultimo and inside[ultimo]<cuantos[ultimo])
	morir();
    } else if (ultimo<numpartes) {
      if (primero<ultimo and inside[primero]<cuantos[primero])
	morir();
    } else if (primero<ultimo and inside[primero]<cuantos[primero] and inside[ultimo]<cuantos[ultimo])
      morir();
  }
  fagocito nextfag;
  if (primero==1 and (primero==ultimo or inside[primero]==cuantos[primero]))
    meterconjunto0(nextfag,i);
  int iv=0;
  for (int k=1;k<=numpartes;k++) {
    while (fag.a[iv]<k) iv++;
    if (inside[k]<cuantos[k]) {
      if (inside[0]) {
	if (primero==1 and (primero==ultimo or inside[primero]==cuantos[primero])) {
	  meterlosdedentro(fag,nextfag,iv,k,i);
	  meterlosdefuera(fag,nextfag,iv,k,i);
	} else {
	  meterlosdefuera(fag,nextfag,iv,k,i);
	  meterlosdedentro(fag,nextfag,iv,k,i);
	}
      } else if (k==primero) {
	meterlosdefuera(fag,nextfag,iv,k,i);
	meterlosdedentro(fag,nextfag,iv,k,i);
      } else {
	meterlosdedentro(fag,nextfag,iv,k,i);
	meterlosdefuera(fag,nextfag,iv,k,i);
      }
    } else {
      meterlosdedentro(fag,nextfag,iv,k,i);
    }
  }
  if (not(primero==1 and (primero==ultimo or inside[primero]==cuantos[primero])))
    meterconjunto0(nextfag,i);
  nextfag.acumula();
  fag=nextfag;
}

