using namespace std;

typedef long long ll;

const int MaxN = 1e5;
const int MaxLog = 20;
const int MaxVal = (1 << 20);

int a[MaxN];

int or_matrix[MaxN][MaxLog];
int step_two[MaxN + 1];

bool used[MaxVal];

void build(int n) {
    step_two[1] = 0;
    int cur_val = 1;
    for (int i = 2; i <= MaxN; ++i) {
        step_two[i] = step_two[i - 1];
        if (cur_val * 2 <= i) {
            step_two[i]++;
            cur_val *= 2;
        }
    }

    for (int i = 0; i < n; ++i)
        or_matrix[i][0] = a[i];

    for (int i = 1; i < MaxLog; ++i)
        for (int j = 0; j < n; ++j)
            if (j + (1 << i) <= n) {
                or_matrix[j][i] = or_matrix[j][i - 1] | or_matrix[j + (1 << (i - 1))][i - 1];
            }

}

int rangeOr(int l, int r) {
    int len = r - l + 1;
    int two_power = step_two[len];
    return or_matrix[l][two_power] | or_matrix[r - (1 << two_power) + 1][two_power];
}

int main() {
    int n;
    scanf ("%d", &n);
    for (int i = 0; i < n; ++i) {
        scanf ("%d", &a[i]);
    }
    build(n);
    for (int i = 0; i < n; ++i) {
        int pos = i;
        int value = a[i];
        used[value] = true;
        while (pos < n - 1) {
            if (rangeOr(i, n - 1) == value) {
                break;
            }
            int l = pos, r = n - 1;
            while (l < r - 1) {
                int mid = (l + r) / 2;
                if (rangeOr(i, mid) == value)
                    l = mid;
                else
                    r = mid;
            }
            value = rangeOr(i, r);
            used[value] = true;
            pos = r;
        }
    }
    int result = 0;
    for (int i = 0; i < MaxVal; ++i)
        if (used[i])
            ++result;

    printf ("%d\n", result);
}

