const int MaxN = 1e3;
const int MaxPoints = 2 + MaxN * 4;

char directions[MaxN];
int lengths[MaxN];
bool closed[MaxPoints][MaxPoints];

const int MaxSize = MaxPoints * MaxPoints;

pair<int, int> q[MaxSize];
bool visited[MaxPoints][MaxPoints];


int main() {
	int n;
	scanf ("%d", &n);
	ll cur_x = 5e9, cur_y = 5e9;
	vector<ll> xs = {0, (ll)1e10};
	vector<ll> ys = {0, (ll)1e10}; 
	for (int i = 0; i < n; ++i) {
		char direction;
		int length;
		scanf ("\n%c%d", &direction, &length);
		directions[i] = direction;
		lengths[i] = length;

		xs.push_back(cur_x);
		xs.push_back(cur_x - 1);
		xs.push_back(cur_x + 1);
		ys.push_back(cur_y);
		ys.push_back(cur_y - 1);
		ys.push_back(cur_y + 1);

		switch (direction) {
			case 'L' : {
				cur_x -= length;				
				break;
			}
			case 'R' : {
				cur_x += length;
				break;
			}
			case 'U' : {
				cur_y -= length;
				break;
			}
			case 'D' : {
				cur_y += length;
				break;
			}
		}

		xs.push_back(cur_x);
		xs.push_back(cur_x - 1);
		xs.push_back(cur_x + 1);
		ys.push_back(cur_y);
		ys.push_back(cur_y - 1);
		ys.push_back(cur_y + 1);
	}

	sort(xs.begin(), xs.end());
	xs.resize(unique(xs.begin(), xs.end()) - xs.begin());
	sort(ys.begin(), ys.end());
	ys.resize(unique(ys.begin(), ys.end()) - ys.begin());

	cur_x = 5e9, cur_y = 5e9;
	for (int i = 0; i < n; ++i) {
		int start_x = lower_bound(xs.begin(), xs.end(), cur_x) - xs.begin();
		int start_y = lower_bound(ys.begin(), ys.end(), cur_y) - ys.begin();

		char direction = directions[i];
		int length = lengths[i];

		switch (direction) {
			case 'L' : {
				cur_x -= length;				
				break;
			}
			case 'R' : {
				cur_x += length;
				break;
			}
			case 'U' : {
				cur_y -= length;
				break;
			}
			case 'D' : {
				cur_y += length;
				break;
			}
		}

		int finish_x = lower_bound(xs.begin(), xs.end(), cur_x) - xs.begin();
		int finish_y = lower_bound(ys.begin(), ys.end(), cur_y) - ys.begin();


		for (int x = min(start_x, finish_x); x <= max(start_x, finish_x); ++x)
			for (int y = min(start_y, finish_y); y <= max(start_y, finish_y); ++y)
				closed[x][y] = true;
	}

	int l = 0, r = 1;
	visited[0][0] = true;
	q[l] = {0, 0};
	while (l < r) {
		pair<int, int> position = q[l++];

		for (int add_x = -1; add_x <= 1; ++add_x)
			for (int add_y = -1; add_y <= 1; ++add_y) {
				if (add_x * add_y != 0 || abs(add_x + add_y) != 1)
					continue;

				int x = position.first + add_x;
				int y = position.second + add_y;
				if (x < 0 || x >= (int)xs.size())
					continue;
				if (y < 0 || y >= (int)ys.size())
					continue;

				if (visited[x][y] || closed[x][y]) 
					continue;



				visited[x][y] = true;
				q[r++] = {x, y};
			}
	}

	ll result = 0;
	for (int i = 0; i < (int)xs.size(); ++i)
		for (int j = 0; j < (int)ys.size(); ++j) {
			if (!visited[i][j]) {
				result += (xs[i + 1] - xs[i]) * (ys[j + 1] - ys[j]);
			}
		}

	printf ("%lld", result);



	return 0;	
}

