const int MaxN = 5e5;

char s[MaxN + 1];
char current[MaxN + 1];
int n, t;

int dp[MaxN];
int start[MaxN];
int finish[MaxN];
int pos_len;

int getTime(int initial_count) {

	int tot_houses = 0;
	int tot_shops = 0;
	int last_house = 0;
	int last_shop;
	for (int i = 0; i < n; ++i) {
		if (s[i] == 'H') {
			tot_houses++;
			last_house = i;
		}
		if (s[i] == 'S')
			tot_shops++;
	}

	int need_shops = max(0, tot_houses - initial_count);
	if (need_shops > tot_shops)
		return (int)2e9;

	int cur_shops = 0;
	for (int i = 0; i < n; ++i) {
		current[i] = s[i];
		if (s[i] == 'S')
			++cur_shops;
		if (cur_shops > need_shops)
			current[i] = '.';
		if (current[i] == 'S')
			last_shop = i;
	}

	pos_len = 0;
	int count = initial_count;
	for (int i = 0; i < n; ++i) {
		if (current[i] == 'S') {
			++count;
			if (count == 0)
				finish[pos_len++] = i;
		}
		if (current[i] == 'H') {
			if (count == 0)
				start[pos_len] = i;
			--count;
		}
	}

	if (pos_len == 0)
		return last_house + 1;

	// cout << pos_len << endl;
	// for (int i = 0; i < pos_len; ++i)
	// 	cout << start[i] << " " << finish[i] << endl;
	// cout << endl;

	// cout << current << endl;

	// cout << 2 * (max(last_shop, last_house) - start[pos_len - 1]) << endl;
	// cout << 3 * (finish[pos_len - 1] - start[pos_len - 1]) + (last_shop - finish[pos_len - 1]) << endl;
	dp[pos_len - 1] = min(2 * (max(last_shop, last_house) - start[pos_len - 1]), 
		                  3 * (finish[pos_len - 1] - start[pos_len - 1]) + (max(last_shop, last_house) - finish[pos_len - 1]));

	for (int i = pos_len - 2; i >= 0; --i) {
		dp[i] = 2 * (max(last_shop, last_house) - start[i]);
		dp[i] = min(dp[i], 
			        3 * (finish[i] - start[i]) + (start[i + 1] - finish[i]) + dp[i + 1]);
	} 

	// cout << dp[0] << endl;

	return start[0] + 1 + dp[0];

}

int main() {
	scanf ("%d%d", &n, &t);
	scanf ("%s", s);

	// cout << getTime(1) << endl;
	// return 0;

	int l = 0, r = n;
	if (getTime(l) <= t) {
		printf ("0");
		return 0;
	}

	if (getTime(r) > t) {
		printf ("-1");
		return 0;
	}

	while (l < r - 1) {
		int mid = (l + r) / 2;
		if (getTime(mid) <= t)
			r = mid;
		else
			l = mid;
	}
	printf ("%d", r);
	return 0;	
}

