const int MaxN = 1e5;
const int MaxCount = 100;

int initial_pots[MaxN];
int pots[MaxN];

long double p[MaxN][MaxCount + 1];
long double p_new[MaxCount + 1];

long double Transfer(int from, int to) {

	for (int untasted = 0; untasted <= min(pots[from], initial_pots[from]); ++untasted) {
		p_new[untasted] = p[from][untasted] * (pots[from] - untasted) / (long double)pots[from];
		if (untasted != min(pots[from], initial_pots[from]))
			p_new[untasted] += p[from][untasted + 1] * (untasted + 1) / (long double)pots[from];
	}

	long double result = -p[from][0] + p_new[0];

	for (int untasted = 0; untasted <= min(pots[from], initial_pots[from]); ++untasted)
		p[from][untasted] = p_new[untasted];

	pots[from]--;

	return result;
}

int main() {
	int n;
	scanf ("%d", &n);
	long double result = 0;
	for (int i = 0; i < n; ++i) {
		scanf ("%d", &initial_pots[i]);
		pots[i] = initial_pots[i];
		p[i][pots[i]] = 1.0;
		if (pots[i] == 0)
			result += 1.0;
	}

	int q;
	scanf ("%d", &q);
	for (int query = 0; query < q; ++query) {

		int from, to, count;
		scanf ("%d%d%d", &from, &to, &count);

		--from, --to;
		for (int i = 0; i < count; ++i) {
			long double change = Transfer(from, to);
			result += change;
		}

		pots[to] += count;
		printf ("%.12Lf\n", result);
	}

	return 0;	
}

