ull smu(ull x){
	ull ret;
	if (x % 2==1) {
		ret=(x+1)/2*(2*x+1)%mo*x%mo;
	}
	else {
		ret=x/2*(2*x+1)%mo*(x+1)%mo;
	}
	while (ret % 3!=0) ret+=mo;
	ret /= 3;
	ret %= mo;
	return ret;
}

db smd(db x){
	return (x+1)*(2*x+1)*x / 6;
}

void calc(ull x,ull y,int pq){
	if (min(x,y)==0) return;
	ull w=min(x,y);
	db ad1;
	ull ad2;
	ad1=1.0*w*w*(0.0+w*w+1)/2;
	if (w*w % 2==1) ad2=(w*w+1) / 2 % mo * w % mo * w % mo;
	else ad2=(w*w+1) % mo * w % mo * (w / 2) % mo;
	if (x>y) {
		ad1=ad1+(smd(x)-smd(y))*y-1.0*(y-1)*y/2*(x-y);
		ad2=(ad2+(smu(x)-smu(y)+mo)%mo*y%mo+mo-(y-1)*y/2%mo*(x-y)%mo)%mo;
	}
	else {
		db tmp=smd(y-1)-smd(x-1);
		ad1=ad1+(smd(y-1)-smd(x-1))*x;
		ad1+=1.0*(x+1)*x/2*(y-x);
		ad2=(ad2+(smu(y-1)-smu(x-1)+mo)%mo*x%mo+(x+1)*x/2%mo*(y-x)%mo)%mo;
	}
	ans1+=ad1*pq;
	ans2+=ad2*pq;
}

