            if(mid < n) update(tmp, ya[mid + 1].v, yb[i], len[i], ya[mid].o, i);
            if(ans == 0 || tmp < ans){
                LFT = lft;
                RGT = rgt;
                ans = tmp;
            }
        }
        printf("%d %d\n", LFT, RGT);
    }
