ll L = 1;


ll gcd(ll a, ll b) {
	return a == 0 ? b : gcd(b % a, a);
}


ll lcm(ll a, ll b) {
	return a / gcd(a, b) * b;
}


int dp[360365];
int k;


inline int calc(int b, int a) {
	memset(dp, 0b00001000, sizeof dp);
	dp[a] = 0;
	for (int i = a; i >= b; i--) {
		for (int x = 2; x <= k; x++) {
			int delta = i % x;
			if (delta > 0) {
				dp[i - delta] = min(dp[i - delta], dp[i] + 1);
			}
		}
		dp[i - 1] = min(dp[i - 1], dp[i] + 1);
	}
	return dp[b];
}


int main() {
	ll a, b;
	cin >> a >> b >> k;
	for (int i = 2; i <= k; i++) {
		L = lcm(L, i);
	}
	ll num_seg = a / L - b / L;
	if (num_seg == 0ll) {
		cout << calc(b % L, a % L);
	}
	else {
		cout << calc(b % L, L) + calc(0ll, a % L) +
			(num_seg == 1ll ? 0ll : calc(0ll, L) * (num_seg - 1ll));
	}
}

