ll get(ll x, ll y, ll m) {
    m--;
    if (m < 0)
        return 0;
    if (m >= x && m >= y && m - x + 1 >= y && m - y + 1 >= x)
        return x * y;
    x = min(x, m);
    y = min(y, m);
    ll ans = m * (m + 1) / 2;
    if (m > x)
        ans -= get(m - x, m - x, m - x + 1);
    if (m > y)
        ans -= get(m - y, m - y, m - y + 1);
    return ans;
