lint sqrt2(lint n) {
    lint var = sqrt(n);
    lint ans = -1;
    for (int x = -15; x <= 15; ++ x) {
        lint nou_var = var + x;
        if (nou_var >= 1) {
            if (nou_var <= n / nou_var)
                ans = max(ans, nou_var);
        }
    }
    return ans;
}

lint sqrt4(lint n) {
    lint var = pow(n, 0.25);
    lint ans = n + 100;
    for (int x = -15; x <= 15; ++ x) {
        lint nou_var = var + x;
        if (nou_var >= 1) {
            if (nou_var > (n - 1) / nou_var / nou_var / nou_var)
                ans = min(ans, nou_var);
        }
    }
    return ans;
}

int mex(vector <int> &v) {
    sort(v.begin(), v.end());
    v.resize(unique(v.begin(), v.end()) - v.begin());

    for (int i = 0; i < v.size(); ++ i)
        if (v[i] != i)
            return i;
    return v.size();
}

bool contains(lint nr, int a, int b) {
    lint rad4 = sqrt4(nr);
    lint rad2 = sqrt2(nr);

    if (rad4 > rad2)
        return false;

    return max(rad4, 1LL * a) <= min(rad2, 1LL * b);
}

