void bruteSpGr() {
    dp[0] = 0;
    for (int i = 1; i <= 1000; ++ i) {
        vector <int> vals;
        for (int y = 0; y < i; ++ y)
            if (1LL * y * y <= i && i <= 1LL * y * y * y * y)
                vals.push_back(dp[y]);

        dp[i] = mex(vals);
