}

int computeSpGr(lint nr) {
    if (nr <= 1000)
        return dp[nr];
    else if (nr <= 1000000) {
        if (nr < 6724)
            return 0;
        else if (nr <= 50625)
            return 3;
        else
            return 1;
    }
    else {
        vector <int> vals;
        if (contains(nr, 0, 3))
            vals.push_back(0);
        if (contains(nr, 4, 15))
            vals.push_back(1);
        if (contains(nr, 16, 81))
            vals.push_back(2);
        if (contains(nr, 82, 6723))
            vals.push_back(0);
        if (contains(nr, 6724, 50625))
            vals.push_back(3);
        if (contains(nr, 50625, 1000000))
            vals.push_back(1);

        return mex(vals);
    }
}

