LL fpow(LL nr, LL put){
    LL res=1;
    while (put){
        if (put&1) res=(res*nr)%prim;
        nr=(nr*nr)%prim;
        put>>=1;
    }
    return res;
}

LL find_leftmost(LL x){
    LL l=1,r=N,mid;
    while (l<r){
        mid=(l+r)/2;
        if (a[mid]>=x) r=mid;
        else l=mid+1;
    }
    return r;
}


