        for (j=i; j<=a[N]; j+=i)
            dv[j].push_back(i);

    LL res=0,aux,l,r;
    for (i=1; i<=a[N]; i++){
        aux=1;
        for (j=0; j<dv[i].size(); j++){
            l=find_leftmost(dv[i][j]);
