ll mod  = 1000*1000*1000 + 7;
ll solve(int pos,int rem,int lb)
{
	if(rem < 0) return 0;
	if(pos == sz) return rem == 0 ? 1 : 0;
	ll &ret = DP[pos][rem][lb];
	if(ret != -1) return ret;
	ret = 0;
	int x = num.at(pos) - '0';
	for(int i = 0 ; i <= 9 ; ++i)
	{
		if(!lb && i > x) continue;
		int f = 0;
		if(i == 4) f = 1;
		if(i == 7) f = 1;
		ret += solve(pos + 1,rem - f,lb || (i < x));
	}
	return ret%mod;
}
ll sum = 0;
vector<int> v;
int cnt[12];
void backtrack(int idx,int atmost,int mx)
{

	if(atmost < 0) return;
	if(idx == 6)
	{
		// handle
		memset(cnt,0,sizeof(cnt));
		REP(j,v)
		{
			cnt[v[j]]++;
		}
		ll ans = 1;
		int tot = 0;
		for(int i = 0 ; i < 12 ; ++i)
		{
			if(!cnt[i]) continue;
			ll c = solve(0,i,0);
			if(i == 0) --c;
			tot += i*cnt[i];
			int same = cnt[i];
			ll r = 1;
			if(c >= same)
			{
				ll rr = 1;
				for(int j = 0 ; j < same; ++j)
				{
					rr *= ((c - j)%mod);
					rr %= mod;
				}
				rr %= mod;
				r = rr;

			}
			else r = 0;
			ans *= r;
			ans %= mod;
		}
		if(tot >= mx) ans = 0;
		sum += ans;
		sum %= mod;

		return;
	}
	for(int j = 0 ; j <= atmost ; ++j)
	{
		v.push_back(j);
		backtrack(idx + 1,atmost,mx);
		v.pop_back();
	}
}
int main()
{

	scanf("%d",&n);
	num = to_string(n);
	memset(DP,-1,sizeof(DP));
	sz = sz(num);
	ll ans = 0;
	for(int i = 1 ; i < 12 ; ++i)
	{
		ll left = solve(0,i,0);
		if(left == 0) continue;
		left %= mod;
		sum = 0;
		backtrack(0,i - 1,i);
		sum %= mod;
		ans += (left%mod)*(sum%mod);
		ans %= mod;
	}
	cout << ans % mod;
}

