int prime(int n)
{
    int cnt=0;
    if(n%2==0)
        cnt++;
    while (n%2 == 0)
        n = n/2;

    for (int i = 3; i <= sqrt(n); i = i+2)
    {
        if(n%i==0)
            cnt++;
        while (n%i == 0)
            n = n/i;
    }
    if (n > 2)
        cnt++;

    if(cnt==2)
        return 1;
    else
        return 0;
}

