				f[j + 1][k + a[i]] += f[j][k];
	}
	rep(i, 1, n + 1)
		rep(j, p - a[x] + 1, p + 1)
			ans += f[i][j] * i * exp(lg[i] + lg[n - i - 1] - lg[n]);
}
