const int maxn=1e5+5;
const int maxm=2e5+15;
const int INF=0x3f3f3f3f;
struct Segment_Tree
{
    int n;
    int Max[maxm*4];
    int query(int id,int L,int R,int qL,int qR)
    {
        if(qL<=L && R<=qR) return Max[id];
        int M=(L+R)>>1,res=0;
        if(qL<=M) getmax(res,query(lc(id),L,M,qL,qR));
        if(qR >M) getmax(res,query(rc(id),M+1,R,qL,qR));
        return res;
    }
    void modify(int id,int L,int R,int mx,int mv)
    {
        if(L==R) {Max[id]=mv;return ;}
        int M=(L+R)>>1;
        if(mx<=M) modify(lc(id),L,M,mx,mv);
        else modify(rc(id),M+1,R,mx,mv);
        Max[id]=max(Max[lc(id)],Max[rc(id)]);
    }
    inline void modify(int p,int v)
    {
        modify(1,0,n-1,p,v);
    }
    inline int updateval(int p)
    {
        int v=query(1,0,n-1,p+1,n-1);
        modify(p,v+1);
        return v+1;
    }
}STx,STy;
set<int> Posx,Posy;
int x[maxn],y[maxm];
inline void plant(int p,int h)
{
    h+=2e5;
    
    vector<int> tomodify;
    for(set<int>::iterator it=Posy.begin();it!=Posy.end() && (*it)<h;it++) tomodify.PB(*it);

    debugf("plant(%d,%d)\n",p,h);
    tomodify.PB(h);
    Posx.insert(p);x[p]=h;
    Posy.insert(h);y[h]=p;
    
    assert(SZ(tomodify)<=10);
    for(const int& i:tomodify)
    {
        debugf("STx.modify(%d,%d) STy.modify(%d,%d)\n",y[i],-INF,i,-INF);
        STx.modify(y[i],-INF);
        STy.modify(i,-INF);
    }
    for(int i=SZ(tomodify)-1;i>=0;i--)
    {
        int v=STx.updateval(y[tomodify[i]]);
        STy.modify(tomodify[i],v);
        debugf("STx.updateval(%d)=%d STy.modify(%d,%d)\n",y[tomodify[i]],v,tomodify[i],v);
    }
}
inline void cut(int leftr)
{
    vector<int> tomodify;
    for(set<int>::iterator it=Posx.begin();it!=Posx.end() && leftr;leftr--,it++) tomodify.PB(*it);
    int p=tomodify[SZ(tomodify)-1],h=x[p];
    
    debugf("cut(%d,%d)\n",p,h);
    
    assert(SZ(tomodify)<=10);
    for(const int& i:tomodify)
    {
        debugf("STy.modify(%d,%d) STx.modify(%d,%d)\n",x[i],-INF,i,-INF);
        STy.modify(x[i],-INF);
        STx.modify(i,-INF);
    }
    for(int i=SZ(tomodify)-2;i>=0;i--)
    {
        int v=STy.updateval(x[tomodify[i]]);
        STx.modify(tomodify[i],v);
        debugf("STy.updateval(%d)=%d STx.modify(%d,%d)\n",x[tomodify[i]],v,tomodify[i],v);
    }
    Posx.erase(p);x[p]=-INF;
    Posy.erase(h);y[h]=-INF;
}
int main()
{
    int n,m;
    scanf("%d%d",&n,&m);
    STx.n=n;
    STy.n=maxm;
    for(int i=0,type,a,b;i<m;i++)
    {
        scanf("%d",&type);
        if(type==1)
        {
            scanf("%d%d",&a,&b);a--;
            plant(a,b-i);
        }
        else
        {
            scanf("%d",&a);
            cut(a);
        }
        assert(STx.Max[1] == STy.Max[1]);
        printf("%d\n",STx.Max[1]==-INF?0:STx.Max[1]);
    }
}

