struct EulerUndirected {
	int n;
	vector<vector<int>> adj, invid;
	EulerUndirected(int n): n(n), adj(n), invid(n) {}
	void add_edge(int a, int b) {
		invid[a].push_back(adj[b].size());
		invid[b].push_back(adj[a].size());
		adj[a].push_back(b);
		adj[b].push_back(a);
	}
	vector<int> solve() {
		int source=0, nodd=0;
		for (int v=0; v<n; v++) if (!adj[v].empty()) source=v;
		for (int v=0; v<n; v++) if (adj[v].size()%2==1) source=v, nodd++;
		if (nodd>2) return {};
		int nedge=0;
		for (int v=0; v<n; v++) nedge+=adj[v].size();
		nedge/=2;
		vector<int> result;
		stack<int> st;
		st.push(source);
		while (!st.empty()) {
			int v=st.top();
			while (!adj[v].empty() and adj[v].back()==-1) adj[v].pop_back(), invid[v].pop_back();
			if (!adj[v].empty()) {
				int u=adj[v].back(), id2=invid[v].back();
				adj[v].pop_back(), invid[v].pop_back();
				adj[u][id2]=-1;
				st.push(u);
			} else {
				result.push_back(v);
				st.pop();
			}
		}
		if ((int)result.size()!=1+nedge) return {};
		reverse(result.begin(), result.end());
		return move(result);
	}
};

bool solve(int testNumber) {
