inline int T_T(string &s){
	int l=s.length(),i=0,j=1,k=0;
	for(;i<l && j<l && k<l;)
		if(s[(i+k)%l]==s[(j+k)%l]) k++;
		else{
			if(s[(i+k)%l]>s[(j+k)%l]) i+=k+1;
			else j+=k+1;
			if(i==j) j++;
			k=0;
		}
	return min(i,j);
}
inline void O_O(string &s,vector<int> &rs){
	memset(vis,0,sizeof(vis));vs.clear();pp.clear();
	for(int i=0;i<n+n+m+m;i++) if(!vis[i]){
		string cs,t1,t2;vector<int> cp;
		int pr=i,cu=g[i][0];
		for(cp.push_back(pr),cp.push_back(cu);;){
			int r=g[cu][pr==g[cu][0]];
			if(r==i) break;
			cp.push_back(r);
			pr=cu;cu=r;
		}
		for(auto &a : cp) vis[a]=1,cs.push_back(Side(a));
		int tp1=T_T(cs);
		for(int j=0;j<cp.size();j++) t1.push_back(cs[(tp1+j)%cp.size()]);
		reverse(cs.begin(),cs.end());
		int tp2=T_T(cs);
		for(int j=0;j<cp.size();j++) t2.push_back(cs[(tp2+j)%cp.size()]);
		if(t2<t1) t2.swap(t1),swap(tp1,tp2),reverse(cp.begin(),cp.end());
		vs.push_back(t1);
		vector<int> tt;
		for(int j=0;j<cp.size();j++) tt.push_back(cp[(tp1+j)%cp.size()]);
		pp.push_back(tt);
	}
	for(int i=0;i<vs.size();i++) P[i]=i;
	sort(P,P+vs.size(),[](int a,int b) -> bool {return vs[a]<vs[b];});
	for(int i=0;i<vs.size();i++){
		s+=vs[P[i]];s+="#";
		for(auto &x : pp[P[i]]) rs.push_back(x);
	}
}
