const int N = 1e2 + 2;

struct Edge {
    int x, y, id, cnt = 0;
    Edge(){}
    Edge(int a, int b, int i) {
        if (a > b)
            swap(a, b);
        x = a;
        y = b;
        id = i;
    }
    bool operator < (const Edge& a) {
        return cnt > a.cnt;
    }
};
bool cont(int x, const Edge& a) {
    return (x > a.x && x < a.y);
}
bool inter(const Edge& a, const Edge& b) {
    return (cont(a.x, b) != cont(a.y, b) && a.x != b.x && a.y != b.y);
}
int diff(int x) {
    return ((x == 1) ? 2 : 1);
}

int group[N], n, m;
vector<Edge> edges;
vector<int> g[N];
int color[N];

bool dfs(int v) {
    cerr << "v: " << v << endl;
    for (auto u: g[v]) {
        if (color[u] == color[v])
            return false;
        if (!color[u]) {
            color[u] = diff(color[v]);
            if (!dfs(u))
                return false;
        }
    }
    return true;
}
void solve() {
    cin >> n >> m;
    int x, y;
    for (int i = 0; i < m; i++) {
        scanf("%d %d\n", &x, &y);
        edges.pb(Edge(x, y, i));
    }
    for (auto &j: edges) {
        for (auto &i: edges) {
            if (inter(i, j)) {
                g[i.id].pb(j.id);
                g[j.id].pb(i.id);
            }
        }
    }
    for (auto &j: edges) {
        if (!color[j.id]) {
            color[j.id] = 1;
            if (!dfs(j.id)) {
                cout << "Impossible";
                return;
            }
        }
    }
    for (int i = 0; i < m; i++) {
        printf("%c", (color[i] == 1) ? 'o' : 'i');
    }
}

int main() {
    #ifdef _DEBUG27_
        freopen("input.txt", "r", stdin);
    #endif

    solve();

    #ifdef _DEBUG27_
        cout << endl << "Time: " << clock() / 1000.0 << " ms";
    #endif
    return 0;
}

