using namespace std;
const int MAXN = (1 << 20);

int pow(int x, int p, int mod)
{
	if(p == 0) return 1;

	if(p % 2 == 0) 
	{
		int d = pow(x, p / 2, mod);
		return (d * d) % mod;
	}

	return (pow(x, p - 1, mod) * x) % mod;
}

int n, m;
int a[MAXN];
int b[MAXN];

void read()
{
	cin >> n;
	for(int i = 0; i < n; i++) cin >> a[i];
	for(int j = 0; j < n; j++) cin >> b[j];
	cin >> m;
}

int fact[MAXN];
map<pair<int, int>, int> cnt;

int lp[MAXN];

void seive()
{
	for(int i = 2; i < MAXN; i++)
		if(!lp[i])
		{
			lp[i] = i;
			for(int j = 2 * i; j < MAXN; j += i)
				if(!lp[j]) lp[j] = i;
		}
}

int phi(int x)
{
	int ret = x;
	set<int> st;

	while(x != 1)
	{
		st.insert(lp[x]);
		x /= lp[x];
	}

	for(int dv: st)
		ret /= dv, ret *= (dv - 1);
	
	return ret;
}

int inv(int x, int mod)
{
	int p = phi(mod);

	int ret = 1;
	while(x != 1)
	{
		ret = (ret * pow(lp[x], p - 1, mod)) % mod;	
		x /= lp[x];
	}

	return ret;
}

int c[MAXN];

void solve()
{
	seive();

	fact[0] = 1;
	for(int i = 1; i < MAXN; i++)
		fact[i] = (fact[i - 1] * i) % m;

	for(int i = 0; i < n; i++) cnt[{a[i], i}]++;
	for(int i = 0; i < n; i++) cnt[{b[i], i}]++;

	int del2 = 0, ans = 1;  
	for(auto p: cnt)
		if(p.second == 2) del2++;
	
	for(int i = 0; i < n; i++) c[i] = a[i];
	for(int j = 0; j < n; j++) c[j + n] = b[j];

	sort(c, c + 2 * n);

	for(int i = 0; i < 2 * n; )
	{
		int l = i; while(c[l] == c[i] && i < 2 * n) i++; 
		//ans = (ans * fact[i - l]) % m;
	
		for(int cnt = 1; cnt <= i - l; cnt++)
		{
			int p = cnt;
			while(p % 2 == 0 && del2)
				del2--, p /= 2;
			ans = (ans * p) % m;
		}
	}

	cout << ans << endl;
}

