const int N = (int)1e5 + 5, X = N;
int n, m, k, xs, ys, dxs, dys, x, y, dx, dy;
long long tim;
bool turnedback;
vector<int> mems[X * 2], *s = mems + X, t[X * 2];

void add(int x, int y) {
  s[y - x].push_back(x);
  y++;
  t[y + x].push_back(x);
}

int getx(int x, int y) {
  if (dx > 0)
    if (dy > 0)
      return *lower_bound(s[y - x].begin(), s[y - x].end(), x);
    else
      return *lower_bound(t[y + x].begin(), t[y + x].end(), x);
  else if (dy > 0)
    return *(upper_bound(t[y + x].begin(), t[y + x].end(), x - 1) - 1) + 1;
  else
    return *(upper_bound(s[y - x].begin(), s[y - x].end(), x - 1) - 1) + 1;
}

void getnext() {
  int xx = getx(x, y);
  int yy = y + (xx - x) * dx * dy;
  int x0 = getx(xx, yy - dy);
  int x1 = getx(xx - dx, yy);
  if (x0 == xx)
    if (x1 == xx - dx) {
      turnedback = true;
      dx *= -1;
      dy *= -1;
    } else {
      dx *= -1;
    }
  else if (x1 == xx - dx) {
    dy *= -1;
  } else {
    turnedback = true;
    dx *= -1;
    dy *= -1;
  }
  x = xx;
  y = yy;
}

int main() {
  scanf("%d%d%d", &n, &m, &k);
  while (k--) {
    int x, y;
    scanf("%d%d", &x, &y);
