  for (int j = 0; j <= m + 1; j++) add(0, j), add(n + 1, j);
  for (int i = 1; i <= n; i++) add(i, 0), add(i, m + 1);
  for (int i = 0; i < X * 2; i++) sort(mems[i].begin(), mems[i].end());
  for (int i = 0; i < X * 2; i++) sort(t[i].begin(), t[i].end());
  scanf("%d%d", &x, &y);
  static char str[5];
  scanf("%s", str);
  dx = str[0] == 'S' ? 1 : -1;
  dy = str[1] == 'E' ? 1 : -1;
  if (dx > 0) x++;
  if (dy > 0) y++;
  getnext();
  xs = x;
  ys = y;
  dxs = dx;
  dys = dy;
  for (;;) {
    int tx = x;
    getnext();
    tim += abs(x - tx);
    if (x == xs && y == ys && dx == dxs && dy == dys) break;
  }
  printf("%I64d\n", turnedback ? tim / 2 : tim);
}

