pair<ll, ll> dfs(int cur, int par) {
	pair<ll, ll> tmp, ans = {0, 0};

	for (int child : edges[cur]) {
		if (child != par) {
			tmp = dfs(child, cur);
			ans.ADD = max(ans.ADD, tmp.ADD);
			ans.SUB = max(ans.SUB, tmp.SUB);
		}
	}

	if ((val[cur] += ans.ADD - ans.SUB) > 0)
		ans.SUB += val[cur];
	else
		ans.ADD -= val[cur];

	return ans;
}

