      dist[i][j] =
          (x[i] - x[j]) * (x[i] - x[j]) + (y[i] - y[j]) * (y[i] - y[j]);
  for (i = 1; i <= n; ++i)
    for (j = i + 1; j <= n; ++j)
      for (k = j + 1; k <= n; ++k)
        if (cal(i, j, k) > 0 && cal(j, i, k) > 0 && cal(k, i, j) > 0) {
          a1 = -2 * (x[j] - x[i]);
          b1 = -2 * (y[j] - y[i]);
          c1 = x[i] * x[i] - x[j] * x[j] + y[i] * y[i] - y[j] * y[j];
