          if (x[i] == x[j]) swap(a1, a2), swap(b1, b2), swap(c1, c2);
          b2 -= b1 * a2 / a1;
          c2 -= c1 * a2 / a1;
          a2 = 0;
          b = c2 / b2;
          c1 -= b * b1;
          b1 = 0;
          a = c1 / a1;
          check(a, b, sqrt((x[i] - a) * (x[i] - a) + (y[i] - b) * (y[i] - b)));
        }
  for (i = 1; i <= n; ++i)
    for (j = 1; j <= n; ++j)
      if (i != j)
        for (k = 1; k <= n; ++k)
          if (i != k && j != k)
            if (dist[i][j] == dist[i][k] && dist[j][k] == 2 * dist[i][j])
              for (l = 1; l <= n; ++l)
                if (dist[j][l] == dist[i][j] && dist[k][l] == dist[i][j] &&
                    dist[i][l] == 2 * dist[i][j])
                  check(0.5 * (x[i] + x[l]), 0.5 * (y[i] + y[l]),
                        sqrt(2 * dist[i][j]) / 2);
