#include <bits/stdc++.h>
using namespace std;


map< int, vector< pair<int,int> > > cutsX,cutsY;

int getO(vector< pair<int,int> >& cords){
	sort(cords.begin(),cords.end());
	int total = 0;
	int st = 0,ed = 0;
	for(int i=0;i<cords.size();i++){
		if(cords[i].first > ed){
			total += ed-st;
			st = cords[i].first;
		}
		ed = max(ed,cords[i].second);
	}
	total += ed-st;
	return total;	
}
int getLb(int val){
	int lb = 0;
	while(val != 1){
		val >>= 1;
		lb += 1;
	}
	return lb;
}

int getCuts(vector< pair<int,int> >& cords,int cuts){
	int rem = 0;
	int st = 0,ed = 0;
	for(int i=0;i<cords.size();i++){
		if(cords[i].first > ed){
			rem += cords[i].first - ed;
			st = cords[i].first;
			if(rem >= cuts){
				return cords[i].first-(rem-cuts);
			}
		}
		ed = max(ed,cords[i].second);
	}
	return ed+(cuts-rem);
}
int main(){
	int N,M,K;cin>>N>>M>>K;
	for(int i=0;i<K;i++){
		int x1,y1,x2,y2;cin>>x1>>y1>>x2>>y2;
		if(x1 == x2) cutsX[x1].push_back(make_pair(min(y1,y2),max(y1,y2)));
		else cutsY[y1].push_back(make_pair(min(x1,x2),max(x1,x2)));
	}
	int total = 0;
	if((N-cutsX.size())%2 == 0) total ^= M;
	if((M-cutsY.size())%2 == 0) total ^= N;
	vector< pair<int,int> > remX,remY;
	int npX = 1,npY = 1;
	for(auto it = cutsX.begin();it != cutsX.end();it++){
		if(it->first == npX) npX += 1;
		int rem = (M-getO(it->second));
		total ^= rem;
		remX.push_back(make_pair(it->first,rem));
	}
	for(auto it = cutsY.begin();it != cutsY.end();it++){
		if(it->first == npY) npY += 1;
		int rem = (N-getO(it->second));
		total ^= rem;
		remY.push_back(make_pair(it->first,rem));
	}
	if(N-1 > cutsX.size()) remX.push_back(make_pair(npX,M));
	if(M-1 > cutsY.size()) remY.push_back(make_pair(npY,N));
	if(total == 0) cout<<"SECOND"<<endl;
	else{
		cout<<"FIRST"<<endl;
		int lb = getLb(total);
		for(int i=0;i<remX.size();i++) if(remX[i].second != 0 && getLb(remX[i].second) == lb){
				int cuts = remX[i].second - (total^remX[i].second);
				int fcuts = getCuts(cutsX[remX[i].first],cuts);
				cout<<remX[i].first<<" "<<0<<" "<<remX[i].first<<" "<<fcuts<<endl;
				return 0;
		}
		for(int i=0;i<remY.size();i++) if(remY[i].second != 0 && getLb(remY[i].second) == lb){
				int cuts = remY[i].second - (total^remY[i].second);
				int fcuts = getCuts(cutsY[remY[i].first],cuts);
				cout<<0<<" "<<remY[i].first<<" "<<fcuts<<" "<<remY[i].first<<endl;
				return 0;
		}
	}
	return 0;
}

