const int MAXN = 1e5 + 5, MAXK = 25;

int N, M;
int A[MAXN];

namespace SEGT
{

const int SIZE = MAXN * 4 + 5;

struct Atom {
    int l, r, s;

    Atom(): l(0), r(0), s(0) { }
    Atom(int p, int x): l(p), r(p), s(x) { }
    Atom(int l_, int r_, int s_): l(l_), r(r_), s(s_) { }

    friend bool operator< (const Atom &a, const Atom &b) { return a.s < b.s; }
    friend Atom operator+ (const Atom &a, const Atom &b) { return a.r + 1 == b.l ? Atom(a.l, b.r, a.s + b.s) : Atom(); }

    void xswap(Atom &x)
    {
        std::swap(*this, x);
        s = -s; x.s = -x.s;
    }
};

struct Node {
    Atom x[2], y[2], z[2], all;
    Atom u[2], v[2], w[2];

    Node() { }
    Node(int p_, int x_)
    {
        x[0] = y[0] = z[0] = Atom(p_, x_);
        u[0] = v[0] = w[0] = Atom(p_, x_);
        all = Atom(p_, x_);
    }

    void tagRev()
    {
        x[0].xswap(x[1]); u[0].xswap(u[1]); std::swap(x[0], u[0]); std::swap(x[1], u[1]);
        y[0].xswap(y[1]); v[0].xswap(v[1]); std::swap(y[0], v[0]); std::swap(y[1], v[1]);
        z[0].xswap(z[1]); w[0].xswap(w[1]); std::swap(z[0], w[0]); std::swap(z[1], w[1]);
        all.s = -all.s;
    }

    friend Node operator+ (const Node &a, const Node &b)
    {
        Node ret;
        for (int i = 0; i < 2; ++i) {
            ret.x[i] = std::max(a.x[i], a.all + b.x[i]);
            ret.y[i] = std::max(b.y[i], a.y[i] + b.all);
            ret.z[i] = std::max(std::max(a.z[i], b.z[i]), a.y[i] + b.x[i]);
            ret.u[i] = std::min(a.u[i], a.all + b.u[i]);
            ret.v[i] = std::min(b.v[i], a.v[i] + b.all);
            ret.w[i] = std::min(std::min(a.w[i], b.w[i]), a.v[i] + b.u[i]);
        }
        assert(a.all.r + 1 == b.all.l);
        ret.all = a.all + b.all;
        return ret;
    }
};

Node node[SIZE];
int revt[SIZE];

#define LC (u << 1)
#define RC (u << 1 | 1)

inline void pushdown(int u)
{
    if (revt[u]) {
        node[LC].tagRev(); revt[LC] ^= 1;
        node[RC].tagRev(); revt[RC] ^= 1;
        revt[u] = 0;
    }
}

void _modify(int u, int l, int r, int ql, int qr)
{
    if (l == r) {
        node[u] = Node(l, A[l]);
        return;
    }
    pushdown(u);
    int mid = (l + r) >> 1;
    if (ql <= mid) _modify(LC, l, mid, ql, qr);
    if (mid < qr) _modify(RC, mid + 1, r, ql, qr);
    node[u] = node[LC] + node[RC];
}

Node _query(int u, int l, int r, int ql, int qr)
{
    if (ql <= l && r <= qr)
        return node[u];
    pushdown(u);
    int mid = (l + r) >> 1;
    if (ql <= mid && mid < qr)
        return _query(LC, l, mid, ql, qr) + _query(RC, mid + 1, r, ql, qr);
    return ql <= mid ? _query(LC, l, mid, ql, qr) : _query(RC, mid + 1, r, ql, qr);
}

void _rev(int u, int l, int r, int ql, int qr)
{
    if (ql <= l && r <= qr) {
        node[u].tagRev(); revt[u] ^= 1;
        return;
    }
    pushdown(u);
    int mid = (l + r) >> 1;
    if (ql <= mid) _rev(LC, l, mid, ql, qr);
    if (mid < qr) _rev(RC, mid + 1, r, ql, qr);
    node[u] = node[LC] + node[RC];
}

}

void input()
{
    read(N);
    for (int i = 1; i <= N; ++i) {
        read(A[i]);
    }
    read(M);
}

void solve()
{
    SEGT::_modify(1, 1, N, 1, N);
    while (M--) {
        int type;
        read(type);
        if (type == 0) {
            int p, val;
            read(p); read(val);
            A[p] = val;
            SEGT::_modify(1, 1, N, p, p);
        } else {
            int l, r, k;
            read(l); read(r); read(k);
            Pii st[MAXK];
            int top = 0;
            int ans = 0;
            while (k--) {
                SEGT::Node t = SEGT::_query(1, 1, N, l, r);
                SEGT::Atom x = std::max(t.z[0], t.z[1]);
                // printf("x = (%d, %d, %d)\n", x.l, x.r, x.s);
                // printf("all = (%d, %d, %d)\n", t.all.l, t.all.r, t.all.s);
                if (x.s <= 0)
                    break;
                SEGT::_rev(1, 1, N, x.l, x.r);
                // printf("rev(%d, %d)\n", x.l, x.r);
                ans += x.s;
                st[++top] = MP(x.l, x.r);
            }
            for (; top > 0; --top) {
                SEGT::_rev(1, 1, N, st[top].x, st[top].y);
                // printf("rev(%d, %d)\n", st[top].x, st[top].y);
            }
            printf("%d\n", ans);
        }
    }
}

