void pre_dfs(int v, int p)
{
    if (min_order[v]) return;
    min_order[v] = 302;
    max_order[v] = 0;
    for (int i(0); i < g[v].size(); ++i)
        if (g[v][i].next != p)
        {
            pre_dfs(g[v][i].next, v);
            cnt[v] += cnt[g[v][i].next];
            g[v][i].y = min_order[g[v][i].next];
            min_order[v] = min(min_order[v], min_order[g[v][i].next]);
            max_order[v] = max(max_order[v], max_order[g[v][i].next]);
        }
    sort(g[v].begin(), g[v].end());
    if (max_order[v] - min_order[v] + 1 != cnt[v]) ans = false;
}

void final_dfs(int v, int p)
{
    cout << v << ' ';
    for (int i(0); i < g[v].size(); ++i)
        if (g[v][i].next != p)
        {
            final_dfs(g[v][i].next, v);
            cout << v << ' ';
        }
}

