#include<bits/stdc++.h>
#define MAXN 100010
using namespace std;

struct node{
	int ap,bp;
}qry[MAXN];

int a[MAXN],b[MAXN],lazy[4*MAXN];

void update(int x,int y,int val,int l,int r,int node){
	if(lazy[node]){
		if(l!=r){
			lazy[node<<1]=lazy[node];
			lazy[node<<1|1]=lazy[node];
			lazy[node]=0;
		}	
	}
	if(l>y || r<x)
		return ;
	else if(l>=x && r<=y){
		lazy[node]=val;
		return ;
	}
	int mid=(l+r)>>1;
	update(x,y,val,l,mid,node<<1);
	update(x,y,val,mid+1,r,node<<1|1);
}

int query(int x,int l,int r,int node){
	if(lazy[node]){
		if(l!=r){
			lazy[node<<1]=lazy[node];
			lazy[node<<1|1]=lazy[node];
			lazy[node]=0;
		}	
	}
	if(l==r){
		return lazy[node];
	}
	int mid=(l+r)>>1;
	if(x>=l && x<=mid)
		query(x,l,mid,node<<1);
	else
		query(x,mid+1,r,node<<1|1);
}


