		if(ty==1){
			scanf("%d%d%d",&qry[i].ap,&qry[i].bp,&k);
			qry[i].ap--;qry[i].bp--;
			update(qry[i].bp,qry[i].bp+k-1,i,0,n-1,1);
		}
		else{
			scanf("%d",&k);
			k--;
			int tmp=query(k,0,n-1,1);
			if(tmp){
				printf("%d\n",a[qry[tmp].ap+k-qry[tmp].bp]);
			}
			else{
				printf("%d\n",b[k]);
			}
		}
	}
