const int N = 500 + 10, M = 10 * 1000 + 10;
vector <pii> graph[N], e;
int par[N], mark[M], is[M];

int root(int v)
{
	if (v == par[v])
		return v;
	return par[v] = root(par[v]);
}

bool merge(int v, int u)
{
	v = root(v);
	u = root(u);
	if (v == u)
		return false;
	par[v] = u;
	return true;
}

void dfs(int v, int l, int r, int t)
{
	mark[v] ^= 1;
	FOR (i, 0, SZ(graph[v]) - 1)
	{
		int u = graph[v][i].F, id = graph[v][i].S;
		if(mark[u] == t && (id < l || id > r))
			dfs(u, l, r, t);
	}
}
int main()
{
	good_time();
	int n, m;
	cin >> n >> m;
	FOR (i, 0, m - 1)
	{
		int a, b;
		cin >> a >> b;
		a--;
		b--;
		e.PB(MP(a, b));
	}	
	FOR (i, 0, n - 1)
		par[i] = i;
	FOR (i, 0, m - 1)
		is[i] = merge(e[i].F , e[i].S);
	FOR (i, 0, n - 1)
		par[i] = i;
	ROF (i, m - 1, 0)
		is[i] = is[i] || merge(e[i].F, e[i].S);
	FOR (i, 0, m - 1)
		if(is[i] == true)
		{
			graph[e[i].F].PB(MP(e[i].S, i));
			graph[e[i].S].PB(MP(e[i].F, i));
		}
	int k;
