	while (k--)
	{
		int l, r;
		cin >> l >> r;
		l--;
		r--;
		int ans = 0;
		FOR (i, 0, n - 1)
		{
			if(mark[i] == t)
			{
				dfs(i, l, r, t);
				ans++;
			}
		}
		t ^= 1;
		cout << ans << endl;
	}
	return 0;
}

