vector<int> dg, ip;
int d[20];
vector<vector<int> > ans;
void gt(int n, int m) {
	if (n == 4) {
		if (d[m] == -1)ans.push_back(ip);
	} else if (!d[m]) {//*****handling prefix
		ip[n] = 0;
        gt(n + 1, m + 1);
	} else {
		ip[n] = 0;//which pos
		for (int i = m; d[i] != -1; ++i) {
			ip[n] = ip[n] * 10 + d[i];
			if (ip[n] < 256)gt(n + 1, i + 1);
		}
	}
}
void solve(int l, int r, int mk) {
	if (l <= r) {
		for (int i = 0; i < (int)dg.size(); ++i) {
			d[l] = d[r] = dg[i];
			solve(l + 1, r - 1, mk & ~(1 << i));
		}
	} else if (!mk)gt(0,0);
}
int main() {
	int n;
	scanf("%d", &n);
	dg.resize(n);
	for (int i = 0; i < n; ++i)scanf("%d", &dg[i]);
	ip.resize(4);
	for (int i = 4; i <= 12; ++i) {
		d[i] = -1;
		solve(0, i - 1, (1 << n) - 1);
	}
	printf("%d\n", (int)ans.size());
	for (const auto &jj:ans)printf("%d.%d.%d.%d\n", jj[0], jj[1], jj[2], jj[3]);
	return 0;
}

