#include <bits/stdc++.h>
using namespace std;

struct splay_tree {
	static const int maxNode = 1e5 + 100;
#define splay_node sn
#define lc ch[0]
#define rc ch[1]
	typedef long long LL;
	struct splay_node {
		splay_node*fa, *ch[2];
		int d() {
			return fa->ch[0] == this;
		}
		int sz;

		LL lm, rm, p;
		LL ls, rs, ss;

		splay_node() {
			fa = ch[0] = ch[1] = NULL;
			ls = rs = ss = 0;
			lm = rm = p = 0;
		}

		void init(int _p) {
			fa = ch[0] = ch[1] = NULL;
			ls = rs = ss = 0;
			lm = rm = p = 0;
			p = _p;
		}

		void update() {
			if (ch[0] && ch[1]) {
				ls = ch[0]->ls + p - ch[0]->lm + (ch[1]->lm - ch[0]->lm) * ch[1]->sz + ch[1]->ls;
				rs = ch[1]->rs + ch[1]->rm - p + (ch[1]->rm - ch[0]->rm) * ch[0]->sz + ch[0]->rs;
				ss = ch[0]->ss + ch[1]->ss 
					+ ch[0]->rs + ch[0]->sz * (p - ch[0]->rm)
					+ ch[1]->ls + ch[1]->sz * (ch[1]->lm - p)
					+ ((0LL + ch[1]->lm - ch[0]->rm) * ch[1]->sz + ch[1]->ls) * ch[0]->sz + ch[0]->rs * ch[1]->sz;
				lm = ch[0]->lm;
				rm = ch[1]->rm;
				sz = ch[0]->sz + ch[1]->sz + 1;
			} else if (ch[0] && !ch[1]) {
				ls = ch[0]->ls + p - ch[0]->lm;
				rs = ch[0]->rs + (0LL + p - ch[0]->rm) * ch[0]->sz;
				ss = ch[0]->ss + rs;
				lm = ch[0]->lm;
				rm = p;
				sz = ch[0]->sz + 1;
			} else if (!ch[0] && ch[1]) {
				ls = ch[1]->ls + (0LL + ch[1]->lm - p) * ch[1]->sz;
				rs = ch[1]->rs + ch[1]->rm - p;
				ss = ch[1]->ss + ls;
				lm = p;
				rm = ch[1]->rm;
				sz = ch[1]->sz + 1;
			} else {
				ls = 0;
				rs = 0;
				ss = 0;
				lm = p;
				rm = p;
				sz = 1;
			}
		}

	} node_pool[maxNode], *loc = node_pool;

	splay_node *root, *lmost, *rmost;

	void init() {
		lmost = loc++;
		rmost = loc++;
		lmost->p = INT_MIN;
		rmost->p = INT_MAX;
		lmost->ch[1] = rmost;
		rmost->fa = lmost;
		root = lmost;
		rmost->update();
		lmost->update();
	}

	void rot(splay_node*x) {
		splay_node*y = x->fa, *z = y->fa;
		int d = x->d();
		y->ch[d^1] = x->ch[d];
		if (x->ch[d]) x->ch[d]->fa = y;
		x->ch[d] = y;
		y->fa = x;
		x->fa = z;
		if (z) z->ch[z->ch[1]==y] = x;
		y->update();
	}

	void splay(splay_node*x, splay_node*g) {
		for (; x->fa != g; rot(x)) {
			splay_node*y = x->fa;
			if (y->fa != g) {
				if (x->d() == y->d())
					rot(y);
				else rot(x);
			}
		}
		x->update();
		if (!g) root = x;
	}

	void insert(splay_node*&pos, splay_node*nd) {
		if (!pos) {
			pos = nd;
			nd->update();
			return ;
		}
		if (nd->p < pos->p) {
			insert(pos->ch[0], nd);
			pos->ch[0]->fa = pos;
		}
		else {
			insert(pos->ch[1], nd);
			pos->ch[1]->fa = pos;
		}
		pos->update();
	}

	void insert(int p) {
		splay_node *new_node = loc++;
		new_node->init(p);
		insert(root, new_node);
		splay(new_node, NULL);
	}

	splay_node*get_prev(splay_node*pos, int p) {
		if (!pos) return NULL;
		if (p <= pos->p) {
			return get_prev(pos->ch[0], p);
		} else {
			splay_node*temp = get_prev(pos->ch[1], p);
			if (!temp || p <= temp->p)
				return pos;
			else return temp;
		}
	}
	splay_node*get_succ(splay_node*pos, int p) {
		if (!pos) return NULL;
		if (pos->p <= p) {
			return get_succ(pos->ch[1], p);
		} else {
			splay_node*temp = get_succ(pos->ch[0], p);
			if (!temp || temp->p <= p)
				return pos;
			else return temp;
		}
	}

	splay_node*get_by_rnk(splay_node*x, int k) {
		if (k > x->sz) return NULL;
		if (x->ch[0]) {
			if (x->ch[0]->sz < k)
				k -= x->ch[0]->sz;
			else return get_by_rnk(x->ch[0], k);
		}
		if (k == 1) return x;
		return get_by_rnk(x->ch[1], k-1);
	}


	splay_node*get_prev(int p) {
		return get_prev(root, p);
	}
	splay_node*get_succ(int p) {
		return get_succ(root, p);
	}
	splay_node*get_by_rnk(int k) {
		return get_by_rnk(root, k+1);
	}

	void del_node(splay_node*x) {
		splay(x, NULL);
		int s = x->ch[0] ? x->ch[0]->sz : 1;
		splay_node*l = get_by_rnk(s-1), *r = get_by_rnk(s+1);
		splay(l, NULL);
		splay(r, l);
		assert(r->ch[0] == x);
		r->ch[0] = NULL;
	//	if (r->ch[0] != x) {
	//		printf("%d\n", s);
	//		splay(x, NULL);
	//		printf("%d\n", x->ch[0] ? 0 : x->ch[0]->sz);
	//		exit(0);
	//	}
		x->fa = NULL;
		r->update();
		l->update();
	}
};


