inline
bool able(int x, int y, int val) {
	for (int i = 0; i < pc[val]; ++i) {
		if (x <= px[val][i] && y <= py[val][i]) return false;
		if (x >= px[val][i] && y >= py[val][i]) return false;
	}
	return true;
}

inline
int P(int m, int n) {
	return fac[m] / fac[m - n];
}

void dfs(const int &x, const int &y, const int &tot, const int &free) {
	if (x == n) {
//		printf("%d %d\n", tot, free);
		ans += P(k - (tot - free), free);
		ans %= mod;
		return;
	}

	int nx = x, ny = y;
	next(nx, ny);
	if (ns[x][y]) {
		dfs(nx, ny, tot, free);
	} else {
		for (int i = 1; i <= tot; ++i) {
			if (able(x, y, i)) {
				set(x, y, i);
				dfs(nx, ny, tot, free);
				reset(x, y, i);
			}
		}
		if (tot < k) {
			set(x, y, tot + 1);
			dfs(nx, ny, tot + 1, free + 1);
			reset(x, y, tot + 1);
		}
	}
}
