int main() {
    int n, v, t, p, capacity = 0;
    vector< pair<int, int> > kayak;
    vector< pair<int, int> > catamaran;
    vector< pair<int, int> > ans;
    int last_catamaran = 0, last_kayak = 0; // the final ans contains the catamarans numbered from 0 to lastcatamaran and the kayaks numbered from 0 to last_kayak (the catamarans and kayaks are all sorted based on their capacities)
    bool flag = true;

    cin >> n >> v;
    for (int i = 1; i <= n; i++) {
        cin >> t >> p;
        if (t == 1)
            kayak.push_back(make_pair(i, p));
        else
            catamaran.push_back(make_pair(i, p));
    }

    sort(kayak.begin(), kayak.end(), cmp);
    sort(catamaran.begin(), catamaran.end(), cmp);

    // put in as many catamarans as possible, then put in as many kayak as possible
    last_catamaran = min(v/2, (int)catamaran.size());
    for (int i = 0; i < last_catamaran; i++)
        capacity += catamaran[i].second;
    last_kayak = min(v-last_catamaran*2, (int)kayak.size());
    for (int i = 0; i < last_kayak; i++)
        capacity += kayak[i].second;

    last_catamaran--;

    // now we check if replacing a catamaran by two kayaks will lead to more capacity
    while (last_catamaran >= 0 && last_kayak <= kayak.size() - 2) {
        if (catamaran[last_catamaran].second < kayak[last_kayak].second + kayak[last_kayak + 1].second) {
            capacity = capacity - catamaran[last_catamaran].second + kayak[last_kayak].second + kayak[last_kayak + 1].second;
            last_catamaran--;
            last_kayak += 2;
        }
        else {
            flag = false;
            break;
        }
    }
    if (flag && last_catamaran >= 0 && last_kayak == kayak.size() - 1)
        if (catamaran.at(last_catamaran).second < kayak.at(last_kayak).second) {
            capacity = capacity - catamaran.at(last_catamaran).second + kayak.at(last_kayak).second;
            last_catamaran--;
            last_kayak++;
        }

    cout << capacity << endl;
    for (int i = 0; i <= last_catamaran; i++)
        cout << catamaran[i].first << endl;
    for (int i = 0; i < last_kayak; i++)
        cout << kayak[i].first << endl;

    return 0;
}

