class triple
{
	public:
	int time,x,y;
	double prob;
	triple(int x1, int y1,int tim1, double prb) { 
		time = tim1;
		x = x1;
		y = y1;
		prob = prb;
	}
};

class customSort
{
	public:
		bool operator () (triple t1, triple t2)
		{
			if (t1.time < t2.time) return true;
			return false;
		}
};

bool canHit(triple t1, triple t2)
{
	if (abs(t2.time - t1.time) == 0) return false;
	double dist = (pow(abs(t1.x - t2.x),2) + pow(abs(t1.y - t2.y),2));
	if (dist <= pow(abs(t2.time - t1.time), 2))
		return true;
	else
		return false;
}

