		vec.pb(triple(x,y,t,pr));

	}
	sort(all(vec), customSort());
	dp[n-1] = vec[n-1].prob;
	for(int i = n-2; i >= 0; i--)
	{
		double ma = 0.0;
		for(int j = i + 1; j < n; j++)
		{
			if (canHit(vec[i], vec[j]))
			{
				ma = max(ma, dp[j]);	
			}
		}
		dp[i] = vec[i].prob + ma;
	}
