constexpr int N = 300000;
int n, m;

int segset[N * 4];
int segans[N * 4];

#define lch node * 2, first, mid
#define rch node * 2 + 1, mid + 1, last

int ql, qr, v;

void segtree_set(int node, int first, int last)
{
	if (first >= ql && last <= qr) {
		segset[node] = std::max(segset[node], v);
		segans[node] = std::max(segans[node], v);
		return;
	}
	int mid = first + (last - first) / 2;
	if (ql <= mid)
		segtree_set(lch);
	if (qr > mid)
		segtree_set(rch);
	segans[node] = std::max(segans[node * 2], segans[node * 2 + 1]);
}

int segtree_get(int node, int first, int last)
{
	if (first >= ql && last <= qr)
		return segans[node];
	int ans = segset[node];
	int mid = first + (last - first) / 2;
	if (ql <= mid)
		ans = std::max(ans, segtree_get(lch));
	if (qr > mid)
		ans = std::max(ans, segtree_get(rch));
	return ans;
}

