    if (m == 1) {
        cout << "-1\n";
        return 0;
    }

    vector<int> vertices;

    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        --a, --b;
        vertices.pb(a);
        vertices.pb(b);
        edges.pb({a, b});
        edges.pb({b, a});
    }

    sort(all(vertices));
    vertices.resize(unique(all(vertices)) - vertices.begin());
    n = sz(vertices);

    g.resize(n);
    for (int i = 0; i < sz(edges); ++i) {
        edges[i].from = lower_bound(all(vertices), edges[i].from) - vertices.begin();
        edges[i].to = lower_bound(all(vertices), edges[i].to) - vertices.begin();
        g[edges[i].from].pb(i);
    }

    comp_id.assign(n, -1);
    deg.resize(n);

    for (int v = 0; v < n; ++v) {
        deg[v] = sz(g[v]);
    }

    for (int v = 0; v < n; ++v) {
        if (comp_id[v] == -1) {
            dfs1(v);
            ++cnt_comps;
        }
    }

    if (cnt_comps > 2) {
        cout << "-1\n";
        return 0;
    }

    int odd_degree = 0;
    for (int v = 0; v < n; ++v) {
        if (deg[v] & 1) {
            ++odd_degree;
        }
    }

    if (odd_degree > 4) {
        cout << "-1\n";
