double solve(int last_h, int last_r, int last_R, int h, int r, int R) {
    if (r >= last_R)
        return last_h;
    else if (R <= last_r)
        return 0;
    double ret = 0;
    if (r >= last_r)
        ret = fmax(ret, last_h * (r - last_r) / double(last_R - last_r));
    if (R >= last_R)
        ret = fmax(ret, last_h - h * (last_R - r) / double(R - r));
    if (R <= last_R)
        ret = fmax(ret, last_h * (R - last_r) / double(last_R - last_r) - h);
    return ret;
}

