        for (int j = 0; j < i; ++j) {
            double f = fmax(0, solve(h[j], r[j], R[j], h[i], r[i], R[i]));
            dp[i] = fmax(dp[i], dp[j] + f);
        }
        ans = fmax(ans, dp[i] + h[i]);
    }
    ofstream fout("output.txt");
    fout << setprecision(6) << fixed << ans;
    return 0;
}

