int solve(int n, int m, int k) {
  if (min(n, m) % (k + 1) == 0)
    return 1;
  int ret = (n + m) & 1;
  if (k > 1 && (min(n, m) / (k + 1) & 1))
    ret ^= 1;
  return ret;
}

