	int sum=0, maxi=0;
	for (int i=0; i<(int)str.size(); i++) {
		int v=str[i]-'a'+1;
		sum+=v;
		maxi=max(maxi, v);
	}
	bool leaf=true;
	vector<int> ans(3, 0);
	ans[1]=-1;
	for (char c='a'; c<='z'; c++) {
		string nstr=string(1, c)+str;
		int v=c-'a'+1, nsum=sum+v, nmaxi=max(maxi, v);
		if (counter.count(nstr)) {
			leaf=false;
			vector<int> aux=dp(nstr);
			aux[0]=1-aux[0];
			swap(aux[1] ,aux[2]);
			aux[1]+=nsum*nmaxi+counter[nstr];
			if (aux[0]>ans[0] or (aux[0]==ans[0] and aux[1]>ans[1]) or (aux[0]==ans[0] and aux[1]==ans[1] and aux[2]<ans[2])) ans=aux;
		}
		nstr=str+string(1, c);
		if (counter.count(nstr)) {
			leaf=false;
			vector<int> aux=dp(nstr);
			aux[0]=1-aux[0];
			swap(aux[1] ,aux[2]);
			aux[1]+=nsum*nmaxi+counter[nstr];
			if (aux[0]>ans[0] or (aux[0]==ans[0] and aux[1]>ans[1]) or (aux[0]==ans[0] and aux[1]==ans[1] and aux[2]<ans[2])) ans=aux;
