  return x;
}
void cheng(int a[]) {
  int i;
  for (i = 1; i <= a[0]; ++i) a[i] *= 12;
  for (i = 1; i <= a[0] || a[i]; ++i) a[i + 1] += a[i] / 10, a[i] %= 10;
  a[0] = i - 1;
}
void add(int a[], int b[]) {
  int i, l = max(a[0], b[0]);
  for (i = 1; i <= l; ++i) a[i] += b[i];
  for (i = 1; i <= l || a[i]; ++i) a[i + 1] += a[i] / 10, a[i] %= 10;
  a[0] = i - 1;
}
