  for (i = 1; i <= a[0]; ++i) a[i] -= b[i];
  for (i = 1; i <= a[0]; ++i)
    if (a[i] < 0) a[i] += 10, a[i + 1]--;
  while (a[0] > 1 && !a[a[0]]) a[0]--;
