int ans = 0;

int cal(int p, int d) {
	if (p == n) {
		return 1;
	}
	int &ret = dp[p][d];
	if (ret != -1) return ret;
	ret = 0;
	int nxt = d + (s[p + 1] - '0');

	if (nxt % 2 == 0) {
		ret += cal(p + 1, nxt / 2);
	}
	else {
		ret += cal(p + 1, (nxt - nxt % 2) / 2);
		ret += cal(p + 1, (nxt + nxt % 2) / 2);
	}
	return ret;
}

void dfs(int p, int d) {
	if (p == n && d == s[p] - '0') {
		ans--;
		return;
	}
	int nxt = d + s[p + 1] - '0';
	if (nxt % 2 == 0) {
		if (nxt / 2 == s[p + 1] - '0') dfs(p + 1, nxt / 2);
	}
	else {
		if (nxt / 2 == s[p + 1] - '0') dfs(p + 1, nxt / 2);
		else if (nxt / 2 + 1 == s[p + 1] - '0') dfs(p + 1, nxt / 2 + 1);
	}
}

