			for(j=i*i;j<=MAX+5;j+=i)
			{
				prime[j] = 1;
			}
		}
	}

	vec.pb(2);
	for(i=3;i<=MAX;i+=2)
	{
		if(!prime[i])
			vec.pb(i);
	}

