	if(!prime[nc])
	{
		for(i=0;i<n;i++)
		{
			printf("1 ");
		}
		printf("\n");

		return 0;
	}
	else if(nc%2 == 0)
	{
		int a, b;

		for(i=0;i<vec.size();i++)
		{
			if(!prime[nc - vec[i]])
			{
				a = vec[i];
				b = nc - vec[i];
				break;
			}
		}

		for(i = min(a, n);i>=1;i--)
		{
			if(i <= a)
			{
				a -= i;
				color[i] = 1;
			}
		}

		for(i=1;i<=n;i++)
		{
			if(color[i] == 0)
				color[i] = 2;
		}
