        s.insert(mp(abs(p->a-p->next->a), p->i));
    }
}

void erase(Node* p) {
    if(p==nullptr || p->next==nullptr) return;
    if(p->sex!=p->next->sex) {
        s.erase(mp(abs(p->a-p->next->a), p->i));
