	int tail = node % 202;
	if(head + tail > r) return;
	v[node] = 1;
	for(int i = 1; i <= min(n, head); i++) {
		int newhead, newtail;
		newhead = head - i + hh[i];
		newtail = tail + ht[i];
		if(newtail > 201) newhead = 201;
		if(newhead > 201) newhead = 201;
		newhead = newhead * 202 + newtail;
		if(v[newhead] == 0) {
			dfs(newhead);
		}
		else if(v[newhead] == 1) cycle = 1;
	}
	for(int i = 1; i <= min(tail, m); i++) {
		int newhead, newtail;
		newhead = head + th[i];
		newtail = tail - i + tt[i];
		if(newtail > 201) newhead = 201;
