void segment_tree::build(long long input[], long long sgt[], long long low, long long high, long long pos)
{
	if (low == high)
	{
		sgt[pos] = input[low];
		return;
	}
	long long mid = (high + low) / 2;
	build(input, sgt, low, mid, 2 * pos + 1);
	build(input, sgt, mid + 1, high, 2 * pos + 2);
	sgt[pos] = min(sgt[2 * pos + 1], sgt[2 * pos + 2]);
}
long long segment_tree::RMQ(long long sgt[], long long qlow, long long qhigh, long long low, long long high, long long pos)
{
	if (low > high)
		return INT64_MAX;
	if (lazy[pos])
	{
		sgt[pos] += lazy[pos];
		if (low != high)
		{
			lazy[2 * pos + 1] += lazy[pos];
			lazy[2 * pos + 2] += lazy[pos];
		}
		lazy[pos] = 0;
	}
	if (qlow>high || qhigh<low)
	{
		return INT64_MAX;
	}
	if (qlow <= low&&qhigh >= high)
	{
		return sgt[pos];
	}
	long long mid = (high + low) / 2;
	return min(RMQ(sgt, qlow, qhigh, low, mid, 2 * pos + 1), RMQ(sgt, qlow, qhigh, mid + 1, high, 2 * pos + 2));

}
void segment_tree::update_lazy(long long sgt[], long long qlow, long long qhigh, long long low, long long high, long long pos, long long delta)
{
	if (low > high)
		return;
	if (lazy[pos])
	{
		sgt[pos] += lazy[pos];
		if (low != high)
		{
			lazy[2 * pos + 1] += lazy[pos];
			lazy[2 * pos + 2] += lazy[pos];
		}
		lazy[pos] = 0;
	}
	if (qlow > high || qhigh < low)
	{
		return;
	}
	if (qlow <= low&&qhigh >= high)
	{
		sgt[pos] += delta;
		if (low != high)
		{
			lazy[2 * pos + 1] += delta;
			lazy[2 * pos + 2] += delta;
		}
		return;
	}
	if (low == high)
	{
		sgt[pos] += delta;
		return;
	}
	long long mid = (low + high) / 2;
	update_lazy(sgt, qlow, qhigh, low, mid, 2 * pos + 1, delta);
	update_lazy(sgt, qlow, qhigh, mid + 1, high, 2 * pos + 2, delta);
	sgt[pos] = min(sgt[2 * pos + 1], sgt[2 * pos + 2]);
}
