vector<string> rotatePuzzle(vector<string> s){
	int l = s[0].size();
	vector<string> res(l, string (s.size(),' '));
	
	rep(i, s.size()){
		rep(j, l)
			res[l-j-1][i] = s[i][j];
	}
	return res;
