vector<string> cutPicture(vector<string> s, int indx, int indy, int x, int y){
	vector<string> result(x, string(y, ' '));
	for (int i = indx*x; i < (indx + 1)*x; ++i){
		for (int j = indy*y; j < (indy + 1)*y; ++j){
			result[i - indx*x][j - indy*y] = s[i][j];
		}
	}

	return result;
}


bool validCutPicture(int x, int y){
	set<vector<string>> sp;
	bool result = true;

	for (int i = 0; i < n/x; ++i){
		for (int j = 0; j < m/y; ++j){
			vector<string> tmp = cutPicture(str, i, j, x, y), ortmp = tmp;
			bool flag = false;

			if (x == y){
				if (sp.count(tmp) != 0){
					flag = true;
				}

				tmp = rotatePuzzle(tmp);
				if (sp.count(tmp) != 0){
					flag = true;
				}

				tmp = rotatePuzzle(tmp);
				if (sp.count(tmp) != 0){
					flag = true;
				}

				tmp = rotatePuzzle(tmp);
				if (sp.count(tmp) != 0){
					flag = true;
				}
			}
			else{
				if (sp.count(tmp) != 0){
					flag = true;
				}

				tmp = rotatePuzzle(tmp);
				tmp = rotatePuzzle(tmp);
				if (sp.count(tmp) != 0){
