lint calc(vector<lint> vet, vector<string> &op) {
    int n=(int)vet.size();
    if (n==1) return vet[0];
    lint ans=LONG_LONG_MAX;
    for (int i=0; i<n; i++) for (int j=i+1; j<n; j++) {
        vector<lint> aux(1, op[4-n]=="+"?vet[i]+vet[j]:vet[i]*vet[j]);
        for (int k=0; k<n; k++) if (k!=i and k!=j) aux.push_back(vet[k]);
        ans=min(ans, calc(aux, op));
    }
    return ans;
}

