    vector<vector<int> > dp(n+1, vector<int>(m+1)), action=dp;
    for (int i=0; i<=n; i++) for (int j=0; j<=m; j++) {
        if (!i and !j) {
            dp[0][0]=0;
            action[i][j]=0;
            continue;
        }
        dp[i][j]=INT_MAX;
        if (j and dp[i][j-1]+1<dp[i][j]) {
            dp[i][j]=dp[i][j-1]+1;
            action[i][j]=1;
        }
