const int MOD=1000000007;

lint inverse(lint a) {
    lint ans=1;
    for (int b=MOD-2; b; b/=2) {
        if (b%2) ans=ans*a%MOD;
        a=a*a%MOD;
    }
    return ans;
}

bool solve(int testNumber) {
    int n;
    if (scanf("%d", &n)==EOF) return false;
    if (n==1) {
        printf("1\n");
        return true;
    }
    vector<lint> fat(2*n+1), inv(2*n+1);
    fat[0]=1;
    for (int i=1; i<=2*n; i++) fat[i]=fat[i-1]*i%MOD;
    inv[2*n]=inverse(fat[2*n]);
    for (int i=2*n-1; i>=0; i--) inv[i]=inv[i+1]*(i+1)%MOD;
    lint ans=0;
    for (int i=0; i<n; i++) {
        lint aux=fat[i+n-2]*inv[n-2]%MOD*inv[i]%MOD*(n-i)%MOD;
        if (i) aux=aux*2%MOD;
        ans=(ans+aux)%MOD;
    }
    printf("%lld\n", ans);
    return true;
}

