const ldouble PI=2*acosl(0);

vector<set<int>> graph;
set<pair<int, int>> cant;
map<pair<int, int>, int> id;
vector<int> dist, from, to, pre;

void bfs(int n) {
	dist.assign(n, -1);
	pre.assign(n, -1);
	queue<int> Q;
	for (int ed: graph[0]) {
		dist[ed]=1;
		Q.push(ed);
	}
	graph[0].clear();
	while (!Q.empty()) {
		int ed=Q.front();
		Q.pop();
		int u=to[ed];
		vector<int> vet;
		for (int ed2: graph[u]) if (!cant.count({ed, ed2})) {
			dist[ed2]=dist[ed]+1;
			pre[ed2]=ed;
			Q.push(ed2);
			vet.push_back(ed2);
		}
		for (int x: vet) graph[u].erase(x);
	}
}

bool solve(int testNumber) {
	int n, m, k;
	if (scanf("%d %d %d", &n, &m, &k)==EOF) return false;
	graph.assign(n, {});
	id.clear();
	from.resize(2*m);
	to.resize(2*m);
	for (int i=0; i<m; i++) {
		int u, v;
		scanf("%d %d", &u, &v);
		u--, v--;
		graph[u].insert(2*i);
		graph[v].insert(2*i+1);
		id[{u, v}]=2*i;
		id[{v, u}]=2*i+1;
		from[2*i]=u, to[2*i]=v;
		from[2*i+1]=v, to[2*i+1]=u;
	}
	cant.clear();
	for (int i=0; i<k; i++) {
		int u, v, w;
		scanf("%d %d %d", &u, &v, &w);
		u--, v--, w--;
		if (id.count({u, v}) and id.count({v, w})) cant.insert({id[{u, v}], id[{v, w}]});
	}
	bfs(2*m);
	int ed=-1;
	for (int i=0; i<2*m; i++) if (to[i]==n-1 and dist[i]!=-1 and (ed==-1 or dist[ed]>dist[i])) ed=i;
	if (ed==-1) printf("-1\n");
	else {
		printf("%d\n", dist[ed]);
		stack<int> S;
		S.push(n-1);
		while (ed!=-1) {
			S.push(from[ed]);
			ed=pre[ed];
		}
		while (!S.empty()) {
			printf("%d ", S.top()+1);
			S.pop();
		}
		printf("\n");
	}
	return true;
}

