void euler(int v, int cur) {
	while(!ve[v].empty()) {
		multiset<int>::iterator jt;
		if(cur<=M)
			jt = ve[v].lower_bound(p[cur]);
		else if(cur==M+1)
			jt = ve[v].upper_bound(p[cur]);
		else
			jt = ve[v].begin();
		if(jt == ve[v].end()) {
			ok = 0;
			return;
		}
		int w = *jt;
		multiset<int>::iterator kt = ve[w].find(v);
		ve[v].erase(jt); ve[w].erase(kt);
		euler(w, cur+1);
		if(!ok)
			return;
		res.PB(v);
	}
}

