using namespace std;

typedef int mask;
typedef bool bit;

const mask full = (1 << 19) - 1;

void set_bit(mask &m, short pos, bit val) { m |= val << pos; }

short step[15][5] =
{
    { 0, 1, 2, -1, -1 },
    { 3, 4, 5, 6, -1 },
    { 7, 8, 9, 10, 11 },
    { 12, 13, 14, 15, -1 },
    { 16, 17, 18, -1, -1 },
    { 2, 6, 11, -1, -1 },
    { 1, 5, 10, 15, -1 },
    { 0, 4, 9, 14, 18 },
    { 3, 8, 13, 17, -1 },
    { 7, 12, 16, -1, -1 },
    { 7, 3, 0, -1, -1 },
    { 12, 8, 4, 1, -1 },
    { 16, 13, 9, 5, 2 },
    { 17, 14, 10, 6, -1 },
    { 18, 15, 11, -1, -1 }
};

vector <mask> turn;

bool win[600000];

int main()
{
    mask tmp, next;
    for (short i(0); i < 15; ++i)
    {
        for (short beg(0); beg < 5 && step[i][beg] >= 0; ++beg)
        {
            tmp = 0;
            for (short j(beg); j < 5 && step[i][j] >= 0; ++j)
            {
                set_bit(tmp, step[i][j], 1);
                turn.push_back(tmp);
            }
        }
    }
    char c;
    tmp = 0;
    for (int i(0); i < 19; ++i)
    {
        cin >> c;
        set_bit(tmp, i, c == 'O');
    }
    for (mask i(1); i < (1 << 19); ++i)
        if ((i & tmp) == i)
        {
            for (int go(0); go < turn.size(); ++go)
                if ((i & turn[go]) == turn[go])
                {
                    next = i & (full ^ turn[go]);
                    if (next != i)
                        if (!win[next])
                        {
                            win[i] = true;
                            break;
                        }
                }
        }
    cout << (win[tmp] ? "Karlsson" : "Lillebror");
}

