int solve(VI a) {
    const int n=sz(a);
    VI tr(n+1);
    const auto upt=[&tr,n](int x, int v) {
        for(; x<=n; x+=x&-x) setmax(tr[x], v);
    };
    const auto get=[&tr](int x) {
        int r=0;
        for(; x>=1; x-=x&-x) setmax(r, tr[x]);
        return r;
    };
    int ans=0;
    repn(i, n) {
        int cur=get(n-a[i])+1;
        upt(n-a[i], cur);
        setmax(ans, cur);
    }
    return ans;
}

