#define MAX 7
 
int n;
 
int minf[MAX][MAX], maxf[MAX][MAX], cost[MAX][MAX];
vi sol;
int fs, cs;
 
map<vi,int> m;
 
int solve() {
  if (sol[0] == n-1) return 0;
  if (m.count(sol)) return m[sol];
  int &r = m[sol];
  r = -INF;
  int v = sol[0];
  int u = sol[1];
  if (u == n) {
    if (sol[v+2] > 0) return r = -INF;
    sol[0] = v+1;
    sol[1] = v+2;
    r = solve();
    sol[0] = v;
    sol[1] = n;
    return r;
  }
  if (sol[v+2] < minf[v][u]) return r = -INF;
  for (int i = minf[v][u]; i <= min(sol[v+2],maxf[v][u]); i++) {
    int c = i*i;
    if (i > 0) c += cost[v][u];
    sol[v+2] -= i;
    sol[1]++;
    sol[u+2] += i;
    int rs = solve();
    if (rs > -INF) r = max(r,rs+c);
    sol[1]--;
    sol[u+2] -= i;
    sol[v+2] += i;
  }
  return r;
}
 
