			if(nxt[j][i+1] == n) continue;
			int bs = query(i+1, nxt[j][i+1] - 1);
			if((bs >> (str[i] - 'A')) & 1) continue;
			dp[bs] += c2[str[i] - 'A'][j];
			dp[bs | (1 << j)] -= c2[str[i] - 'A'][j];
			dp[bs | (1 << (str[i] - 'A'))] -= c2[str[i] - 'A'][j];
			dp[bs | (1 << j) | (1 << (str[i] - 'A'))] += c2[str[i] - 'A'][j];
		}
	}
	for(int i=0; i<k; i++){
		for(int j=0; j<(1<<k); j++){
			if((j >> i) & 1){
				dp[j] += dp[j ^ (1<<i)];
			}
		}
	}
	int ret = 0;
	for(int i=0; i<(1<<k); i++){
		if(((~jc) & i)) continue;
		if(i == jc) continue;
		for(int j=0; j<k; j++){
			if((i >> j) & 1) dp[i] += c1[j];
		}
		if(dp[i] <= t){
		//	printf("%d %lld\n", i, dp[i]);
			ret++;
		}
	}
	cout << ret;
}

