long long po(long long a,long long b,long long mod){
	long long x=1,y=a;
	while(b>0){
		if(b%2){
			x=x*y;
			x%=mod;
		}
		y=y*y;
		y%=mod;
		b/=2;
	}
	return x;
}

long long mul(long long a,long long b,long long mod){
	long long ans = (a*b)%mod;
	return ans;
}

long long add(long long a,long long b,long long mod){
	long long ans = (a+b);
	if(ans>=mod)
		ans-=mod;
	return ans;
}

/*	Hashing part starts here */
static long long po1[100001],po2[100001],ipo1[100001],ipo2[100001];
const int p1 = 89,p2 = 101;	// chosen base primes.
const int mod1 =  1000000007, mod2 = 1000000009; // chosen mod primes.

int conv(char c){
	if(c=='_'){
		return 1;
	} else
	if(c>=48&&c<=58){
		return (27+26+c-'0'+1);
	}
	if(c<='Z'){
		return (1+c-'A'+1);
	} else {
		return (27+c-'a'+1);
	}
}

void pre(){
	po1[0] = po2[0] = 1;
	ipo1[0] = ipo2[0] = 1;
	for(int i=1;i<=100000;i++){
		po1[i] = po1[i-1] * p1;
		po1[i]%=mod1;
		po2[i] = po2[i-1] * p2;
		po2[i]%=mod2;
		ipo1[i] = po(po1[i],mod1-2,mod1);
		ipo2[i] = po(po2[i],mod2-2,mod2);
	}
	return;
}

struct Hash{
	vector<long long int> vc1,vc2;
	pair<long long,long long> overall;
	Hash(string s){
		int n = s.length();
		vc1.resize(n+1);
		vc2.resize(n+1);

		vc1[0] = vc2[0] = 0;
		for(int i=1;i<=n;i++){
			vc1[i] = add(mul(conv(s[i-1]),po1[i-1],mod1),vc1[i-1],mod1);
			vc2[i] = add(mul(conv(s[i-1]),po2[i-1],mod2),vc2[i-1],mod2);
		}
		overall = make_pair(vc1[n],vc2[n]);
		return;
	}
};
