const int MAXN = 10005, MAXK = 10, MAXM = 105, inf = 0x3f3f3f3f;
int n, K, m, len, x[MAXK + 5], a[MAXM], dis[MAXN], s[MAXK << 1], pos[1 << (MAXK << 1)], G[MAXK << 1][MAXK << 1], f[1 << (MAXK << 1)];
queue<int> q;
inline void bfs(int S) {
	memset(dis, -1, sizeof dis);
	dis[S] = 0;
	q.push(S);
	while(!q.empty()) {
		Int u = q.front(); q.pop();
		for(Int i = 1; i <= m; ++i) {
			if(u - a[i] >= 1 && dis[u - a[i]] < 0) dis[u - a[i]] = dis[u] + 1, q.push(u - a[i]);
			if(u + a[i] <= n && dis[u + a[i]] < 0) dis[u + a[i]] = dis[u] + 1, q.push(u + a[i]);
		}
	}
}

int calc(int S) {
	if(!S) return 0;
	if(f[S] != -1) return f[S];
	f[S] = inf;
	int T = S^(S&-S), i = S&-S, j;
	while(T) {
		j = T&-T;
		T ^= j;
		if(G[pos[i]][pos[j]] != inf)
			f[S] = min(f[S], calc(S ^ i ^ j) + G[pos[i]][pos[j]]);
	}
	return f[S];
}

int main() {
	scanf("%d%d%d", &n, &K, &m);
	for(Int i = 1; i <= K; ++i) scanf("%d", x + i);
	for(Int i = 1; i <= m; ++i) scanf("%d", a + i);
	x[0] = x[K + 1] = -1;
	for(Int i = 1; i <= K; ++i) {
		if(x[i] != x[i - 1] + 1) s[len++] = x[i] - 1;
		if(x[i] != x[i + 1] - 1) s[len++] = x[i];
	}
	
	for(Int i = 0; i < len; ++i) {
		pos[1 << i] = i;
		bfs(s[i]);
		for(Int j = 0; j < len; ++j)
			G[i][j] = dis[s[j]] < 0 ? inf : dis[s[j]];
	}
	
	memset(f, -1, sizeof (int) * (1 << len));
	if(calc((1 << len) - 1) == inf) puts("-1");
	else printf("%d\n", calc((1 << len) - 1));
	return 0;
}

