struct ${$(){ios_base::sync_with_stdio(false);cin.tie(nullptr);}}$;

using Pt = array<int, 2>;

int t0, t1;
Pt c, s, h;
using flt = long double;
const flt pi = acos(flt(-1));
const flt K = 1 + 1e-15;

int answer(flt a) {
	cout << fixed << setprecision(9) << a << '\n';
	return 0;
}

bool inter(flt x0, flt y0, flt r0, flt x1, flt y1, flt r1, flt x2, flt y2, flt r2) {
	r0 *= K; r1 *= K; r2 *= K;
	flt dx = x1 - x0, dy = y1 - y0;
	flt d = hypot(dx, dy);
	r0 /= d; r1 /= d;
	flt k = (r0 * r0 - r1 * r1 + 1) / 2;
	flt l = r0 * r0 - k * k;
	if (l < 0) return false;
	l = sqrt(l);
	if (hypot(x0 + k * dx + l * dy - x2, y0 + k * dy - l * dx - y2) <= r2) return true;
	if (hypot(x0 + k * dx - l * dy - x2, y0 + k * dy + l * dx - y2) <= r2) return true;
	return false;
}

bool can(flt r) {
	flt r0 = hypot(flt(s[0]), flt(s[1])) + t0 - r;
	flt r1 = hypot(flt(h[0]), flt(h[1])) + t1 - r;
	return inter(0, 0, r, s[0], s[1], r0, h[0], h[1], r1)
	    || inter(s[0], s[1], r0, h[0], h[1], r1, 0, 0, r)
	    || inter(h[0], h[1], r1, 0, 0, r, s[0], s[1], r0);
}

int main() {
	cin >> t0 >> t1;
	cin >> c[0] >> c[1];
	cin >> h[0] >> h[1];
	cin >> s[0] >> s[1];
	s[0] -= c[0];
	s[1] -= c[1];
	h[0] -= c[0];
	h[1] -= c[1];
	flt E0 = hypot(flt(h[0]), flt(h[1])) + hypot(flt(h[0] - s[0]), flt(h[1] - s[1])) - hypot(flt(s[0]), flt(s[1]));
	assert(E0 >= 0);
	flt E1 = hypot(flt(s[0]), flt(s[1])) + hypot(flt(h[0] - s[0]), flt(h[1] - s[1])) - hypot(flt(h[0]), flt(h[1]));
	assert(E1 >= 0);
	E0 = t0 - E0;
	E1 = t1 - E1;
	if (E1 >= 0)
		return answer(hypot(flt(s[0]), flt(s[1])) + hypot(flt(h[0] - s[0]), flt(h[1] - s[1])) + min(flt(t0), E1));
	if (E0 >= 0)
		return answer(hypot(flt(h[0]), flt(h[1])) + min(flt(t1), (t1 + E0) / 2));
	flt low = min(t0, t1), high = min(hypot(flt(s[0]), flt(s[1])) + t0, hypot(flt(h[0]), flt(h[1])) + t1);
	//E(low, high, can(250)); return 1;
	for (int i = 0; i < 100; ++i) {
		flt mid = low + (high - low) / 2;
		bool cn = can(mid);
		//E(low, high, mid, boolalpha, cn);
		if (cn)
			low = mid;
		else
			high = mid;
	}
	return answer(low + (high - low) / 2);
}

