void dfs(int u, int p = -1)
{
	if (p != -1 && k[u] == 0)
	{
		return;
	}
	vector<ll> vec;
	ll b = 0;
	for (auto v : g[u])
	{
		if (v == p)
		{
			continue;
		}
		dfs(v, u);
		if (x[v] > 0)
		{
			vec.push_back(x[v]);
		}		
		b += y[v];
	}
	sort(vec.begin(), vec.end(), greater<ll>());
	y[u] = k[u];
	if (p != -1)
	{
		y[u]--;
		x[u]++;
	}
	for (int i = 0; i < vec.size() && y[u] > 0; i++)
	{
		x[u] += vec[i] + 1;
		y[u]--;
	}
	vec.clear();
	ll val = min(y[u], b);
	y[u] -= val;
	x[u] += val * 2;	
}


