#include<cstdio>
#include<cstdlib>
#include<vector>
#define endl "\n"
using namespace std;
struct target{int L, R, H, index;};
target arr[20002];
int RESULT[20002];
bool cmp(target A, target B){
     return (A.L < B.L);    
}
double dist(int Fx, int Fy, int Sx, int Sy){
    return sqrt((Fx-Sx)*(Fx-Sx)+(Fy-Sy)*(Fy-Sy));    
}


int main(){
    int N = 0, M = 0;
    scanf("%i",&N);
    for(int i=1;i<=N;i++){
            int pos = 0, R = 0;
            scanf("%i%i",&pos,&R);
            arr[i].L = pos - R;
            arr[i].R = pos + R;
			arr[i].H = R;
			arr[i].index = i;
			RESULT[i] = -1;
    }
    stable_sort(arr+1,arr+N+1,cmp);
    int ALL = 0;
    scanf("%i",&M);
    for(int i=1;i<=M;i++){
          int curX = 0, curY = 0; 
          scanf("%i%i",&curX,&curY);

		  int l = 1, r = N,id = 0;

		  while(l <= r){
				  int mid = (l+r) >> 1;
				  if(arr[mid].L == curX){
							if(mid > 1 && arr[mid-1].R == curX){
								if(RESULT[arr[mid-1].index] == -1 && dist((arr[mid-1].L+arr[mid-1].R)>>1,0,curX,curY)<=arr[mid-1].H){ALL++;RESULT[arr[mid-1].index] = i;}
							}
						id = mid;
						break;
				  }
				  else if(arr[mid].R == curX){
							if(mid < N && arr[mid+1].L == curX){
								if(RESULT[arr[mid+1].index] == -1 && dist((arr[mid+1].L+arr[mid+1].R)>>1,0,curX,curY)<=arr[mid+1].H){ALL++;RESULT[arr[mid+1].index] = i;}
							}
						id = mid;
						break;
				  }
				  if(arr[mid].L < curX && arr[mid].R > curX){id = mid;break;}
				  else if(arr[mid].L > curX) r = mid-1;
				  else if(arr[mid].R < curX) l = mid+1;
		  }

		  if(RESULT[arr[id].index] == -1 && dist((arr[id].L+arr[id].R)>>1,0,curX,curY)<=arr[id].H){RESULT[arr[id].index] = i;ALL++;}

	}
	cout << ALL << endl;
	for(int i=1;i<=N;i++){
			cout << RESULT[i] << " ";
	}

    //system("pause");
    return 0;    
}

#include <bits/stdc++.h>

using namespace std;

using vi = vector<int>; using vvi = vector<vi>;
using ii = pair<int,int>; using vii = vector<ii>;
using l = long long; using vl = vector<l>; using vvl = vector<vl>;
using ll = pair<l,l>; using vll = vector<ll>; using vvll = vector<vll>;
using lu = unsigned long long;
using vb = vector<bool>; using vvb = vector<vb>;
using vd = vector<double>; using vvd = vector<vd>;
const int INF = numeric_limits<int>::max();
const double EPS = 1e-10;
const l e0 = 1, e5 = 100000, e6 = 1000000, e7 = 10000000, e9 = 1000000000;

// #define ONLINE_JUDGE
#if defined ONLINE_JUDGE
const bool enable_log = false;
#else
const bool enable_log = true;
#endif
struct VoidStream { void operator&(std::ostream&) { } };
#define LOG !(enable_log) ? (void) 0 : VoidStream() & cerr

const l dx[] = {0, 0, 1, -1};
const l dy[] = {-1, 1, 0, 0};

struct point { l x, y; };

const l Z = 26;
const l MAX = 50;

point start, finish;
l n, m, k;
l around_start, around_finish;
l shortest;
string answer;
l D[MAX][MAX];
vector<string> M;

bool fit(l x, l y) {
  return (x >= 0) and (x < n) and (y >= 0) and (y < m);
}

l to_bit(char c) { return e0 << (c - 'a'); }

void check(l mask) {
  if ((mask & around_finish) == 0) return;
  fill(&D[0][0], &D[MAX][0], 0);
  queue<point> q;
  q.emplace(finish);
  D[finish.x][finish.y] = 1;
  while (not q.empty()) {
    auto u = q.front(); q.pop();
    l r = D[u.x][u.y];
    if (r > shortest) return;
    for (l d = 0; d < 4; d++) {
      l x = u.x + dx[d], y = u.y + dy[d];
      if ((not fit(x, y)) or D[x][y] != 0) continue;
      if (M[x][y] == 'S') {
        string candidate = "";
        vector<point> wave; wave.push_back({x, y});
        for (l i = r; i > 1; i--) {
          vector<point> next;
          char c = 'z' + 1;
          for (const auto p : wave) {
            for (l j = 0; j < 4; j++) {
              l a = p.x + dx[j], b = p.y + dy[j];
              if ((not fit(a, b)) or (D[a][b] != i)) continue;
              D[a][b] = -1;
              if (M[a][b] < c) {
                next.clear();
                c = M[a][b];
              }
              if (M[a][b] == c) next.push_back({a, b});
            }
          }
          candidate += c;
          swap(next, wave);
        }
        if (r < shortest) {
          answer = candidate;
          shortest = r;
        } else if (candidate < answer) {
          answer = candidate;
        }
        return;
      }
      if (mask & to_bit(M[x][y])) {
        D[x][y] = r + 1;
        q.push({x, y});
      } else {
        D[x][y] = -1;
      }
    }
  }
}

int main() {
  ios_base::sync_with_stdio(false); cin.tie(0);
  while (cin >> n >> m >> k) {
    shortest = INF;
    M.resize(n);
    for (l i = 0; i < n; i++) cin >> M[i];
    l mask = 0;
    for (l i = 0; i < n; i++) {
      for (l j = 0; j < m; j++) {
        if (M[i][j] == 'S') { start = {i, j}; continue; }
        if (M[i][j] == 'T') { finish = {i, j}; continue; }
        mask = mask | to_bit(M[i][j]);
      }
    }
    // LOG << "letters = " << bitset<MAX>(mask) << '\n';
    // LOG << start.x << ' ' << start.y << '\n';
    // LOG << finish.x << ' ' << finish.y << '\n';
    around_start = 0;
    for (l d = 0; d < 4; d++) {
      if (fit(start.x + dx[d], start.y + dy[d])) {
        if (M[start.x + dx[d]][start.y + dy[d]] == 'T') {
          shortest = 0;
          break;
        }
        around_start = around_start | to_bit(M[start.x + dx[d]][start.y + dy[d]]);
      }
    }
    if (shortest == 0) {
      cout << '\n';
      continue;
    }
    around_finish = 0;
    for (l d = 0; d < 4; d++) {
      if (fit(finish.x + dx[d], finish.y + dy[d]))
        around_finish = around_finish | to_bit(M[finish.x + dx[d]][finish.y + dy[d]]);
    }
    for (l a = 0; a < Z; a++) {
      if ((around_start & (e0 << a)) == 0) continue;
      check(e0 << a);
      if (k == 1) continue;
      for (l b = 0; b < Z; b++) {
        if ((b == a) or ((mask & (e0 << b)) == 0)) continue;
        check((e0 << a) | (e0 << b));
        if (k == 2) continue;
        for (l c = b + 1; c < Z; c++) {
          if ((c == a) or ((mask & (e0 << c)) == 0)) continue;
          check((e0 << a) | (e0 << b) | (e0 << c));
          if (k == 3) continue;
          for (l d = c + 1; d < Z; d++) {
            if ((d == a) or ((mask & (e0 << d)) == 0)) continue;
            check((e0 << a) | (e0 << b) | (e0 << c) | (e0 << d));
          }
        }
      }
    }
    if (shortest == INF) {
      cout << "-1\n";
    } else {
      cout << answer << '\n';
    }
    // break;
  }
}

