#define mem(a,val) memset(a,val,sizeof a)
#define endl "\n"
#define maxn 5005

ll vis[maxn],assign[maxn],x[maxn],y[maxn],f,n,dist[maxn][maxn];
vector<ll>v[maxn];

void dfs(ll cur)
{
	vis[cur]=1;
	for(ll i=0;i<v[cur].size();i++)
	{
		ll x=v[cur][i];
		if(!vis[x])
		{
			assign[x]=1-assign[cur];
			dfs(x);
		}
		else
		{
			if(assign[x]!=1-assign[cur])
			{
				f=1;
				return;
			}
		}
	}
}
int ok(ll val)
{
	for(ll i=1;i<=n;i++)
	v[i].clear();
	for(ll i=1;i<=n;i++)
	{
		for(ll j=i+1;j<=n;j++)
		{
			if(dist[i][j]>val)
			{
				v[i].pb(j);
				v[j].pb(i);
			}
		}
	}
	mem(vis,0);
	for(ll i=1;i<=n;i++)
	assign[i]=-1;
	for(ll i=1;i<=n;i++)
	{
		if(vis[i])
		continue;

		assign[i]=1;
		f=0;
		dfs(i);
		if(!f)
		continue;
		return 0;
	}
	return 1;
}
void visit(ll cur)
{
	vis[cur]=1;
	for(ll i=0;i<v[cur].size();i++)
	{
		ll x=v[cur][i];
		if(!vis[x])
		visit(x);
	}
}
int main()
{
	boost1;boost2;	
	ll i,j,val,lo,mid,hi,ans=1;
	cin>>n;
	for(i=1;i<=n;i++)
	cin>>x[i]>>y[i];
	for(i=1;i<=n;i++)
	{
		for(j=i+1;j<=n;j++)
		dist[i][j]=abs(x[i]-x[j])+abs(y[i]-y[j]);
	}
	for(i=1;i<=n;i++)
	{
		for(j=i+1;j<=n;j++)
		hi=max(hi,dist[i][j]);
	}
	lo=-1;
	while(hi-lo>1)
	{
		mid=(lo+hi)/2;
		if(ok(mid))
		hi=mid;
		else
		lo=mid;
	}
	val=hi;
	for(i=1;i<=n;i++)
	v[i].clear();
	for(i=1;i<=n;i++)
	{
		for(j=i+1;j<=n;j++)
		{
			if(abs(x[i]-x[j])+abs(y[i]-y[j])>val)
			{
				v[i].pb(j);
				v[j].pb(i);
			}
		}
	}
	mem(vis,0);
	for(i=1;i<=n;i++)
	{
		if(vis[i])
		continue;
		ans=(1LL*ans*2)%mod;
		visit(i);
	}
	cout<<val<<" "<<ans;
	return 0;
}

