int p[100000];

int main() {
	int k[3], T[3], n;
	f(i, 0, 3)scanf("%d", k + i);
	f(i, 0, 3)scanf("%d", T + i);
	scanf("%d", &n);
	priority_queue<tuple<ll, char, int > > s;
	f(i, 0, n) {
		int x;
		scanf("%d", &x);
		s.emplace(-x, 0, i);
		p[i] = x;
	}
	ll an = 0;
	queue<pair<ll, int> > q[3];
	while (!s.empty()) {
		ll c;
		char o;
		int id;
		tie(c, o, id) = s.top();
		c = -c;
		s.pop();
		if (o == 3) {
			an = max(an, c - p[id]);
			if (id == q[2].front().second)q[2].pop();
		}
		else if (o == 2) {
			if (id == q[1].front().second)q[1].pop();
			ll t;
			if (q[2].size() < k[2])t = c + T[2];
			else t = q[2].front().first + T[2], q[2].pop();
			q[2].emplace(t, id);
			s.emplace(-t, o + 1, id);
		}
		else if (o == 1) {
			if (id == q[0].front().second)q[0].pop();
			ll t;
			if (q[1].size() < k[1])t = c + T[1];
			else t = q[1].front().first + T[1], q[1].pop();
			q[1].emplace(t, id);
			s.emplace(-t, o + 1, id);
		}
		else {
			ll t;
			if (q[0].size() < k[0])t = c + T[0];
			else t = q[0].front().first + T[0], q[0].pop();
			q[0].emplace(t, id);
			s.emplace(-t, o + 1, id);
		}
	}
	printf("%lld", an);
}

