long long arr[200010], arr2[200010], cnt=0, depth[200010], par[200010][20], n, v[200010], trakm[200010], lft[200010], rt[200010], res[200010];
vector <long long> a[200010];
map <long long, long long> pos;
long long dfs(int x, int papa){
  if(papa==-1){
    depth[x]=0;
    par[x][0]=x;
    lft[x]=0;
    rt[x]=0;
  }
  else{
    par[x][0]=papa;
    depth[x]=depth[papa]+1;
    if(v[x]>v[papa]){
      lft[x]=lft[papa]+1;
      rt[x]=rt[papa];
    }
    else{
      lft[x]=lft[papa];
      rt[x]=rt[papa]+1;
    }
  }
  if(a[x].size()==0){
    arr[cnt]=v[x];
    arr2[cnt]=x;
    pos[v[x]]=cnt;
    ++cnt;
  }
  else{
    if(v[a[x][0]]<v[a[x][1]]){
      dfs(a[x][0], x);
      dfs(a[x][1], x);
    }
    else{
      dfs(a[x][1], x);
      dfs(a[x][0], x);
    }
  }
}
void pre(){
  for(int i=1; i<20; ++i){
    for(int j=1; j<=n; ++j){
      par[j][i]=par[par[j][i-1]][i-1];
    }
  }
}
int LCA(int x, int y){
  if(depth[x]>depth[y]){
    for(int i=19; i>=0; --i){
      if(depth[par[x][i]]>=depth[y])
        x=par[x][i];
    }
  }
  if(depth[y]>depth[x]){
    for(int i=19; i>=0; --i){
      if(depth[par[y][i]]>=depth[x])
        y=par[y][i];
    }
  }
  if(x==y)
    return x;
  for(int i=19; i>=0; --i){
    if(par[x][i]!=par[y][i]){
      x=par[x][i];
      y=par[y][i];
    }
  }
  return par[x][0];
}
long long mem[200010][4];
long long dfs2(int x, int bl){
  if(a[x].size()==0){
    return v[x];
  }
  if(mem[x][bl]!=-1){
    return mem[x][bl];
  }
  long long tmp=0;
  if(bl==0){
    if(v[a[x][0]]<v[a[x][1]]){
      tmp=dfs2(a[x][0], 0);
    }
    else{
      tmp=dfs2(a[x][1], 0);
    }
  }
  else{
    if(v[a[x][0]]<v[a[x][1]]){
      tmp=dfs2(a[x][1], 1);
    }
    else{
      tmp=dfs2(a[x][0], 1);
    }
  }
  mem[x][bl]=tmp;
  return tmp;
}
void dfs1(int x, long long val){
  if(a[x].size()==0){
    res[x]=val;
  }
  else{
    if(v[a[x][0]]<v[a[x][1]]){
      dfs1(a[x][0], val+dfs2(a[x][1], 0));
      dfs1(a[x][1], val+dfs2(a[x][0], 1));
    }
    else{
      dfs1(a[x][0], val+dfs2(a[x][1], 1));
      dfs1(a[x][1], val+dfs2(a[x][0], 0));
    }
  }
}
int main(){
  long long x, y, root, k, tmp1, tmp2,tmp, lca;
  long double ans;
  while(cin>>n){
