    pre();
    trakm[0]=-1;
    for(int i=0; i<cnt; ++i){
//      cout<<arr[i]<<" ";
      trakm[i]=trakm[i-1]+arr[i];
    }
//    cout<<endl;
    cin>>k;
    dfs1(root,0);
    for(int i=0; i<k; ++i){
      cin>>x;
      tmp1=arr[lower_bound(arr, arr+cnt, x)-arr-1];
      tmp2=arr[upper_bound(arr, arr+cnt, x)-arr];
//      cout<<tmp1<<" "<<tmp2<<endl;
      if(tmp1==-1){
        tmp=tmp2;
      }
      else if(tmp2==2e9){
        tmp=tmp1;
      }
      else{
        lca=LCA(arr2[pos[tmp1]], arr2[pos[tmp2]]);
//        cout<<arr2[pos[tmp1]]<<" "<<arr2[pos[tmp2]]<<" "<<"lca "<<lca<<" "<<v[lca]<<endl;
        if(x>v[lca]){
          tmp=tmp2;
        }
