    const dbl E = 2.718281828459045235360287471352662498L;
    const dbl EPS = 1e-12L;

    template<typename T1, typename T2>
    T1 bin_pow(T1 a, T2 n) {
        T1 r = 1;
        while (n > 0) {
            if (n & 1)
                r *= a;
            a *= a;
            n /= 2;
        }
        return r;
    }

    template<typename T1, typename T2>
    T1 bin_pow(T1 a, T2 n, const T1& m) {
        if (m == 1)
            return 0;
        T1 r = 1;
        while (n > 0) {
            if (n & 1) {
                r *= a;
                r %= m;
            }
            a *= a;
            a %= m;
            n /= 2;
        }
        return r;
    }

    template<typename T>
    T gcd(const T& a, const T& b) {
        if (b == 0)
            return abs(a);
        return gcd(b, a % b);
    }

    template<typename T>
    T gcd(const T& a, const T& b, T& x, T& y) {
        if (b == 0) {
            x = a < 0 ? -1 : 1;
            y = 0;
            return x * a;
        }
        T d = gcd(b, a % b, y, x);
        y -= (a / b) * x;
        return d;
    }

    template<typename T>
    T lcm(const T& a, const T& b) {
        return abs(a / gcd(a, b) * b);
    }

    template<typename T>
    T mod_add(const T& a, const T& b, const T& m) {
        if (a < m - b)
            return a + b;
        return a - (m - b);
    }

    template<typename T>
    T mod_sub(const T& a, const T& b, const T& m) {
        if (a < b)
            return a + (m - b);
        return a - b;
    }

    template<typename T>
    T mod_mul(T a, T b, const T& m) {
        if (b > a)
            swap(a, b);
        T r = 0;
        while (b > 0) {
            if (b & 1)
                r = mod_add(r, a, m);
            a = mod_add(a, a, m);
            b /= 2;
        }
        return r;
    }

    template<typename T1, typename T2>
    T1 mod_pow(T1 a, T2 n, const T1& m) {
        if (m == 1)
            return 0;
        T1 r = 1;
        while (n > 0) {
            if (n & 1)
                r = mod_mul(r, a, m);
            a = mod_mul(a, a, m);
            n /= 2;
        }
        return r;
    }

    template<typename T>
    T mod_inv(const T& a, const T& m) {
        T x, y;
        T d = gcd(a, m, x, y);
        if (d != 1)
            return 0;
        if (x < 0)
            x += m;
        return x;
    }

    struct Sieve {
        int* lpf = nullptr;
        int* phi = nullptr;
        int size;
        vector<int> primes;

        Sieve(bool calcPhi = false, int n = 0xfffff) : size(n) {
            lpf = new int[size + 1];
            fill(lpf, lpf + size + 1, 0);
            lpf[1] = 1;
            if (calcPhi) {
                phi = new int[size + 1];
                phi[1] = 1;
                for (int i = 2; i <= size; ++i) {
                    if (lpf[i] == 0) {
                        phi[i] = i - 1;
                        lpf[i] = i;
                        primes.push_back(i);
                    }
                    for (int j = 0, t; j < primes.size() && (t = i * primes[j]) <= size; ++j) {
                        lpf[t] = primes[j];
                        if (primes[j] == lpf[i]) {
                            phi[t] = phi[i] * primes[j];
                            break;
                        }
                        phi[t] = phi[i] * (primes[j] - 1);
                    }
                }
            } else {
                for (int i = 2; i <= size; ++i) {
                    if (lpf[i] == 0) {
                        lpf[i] = i;
                        primes.push_back(i);
                    }
                    for (int j = 0, t; j < primes.size() && (t = i * primes[j]) <= size; ++j) {
                        lpf[t] = primes[j];
                        if (primes[j] == lpf[i])
                            break;
                    }
                }
            }
        }

        Sieve(int n) : Sieve(false, n) {}

        ~Sieve() {
            delete [] lpf;
            lpf = nullptr;
            delete [] phi;
            phi = nullptr;
        }
    };

    template<typename T>
    T phi(T n) {
        T r = n;
        for (T i = 2; i * i <= n; ++i) {
            if (n % i == 0) {
                r -= r / i;
                do {
                    n /= i;
                } while (n % i == 0);
            }
        }
        if (n > 1)
            r -= r / n;
        return r;
    }
}

