double Ans,tmp,Ax,Ay,Az,Vx,Vy,Vz,R,r,px,py,pz,Ox,Oy,Oz;
double Get()
{
	double a=Vx*Vx+Vy*Vy+Vz*Vz;
	double b=2*Vx*px+2*Vy*py+2*Vz*pz;
	double c=px*px+py*py+pz*pz-r*r;
	double d=b*b-4*a*c;
	if(d<-eps||b-sqrt(d)<-eps) return 1e63;
	return (b-sqrt(d))/2/a;
}
