		scanf("%lf%lf%lf%lf%d",&Ox,&Oy,&Oz,&r,&M);
		px=Ox-Ax,py=Oy-Ay,pz=Oz-Az,r+=R;
		tmp=Get();
        if(tmp<Ans) Ans=tmp;
        r=R;
        for(j=1;j<=M;++j)
		{
			scanf("%lf%lf%lf",&px,&py,&pz);
			px+=Ox-Ax,py+=Oy-Ay,pz+=Oz-Az;
			tmp=Get();
        	if(tmp<Ans) Ans=tmp;
