struct CHT {

    vector<LL> Slope,Ci,Id; /// Holds Slope and c[i]

    /// Checking the line l1 or l3 is better than line l2

    int Isbad(int l1,int l2,int l3) {
        return 1.0*(Ci[l3]-Ci[l1])*(Slope[l1]-Slope[l2]) <=1.0*(Ci[l2]-Ci[l1])*(Slope[l1]-Slope[l3]);
    }

    /// Adds a new line
    void Add(LL m,LL c,int id) {
        Slope.PB(m);
        Ci.PB(c);
        Id.PB(id);
        while(Slope.sz>=3&& Isbad(Slope.sz-3,Slope.sz-2,Slope.sz-1)) {
            Slope.erase(Slope.end()-2);
            Ci.erase(Ci.end()-2);
            Id.erase(Id.end()-2);
        }
    }

    LL Query(int nw,LL x) {
        return (Slope[nw]*x+Ci[nw]);
    }

    LL GetMin(LL x) {
        int l=-1,r=Slope.sz-1;

        while( (r-l)>1 ) {
            int m=(l+r)/2;
            if(Query(m,x)>=Query(m+1,x))    l=m;
            else                            r=m;
        }
        return Query(r,x);
    }

    pair<LL,int> GetMax(LL x) {
        int l=-1,r=Slope.sz-1;
//        LL an=0;
//        int id;
//        trace1(x)
//        F(i,0,r+1) {
//            LL tp=Query(i,x);
//
//            trace4(Id[i],Slope[i],Ci[i],tp)
//
//            if(tp>=an) {
//                an=tp;
//                id=Id[i];
//            }
//        }
//        return MP(an,id);

        while((r-l)>1) {
            int m=(l+r)/2;
            if(Query(m,x)<=Query(m+1,x))    l=m;
            else                            r=m;
        }
        return MP(Query(r,x),Id[r]);
    }
};

CHT Tree[MX*4];
/// for maximizing

void Merge(int id,int lf,int rg) {
    int l=0,r=0;
    int lln=Tree[lf].Slope.sz,rln=Tree[rg].Slope.sz;
    while(l<lln&& r<rln) {
        if(Tree[lf].Slope[l]<Tree[rg].Slope[r]) {
            Tree[id].Add( Tree[lf].Slope[l],Tree[lf].Ci[l],Tree[lf].Id[l] );
            l++;
        }
         else {
            Tree[id].Add( Tree[rg].Slope[r],Tree[rg].Ci[r],Tree[rg].Id[r] );
            r++;
        }
    }
    while(l<lln) {
        Tree[id].Add( Tree[lf].Slope[l],Tree[lf].Ci[l],Tree[lf].Id[l] );
        l++;
    }
    while(r<rln) {
        Tree[id].Add( Tree[rg].Slope[r],Tree[rg].Ci[r],Tree[rg].Id[r] );
        r++;
    }
    return;
}

int a[MX];
int b[MX];

void Upd(int id,int l,int r) {
    if(l==r) {
        Tree[id].Add( b[l],a[l],l );
        return;
    }

    int mid=(l+r)/2;
    int lft=2*id;
    int rgt=lft+1;

    Upd(lft,l,mid);
    Upd(rgt,mid+1,r);
    Merge(id,lft,rgt);
}

LL P;
pair<LL,int> Qry(int id,int l,int r,int s,int e) {

    if(s<=l&&e>=r) {
        return Tree[id].GetMax(P);
    }

    int mid=(l+r)/2;
    int lft=2*id;
    int rgt=lft+1;

    if(e<=mid)      return Qry(lft,l,mid,s,e);
    else if(s>mid)  return Qry(rgt,mid+1,r,s,e);
    else {
        pair<LL,int>lf=Qry(lft,l,mid,s,e);
        pair<LL,int>rg=Qry(rgt,mid+1,r,s,e);
        if( lf.ff>=rg.ff  ) return lf;
        return rg;
    }
}



