int A[100007];
int dp[100007];
int n;
int f( int a)
{
	int st = a+1; int en = n+1;
	if(dp[st]>=A[a])
	{
		return a;
	}
	while(st<en)
	{
		if(en==st)
		{
			if(dp[en]>A[a])
			{
				return en-1;
			}
		}
		if(en-st==1)
		{
			if(dp[en]<A[a])
			{
				return en;
			}
			else
			return st;
		}
		int mid = (st+en)>>1;
		if(dp[mid]<A[a])
		{
			st = mid;
		}
		else
		{
			en = mid-1;
		}
	}	
}
