using namespace std;

int get(){
	char ch;
	int s=0;
	bool bz=0;
	while(ch=getchar(),(ch<'0'||ch>'9')&&ch!='-');
	if (ch=='-')bz=1;else s=ch-'0';
	while(ch=getchar(),ch>='0'&&ch<='9')s=s*10+ch-'0';
	if (bz)return -s;
	return s;
}

const int N = 1e+5+10;

struct edge{
	int x,nxt,id;
}e[N*2];
int h[N],tot;
int s[N],fa[N][20],n,m,q,dep[N];
int dfn[N],f[N],k,sta[N],top,tim,b[N],te;
bool pd[N],bz[N];

void inse(int x,int y,int id){
	e[++tot].x=y;
	e[tot].nxt=h[x];
	e[tot].id=id;
	h[x]=tot;
}

void tarjan(int x,int co){
	dfn[x]=f[x]=++k;
	sta[++top]=x;
	pd[x]=1;
	fo(i,1,tim)fa[x][i]=fa[fa[x][i-1]][i-1];
	for(int p=h[x];p;p=e[p].nxt)
		if (e[p].id!=co){
			if (!dfn[e[p].x]){
				fa[e[p].x][0]=x;
				dep[e[p].x]=dep[x]+1;
				tarjan(e[p].x,e[p].id);
				f[x]=min(f[x],f[e[p].x]);
			}
			else 
				if (pd[e[p].x]){
					f[x]=min(f[x],dfn[e[p].x]);
					if (dep[e[p].x]%2==dep[x]%2)bz[x]=1;
				}
		}
	pd[x]=0;
	if (dfn[x]==f[x]){
		int w=top;bool v=0;
		while(sta[w]!=x)v|=bz[sta[w--]];
		if (v)fo(i,w+1,top)s[sta[i]]++;
		te++;
		fo(i,w,top){
			b[sta[i]]=te;
			pd[sta[i]]=0;
		}
		top=w-1;
	}
}

int getfather(int x,int y){
	if (dep[x]<dep[y])swap(x,y);
	fd(i,tim,0)
	if (dep[fa[x][i]]>=dep[y])x=fa[x][i];
	if (x==y)return x;
	fd(i,tim,0)
	if (fa[x][i]!=fa[y][i])x=fa[x][i],y=fa[y][i];
	return fa[x][0];
}

void dfs(int x){
	for(int p=h[x];p;p=e[p].nxt)
		if (fa[e[p].x][0]==x){
			s[e[p].x]+=s[x];
			dfs(e[p].x);
		}
}

