ld cdist[Maxn][Maxn];

bool Enough(ld x)
{
	for (int i = 0; i <= 2 * n; i++)
		for (int j = 0; j <= 2 * n; j++)
			cdist[i][j] = dist[i][j] - x;
	for (int k = 0; k <= 2 * n; k++)
		for (int i = 0; i <= 2 * n; i++) if (cdist[i][k] >= -100.0l)
			for (int j = 0; j <= 2 * n; j++) if (cdist[k][j] >= -100.0l)
				cdist[i][j] = max(cdist[i][j], cdist[i][k] + cdist[k][j]);
	for (int i = 0; i <= 2 * n; i++)
		if (cdist[i][i] >= 0.0l) return true;
	return false;
}

