bool dfs_path(int x, int y, int dest, vector <int> & path) {
	if (x == dest) {
		path.push_back(x);
		return true;
	}
	for (auto v : graf[x]) {
		if (v != y) {
			if (dfs_path(v, x, dest, path)) {
				path.push_back(x);
				return true;
			}
		}
	}
	return false;
}
