int powmod(int a, int b)
{
    int tmp = a;
    int ans = 1;
    while (b)
    {
        if (b & 1) ans = ((ll)ans * tmp) % MOD;
        tmp = ((ll)tmp * tmp) % MOD;
        b >>= 1;
    }
    return ans;
}

string btw(ll x)
{
