    for (int i = 0; i < n; i++) if (p[i].fi >= m)
    {
        for (int j = m - forb; j >= 0; j--)
        {
            ans[j] = (ll)ans[j] * (p[i].fi - forb - j) % MOD * blocks[i] % MOD;
            if (j > 0) ans[j] = (ans[j] + (ll)ans[j - 1] * j % MOD * blocks[i]) % MOD;
        }
    }
    if (m >= 22)
