const int set_size = 2e5+50;

struct disjoint_set {
    int *parent; // initialized as: parent[i] = i
    disjoint_set() { parent = new int[set_size]; init_set(2e5);}
    void init_set(int n) { for(int i = 0 ; i <= n ; i ++) parent[i] = i; }
    int find(int x) { return parent[x] = (x == parent[x] ? x : find(parent[x])); }
    void join(int x, int y) { parent[find(x)] = find(y); }
    bool disjoint(int x, int y) { return find(x) != find(y); }
} ds;

int n, m1, m2, k;
map<string, int> key;

int is_syn(string &a, string &b) {
    return !ds.disjoint(key[a], key[b]) || !ds.disjoint(key[a]+1, key[b]+1);
}

int is_ant(string &a, string &b) {
    return !ds.disjoint(key[a]+1, key[b]) || !ds.disjoint(key[a], key[b]+1);
}

void set_syn(string &a, string &b) {
    ds.join(key[a], key[b]); ds.join(key[a]+1, key[b]+1);
}

void set_ant(string &a, string &b) {
    ds.join(key[a]+1, key[b]); ds.join(key[a], key[b]+1);
}

