        s.pb('A' + i);
        names.pb(s);
    }
    forrn(i, 26, 50) {
        string s;
        s.pb('A'); s.pb('a' + i - 26);
        names.pb(s);
    }

    vector<string> ans(n);

    int fy = -1;
    forn(i, n - k + 1) {
        ans[i] = names[0];
        if (inp[i] == "YES") {
            forn(j, k) {
                ans[i + j] = names[j];
            }
            fy = i;
            break;
        }
    }

    if (fy != -1) {
        forrn(i, fy + 1, n - k + 1) {
            if (inp[i] == "NO")
                ans[i + k - 1] = ans[i];
            else {
                set<string> s;
                forn(j, k)
                    s.insert(names[j]);
                forn(j, k - 1)
                    s.erase(ans[i + j]);
                ans[i + k - 1] = *(s.begin());
            }
        }
    } else {
        forrn(i, n - k + 1, n)
            ans[i] = names[0];
    }
    
    forn(i, n) {
