long long pa[N];
long long pb[N];

int dp[N];
int ul[N];
int dl[N];

map<long long, int> ff, fa, fb;
map<int, int> dm[N];

int solve(int u, int d) {
    if (u == d) return dp[u];
    if (dm[u].count(d)) return dm[u][d];
    int& res = dm[u][d];
    res = dp[min(u, d)];
    if (u < d) {
        if (dl[d] != -1) res = max(res, solve(u, dl[d]) + 1);
    } else {
        if (ul[u] != -1) res = max(res, solve(ul[u], d) + 1);
    }
    return res;
}

