#include <bits/stdc++.h>

using namespace std;

#define F first
#define S second
#define pb push_back
#define mp make_pair
#define eb emplace_back

typedef long double ld;

const ld EPS = 1e-8;

const int N = 1010;

struct point{
    ld x, y;

    point(ld x, ld y): x(x), y(y) {}
    point(): x(0), y(0) {}
};

point v[N];

bool eq(ld a, ld b) {
    return fabs(a - b) < EPS;
}

ld sq(ld x) {
    return x * x;
}

struct line {
	ld a, b, c;

	line(point p1, point p2) {
		if (!eq(p1.y, p2.y)) {
			a = 1;
			b = (p1.x - p2.x) / (p2.y - p1.y);
		} else {
			b = 1;
			a = (p2.y - p1.y) / (p1.x - p2.x);
		}
		c = -(a * p1.x + b * p1.y);
	}

	point projection(point p) {
		ld t = -(a * p.x + b * p.y + c) / (sq(a) + sq(b));
		return point(p.x + t * a, p.y + t * b);
	}
};

ld dist(point a, point b) {
    return sqrt(sq(a.x - b.x) + sq(a.y - b.y));
}


ld calc(point a, point b, point c) {
    line l(a, c);
    point x = l.projection(b);
    return dist(x, b) / 2;
}

