typedef long long ll;
const ll MOD = (ll) 1e9 + 7;

int gcd(int a, int b) {
	while (b) {
		a %= b;
		swap(a, b);
	}
	return a;
}


template <typename T>
T phi(T n) {
	T ret = n;
	for (T i = 2; i * i <= n; i++) {
		if (n % i == 0) {
			ret -= ret / i;
			while (n % i == 0) {
				n /= i;
			}
		}
	}
	if (n > 1) {
		ret -= ret / n;
	}
	return ret;
}

int naive_phi(int n) {
	int ret = 0;
	for (int i = 1; i <= n; i++) {
		if (gcd(i, n) == 1) ret++;
	}
	return ret;
}

int f(int n) {
	if (n == 1) return 1;
	int ret = 0;
	for (int x = 1; x < n; x++) {
		int y = n - x;
		if (gcd(x, y) == 1) ret++;
	}
	return ret;
}

int g(int n) {
	int ret = 0;
	for (int i = 1; i * i <= n; i++) {
		if (n % i == 0) {
			ret += f(i);
			if (i * i != n) ret += f(n / i);
		}
	}
	return ret;
}

ll f(ll n, ll k) {
	if (k == 1) return phi(n);
	if (k & 1) {
		return phi(f(n, k - 1));
	} else {
		return f(n, k - 1);
	}
}

