void dfs(int v, int p = -1) {
	s[v] = 1;
	for (int to : ng[v]) if (to != p && !cntr[to]) {
		dfs(to, v);
		s[v] += s[to];
	}
}

int center(int v, int all, int p = -1) {
	for (int to : ng[v]) if (to != p && !cntr[to]) {
		if (s[to] > all / 2) return center(to, all, v);
	}
	return v;
}

void makecntr(int v, int step) {
	dfs(v);
	v = center(v, s[v]);
	cntr[v] = true;
	ans[v] = step;
	for (int to : ng[v]) {
		if (!cntr[to]) {
			makecntr(to, step + 1);
		}
	}
}

void makegr() {
	for (int i = 0; i < n; i++) {
		used[i].resize(g[i].size());
		num[i].resize(g[i].size());
	}
	vector < vector <int> > faces;
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < (int) g[i].size(); j++) {
			if (!used[i][j]) {
				int index = faces.size();
				used[i][j] = true;
				num[i][j] = index;
				vector <int> face;
				int a = i;
				int b = g[i][j];
				while (1) {
					face.push_back(b);
					auto x = lower_bound(g[b].begin(), g[b].end(), a) - g[b].begin();
					if (x != 0) {
						x--;
					} else {
						x = g[b].size() - 1;
					}
					if (used[b][x]) break;
					used[b][x] = true;
					num[b][x] = index;
					a = b;
					b = g[b][x];
				}
				faces.push_back(face);
			}
		}
	}					
	
	if (0) {
		int iter = 1;
		for (auto face : faces) {
