			for (int j = 0; j < (int) g[i].size(); j++) {
				cout << i+1 << " " << g[i][j]+1 << " " << num[i][j]+1 << "\n";
			}
		}
	}

	vector <vector <int> > cp(m+1);
	for (int i = 0; i <= m; i++) {
		cp[i] = faces[i];
		sort(cp[i].begin(), cp[i].end());
		reverse(cp[i].begin(), cp[i].end());
	}

	vector <int> per(m+1);
	for (int i = 0; i <= m; i++) {
		per[i] = i;
	}

	sort(per.begin(), per.end(), [&](int i, int j) {
		return cp[i] < cp[j];
	});

	vector <int> imp(m+1);
	for (int i = 0; i <= m; i++) {
		imp[per[i]] = i;
	}

	for (int v = 0; v < (int) faces.size(); v++) {
		auto face = faces[v];
		for (int i = 0; i < (int) face.size(); i++) {
			int a = face[i];
			int b = face[(i+1) % (int) face.size()];
			auto x = lower_bound(g[b].begin(), g[b].end(), a);
			if (x != g[b].end() && *x == a) {
				int index = x - g[b].begin();
				int u = num[b][index];
				ng[imp[v]].push_back(imp[u]);
			}
		}
	}
}

