typedef long long ll;
typedef pair<int, int> pii;

#define pb push_back
#define mp make_pair

int n;
struct RING{
    int a, b, h;
    RING(int a, int b, int h): a(a), b(b), h(h) {}
};
vector<RING> tmp;
vector<RING> mas;

bool cmp(const RING &lhs, const RING &rhs){
    if(lhs.a != rhs.a) return lhs.a > rhs.a;
    return lhs.b > rhs.b;
}
stack<RING> st;
ll cur, mx;

int main()
{
    ios_base::sync_with_stdio(0);
    cin >> n;
    for(int i = 0; i < n; i++){
        int a, b, h;
        cin >> b >> a >> h;
        tmp.pb(RING(a, b, h));
    }
    sort(tmp.begin(), tmp.end(), cmp);
    ll curh = tmp.front().h, cura = tmp.front().a;
    for(int i = 1; i < n; i++){
        if(tmp[i].a == cura){
            curh += tmp[i].h;
        }
        else{
            mas.pb(RING(cura, tmp[i - 1].b, curh));
            curh = tmp[i].h;
            cura = tmp[i].a;
        }
    }
    mas.pb(RING(cura, tmp[n - 1].b, curh));
    for(auto u: mas){
        if(st.empty()){
            st.push(u);
            cur += u.h;
        }
        else{
            while(!st.empty() && st.top().b >= u.a){
                cur -= st.top().h;
                st.pop();
            }
            st.push(u);
            cur += u.h;
        }
        mx = max(mx, cur);
    }
    cout << mx << endl;
    return 0;
}

