	for (int x=up+1;x<=dow;x++){
		if(x==dow || s[x][y]=='L'){
			if(x==dow && las==up)continue;
			foun=1;
			subwork(s,opt,las,x,y);
			las=x;
		}else if(s[x][y]=='D' && (x-up)%2==0)las=x;
	}
	if(!foun)return;
