const int maxn=6e4;
int n;
const double eps=1e-7;
struct node
{
    int pos;
    double v;
}mem[maxn+10];
void findtime(double &r)
{
    double MAX=1.0*(mem[n-1].pos-mem[0].pos)/mem[0].v;
    for(int i=1;i<n;i++)
    {
        MAX=max(MAX,(mem[i].pos-mem[0].pos)/mem[i].v);
        MAX=max(MAX,(mem[n-1].pos-mem[i].pos)/mem[i].v);
    }
    r=MAX;
}
bool isValid(double t)
{
    double MIN,MAX;
    MIN=mem[0].pos-mem[0].v*t;
    MAX=mem[0].pos+mem[0].v*t;
    for(int i=1;i<n;i++)
    {
        MIN=max(MIN,mem[i].pos-mem[i].v*t);
        MAX=min(MAX,mem[i].pos+mem[i].v*t);
        if(MIN>MAX)
            return 0;
    }
    return 1;
}
bool cmp1(node a,node b)
{
    return a.pos<b.pos;
}
int main()
{
    scanf("%d",&n);
    for(int i=0;i<n;i++)
        scanf("%d",&mem[i].pos);
    for(int i=0;i<n;i++)
        scanf("%lf",&mem[i].v);
    sort(mem,mem+n,cmp1);
    double l=0.0,r;
    findtime(r);
    double o1,o2;
    while(l+eps<r)
    {
        o1=(2*l/3+r/3);
        o2=(2*r/3+l/3);
        if(!isValid(o2))
            l=o2;
        else
        {
            r=o2;
            if(!isValid(o1))
                l=o1;
            else
                r=o1;
        }
    }
    printf("%.6f\n",r);
}

