void add(int v, int vl, int vr, int pos, int val) {
  st[v] += val;
  if (vl == vr - 1) {
    return;
  }
  int mid = (vl + vr) / 2;
  if (pos < mid) {
    add(v * 2, vl, mid, pos, val);
  } else {
    add(v * 2 + 1, mid, vr, pos, val);
  }
}

int get(int v, int vl, int vr, int &k) {
  if (k >= st[v]) {
    k -= st[v];
    return vr - vl;
  }
  if (vl == vr - 1) {
    return 0;
  }
  int mid = (vl + vr) / 2;
  int res = get(v * 2, vl, mid, k);
  if (res == mid - vl) {
    res += get(v * 2 + 1, mid, vr, k);
  }
  return res;
}

