    build(rc[o], mid+1, r);
}

void modify(int &o, int p, int l, int r, int pos, int val) {
    o = ++tot;
    lc[o] = lc[p];
    rc[o] = rc[p];
    s[o] = s[p] + val;
    if (l == r) return ;
    int mid = l + r >> 1;
    if (pos <= mid) modify(lc[o], lc[p], l, mid, pos, val);
    else modify(rc[o], rc[p], mid+1, r, pos, val);
}

int kth(int o, int l, int r, int k) {
    if (s[o] < k) return 0;
    if (l == r) return l;
    int mid = l + r >> 1;
    if (k <= s[lc[o]]) return kth(lc[o], l, mid, k);
    else return kth(rc[o], mid+1, r, k-s[lc[o]]);
}

int get_pos(int x, int k) {
    int m = s[root[x]] - k;
    if (m <= 0) return 1;
    return kth(root[x], 1, n, m) + 1;
}

