            modify(root[i], root[i-1], 1, n, pre[a[i]], -1);
            modify(root[i], root[i], 1, n, i, 1);
        } else modify(root[i], root[i-1], 1, n, i, 1);
        pre[a[i]] = i;
    }
    for (int k=1; k<=n; ++k) {
