void findhor(int x, int l, int r) {
	if (r - l < 2) return;
	int m = (l + r) / 2;
	if (m + m > l + r) m--;
	int mx = (r - l - 2) >> 1;
	for (int i = 0; i <= (l + r & 1); i++, m++) {
		int d = ask(x, m);
		if (!d) {
			hor.pb(m);
			findhor(x, l, m);
			findhor(x, m, r);
			return;
		}
		else if (d <= mx) {
			int d2 = ask(x, m + 1);
			if (d2 < d) {
				hor.pb(m + d);
				findhor(x, l, m + d);
				findhor(x, m + d, r);
				return;
			}
			else {
				hor.pb(m - d);
				findhor(x, l, m - d);
				findhor(x, m - d, r);
				return;
			}
		}
	}
}

void findver(int l, int r, int y) {
	if (r - l < 2) return;
	int m = (l + r) / 2;
	if (m + m > l + r) m--;
	int mx = (r - l - 2) >> 1;
	for (int i = 0; i <= (l + r & 1); i++, m++) {
		int d = ask(m, y);
		if (!d) {
			ver.pb(m);
			findver(l, m, y);
			findver(m, r, y);
			return;
		}
		else if (d <= mx) {
			int d2 = ask(m + 1, y);
			if (d2 < d) {
				ver.pb(m + d);
				findver(l, m + d, y);
				findver(m + d, r, y);
				return;
			}
			else {
				ver.pb(m - d);
				findver(l, m - d, y);
				findver(m - d, r, y);
				return;
			}
		}
	}
}

