long long vCount[maxn];
int pre[maxn];

void init(int n)
{
	mem(vCount,0);
	for (int i = 0; i < n; ++i)
	{
		Tree[i].clear();
	}
	for (int i = 1; i <= n; ++i)
	{
		pre[i] = i;
	}
}

int find(int x)
{
	if (pre[x] == x)
	{
		return x;
	}
	else
	{
		//x的父亲更改成它的祖先，降低树高度
		pre[x] = find(pre[x]);
		return pre[x];
	}
}


