		for (int i = 0; i < m; ++i)
		{
			int u,v;
			cin>>u>>v;
			int fu = find(u);
			int fv = find(v);
			if (fu != fv)
			{
				pre[fu] = fv;
			}
		}
		long long _sum = 0;
		for (int i = 1; i <= n ;++i)
		{
			int fi = find(i);
			vCount[fi] ++;
		}
		for (int i = 1;i <= n; ++i)
		{
			long long vertices = vCount[i];
			if (vertices != 0)
			{
				_sum += ((vertices * (vertices - 1)) / 2);
			}
		}
		if (m >= _sum)
