int charToInt(char c) {
    return c - '0';
}

int getSum(string s) {
    int sum = 0;

    for (int i = 0; i < s.length(); i++)
        sum += s[i] - '0';

    return sum;
}

string removeZeroes(string s) {
    for (int i = 0; i < s.length(); i++)
        if (s[i] != '0') return s.substr(i);

    return "0";
}

int main() {
    string s, s1, s2;
    cin >> s;

    int sum = getSum(s), valid2 = 0, valid1 = 0;

    if (sum % 3 == 0) {
        cout << s;
        return 0;
    } else if (sum % 3 == 1) {
        for (int i = (int) (s.length() - 1); i > -1; i--) {
            if (charToInt(s[i]) % 3 == 1 && !valid1) {
                valid1 = 1;
                continue;
            }

            s1.push_back(s[i]);
        }

        for (int i = (int) (s.length() - 1); i > -1; i--) {
            if (charToInt(s[i]) % 3 != 2 || valid2 == 2)
                s2.push_back(s[i]);
            else valid2++;
        }
    } else if (sum % 3 == 2) {
        for (int i = (int) (s.length() - 1); i > -1; i--) {
            if (charToInt(s[i]) % 3 == 2 && !valid1) {
