        }
    }
    reverse(s1.begin(),s1.end());
    reverse(s2.begin(),s2.end());
    if (valid1 && valid2 == 2) {
        cout << removeZeroes(removeZeroes(s1).length() > removeZeroes(s2).length() ? s1 : s2);
