#include <bits/stdc++.h>

using namespace std;
#define ll long long
ll n, q, u, root;
char s[1000000];

ll getStepDown(ll parent, ll target, ll step)
{
    if(target < parent)
        return getStepDown(parent - step, target, step / 2);
    else if(target > parent)
        return getStepDown(parent + step, target, step / 2);
    else
        return step;
}
ll getParent(ll parent, ll cur, ll target, ll step)
{
    if(cur == target) return parent;

    if(cur < target) return getParent(cur, cur + step, target, step / 2);

    if(cur > target) return getParent(cur, cur - step, target, step / 2);
}

ll getAns(ll cur, ll stepUp, int i)
{
    if(i >= strlen(s)) return cur;

    ll MAXSTEP = (n + 1) / 2;

    switch(s[i])
    {
    case 'U':

        // if root
        if(cur == MAXSTEP)
            return getAns(cur, stepUp, i + 1);
        else
        {
            ll parent = getParent(root, root, cur, root / 2);
            return getAns(parent, stepUp * 2, i + 1);
        }

        break;

    case 'L':

        // if leaf
        if(cur % 2)
        {
            return getAns(cur, 1, i + 1);
        }
        else
        {
            return  getAns(cur - stepUp / 2, stepUp / 2, i + 1);
        }

    case 'R':

        // if leaf
        if(cur % 2)
        {
            return getAns(cur, 1, i + 1);
        }
        else
        {
            return  getAns(cur + stepUp / 2, stepUp / 2, i + 1);
        }
    }
}

int main()
{
    scanf("%lld %lld", &n, &q);
    root = (n + 1) / 2;

    while(q--)
    {
        scanf("%lld %s", &u, s);
        ll stepDown = getStepDown(root, u, root / 2);
        ll stepUp = (stepDown == 0) ? 1 : stepDown * 2;
        printf("%lld\n", getAns(u, stepUp, 0));
    }
}

