#include <bits/stdc++.h>
using namespace std;

typedef long double ld;

struct mice_s{
    int x, y;
    int vx, vy;
    ld t1x, t2x;
    ld t1y, t2y;
    ld t1, t2;
};

int n;
int bx1, bx2, by1, by2;
ld t1, t2;
mice_s mice[100001];

void swap(ld &a, ld &b){
    ld tmp = a;
    a = b;
    b = tmp;
}

bool calcTime(mice_s &m){
    if(m.vx != 0){
        m.t1x = (bx1 - m.x) / (ld)m.vx;
        m.t2x = (bx2 - m.x) / (ld)m.vx;
    }else{  // == 0
        if(m.x > bx1 && m.x < bx2){
            m.t1x = 0;
            m.t2x = 9999999999999;
        }else{
            return true;
        }
    }

    if(m.vy != 0){
        m.t1y = (by1 - m.y) / (ld)m.vy;
        m.t2y = (by2 - m.y) / (ld)m.vy;
    }else{ // == 0
        if(m.y > by1 && m.y < by2){
            m.t1y = 0;
            m.t2y = 9999999999999;
        }else{
            return true;
        }
    }

    if(m.t1x > m.t2x){
        swap(m.t1x, m.t2x);
    }

    if(m.t1y > m.t2y){
        swap(m.t1y, m.t2y);
    }

    m.t1 = max(m.t1x, m.t1y);
    m.t2 = min(m.t2x, m.t2y);

    if(m.t1 > m.t2)return true;         // "-1"
    return false;                       // OK
}

int main(){
    cin >> n;
    cin >> bx1 >> by1 >> bx2 >> by2;

    for(int i=0; i < n; i++){
        cin >> mice[i].x >> mice[i].y >> mice[i].vx >> mice[i].vy;

        //Odredi vremena ulaska i izlaska
        if (calcTime(mice[i]) ){        //Early exit
            cout << "-1\n";
            return 0;
        }

    }


    //Presjek svih vremena
    t1 = max(mice[0].t1, (ld)0);        //Vrijeme ne moze biti negativno
    t2 = mice[0].t2;
    for(int i=1; i < n; i++){
        t1 = max(t1, mice[i].t1);
        t2 = min(t2, mice[i].t2);
    }

    if(t1 >= t2)
        printf("-1\n");
    else
        printf("%.15Lf\n", t1);

    return 0;
}

