		b[i]=min(a[i],max(a[i-1],a[i+1]));
	}
	int ji,ou;
	if(n%2==1)
	{
		ji=n;
		ou=n-1;
	}
	else
	{
		ji=n-1;
		ou=n;
	}
	maxn=0;
	for(int i=ou;i>=2;i-=2)
	{
		int l=i/2-1;
		int r=n-i/2;
		maxn=max(maxn,max(a[l],a[r]));
