const double EPS=1e-6;
const int INF = 3e5+1;
int check[INF];
vector<int> graf[INF];
set<int> child[INF];
bool comp(int a, int b)
{
	return graf[a]<graf[b];
}
void solve()
{
	ll a,b;
	cin>>a>>b;

	for(int i=0;i<b;++i)
	{
		int l,r;
		cin>>l>>r;
		graf[l].pb(r);
		graf[r].pb(l);
	}

	vector<int> x;
	for(int i=1;i<=a;++i)
	{
		x.pb(i);
		graf[i].pb(i);
		sort(all(graf[i]));
	}
	sort(all(x),comp);
	vector<int> color(INF);
	int col=1;
	color[x[0]]=col++;
	for(int i=2; i<=a;++i)
	{
		if(graf[x[i-1]]==graf[x[i-2]])
		{
			color[x[i-1]]=color[x[i-2]];
		}

		else
		{
			color[x[i-1]]=col++;
		}
	}

	if(col==2)
	{
		cout<<"YES"<<endl;
		for(int i=1;i<=a;++i)
		{
			cout<<1<<" ";
		}
		exit(0);
	}
	for(int i=1;i<=a;++i)
	{
		int size = graf[i].size();
		for(int j=0;j<size;++j)
		{
			if(color[i]!=color[graf[i][j]])
			{
				child[color[i]].insert(color[graf[i][j]]);
			}
		}
	}
	int curVert=0;
	for(int i=1;i<=a;++i)
	{
		if(child[i].size()>=3)
		{
			err(1);
		}
		else if(child[i].size()==1)
		{
			curVert=i;
		}
	}

	if(!curVert)
		err(1);

	vector<int> res(INF);
	res[curVert]=1;
	check[curVert]=1;
	int to = *child[curVert].begin();
	int curCol=1;
	while(to)
	{
		res[to]=++curCol;
		check[to]=1;

		int toVert=0;
		for(auto i=child[to].begin();i!=child[to].end();++i)
		{
			if(!res[*i])
			{
				toVert=*i;
				break;
			}
		}	
		to=toVert;
	}
	cout<<"YES"<<endl;
	for(int i=1;i<=a;++i)
	{
		cout<<res[color[i]]<<" ";
	}
}	

