#include <bits/stdc++.h>

using namespace std;

typedef long long ll;
typedef pair<int, int> ii;

const int MAXN = 100010;


int n, q;
int ar[MAXN];

int pw[10];

int lazy[MAXN * 4][10];
ll sum[4 * MAXN][10];

#define left (index << 1)
#define right (left + 1)
#define mid ((l + r) / 2)

void build(int index, int l, int r)
{
	if (l == r)
	{
		for (int i = 0; i < 10; i++) lazy[index][i] = i;
		int cnt = 0;
		while (ar[l]) {
			int x = ar[l] % 10;
			sum[index][x] += pw[cnt];
			ar[l] /= 10;
			cnt++;
		}
		return;
	}

	build(left, l, mid);
	build(right, mid + 1, r);
	for (int i = 0; i < 10; i++) {
		lazy[index][i] = i;
		sum[index][i] = sum[left][i] + sum[right][i];
	}
}

int tmp1[10], tmp2[10];
ll tmp[10];

void upd(int index, int l, int r)
{
	if (l != r) {
		memset(tmp1, 0, sizeof tmp1);
		memset(tmp2, 0, sizeof tmp2);

		for (int i = 0; i < 10; i++) {
			tmp1[i] = lazy[index][lazy[left][i]];
			tmp2[i] = lazy[index][lazy[right][i]];
		}
		for (int i = 0; i < 10; i++) {
			lazy[left][i] = tmp1[i];
			lazy[right][i] = tmp2[i];
		}
	}

	memset(tmp, 0, sizeof tmp);

	for (int i = 0; i < 10; i++) {
		tmp[lazy[index][i]] += sum[index][i];
	}
	for (int i = 0; i < 10; i++) {
		sum[index][i] = tmp[i];
	}

	for (int i = 0; i < 10; i++) {
		lazy[index][i] = i;
	}
}

void update(int index, int l, int r, int ql, int qr, int u, int v)
{
	upd(index, l, r);
	if (l >= ql && r <= qr) {
		lazy[index][u] = v;
		upd(index, l, r);
		return;
	}

	if (l > qr || r < ql) return;

	update(left, l, mid, ql, qr, u, v);
	update(right, mid + 1, r, ql, qr, u, v);

	for (int i = 0; i < 10; i++) {
		sum[index][i] = sum[left][i] + sum[right][i];
	}
}

ll query(int index, int l, int r, int ql, int qr)
{
	upd(index, l, r);

	if (l > qr || r < ql) return 0;

	if (l >= ql && r <= qr) {
		ll ret = 0;
		for (int i = 0; i < 10; i++) {
			ret += i * sum[index][i];
		}
		return ret;
	}

	ll a = query(left, l, mid, ql, qr);
	ll b = query(right, mid + 1, r, ql, qr);

	return a + b;
}


int main()
{
	pw[0] = 1;
	for (int i = 1; i < 10; i++) pw[i] = 10 * pw[i - 1];

	scanf("%d%d", &n, &q);
	for (int i = 0; i < n; i++) {
		scanf("%d", &ar[i]);
	}
	build(1, 0, n - 1);

	for (int i = 0; i < q; i++) {
		int t, l, r;
		scanf("%d%d%d", &t, &l, &r);

		l--, r--;

		if (t == 1) {
			int u, v;
			scanf("%d%d", &u, &v);
			
			update(1, 0, n - 1, l, r, u, v);
		}
		else {
			printf("%lld\n", query(1, 0, n - 1, l, r));
		}
	}
}

