int power(int a,int n)
{
    if(n==0)
       return 1;
    int ret=power(a,n/2);
    ret=(int)((long long)ret*(long long)ret%mod);
    if(n%2)
       ret=(int)((long long)ret*(long long)a%mod);
    return ret;
}
int C(int n,int m)
{
	if(m<0||m>n)
	   return 0;
    int ret=(int)((long long)fac[n]*(long long)inv[m]%mod);
    ret=(int)((long long)ret*(long long)inv[n-m]%mod);
    return ret;
}
int gcd(int a,int b)
{
	int tmp;
	while(b!=0)
	{
		tmp=a%b;
		a=b;
		b=tmp;
	}
	return a;
}
