bool ok(int x)
{
    int cnt = k;
    int i = 0;
    while (cnt)
    {
        if (f[i + x + 1] < f[i]) return 0;
        i = Next[i + x + 1];
        cnt --;
        if (cnt > 0 && i + x + 1 >= n-1) return 1;
    }
    return n - i - 2 <= x;
}

