int helper1(int id,int l,int r)
{
	int cur=l;
	for(int i=0;i<s[id].length();i++)
	{
		if(cur==r+1)
		return 1;
		if(s[id][i]==S[cur])
		{
			cur++;
			if(cur==r+1)
			return 1;
		}
	}
	return 0;
}
void pre_calc()
{
	for(int i=1;i<=n;i++)
	{
		for(int j=1;j<=l;j++)
		{
			int lo=0;
			int hi=min(j,(int)s[i].length())+1;
			while(hi-lo>1)
			{
				int mid=(lo+hi)/2;
				if(helper1(i,j-mid+1,j))
				lo=mid;
				else
				hi=mid;
			}
			store[i][j]=lo;
		}
	}
}
inline int helper(int str_idx,int idx)
{
	return store[str_idx][idx];
}
