const int maxn = 5e5 + 5;
int n, a[maxn], b[maxn], ans[maxn], vis[maxn];
pii tree[maxn*4];
vector<int> tp;

void build(int l, int r, int t) {
  if (l == r) {
    tree[t] = pii(b[l], l);
  } else {
    int mid = (l + r) / 2;
    build(l, mid, ls);
    build(mid + 1, r, rs);
    tree[t] = max(tree[ls], tree[rs]);
  }
}

void delet(int l, int r, int t, int p) {
  if (l == r) {
    tree[t] = pii(0, 0);
  } else {
    int mid = (l + r) / 2;
    if (p <= mid) delet(l, mid, ls, p);
    else delet(mid + 1, r, rs, p);
    tree[t] = max(tree[ls], tree[rs]);
  }
}

pii query(int l, int r, int st, int ed, int t) {
  if (st > ed) return pii(0, 0);
  if (st <= l && r <= ed) return tree[t];
  int mid = (l + r) / 2;
  pii ans = pii(0, 0);
  if (st <= mid) ans = max(ans, query(l, mid, st, ed, ls));
  if (ed >= mid + 1) ans = max(ans, query(mid + 1, r, st, ed, rs));
  return ans;
}

