  delet(1, n, 1, t);
  vis[t] = 1;
  if (b[t] != n + 1 && !vis[b[t]]) dfs(b[t]);
  while (1) {
    pii tmp = query(1, n, 1, a[t] - 1, 1);
    if (tmp.fst > t) dfs(tmp.snd);
    else break;
  }
  tp.push_back(t);
}

void solve() {
  scanf("%d", &n);
  for (int i = 1; i <= n; i++) b[i] = n + 1;
  for (int i = 1; i <= n; i++) {
    scanf("%d", &a[i]);
    if (a[i] == -1) a[i] = n + 1;
    else b[a[i]] = i;
  }
  build(1, n, 1);
  for (int i = 1; i <= n; i++) if (!vis[i]) dfs(i);
  int k = 1;
  for (auto u : tp) ans[u] = k++;
  for (int i = 1; i <= n; i++) printf("%d ", ans[i]);
}

int main() {
  solve();
  return 0;
}

