int sieve(int n){
	int tot=0;
	mu[1]=1;
	phi[1]=1;
	for (int i=2;i<=n;i++){
		if (!bo[i]){
			prime[++tot]=i;
			mu[i]=-1;
			phi[i]=i-1;
		}
		for (int j=1;j<=tot && prime[j]*i<=n;j++){
			bo[i*prime[j]]=1;
			if(i%prime[j]==0){
				mu[i*prime[j]]=0;
				phi[i*prime[j]]=phi[i]*prime[j];
				break;
			}else{
				mu[i*prime[j]]=-mu[i];
				phi[i*prime[j]]=phi[i]*(prime[j]-1);
			}
		}
	}
	return tot;
}

