    {
        int st = (d1 >= n - k + 1 ? d1 - n + k : 0);
        int fn = min(k, d1);
        for (int p = fn; p >= st; p--)
        {
            for (int r = p; r >= st; r--)
            {
                if (p != 0)
                    dp[p][r] = min(dp[p][r], dp[p-1][r] + p1[d1]);
                if (r != 0)
                    dp[p][r] = min(dp[p][r], dp[p][r-1] + r1[d1]);
                if (p != 0 && r != 0)
                    dp[p][r] = min(dp[p][r], dp[p-1][r-1] + r1[d1] + p1[d1]);
            }
        }
    }

    cout << dp[k][k] << endl;
    return 0;
}

