		seg[k].mnB=seg[k].mr=P(B,k-mum+1);
		seg[k].opt1=seg[k].opt2=PP(A+B,P(k-mum+1,k-mum+1));
		while(k>0)
		{
			k=(k-1)/2;
			seg[k]=merge(seg[k*2+1],seg[k*2+2]);
