ll bin_pow(ll a,int n){
    if(n==0){
        return 1;
    } else if(n%2==0){
        ll x = bin_pow(a,n/2);
        return (x*x)%mod;
    } else {
        ll x = bin_pow(a,n-1);
        return (x*a)%mod;
    }
}
