typedef long double dbl;


struct vertex{
    int tl,tr;
    vertex *l,*r;
    bool pushed;
    int val;

    vertex (int TL,int TR,int VAL,bool Pushed){
        tl = TL;
        tr = TR;
        val = VAL;
        pushed = Pushed;
        l = r = NULL;
    }
};
int n,k;

struct segment_tree{
    int n;
    int *t;
    int NN;
    void init(int N){
        n = 1;
        NN = N;
        while(n<N){
            n=n<<1;
        }
        t = new int[2*n];
        fill(t,t+2*n,inf_int);
    }

    void build(){
        for(int i=n-1;i>=1;--i){
            t[i]=min(t[i<<1],t[i<<1|1]);
        }
    }

    int query(int l,int r){ //[l,r]
        if(l<=r){
            return get(l,r+1);
        } else {
            return min(get(l,NN),get(0,r+1));
        }
    }

    int get(int l,int r){ // [l,r)
        l = l+n,r = r+n;
        int res = inf_int;
        for(;l<r;l>>=1,r>>=1){
            if(l&1)
                res=min(res,t[l++]);
            if(r&1)
                res=min(res,t[--r]);
        }
        return res;
    }
};
segment_tree tree;

inline void push(vertex* v){
    if(v->pushed){
        v->l->val = v->val;
        v->r->val = v->val;
        v->l->pushed = 1;
        v->r->pushed = 1;
        v->pushed = 0;
    }
}

int get(vertex* v,int l,int r){
    if(l>r){
        return inf_int;
    }
    int tl = v->tl,tr = v->tr;
    if(tl==l && tr==r){
        return v->val;
    } else {
        int tm=(tl+tr)>>1;
        if(v->l==NULL){
            if(v->pushed){
                v->l = new vertex(tl,tm,v->val,1);
            } else {
                int cur_val;
                if(tm-tl>=n-1)
                    cur_val = tree.get(0,n);
                else
                    cur_val = tree.query(tl%n,tm%n);

                v->l = new vertex(tl,tm,cur_val,0);
            }
        }

        if(v->r==NULL){

            if(v->pushed){
                v->r = new vertex(tm+1,tr,v->val,1);
            } else {
                int cur_val;
                if(tr-(tm+1)>=n-1)
                    cur_val = tree.get(0,n);
                else
                    cur_val = tree.query((tm+1)%n,tr%n);
                v->r = new vertex(tm+1,tr,cur_val,0);
            }
        }
        push(v);
        return min(get(v->l,l,min(r,tm)),get(v->r,max(tm+1,l),r));
    }
}


void update(vertex* v,int l,int r,int val){
    if(l>r)
        return;
    int tl=v->tl,tr=v->tr;
    if(tl==l && tr==r){
        v->val = val;
        v->pushed = 1;
    } else {
        int tm=(tl+tr)>>1;
        if(v->l==NULL){
            if(v->pushed){
                v->l = new vertex(tl,tm,v->val,1);
            } else {
                int cur_val;
                if(tm-tl>=n-1)
                    cur_val = tree.get(0,n);
                else
                    cur_val = tree.query(tl%n,tm%n);
        //        cout <<"add"<<tl<<" "<<tm <<" "<<tl%n<< " "<<tm%n<< " "<<cur_val<<endl;
                v->l = new vertex(tl,tm,cur_val,0);
            }
        }

        if(v->r==NULL){

            if(v->pushed){
                v->r = new vertex(tm+1,tr,v->val,1);
            } else {
                int cur_val;
                if(tr-(tm+1)>=n-1)
                    cur_val = tree.get(0,n);
                else
                    cur_val = tree.query((tm+1)%n,tr%n);
                v->r = new vertex(tm+1,tr,cur_val,0);
            }
        }
        push(v);
        update(v->l,l,min(r,tm),val);
        update(v->r,max(tm+1,l),r,val);
        v->val = min(v->l->val,v->r->val);


    }
}

void print(vertex* v){
    if(v==NULL)
        return;
    int tl = v->tl,tr=v->tr;
    cout << tl <<" "<<tr<<" "<<v->val<<" "<<v->pushed<<endl;
    print(v->l);
    print(v->r);
}
void solve()
{

    cin >> n >> k;
    tree.init(n);
    for(int i=0;i<n;++i){
        int x;
        cin >> x;
        tree.t[i+tree.n]=x;
    }
    tree.build();
    vertex* root = new vertex(0,n*k-1,tree.get(0,n),0);
    int q;
    cin >> q;
    while(q--){
        int t,l,r;
        cin >> t >> l >> r;
        l--;r--;
        if(t==2){
            cout <<get(root,l,r)<<"\n";
        } else {
            int val;
            cin >> val;
            update(root,l,r,val);
        }
      //  print(root);
    }
}



