typedef long long ll;

int N,M;
const int MAX_N = 300000;
int ans = 1;
int color [MAX_N + 1];
vector<int> A [MAX_N + 1];
vector<int> edge [MAX_N + 1];

void dfs(int curr,int prev = -1)
{
	set<int> used;
	for(const auto& it : A [curr]) if(color [it]){
		used.insert(color [it]);
	}
	int id = 1;
	for(const auto& it : A [curr]) if(color [it] == 0){
		while(id <= ans && used.count(id)) id++;
		color [it] = id;
		used.insert(id);
	}
	for(const auto& it : edge [curr]) if(it != prev){
		dfs(it,curr);
	}
}

int main()
{
	scanf("%d%d",&N,&M);
	FOR(i,1,N + 1){
		int S;
		scanf("%d",&S);
		chmax(ans,S);
		A [i].assign(S,0);
		FOR(j,0,S){
			scanf("%d",&A [i] [j]);
		}
	}
	FOR(i,0,N - 1){
		int u,v;
		scanf("%d%d",&u,&v);
		edge [u].push_back(v);
		edge [v].push_back(u);
	}

	dfs(1);
