const ll INF = (ll)3e18;

ll solve()
{
    ll x, y, p, q;
    scanf("%lld%lld%lld%lld", &x, &y, &p, &q);
    if (p == q && x < y) return -1;
    if (p == 0 && x > 0) return -1;
    ll l = 0, r = INF / q;
    while(r - l > 1)
    {
        ll d = (l + r) / 2;
        ll qq = q * d, pp = p * d;
        if (y <= qq && x <= pp && pp - x <= qq - y)
            r = d;
        else
            l = d;
    }
    return q * r - y;
}

