typedef long long LL;
LL n;
int pownum[2005];   //pownum[i]表示2的i次方有多少个
int betnum[2005];   //betnum[i]表示大于2的i次幂小于2的i+1次幂的个数

int check(LL x)
{
    //x表示当前的可更新的链的个数，初始一定为x，即总个数
    LL t = pownum[0] - x; // 多余的1的个数
    for(int i = 1; i < 64; ++i)
    {
        if(x >= pownum[i])
        {
            t -= min(t, x-pownum[i]);
            x = pownum[i];
        }
        else
            t += pownum[i]-x;
        t += betnum[i];

    }
    return t<=x;
}

int main()
{
    ios::sync_with_stdio(false);
    cin >> n;
    LL x;
    for(int i = 0; i < n; ++i)
    {
        cin >> x;
        bool flag = 1;
        int id = 0;
        while(x>1)
        {
            if(x&1) // x不是2的幂次
                flag = 0;
            id++;
            x >>= 1;
        }
        if(flag)
            pownum[id]++;
        else
            betnum[id]++;
    }

    LL ans = -1, l = 1, r = pownum[0];
    //二分个数， 最大为2^0的个数
    while(l <= r)
    {
        LL mid = (l+r) >> 1;

        if(check(mid))
        {
            ans = mid;
            r = mid - 1;
        }
        else
            l = mid + 1;
    }

    if(ans == -1)
    {
        cout << ans << endl;
    }
    else for(int i = ans; i <= pownum[0]; ++i)
    {
        cout << i << " ";
    }
    return 0;
}

