  if (grid[x][y] == 'F') return true;
  if (grid[x][y] == '*') return false;
  if (vis[x][y]) return false;
  vis[x][y] = true;
  if (dfs(x + 1, y)) {
    nx[x][y] = x + 1;
    ny[x][y] = y;
    mv[x][y] = 'D';
  } else if (dfs(x - 1, y)) {
    nx[x][y] = x - 1;
    ny[x][y] = y;
    mv[x][y] = 'U';
  } else if (dfs(x, y + 1)) {
    nx[x][y] = x;
    ny[x][y] = y + 1;
    mv[x][y] = 'R';
  } else if (dfs(x, y - 1)) {
    nx[x][y] = x;
    ny[x][y] = y - 1;
    mv[x][y] = 'L';
  } else {
    return false;
  }
  return true;
}

