//start

const int maxn = 1e5+1;

//stack begin

int stk[maxn], top=0;
//stack end

// dsu begin
int pa[maxn], sz[maxn], dis[maxn];
void init(int n)
{
    top = 0;
    for (int i = 1; i <= n; ++i)
    {
        pa[i] = i, sz[i] = 1, dis[i] = 0;
    }
}
int findpa(int id)
{
    while (id != pa[id])
    {
        id = pa[id];
    }
    return id;
}
int distance(int id)
{
    int ret = 0;
    while (id != pa[id])
    {
        ret ^= dis[id];
        id = pa[id];
    }
    return ret;
}
bool merge(int x, int y)
{
    int xp = findpa(x), yp = findpa(y);
    int d = distance(x)^distance(y);
    if (xp == yp)
    {
        if (!d)
        {
            return false;
        }
    }
    else
    {
        if (sz[xp] > sz[yp])
        {
            swap(xp, yp);
        }
        sz[yp] += sz[xp];
        pa[xp] = yp;
        dis[xp] = d^1;
        stk[top++] = xp;
    }
    return true;
}
void rewind(int t)
{
    while (top > t)
    {
        int cur = stk[--top];
        sz[pa[cur]] -= sz[cur];
        pa[cur] = cur;
        dis[cur] = 0;
    }
}
// dsu end
int n, q, tot;
map<ii, int> ma;
ii res[maxn];
ii e[maxn];
void solve(int l, int r, int tot);
int main()
{
    scanf("%d %d", &n, &q);
    tot = 0;
    for (int i = 0; i < q; ++i)
    {
        int u, v; scanf("%d %d", &u, &v);
        if (u > v)
        {
            swap(u, v);
        }
        ii cur(u, v);
        if (ma.count(cur))
        {
            int e = ma[cur];
            res[e].second = i-1;
            ma.erase(cur);
        }
        else
        {
            res[tot].first = i;
            res[tot].second = q;
            e[tot] = cur;
            ma[cur] = tot++;
        }
    }
    init(n);
    solve(0, q-1, tot);
}

void solve(int l, int r, int tot)
{
    int start_t = top;
    for (int i = 0; i < tot; ++i)
    {
        if (res[i].first <= l && res[i].second >= r)
        {
            if (!merge(e[i].first, e[i].second))
            {
                for (int i = l; i <= r; ++i)
                {
                    puts("NO");
                }
                rewind(start_t); return;
            }
            swap(res[i], res[--tot]);
            swap(e[i--], e[tot]);
        }
    }
    if (l == r)
    {
        puts("YES");
    }
    else
    {
        int mid = (l+r)>>1;
        int k = 0;
        for (int i = 0; i < tot; ++i)
        {
            if (res[i].first <= mid)
            {
                swap(res[i], res[k]);
                swap(e[i], e[k++]);
            }
        }
        solve(l, mid, k);
        k = 0;
        for (int i = 0; i < tot; ++i)
        {
            if (res[i].second > mid)
            {
                swap(res[i], res[k]);
                swap(e[i], e[k++]);
            }
        }
        solve(mid+1, r, k);
    }
    rewind(start_t);
}

