int dp1[N][N][N], dp2[N][N], d[N], ip2[N], fact[3 * N], n;

int f(int nd, int p1, int p2)
{
    if(p1 < 0 or p2 < 0)
        return 0;
    if(dp1[nd][p1][p2] != -1)
        return dp1[nd][p1][p2];
    int ret;
    if(nd)
        ret = (mul(p1, f(nd-1, p1-1, p2)) + mul(p2, f(nd-1, p1+1, p2-1))) % MOD;
    else if(p1)
        ret = (mul(p1-1, f(0, p1-2, p2)) + mul(p2, f(0, p1, p2-1))) % MOD;
    else if(p2 > 2)
    {
        ret = 0;
        int tf = ((p2-1) * (p2-2)) / 2;
        for(int i=3; i<=p2; i++)
        {
            ret += mul(tf, f(0, 0, p2-i));
            ret %= MOD;
            tf = mul(tf, p2-i);
        }
    }
    else
        ret = !p2;
    dp1[nd][p1][p2] = ret;
    return ret;
}

int g(int l, int r)
{
    if(dp2[l][r] != -1)
        return dp2[l][r];
    int ret, p1 = 0, p2 = 0;
    for(int i=l; i<=r; i++)
    {
        if(d[i] == 2)
            p1++;
        else
            p2++;
    }
    if(r == n)
        ret = f(0, p1, p2);
    else
    {
        ret = 0;
        for(int i=r+1; i<=n; i++)
        {
            ret += mul(f(i-r, p1, p2), g(r+1, i));
            ret %= MOD;
        }
    }
    dp2[l][r] = ret;
    return ret;
}

