	if(zan==1)
	{
		if(l!=-1&&vec[l]==R-L+1) return m;
		if(r!=-1&&vec[r]==R-L+1) return m;
	}
	int id=mp[m-L];
	ll nm=0;
	if(l!=-1) nm+=dp[id][l];
	if(r!=-1) nm+=dp[id][r];
	//printf("%lld %d : %lld\n",m-L,id,nm);
	//if(L+1<=R) printf("%lld %d : %lld\n",m-L,id,nm);
	if(nm>=zan) return solve(L,m-1,zan,l,r);
	return solve(m+1,R,zan-nm,l,r);
}
