long long ncr(long long n,long long k)
{
	if(k==0)return 1;
	if(n<k)return  0;
	long long ans=fact[n];
	ans=(ans*ifact[k])%MOD;
	ans=(ans*ifact[n-k])%MOD;
	if(ans<0)ans+=MOD;
	return ans;
}



