void add(ll x)
{
    int v = 0, i = 30;
    while(i>=0)
    {
        ll bit = ((x&(1<<i))>0)?1:0;
        if(tr[v][bit] == 0)    // if ith bit is 0
            tr[v][bit] = nxt++;
        cnt[v][bit]++;
        v = tr[v][bit];
        i--;
    }
}

void del(ll x)
{
    int v = 0, i = 30;
    while(i>=0)
    {
        ll bit = ((x&(1<<i))>0)?1:0;
        cnt[v][bit]--;
        int go = tr[v][bit];
        if(cnt[v][bit]==0)
            tr[v][bit]=0;
        v=go;
        i--;
    }
}

int query(ll x,ll y)
{
    ll ans = 0;
    int i = 30, v = 0;
    while(i>=0)
    {
        ll bit = (y&(1<<i));
        if(bit)
        {
            if(x&(1<<i))
            {
                ans+=cnt[v][1];
                v=tr[v][0];
            }
            else
            {
                ans+=cnt[v][0];
                v=tr[v][1];
            }
        }
        else
        {
            if((x&(1<<i)))
                v = tr[v][1];
            else
                v=tr[v][0];
        }
        if(v==0)
            break;
        i--;
    }
    return ans;
}

