void prime(int k){
	int temp = k;
	for(int i = 2;i*i<=temp;i++){
		int c = 0;
		while(k%i == 0){
			k/=i;
			c++;
		}
		if(c)
		v.push_back({i,c});
	}
	if(k != 1)
		v.push_back({k,1});
}
bool check(){
	for(int i = 0;i < v.size();i++)
		if(lol[i] < v[i].second)return true;
	return false;
}
void fix(int u,bool t){
	for(int i = 0;i < v.size();i++)
		while(u%v[i].first == 0){
			u/=v[i].first;
			if(t)lol[i]++;
			else lol[i]--;
		}
}
