	int r = -1;
	long long ans = 0;
	for(int l = 0;l < n;l++){
		if(l > r){
			r++;
			fix(a[r],1);
		}
		while(r < n - 1 && check()){
			r++;
			fix(a[r],1);
		}
		if(!check())
			ans+= n - r;
		fix(a[l],0);
	}
	printf("%lld\n",ans);
}

