bool check(const vector<long long> &a, long long k, long long n)
{
	long long sum = 0;

	if (n < maxd)
		return true;

	for (auto it : a)
	{
		auto t = n - (it % n);

		if (t != n)
			sum += t;
	}

	if (sum <= k)
	{
		maxd = n;

		return true;
	}

	return false;
}

