bool func(vector<node> &v , ll k , ll noOfQuestionMark) {
	ll sum = 0;
	rep(i, 0, 25) {
    	if(v[i].needed) {
            if(v[i].needed*k-v[i].diff > 0) {
                sum += v[i].needed*k-v[i].diff;
            }
    	}
    }
    return (sum <= noOfQuestionMark);
}

ll binary_search(vector<node> &v , ll k , ll noOfQuestionMark) {
	ll l = 0;
	ll u = k;
	while(l<u) {
		ll m = l + (u-l+1)/2;
		if(func(v, m, noOfQuestionMark))
			l = m;
		else
			u = m-1;
	}
	if(l>u)
		return 0;
	else
		return l;
}

