using namespace std;
const int MAXN = (1 << 13);
const int64_t base = 29;
int64_t mod = (int)1e9 + 9;

int n;
string s;

void read()
{
    cin >> s;
    n = s.size();
}

int64_t base_pow[MAXN], hsh[MAXN];
int16_t dp[MAXN], cost[MAXN][MAXN];

uint64_t get_hash(int l, int r)
{
    if(l == 0) return hsh[r];
    else return (hsh[r] - (base_pow[r - l + 1] * hsh[l - 1]) % mod + mod) % mod;
}

int16_t cnt_digs[MAXN];

std::mt19937 rnd(std::chrono::system_clock::now().time_since_epoch().count());
int const HALFBILLION = 500000000;

bool prime(int x) {
  for (int i = 2; i * i <= x; i++) {
    if (x % i == 0) return false;
  }
  return true;
}

void gen(int64_t & M) {
  M = rnd() % HALFBILLION + HALFBILLION;
  while (!prime(M)) {
    ++M;
  }
}

void solve()
{
    gen(mod);

    base_pow[0] = 1;
    for(int i = 0; i < n; i++)
    {
        hsh[i] = (((i) ? hsh[i - 1] : 0) * base + s[i] - 'a' + 1) % mod;
        base_pow[i + 1] = (base_pow[i] * base) % mod;
        cnt_digs[i + 1] = cnt_digs[(i + 1) / 10] + 1;
    }

    for(int i = 0; i < n; i++)
    {
        for(int j = i; j < n; j++)
            cost[i][j] = (j - i + 1);

        for(int j = i; j < n; j++)
            if(get_hash(i, i + cost[i][j] - 1) == get_hash(j + 1, j + cost[i][j]))
                cost[i][j + cost[i][j]] = min(cost[i][j + cost[i][j]], cost[i][j]);

        for(int j = i; j < n; j++)
            cost[i][j] += cnt_digs[(j - i + 1) / cost[i][j]];
    }

    for(int i = 0; i < n; i++)
    {
        dp[i] = cost[0][i];
        for(int j = 0; j < i; j++)
            if(dp[j] + cost[j + 1][i] < dp[i])
                dp[i] = dp[j] + cost[j + 1][i];
    }

    cout << dp[n - 1] << endl;
}

