	for (ll x = 1; x <= n; x++) {
		for (ll a = 0; a * x <= n - 1; a++) {
			ll rest = n - 1 - a * x;
			if (rest % (x + 1) != 0) continue;
			ll b = rest / (x + 1);
			if (a + b != k) {
				continue;
			}
			ll cur = 0;
			if (a >= 1) {
				maxi(cur, x);
			}
