				maxi(cur, x + 1);
			}
			if (a >= 2) {
				maxi(cur, 2 * x);
			}
			if (b >= 2) {
				maxi(cur, 2 * (x + 1));
			}
			if (a >= 1 && b >= 1) {
				maxi(cur, x + (x + 1));
			}
			
			if (mini(ans.best, cur)) {
				ans.a = a;
				ans.b = b;
				ans.x = x;
			}
		}
