		if(par[i][s] != par[i][e]){
			s = par[i][s];
			e = par[i][e];
		}
	}
	if(s != e) s = par[0][s];
	return s;
}

int query(int s, int e){
	int l = lca(s, e);
	int ans = 0;
	for(int i=17; i>=0; i--){
		if(dep[s] - (1<<i) >= dep[l]){
			ans = max(ans, mxv[i][s]);
			s = par[i][s];
		}
		if(dep[e] - (1<<i) >= dep[l]){
			ans = max(ans, mxv[i][e]);
			e = par[i][e];
		}
	}
	return ans;
}

int gap[MAXN];

int comp(int s, int e, int x){
	if(dep[s] <= dep[e]) return e;
	ret[idx[s]] = min(ret[idx[s]], x);
	return gap[s] = comp(gap[par[0][s]], e, x);
}

