int n,m,fa[maxn],par[maxn][20],max_w[maxn][20],dep[maxn],in_mst[maxn],ans[maxn],r[maxn];
//par-边值，max_w-最大的边值，par-祖先,dep点的深度,in_mst-是否在mst内,r-表示这个点所在边的id
struct edge { //定义边的结构体
    int u,v,w,id; //w-边值，id-边的序号
} e[maxn];
vector<edge> G[maxn];

bool cmp(edge a,edge b) {
    return a.w < b.w;
}

int query(int x) {
    return fa[x] == x ? fa[x] : fa[x] = query(fa[x]);
}

void dfs(int u,int fa,int d) {
    dep[u] = dep[fa]+1; par[u][0] = fa; max_w[u][0] = d;
    for(int i = 1;i <= 18;i++) {
        par[u][i] = par[par[u][i-1]][i-1];
        max_w[u][i] = max(max_w[u][i-1],max_w[par[u][i-1]][i-1]);
    }
    for(int i = 0;i < G[u].size();i++)  {
        edge temp_e = G[u][i];
        int v = temp_e.v;
        if(v == fa) continue;
        r[v] = temp_e.id;
        dfs(v, u, temp_e.w);
    }
}

int lca(int x,int y,int &d)   //倍增求出lca
{
    d = 0;
    if(dep[x] < dep[y]) swap(x, y);
    for(int i = 18;i >= 0;i--)
    {
        if(dep[par[x][i]] >= dep[y])
        {
            d = max(d, max_w[x][i]);
            x = par[x][i];
        }
    }// leap to the equal dep
    if(x == y) return x;
    for(int i=18;i>=0;i--)
    {
        if(par[x][i] != par[y][i])
        {
            d = max(d, max(max_w[x][i], max_w[y][i]));
            x = par[x][i]; y = par[y][i];
        }
    }
    // now they are both after lca 1 step
    d = max(d, max(max_w[x][0], max_w[y][0]));
    return par[x][0];
}
void slove(int x,int u,int d) // u is lca
{
    x = query(x);
    while(dep[x] > dep[u])
    {
        ans[r[x]] = min(ans[r[x]], d);
        int y = query(par[x][0]);  //这里用路径压缩，因为非mst内的边已经排好序了，所以每个mst内的边只要更新一次，就用路径压缩跳过
        fa[x] = y;
        x = query(x);
    }
}

int main() {
    cin>>n>>m;
    for(int i = 1;i <= m;i++) {
        int u,v,w;
        scanf("%d%d%d",&u,&v,&w);
        e[i] = edge{u,v,w,i};
    }
    sort(e+1,e+1+m,cmp); //按边值排序
    clr(in_mst,0);
    for(int i = 1;i <= n;i++) fa[i] = i;
    for(int i = 1;i <= m;i++) {
        int x = e[i].u,y = e[i].v;
        int fx = query(x),fy = query(y);
        if(fx != fy) {
            fa[fy] = fx;
            in_mst[e[i].id] = 1;  //表明这条边在mst内
            G[x].pb(e[i]);    //建mst
            edge tmp = e[i];
            swap(e[i].u,e[i].v);
            G[y].pb(e[i]);
        }
    }
    dfs(1,0,0);   //dfs预处理倍增的数组，还有两点之间最大的边值
    clr(ans,inf);
    for(int i = 1;i <= n;i++) fa[i] = i;
    for(int i = 1;i <= m;i++) {
        if(!in_mst[e[i].id]) {  //如果这条边没有在mst内
            int x = e[i].u,y = e[i].v,u = lca(x,y,ans[e[i].id]); //求lca
            ans[e[i].id]--; //mst外的边就是点x~点y之间最大边值-1
            slove(x,u,e[i].w-1);  //mst内的边就用mst外的每一条边去更新，答案是最小的边值
            slove(y,u,e[i].w-1);
        }
    }
    for(int i = 1;i <= m;i++) {
        if(ans[i] == inf) printf("-1 ");
        else printf("%d ",ans[i]);
    }
    cout<<endl;
}

