struct bit {
    int tree[MAXN];
    void update(int p, int v) {
        for(; p <= n; p += p&-p) tree[p] += v;
    }
    int query(int p) {
        int c = 0;
        for(; p; p -= p&-p) c += tree[p];
        return c;
    }
    int query(int i, int j) { return query(j) - query(i - 1); }
} BIT;


int dist(int i, int j) {
    if(i <= j) return j - i + 1 - BIT.query(i, j);
    else return dist(1, j) + dist(i, n);
}

