            for( int i = 0 ; i < n ; i++ ) 
                for( int j = 0 ; j < S ; j++ ) 
                    dp[i][j] = up[i][j] = vector<int>();

            for( int i = 0 ; i < m ; i++ ){ 
                int u, v; cin >> u >> v;
                u--; v--; 
                c[u].push_back(v); 
                c[v].push_back(u);
            }
            for( int i = 0 ; i < n ; i++ ) 
                if( !mark[i] ) 
                    dfs( i );

            memset( mark , 0 , sizeof mark ); 
            for( int i = 0 ; i < n ; i++ ) 
                if( !mark[i] ) { 
                    solve(i); 
                    int k = c[i].size();
                    for( int j = 0 ; j < S ; j++ ) { 
                        if( dp[i][j][k] >= 0 ) {
                            calc(i,j,k);
