const int SIZE = 100001;
int tree[4 * SIZE];
std::vector<int> vec[SIZE];
std::vector<int>::iterator it;
void build(int node, int s, int e)
{
	if (s == e)
	{
		tree[node] = 1;
		return;
	}
	int mid = (s + e) / 2;
	build(2 * node, s, mid);
	build(2 * node + 1, mid + 1, e);
	tree[node] = tree[2 * node] + tree[2 * node + 1];
}
void update(int node, int s, int e, int pos)
{
	if (s == e)
	{
		tree[node] = 0;
		return;
	}
	int mid = (s + e) / 2;
	if (pos <= mid)
		update(2 * node, s, mid, pos);
	else
		update(2 * node + 1, mid + 1, e, pos);
	tree[node] = tree[2 * node] + tree[2 * node + 1];
}
int query(int node, int s, int e, int l, int r)
{
	if (l > r || e < l || s > r)
		return 0;
	if (s >= l && e <= r)
		return tree[node];
	int mid = (s + e) / 2;
	int p = query(2 * node, s, mid, l, r);
	int q = query(2 * node + 1, mid + 1, e, l, r);
	return p + q;
}
