const int MAXN = 100000;
struct node{
    int v;
    node *next;
}Edges[MAXN*2+10], *ecnt=Edges, *adj[MAXN+10];
int sz[MAXN+10], Fa[MAXN+10], hson[MAXN+10], tp[MAXN+10], dep[MAXN+10];
int Tree[MAXN*4+10], flg[MAXN*4+10], id[MAXN+10], idcnt;
void push_down(int u, int l, int mid, int r){
    if(flg[u]){
        Tree[u<<1] += flg[u]*(mid-l+1);
        Tree[u<<1|1] += flg[u]*(r-mid);
        flg[u<<1] += flg[u];
        flg[u<<1|1] += flg[u];
        flg[u] = 0;
    }
}
void Insert(int u, int l, int r, int L, int R, int val){
    if(L <= l && r <= R){
        Tree[u] += val*(r-l+1);
        flg[u] += val;
        return ;
    }
    int mid=(l+r)>>1;
    push_down(u, l, mid, r);
    if(L <= mid) Insert(u<<1, l, mid, L, R, val);
    if(R > mid) Insert(u<<1|1, mid+1, r, L, R, val);
    Tree[u] = Tree[u<<1]+Tree[u<<1|1];
}
int Query(int u, int l, int r, int L, int R){
    if(L <= l && r <= R) return Tree[u];
    int mid=(l+r)>>1, ret=0;
    push_down(u, l, mid, r);
    if(L <= mid) ret += Query(u<<1, l, mid, L, R);
    if(R > mid) ret += Query(u<<1|1, mid+1, r, L, R);
    return ret;
}
void addedge(int u, int v){
    ++ecnt;
    ecnt->v = v;
    ecnt->next = adj[u];
    adj[u] = ecnt;
}
void dfs(int u, int fa){
    dep[u] = dep[fa]+1;
    Fa[u] = fa;
    sz[u] = 1;
    for(node *p=adj[u];p;p=p->next){
        if(p->v == fa)
            continue;
        dfs(p->v, u);
        sz[u] += sz[p->v];
        if(sz[p->v] > sz[hson[u]])
            hson[u] = p->v;
    }
}
void dfs2(int u, int tps){
    tp[u] = tps;
    id[u] = ++idcnt;
    if(hson[u]) dfs2(hson[u], tps);
    for(node *p=adj[u];p;p=p->next){
        if(p->v == Fa[u] || p->v == hson[u])
            continue;
        dfs2(p->v, p->v);
    }
}
void AddLink(int x, int y, int v){
    while(tp[x] != tp[y]){
        if(dep[tp[x]] < dep[tp[y]])
            swap(x, y);
        Insert(1, 1, idcnt, id[tp[x]], id[x], v);
        x = Fa[tp[x]];
    }
    if(dep[x] > dep[y]) swap(x, y);
    Insert(1, 1, idcnt, id[x], id[y], v);
}
int QueryLink(int x, int y){
    int ret=0;
    while(tp[x] != tp[y]){
        if(dep[tp[x]] < dep[tp[y]])
            swap(x, y);
        ret += Query(1, 1, idcnt, id[tp[x]], id[x]);
        x = Fa[tp[x]];
    }
    if(dep[x] > dep[y]) swap(x, y);
    ret += Query(1, 1, idcnt, id[x], id[y]);
    return ret;
}
int LCA(int x, int y){
    while(tp[x] != tp[y]){
        if(dep[tp[x]] < dep[tp[y]])
            swap(x, y);
        x = Fa[tp[x]];
    }
    return dep[x]<dep[y]?x:y;
}
int solve(int s, int x, int y){
    int lca1 = LCA(s, x), lca2 = LCA(s, y);
    if(lca1 == lca2){
        int lca3 = LCA(x, y);
        return dep[lca3]+dep[s]-2*dep[lca2]+1;
    }
    return min(dep[s]-dep[lca1], dep[s]-dep[lca2])+1;
}
