int n_=1<<16;
int dp[51][1<<17];
int lazy[51][1<<17];

inline void lazy_eval(int lev,int k){
	dp[lev][k]+=lazy[lev][k];
	if(k<n_-1){
		lazy[lev][k*2+1]+=lazy[lev][k];
		lazy[lev][k*2+2]+=lazy[lev][k];
	}
	lazy[lev][k]=0;
}

inline void lazy_upd(int lev,int k){
	dp[lev][k]=max(dp[lev][k*2+1],dp[lev][k*2+2]);
}

void update(int lev,int a,int b,int v,int k=0,int l=0,int r=n_){
	lazy_eval(lev,k);
	if(b<=l || r<=a)return;
	if(a<=l && r<=b){
		lazy[lev][k]+=v;
		lazy_eval(lev,k);
		return;
	}
	int mid=(l+r)/2;
	update(lev,a,b,v,k*2+1,l,mid);
	update(lev,a,b,v,k*2+2,mid,r);
	lazy_upd(lev,k);
}

int query(int lev,int a,int b,int k=0,int l=0,int r=n_){
	lazy_eval(lev,k);
	if(b<=l || r<=a)return 0;
	if(a<=l && r<=b)return dp[lev][k];
	int mid=(l+r)/2;
	int vl=query(lev,a,b,k*2+1,l,mid);
	int vr=query(lev,a,b,k*2+2,mid,r);
	lazy_upd(lev,k);
	return max(vl,vr);
}

