int build(int tree[], int a[], int root, int low, int high) {
    if(low == high) tree[root] = a[low];
    else {
        int mid = (low + high) / 2;
        tree[root] = max(build(tree, a, root * 2 + 1, low, mid), build(tree, a, root * 2 + 2, mid + 1, high));
    }
    return tree[root];
}
int query(int tree[], int lazy[], int root, int root_low, int root_high, int low, int high) {// max-query
    if(low == root_low && high == root_high) return lazy[root] + tree[root];
    int root_mid = (root_low + root_high) / 2;
    if(high <= root_mid) return query(tree, lazy, root * 2 + 1, root_low, root_mid, low, high) + lazy[root];
    if(root_mid + 1 <= low) return query(tree, lazy, root * 2 + 2, root_mid + 1, root_high, low, high) + lazy[root];
    return max(query(tree, lazy, root * 2 + 1, root_low, root_mid, low, root_mid),
               query(tree, lazy, root * 2 + 2, root_mid + 1, root_high, root_mid + 1, high)) + lazy[root];
}
void update(int tree[], int lazy[], int root, int root_low, int root_high, int low, int high, int diff) {// max-update
    if(low == root_low && high == root_high) lazy[root] += diff;
    else {
        int root_mid = (root_low + root_high) / 2;
        if(high <= root_mid) update(tree, lazy, root * 2 + 1, root_low, root_mid, low, high, diff);
        else if(root_mid + 1 <= low) update(tree, lazy, root * 2 + 2, root_mid + 1, root_high, low, high, diff);
        else {
            update(tree, lazy, root * 2 + 1, root_low, root_mid, low, root_mid, diff);
            update(tree, lazy, root * 2 + 2, root_mid + 1, root_high, root_mid + 1, high, diff);
        }
        tree[root] = max(tree[root * 2 + 1] + lazy[root * 2 + 1], tree[root * 2 + 2] + lazy[root * 2 + 2]);
    }
}

int n, k;
vector<int> tree, lazy, a, f[2], nxt;

int solve() {
    for(int kk = 1, pre = 0, cur = 1; kk <= k; kk++, pre ^= 1, cur ^= 1) {
        build(&tree[0], &f[pre][0], 0, 0, n), fill(lazy.begin(), lazy.end(), 0);
        for(int i = n - 1; i >= 0; i--) {
            update(&tree[0], &lazy[0], 0, 0, n, i + 1, a[i], 1);
            f[cur][i] = query(&tree[0], &lazy[0], 0, 0, n, i + 1, n);
        }
        if(kk == k) return f[cur][0];
    }
}

int main() {
    scanf("%d%d", &n, &k);
    tree.resize(4 * n), lazy.resize(4 * n), a.resize(n), f[0].resize(n + 1), f[1].resize(n + 1), nxt.assign(n + 1, n);
    for(int i = 0; i < n; i++) scanf("%d", &a[i]);
    for(int i = n - 1, t; i >= 0; i--) t = a[i], a[i] = nxt[a[i]], nxt[t] = i;
    printf("%d\n", solve());
    return 0;
}

#include <cstdio>
