struct Edge
{
    int a, b, l, isBanned;
} edges[2 * maxn];
int edgesCount;

vector <int> g[maxn];

void addEdge(int u, int v, int l)
{
    edges[edgesCount].a = u;
    edges[edgesCount].b = v;
    edges[edgesCount].l = l;
    edges[edgesCount].isBanned = false;
    g[u].pb(edgesCount++);
    
    edges[edgesCount].a = v;
    edges[edgesCount].b = u;
    edges[edgesCount].l = l;
    edges[edgesCount].isBanned = false;
    g[v].pb(edgesCount++);
}

int used[maxn];

int cycleSize;
vector <int> cycle;
bool findCycle(int v, int par = -1)
{
    used[v] = 1;
    cycle.pb(v);
    for (int i = 0; i < (int)g[v].size(); ++i)
    {
        int id = g[v][i];
        int to = edges[id].b;
        
        if (to == par || used[to] == 2)
            continue;
        
        if (used[to] == 1)
        {
            reverse(cycle.begin(), cycle.end());
            while (true)
            {
                int sz = (int)cycle.size();
                int v = cycle[sz - 1];
                if (v == to)
                    break;
                cycle.pop_back();
            }
            reverse(cycle.begin(), cycle.end());
            return true;
        }
        
        if (findCycle(to, v))
            return true;
    }
    cycle.pop_back();
    used[v] = 2;
    return false;
}

int ng[maxn];

void findEdgesInCycle()
{
    cycleSize = (int)cycle.size();
    for (int i = 0; i < cycleSize; ++i)
    {
        int v = cycle[i];
        for (int j = 0; j < (int)g[v].size(); ++j)
        {
            int id = g[v][j];
            int to = edges[id].b;
            
            if (to == cycle[(i + 1) % cycleSize])
                ng[v] = id;
        }
    }
}

ll findDepth(int v, int par = -1)
{
    ll res = 0;
    for (int i = 0; i < (int)g[v].size(); ++i)
    {
        int id = g[v][i];
        int to = edges[id].b;
        int len = edges[id].l;
        
        if (to == par || edges[id].isBanned)
            continue;
        
        res = max(res, findDepth(to, v) + len);
    }
    return res;
}

ll w[maxn];

void calcDepth()
{
    for (int i = 0; i < cycleSize; ++i)
    {
        int v = cycle[i];
        edges[ng[v]].isBanned = true;
        edges[ng[v] ^ 1].isBanned = true;
    }
    
    for (int i = 0; i < (int)cycle.size(); ++i)
    {
        int v = cycle[i];
        w[v] = findDepth(v);
    }
    
    for (int i = 0; i < cycleSize; ++i)
    {
        int v = cycle[i];
        edges[ng[v]].isBanned = false;
        edges[ng[v] ^ 1].isBanned = false;
    }
}

pll findDiam(int v, int par = -1)
{
    pll res = mp(0, v);
    
    for (int i = 0; i < (int)g[v].size(); ++i)
    {
        int id = g[v][i];
        int to = edges[id].b;
        int len = edges[id].l;
        
        if (to == par || edges[id].isBanned)
            continue;
        
        pll cur = findDiam(to, v);
        if (res.F < cur.F + len)
            res = mp(cur.F + len, cur.S);
    }
    
    return res;
}

ll prefDiam[maxn], prefPath[maxn], suffDiam[maxn], suffPath[maxn];

int main()
{
    int n;
    cin >> n;
    for (int i = 0; i < n; ++i)
    {
        int u, v, l;
        scanf("%d%d%d", &u, &v, &l);
        addEdge(u, v, l);
    }
    
    findCycle(1);
    findEdgesInCycle();
    calcDepth();
    
    ll maxHead = -INF;
    ll maxPair = 0;
    ll path = 0;
    ll maxPath = 0;
    for (int i = 0; i < cycleSize; ++i)
    {
        int v = cycle[i];
        int id = ng[v];
        
        maxPair = max(maxPair, maxHead + w[v]);
        maxPath = max(maxPath, path + w[v]);
        
        prefDiam[i] = maxPair;
        prefPath[i] = maxPath;
        
        maxHead = max(maxHead, w[v]) + edges[id].l;
        path += edges[id].l;
    }
    
    maxHead = -INF;
    maxPair = 0;
    path = 0;
    maxPath = 0;
    for (int i = cycleSize - 1; i >= 0; --i)
    {
        int v = cycle[i];
        int id = ng[v];
        
        path += edges[id].l;
        maxHead += edges[id].l;
        
        maxPair = max(maxPair, maxHead + w[v]);
        maxPath = max(maxPath, path + w[v]);
        
        suffDiam[i] = maxPair;
        suffPath[i] = maxPath;
        
        maxHead = max(maxHead, w[v]);
    }
    
    suffDiam[cycleSize] = -INF;
    suffPath[cycleSize] = -INF;
    
    ll minPossible = INF, bestEdge = -1;
    
    for (int i = 0; i < cycleSize; ++i)
    {
        int v = cycle[i];
        int id = ng[v];
        
        ll curDiam = max(prefDiam[i], suffDiam[i + 1]);
        curDiam = max(curDiam, prefPath[i] + suffPath[i + 1]);
        
        if (curDiam < minPossible)
        {
            minPossible = curDiam;
            bestEdge = id;
        }
    }
    
    edges[bestEdge].isBanned = true;
    edges[bestEdge ^ 1].isBanned = true;
    
    pll res;
    res = findDiam(1);
    res = findDiam(res.S);
    
    cout << max(minPossible, res.F) << endl;
    
    cerr << (clock() + 0.0) / CLOCKS_PER_SEC << endl;
    return 0;
}

