struct node
{
	node *ch[2];
	LL num, tag;

	node(){ memset(ch, 0, sizeof ch); num = linf; tag = 0; }

	void push()
	{
		if(tag)
		{
			rep(i, 2) ch[i]->tag += tag, ch[i]->num += tag;
			tag = 0;
		}
		return;
	}

	void pull()
	{
		num = min(ch[0]->num, ch[1]->num);
		return;
	}
}*root;

LL a[maxn];
int seg_a, seg_b;
LL seg_q;

void B(node* &u = root, int l = 1, int r = n)
{
	u = new node;
	if(l == r)
	{
		u->num = a[l];
		return;
	}

	int mid = l + r >> 1;
	B(u->ch[0], l, mid);
	B(u->ch[1], mid + 1, r);
	return u->pull();
}

void Q(node* &u = root, int l = 1, int r = n)
{
	if(seg_a <= l && r <= seg_b)
	{
		chkmin(seg_q, u->num);
		return;
	}

	int mid = l + r >> 1;
	u->push();
	if(seg_a <= mid) Q(u->ch[0], l, mid);
	if(seg_b > mid) Q(u->ch[1], mid + 1, r);
	return;
}

void M(node* &u = root, int l = 1, int r = n)
{
	if(seg_a <= l && r <= seg_b)
	{
		u->num += seg_q;
		u->tag += seg_q;
		return;
	}

	int mid = l + r >> 1;
	u->push();
	if(seg_a <= mid) M(u->ch[0], l, mid);
	if(seg_b > mid) M(u->ch[1], mid + 1, r);
	return u->pull();
}

