bool next(vector <int> &v, int m)
{
    int j = v.size() - 1;
    ++v[j];
    while (j > 0 && v[j] == m) {
        v[j] = 0;
        --j;
        ++v[j];
    }
    if (v[j] == m) {
        return false;
    }
    return true;
}

int go(const vector <int> &v, int m)
{
    vector <int> used(m);
    FOR (i, 0, v.size()) {
        int place = v[i] / 2;
        int dir = v[i] % 2;
        int ok = 0;
        if (dir == 0) {
            FOR (i, place, m) {
                if (!used[i]) {
                    used[i] = 1;
                    ok = 1;
                    break;
                }
            }
        } else {
            FORR (i, place, -1) {
                if (!used[i]) {
                    used[i] = 1;
                    ok = 1;
                    break;
                }
            }
        }
        if (!ok) {
            return 0;
        }
    }
