            int mask2=0;
            int pos=0;
            auto vtemp=getRep(mask,v2);
            while(pos<m1){
                if(ct==1){
                    if(graph[vtemp[0]][v1[pos]]){
                        works[pos][mask]=true;
                        mask2=mask2|(1<<pos);
                    }
                    else{
                        works[pos][mask]=false;
                    }
                }
                else{
                    if(works[pos][mask^(1<<firstdel)] && graph[v1[pos]][v2[firstdel]]){
                        works[pos][mask]=true;
                        mask2=mask2|(1<<pos);
                    }
                    else{
                        works[pos][mask]=false;
                    }
                }
                /*
                bool works=true;
                //auto temp=getRep(mask,v2);
                for(int i=0; i<temp.size() && works; i++){
                    works=works&&graph[temp[i]][v1[pos]];
                }
                if(works){
                    mask2=mask2|(1<<pos);
                }*/
                pos++;
                
            }
            mcsz=max(mcsz,dp1[mask2]+ct);
            
        }
    }
    
    
    if(!mcsz) cout<<0;
    else cout<<setprecision(12)<<k*k*(mcsz-1)/(2*mcsz);
    
    return 0;
    
}

