		cin >> a[i];
		cnt[a[i]]++;
	}
	p[0] = 1;
	for (int i = 1; i < N; i++) {
		for (int j = i; j < N; j += i) {
			cntDiv[i] += cnt[j];
		}
		p[i] = (p[i - 1] * 2LL) % mod;
	}
	for (int i = N; i > 1; i--) {
		if (cntDiv[i]) {
			ans[i] = (cntDiv[i] * 1LL * p[cntDiv[i] - 1]) % mod;
			for (int j = 2 * i; j < N; j += i) {
				ans[i] = (ans[i] - ans[j] + mod) % mod;
			}
		}
	}
	ll res = 0;
	for (int i = 2; i < N; i++) {
		(res += i * 1LL * ans[i]) %= mod;
	}
